E["npc:ayessa-dawnsinger"] = {t="npc",n="Ayessa Dawnsinger",z="zephras",s="In Valanaar on Zephras Isle, Ayessa Dawnsinger guides the Horde aligned Skyborne. She leads the Windshapers through their trials and politics.",h="In Valanaar on Zephras Isle, Ayessa Dawnsinger guides the Horde aligned Skyborne.",sec={{t="Leader of the Windshapers",b="From Valanaar on Zephras Isle, Ayessa Dawnsinger leads the Windshapers, the Skyborne aligned with the Horde. She directs their efforts across the island as they face outside threats and divisions among themselves. She guides them through alliances in Kalimdor and beyond, with their survival at stake.",sp=0},{t="The Struggle for Zephras",b="Ayessa Dawnsinger sends trusted champions to resolve conflicts on Zephras Isle. They face rogue constructs and hostile figures such as Lorthuna while the Skyborne confront their fate. Through political and physical struggles, Ayessa guides the Windshapers and keeps their voice and strength respected within the Horde.",sp=1}},faq={{q="Who is Ayessa Dawnsinger?",a="Ayessa Dawnsinger leads the Windshapers, the Horde aligned Skyborne on Zephras Isle.",al={"ayessa lore","who is ayessa","ayessa dawnsinger background"},it="identity"},{q="Where can Ayessa Dawnsinger be found?",a="Ayessa Dawnsinger can be found in Valanaar on Zephras Isle.",al={"where is ayessa","ayessa location","ayessa dawnsinger map"},it="place",gp=true},{q="What are the Windshapers?",a="The Windshapers are the Skyborne faction aligned with the Horde. Ayessa Dawnsinger guides them from Valanaar.",al={"windshapers faction","who are windshapers"},it="people"},{q="What is Ayessa's role in local quests?",a="Ayessa Dawnsinger gives work concerning the island's defense, including investigating rogue constructs, confronting Lorthuna, and shaping Zephras's future.",al={"ayessa quests","ayessa questline"},it="purpose",gp=true},{q="Whose side is Ayessa Dawnsinger on?",a="Ayessa Dawnsinger stands firmly aligned with the Horde. As the leader of the Windshapers, she guides the Horde-allied Skyborne faction operating out of Valanaar on Zephras Isle, directing their efforts and rallying Horde champions to her cause.",al={"ayessa dawnsinger faction","is ayessa horde or alliance","ayessa allegiance"},it="side",add="53a49c44"},{q="Who is Ayessa Dawnsinger tied to?",a="Ayessa Dawnsinger is directly tied to the Windshapers, the faction of Horde Skyborne whom she leads. Based in Valanaar, she coordinates their operations and orchestrates resistance against their local adversaries across Zephras Isle.",al={"ayessa dawnsinger faction ties","ayessa connections","who does ayessa work with"},it="ties",add="e31c8ea2"}},ang={["faction:Horde"]="For the Horde, Ayessa Dawnsinger is a key Skyborne ally and a point of contact on Zephras Isle.",["race:Skyborne"]="As a Skyborne, you can see in Ayessa Dawnsinger the path of those who stand with the Horde to secure their future."},kw={"ayessa","dawnsinger","horde","skyborne","valanaar","windshapers","zephras"},rel={"topic:skyborne","zone:zephras","topic:horde","quest:93746"},src={"Ayessa Dawnsinger"}}
E["npc:halaan-hawk-eye"] = {t="npc",n="Halaan Hawk-Eye",z="zephras",s="From Thendal Village, Halaan Hawk-Eye watches Zephras Isle’s anchor pylons. Though he lacks many Skyborne gifts, his keen natural vision helps him warn visitors as the pylons’ magic falters.",h="From Thendal Village, Halaan Hawk-Eye watches Zephras Isle’s anchor pylons.",sec={{t="A Watchman Without Magic",b="From the tower above Thendal Village, Halaan Hawk-Eye keeps watch. Many Skyborne can draw on the ley lines beneath Zephras Isle or see between worlds with mystical skysight. Halaan has neither gift. So he trusts his sharp natural senses, scanning the horizon for the island’s anchor pylons and calling attention to their increasingly volatile, inconsistent arcane energies.",sp=0}},faq={{q="Who is Halaan Hawk-Eye?",a="Halaan Hawk-Eye watches from the tower above Thendal Village on Zephras Isle. He scans the surrounding land and warns visitors about the erratic magic afflicting the island’s anchor pylons.",al={"halaan hawkeye","who is halaan","thendal watchtower npc"},it="identity"},{q="What makes Halaan different from other Skyborne?",a="Unlike many Skyborne, Halaan cannot see between worlds with mystical skysight or harness the ley lines beneath Zephras Isle. He relies on keen eyesight and natural observation.",al={"halaan abilities","can halaan use magic","halaan skysight"}},{q="Why is Halaan worried about the anchor pylons?",a="Halaan has noticed the distant anchor pylons’ magic growing erratic and inconsistent. He does not know how this threatens Zephras Isle’s stability.",al={"what is wrong with the pylons","anchors of zephras problem"},it="wants"},{q="Where can I find Halaan Hawk-Eye?",a="You can find Halaan Hawk-Eye atop the wooden watchtower in Thendal Village on Zephras Isle. He looks out over the horizon.",al={"where is halaan","halaan location"},it="place",gp=true},{q="Whose side is Halaan Hawk-Eye on?",a="Halaan is one of the Skyborne, standing with his fellow kin on Zephras Isle. Lacking the innate ley line sorcery and otherworldly skysight of his peers, he still serves his people faithfully by keeping watch over Thendal Village and alerting travelers to the creeping instability threatening their homeland.",al={"halaan faction","halaan hawk eye side","who does halaan serve"},it="side",add="d6a0f6c4"},{q="Why is Halaan Hawk-Eye stationed at the watchtower?",a="Halaan keeps watch atop the Thendal Village tower because he cannot draw upon the local ley lines or use magical skysight like other Skyborne. Instead, he uses his sharp natural vision to survey Zephras Isle, monitoring the distant anchor pylons as their magical stability begins to falter.",al={"why is halaan hawk-eye here","why is halaan at the watchtower","halaan location reason"},it="why_here",add="e8313a77"}},ang={["race:Skyborne"]="As a Skyborne, you can see how those without a natural affinity for ley line magic or skysight still serve their community through vigilance and martial duty."},kw={"anchor pylon","halaan","hawk-eye","skyborne","skysight","thendal village","zephras isle"},rel={"quest:94414","zone:zephras","topic:skyborne"},src={"Halaan Hawk-Eye"}}
E["npc:rorian-the-dayseeker"] = {t="npc",n="Rorian the Dayseeker",z="zephras",s="In Thendal Village, young Skyborne look to Rorian the Dayseeker as they approach adulthood. He teaches them to survive, honor tradition, and serve their island home.",h="In Thendal Village, young Skyborne look to Rorian the Dayseeker as they approach adulthood.",sec={{t="Elder of Thendal Village",b="In Thendal Village on Zephras Isle, Rorian the Dayseeker guides young Skyborne through the passage into adulthood. Under his calm instruction, fledglings face a traditional rite that marks their readiness to defend and support their island home.",sp=0},{t="Guiding the New Callings",b="Rorian also directs promising fledglings toward callings suited to their talents. Aspiring warriors, hunters, rogues, mages, shamans, and druids find trainers across the isle through his guidance. When elemental disturbances trouble the island, he alerts them and teaches them to preserve its balance.",sp=0}},faq={{q="Who is Rorian the Dayseeker?",a="Rorian the Dayseeker is an elder Skyborne leader in Thendal Village on Zephras Isle. He guides young Skyborne through their early trials.",al={"who is rorian","rorian role","what does rorian do"},it="identity"},{q="Where can Rorian the Dayseeker be found?",a="Rorian is in Thendal Village, the Skyborne starting settlement on Zephras Isle.",al={"where is rorian","rorian location","find rorian"},it="place",gp=true},{q="What is Rorian's role in the Skyborne coming of age?",a="Rorian guides fledglings through rites of passage into adulthood. He tests their mettle and attunement to island life, then sends them to serve the wider settlement.",al={"rorian coming of age","skyborne trial mentor"},it="purpose"},{q="How does Rorian direct new trainees into their classes?",a="Once a novice proves their worth, Rorian points them toward advanced training as a warrior, hunter, rogue, mage, shaman, or druid.",al={"class quests rorian","choosing a class with rorian"},gp=true},{q="Why does Rorian send adventurers to deal with elementals?",a="Rorian sends capable initiates to investigate and calm elemental unrest. Their efforts help preserve harmony in Thendal Village and the surrounding wildlands.",al={"elemental unrest rorian","why fight elementals zephras"},it="motive"},{q="Who is Aetheen of the Gales?",a="Aetheen of the Gales is on Zephras Isle. Rorian directs fledglings to them as they progress through their island responsibilities and training.",al={"aetheen rorian","aetheen of the gales"},it="ties"},{q="Whose side is Rorian the Dayseeker on?",a="Rorian serves his own people, the Skyborne of Zephras Isle. Stationed within Thendal Village, his loyalty rests firmly with the island's community as he prepares the next generation of Skyborne youth to step out into the world and face whatever threats imperil their homeland.",al={"rorian faction","who does rorian serve","rorian allegiance"},it="side",add="60e564c2"},{q="What does Rorian the Dayseeker want?",a="Rorian is committed to guiding fledgling Skyborne through their traditional rites of passage. He wants each young trainee to embrace their calling—whether martial, arcane, or natural—while ensuring the village is safeguarded against dangerous elemental turmoil.",al={"rorian goal","what is rorian trying to do","rorian dayseeker purpose"},it="wants",add="ec1df735"},{q="Why is Rorian the Dayseeker in Thendal Village?",a="Rorian remains in Thendal Village to oversee the coming-of-age trials for Skyborne initiates. From here, he monitors the island's affairs, directs novices toward specialized trainers, and dispatches capable hands to restore balance when elemental agitation flares up nearby.",al={"why is rorian here","why is rorian in thendal village","rorian location why"},it="why_here",add="c3a8f075"}},ang={["race:Skyborne"]="As a fledgling Skyborne, you meet Rorian the Dayseeker at the first threshold of duty and tradition. He guides your passage into adulthood in Thendal Village.",["class:Warrior"]="Rorian sees your dedication as an aspiring warrior and points you toward mentors who teach battlefield discipline.",["class:Mage"]="As a novice arcanist, you find an understanding guide in Rorian. He directs you toward teachers who can hone your magical potential.",["class:Shaman"]="Rorian stresses the island's harmony and sends you to soothe agitated elementals and connect with ancestral traditions."},kw={"dayseeker","fledgling","mentor","rorian","skyborne","thendal","zephras"},rel={"zone:zephras","topic:skyborne","quest:92460","quest:92461","quest:92464","quest:92469","quest:92471","quest:92474"},src={"Rorian the Dayseeker"}}
E["npc:ventaari-brightwish"] = {t="npc",n="Ventaari Brightwish",z="zephras",s="In Thendal Village, Ventaari Brightwish welcomes travelers from across Azeroth and offers them The Gift of Skysight.",h="In Thendal Village, Ventaari Brightwish welcomes travelers from across Azeroth and offers them The Gift of...",sec={{t="A Dweller of Thendal Village",b="Ventaari Brightwish welcomes newcomers to Thendal Village on Zephras Isle. As a Skyborne resident, she helps visitors from both the Alliance and the Horde. Through The Gift of Skysight, Ventaari introduces them to her people's traditions.",sp=0}},faq={{q="Who is Ventaari Brightwish?",a="Ventaari Brightwish lives in Thendal Village on Zephras Isle. She greets visitors and offers The Gift of Skysight.",al={"ventaari","who is ventaari","ventaari brightwish"},it="identity"},{q="Where can I find Ventaari Brightwish?",a="Find Ventaari Brightwish in Thendal Village on Zephras Isle.",al={"ventaari location","where is ventaari","thendal village ventaari"},it="place",gp=true},{q="Is Ventaari hostile to the Horde or Alliance?",a="No. Ventaari Brightwish speaks with adventurers from both the Alliance and the Horde.",al={"ventaari faction","is ventaari friendly","can horde talk to ventaari"},it="side"}},ang={["race:Skyborne"]="As a Skyborne in Thendal Village, Ventaari Brightwish helps visitors learn about the culture and ways of Zephras Isle."},kw={"brightwish","skyborne","skysight","thendal village","ventaari","zephras isle"},rel={"zone:zephras","quest:92598","topic:skyborne","topic:alliance","topic:horde"},src={"Ventaari Brightwish"}}
E["quest:92460"] = {t="quest",n="Coming of Age",z="zephras",s="In Thendal Village, young Skyborne begin the rite that welcomes them into service to the shen'dorei. Ailee Farheart leads them to Rorian the Dayseeker, who gives each initiate an ancestral relic and hears their pledge to aid their people.",h="In Thendal Village, young Skyborne begin the rite that welcomes them into service to the shen'dorei.",sec={{t="A Rite of Passage",b="Ailee Farheart guides young Skyborne from Thendal Village toward adulthood. They travel just west to the greatfather tree, where the village elder waits. For the shen'dorei, the rite marks a passage into adulthood and a pledge to serve their community. Local troubles are rising.",sp=0},{t="The Ancestral Relic",b="At the entrance to the greatfather tree, Rorian the Dayseeker leads the ceremony. He gives each initiate an ancestral relic, an heirloom passed through generations of shen'dorei. The relic is a token of the winds of home. It stays with its bearer until their ashes are scattered to the breeze.",sp=0}},faq={{q="What is the purpose of the Coming of Age ceremony?",a="The ceremony marks young Skyborne's passage into adulthood, welcomes them into service for the shen'dorei, and grants them an ancestral heirloom.",al={"why coming of age","coming of age purpose","skyborne rite of passage"},it="purpose"},{q="Who initiates the quest?",a="Ailee Farheart welcomes you in Thendal Village on Zephras Isle and guides you to meet the village leadership.",al={"who gives coming of age","where does coming of age start","ailee farheart location"},gp=true},{q="Who do you report to for the ritual?",a="Rorian the Dayseeker, leader of Thendal Village, waits at the entrance to the greatfather tree just west of the settlement.",al={"who is rorian","where is rorian","rorian the dayseeker location"},gp=true},{q="What relic is bestowed during the ceremony?",a="Rorian gives you an inherited relic carried through generations of shen'dorei. Tradition says it stays with you until death, then passes to the next generation.",al={"what is the relic","skyborne relic","what do you get"},it="item"},{q="What does 'shen'dorei' mean in this context?",a="Rorian uses 'shen'dorei' to refer to the Skyborne, recalling their complex history, shared trials, and enduring identity on Zephras Isle.",al={"who are the shendorei","shendorei meaning","skyborne shendorei"},it="people"},{q="Where does your journey lead immediately after this?",a="After your rite of passage, Rorian directs you to local matters threatening the island, beginning with Harmony in Balance and Infestation Investigation.",al={"what quest is next","next steps after coming of age","after rorian"},it="next_step",gp=true},{q="Why does Ailee Farheart send you to Rorian?",a="Ailee Farheart sees you ready to take your place among your people. As a young shen'dorei reaching adulthood, you only experience this milestone once in your life. Thendal Village has eagerly anticipated your arrival and needs your help, but before you can step forward to shoulder responsibility for your community, tradition demands that you first present yourself to village leader Rorian the Dayseeker for the rite of passage.",al={"why does ailee want this done","ailee farheart motive","why send to rorian"},it="motive",add="39b489c8"}},ang={["race:Skyborne"]="As a Skyborne, you enter adulthood bearing a sacred family heirloom wherever the winds carry you."},kw={"ailee farheart","coming of age","rorian the dayseeker","shen'dorei","skyborne","thendal grove","thendal village","zephras isle"},rel={"zone:zephras","npc:rorian-the-dayseeker","topic:skyborne"},m={start="Ailee Farheart",["end"]="Rorian the Dayseeker",level="1",id=92460},src={"Coming of Age (Forever)"},fv=true}
E["quest:92461"] = {t="quest",n="Harmony in Balance",z="zephras",s="On Zephras Isle, Rorian the Dayseeker gives fledgling adventurers an early rite of duty. You thin the vuldren in Thendal Grove to protect the island’s natural balance, for its beasts feel magic shifting in the winds.",h="On Zephras Isle, Rorian the Dayseeker gives fledgling adventurers an early rite of duty.",sec={{t="Tending the Grove",b="In Thendal Grove, vuldren have grown too numerous for the island to sustain. Their numbers threaten the environmental harmony that supports Zephras Isle’s wildlife. Rorian the Dayseeker gives young protectors the duty of thinning the herd before it strains the grove and the life around it.",sp=0},{t="Winds of Unrest",b="Vuldren are usually docile, yet the beasts of Zephras Isle are sensitive to the island’s atmosphere. When magic carried on the winds falls out of balance, they respond sharply. Keeping their numbers in check helps prevent them from becoming unpredictable and dangerous pests.",sp=0}},faq={{q="Why do the vuldren need to be culled?",a="The vuldren population in Thendal Grove has surged beyond sustainable numbers. Left unchecked, they could exhaust local resources and upset the balance that sustains the grove’s other inhabitants.",al={"why kill vuldren","vuldren overpopulation","thendal grove vuldren"},it="motive"},{q="Who is Rorian the Dayseeker?",a="Rorian the Dayseeker is an elder guide and mentor on Zephras Isle. He oversees young adventurers’ training and teaches them to care for their home through great crises and everyday stewardship.",al={"rorian lore","who is rorian"},it="identity"},{q="What makes the vuldren act up?",a="Vuldren are usually docile, but Zephras Isle’s native beasts sense when magic in the island’s winds falls out of balance. That shift can change their behavior.",al={"why are vuldren aggressive","vuldren behavior"},it="threat"},{q="Where does this task take place?",a="You carry out the work in Thendal Grove, just east and southeast of the settlement on Zephras Isle.",al={"thendal grove location","where is thendal grove"},it="place"},{q="What lesson is Rorian trying to teach?",a="Rorian teaches that protecting your home can demand difficult measures. A guardian sometimes has to take a firm guiding hand to restore natural order.",al={"rorian lesson","meaning of harmony in balance"},it="purpose"},{q="What should be done while hunting the vuldren?",a="Nearby, Elatrell Featherlight asks you to look into a swarm of pesky cirrusflies. You can investigate the infestation in the grove while hunting vuldren.",al={"other quests nearby","infestation investigation"},gp=true},{q="What are the juvenile vuldren you are hunting?",a="Juvenile vuldren are native creatures inhabiting Thendal Grove. Although generally docile and an essential part of the local ecosystem, their numbers have surged to unsustainable levels. In addition, local wildlife has begun sensing disturbances in the magic carried on the winds of Zephras, causing them to behave unpredictably if left unchecked.",al={"what are vuldren","juvenile vuldren","who are we hunting"},it="target",add="240c10a3"},{q="Why does Rorian send you instead of handling the cull himself?",a="Having just marked your coming of age, you are being tested with the practical responsibilities of maintaining Zephras. Rorian sees managing the mundane needs of Thendal Grove as a necessary duty and an important lesson: even when facing great uncertainty, protecting their homeland requires a guiding hand to preserve harmony.",al={"why send me","why does rorian need me","why me"},it="why_me",add="b29e78f0"}},ang={["class:Druid"]="As a druid, you know that thinning an overgrown vuldren population can protect the wider ecosystem.",["class:Hunter"]="As a hunter, you learn to manage herd numbers and watch how native beasts respond to changes around them."},kw={"harmony in balance","juvenile vuldren","rorian the dayseeker","thendal grove","vuldren","zephras","zephras isle"},rel={"npc:rorian-the-dayseeker","zone:zephras","quest:92462"},m={start="Rorian the Dayseeker",level="1",id=92461},src={"Harmony in Balance"},fv=true}
E["quest:92462"] = {t="quest",n="Infestation Investigation",z="zephras",s="In Thendal Grove, cirrusflies swarm the eastern woods. Ranger Elatrell Featherlight sends young defenders to thin their growing numbers before nearby settlements are at risk.",h="In Thendal Grove, cirrusflies swarm the eastern woods.",sec={{t="A Swarm in the Canopy",b="Local rangers report a sudden rise in cirrusflies along Thendal Grove’s eastern edge. One is a minor pest, but a swarm grows aggressive and destructive. So Ranger Elatrell Featherlight sends capable youths to cull the insects before they overwhelm the grove.",sp=0},{t="Early Steps of Service",b="After coming of age, young defenders help keep Zephras Isle safe. Clearing pests protects nearby settlements from outbreaks in the woods. Yet entrails and insects clinging to returning hunters show the swarm is far larger than first feared.",sp=0}},faq={{q="What is a cirrusfly?",a="Cirrusflies are winged insect pests native to Zephras Isle. Alone, they are small, but they multiply quickly and can form dangerous swarms in places like Thendal Grove.",al={"cirrusfly","cirrusflies","what are cirrusflies"},it="target"},{q="Who gives the quest Infestation Investigation?",a="Elatrell Featherlight gives the assignment. The ranger is stationed in Thendal Grove and watches the local wildlife and surrounding woods.",al={"quest giver","who starts it","elatrell featherlight"},it="identity"},{q="Where are the cirrusflies located?",a="Cirrusflies gather in the eastern and southeastern reaches of Thendal Grove on Zephras Isle. They are found among the foliage and young vuldren.",al={"where to find flies","cirrusfly location","thendal grove flies"},it="place",gp=true},{q="Why is culling the cirrusflies important?",a="A single cirrusfly poses little danger, but a swarm can grow dense enough to threaten travelers, consume local plants, and upset Thendal Grove’s balance.",al={"why kill flies","why cull cirrusflies","cirrusfly threat"},it="motive"},{q="What comes after Infestation Investigation?",a="After you thin the swarm and report to Elatrell Featherlight, you are sent toward the heart of the infestation to face the Cirrusfly Queen.",al={"next quest","what next","investigation follow up"},sp=1,it="next_step"},{q="Where does this quest fit into the early journey on Zephras?",a="The assignment comes right after the Coming of Age trial. It is one of the first combat duties given to newly recognized defenders of Zephras Isle.",al={"quest chain","when do i get this","level requirement"},it="origin"}},ang={["class:Hunter"]="As a hunter, you track cirrusflies darting among the trees and practice leading fast-moving targets through dense cover.",["class:Druid"]="As a druid, you help preserve Thendal Grove by addressing natural imbalances before aggressive swarms strip the woodland bare."},kw={"cirrusfly","elatrell featherlight","infestation","investigation","pesky cirrusfly","thendal grove","zephras"},rel={"quest:92463","zone:zephras"},m={start="Elatrell Featherlight",level="2",id=92462},src={"Infestation Investigation"},fv=true}
E["quest:92463"] = {t="quest",n="The Cirrusfly Queen",z="zephras",s="In Thendal Grove, cirrusflies threaten the rangers of Zephras Isle. Their swarm has spread far, so Elatrell Featherlight sends you to hunt its queen and thin the flies at their source.",h="In Thendal Grove, cirrusflies threaten the rangers of Zephras Isle.",sec={{t="Striking the Hive",b="You have seen that killing worker cirrusflies does little to curb the swarm spreading through Thendal Grove. Elatrell Featherlight sends you to the grove’s southeastern reaches, where the main hive lies. The queen directs the colony and heavier soldier drones guard her.",sp=0},{t="A Ranger's Burden",b="From afar, cirrusflies may seem like petty pests. Yet the larger breeds threaten anyone who passes beneath Zephras’s boughs. Hunt down the matriarch and withstand her guards, and you prove your skill in battle. Featherlight’s rangers will give you praise and respect.",sp=0}},faq={{q="Where is the Cirrusfly Queen located?",a="The Cirrusfly Queen nests in the southeastern corner of Thendal Grove on Zephras Isle, near the heart of the insect hive.",al={"queen location","where is cirrusfly queen","find the queen"},it="place",gp=true},{q="Why is slaying the worker flies not enough?",a="Hunting wandering workers only thins the swarm’s outer edges. While the queen lives, she breeds aggressive soldiers and replenishes the hive, keeping Thendal Grove in danger.",al={"why kill the queen","culling the hive"},it="motive"},{q="Who issues the hunt for the Cirrusfly Queen?",a="After the first reports from the forest confirm the severity of the cirrusfly infestation, Elatrell Featherlight sends you after the queen.",al={"who gives this quest","quest giver queen"},it="identity"},{q="What makes the queen more dangerous than regular cirrusflies?",a="Larger, more aggressive soldier drones guard the queen and defend the hive.",al={"queen danger","cirrusfly soldiers"},it="threat"},{q="What quest precedes this assignment?",a="The hunt follows Infestation Investigation, which first revealed how widely cirrusflies had spread through the grove.",al={"prerequisite quest","what comes before"},gp=true},{q="What role does Elatrell Featherlight serve in the area?",a="Elatrell Featherlight watches over wilderness security on Zephras Isle, tracks threats in the region, and teaches new adventurers woodland tracking and ranger duties.",al={"featherlight role","who is featherlight"},it="identity"},{q="What is the Cirrusfly Queen?",a="The Cirrusfly Queen is the matriarch at the heart of the infestation spreading through Thendal Grove. Lurking deep in the grove near the main hive, she directs the swarm and relies on aggressive soldier flies to guard her. Slaying the common workers will never halt the proliferation of these insects—only cutting down the queen will break the hive's hold on the forest.",al={"who is cirrusfly queen","what is the cirrusfly queen","cirrusfly queen target"},it="target",add="4d5b02bf"}},ang={["class:Hunter"]="As a hunter, tracking a hive queen and outmaneuvering her guards gives you an early trial in tracking and culling beasts. The local rangers’ praise is at stake.",["race:Skyborne"]="As a Skyborne, clearing invasive swarms from Thendal Grove helps protect Zephras Isle’s natural balance and keep its routes safe for travel."},kw={"cirrusfly","elatrell featherlight","hive","queen","soldier","thendal grove","zephras"},rel={"quest:92462","zone:zephras"},m={start="Elatrell Featherlight",level="3",id=92463},src={"The Cirrusfly Queen"},fv=true}
E["quest:92464"] = {t="quest",n="Elemental Unrest",z="zephras",s="Near the Thendal Standing Stones, lesser wind spirits have grown restless. Their sentient elemental benefactors have departed Zephras Isle, and Rorian the Dayseeker sends you into Thendal Grove to find his apprentice, Yala Windwatcher, and learn what troubles the breeze.",h="Near the Thendal Standing Stones, lesser wind spirits have grown restless.",sec={{t="A Change in the Wind",b="For generations, powerful wind spirits lived beside the people of Zephras. They were sentient, and they guided and protected the islanders. Now those elemental benefactors have departed, leaving Zephras in lasting imbalance. Without them to tend the air, simple sprites reflect the volatile feelings and forces that linger across the land.",sp=0},{t="The Thendal Standing Stones",b="Northeast of Rorian's post, the air near the ancient Thendal Standing Stones has turned hostile. The lesser wind spirits lack true self-awareness, so they act in reaction, not malice. Rorian sent his apprentice, Yala Windwatcher, to watch their erratic behavior from the grove's edge. She is to discover what unseen tension disturbs them.",sp=0}},faq={{q="Why are the wind sprites agitated?",a="Wind sprites grow turbulent when their surroundings fall out of balance. Unlike the island's former elemental benefactors, they lack true self-awareness and instinctively mirror nearby emotions, intentions, and magical forces.",al={"why are elementals mad","wind unrest cause","sprites angry"},it="conflict"},{q="Who are the elemental benefactors Rorian mentions?",a="The elemental benefactors were sentient, benevolent wind spirits who once lived alongside the people of Zephras. Since they departed, the island has suffered continuous unrest without their steadying influence.",al={"elemental benefactors","who left zephras","wind spirits zephras"},it="people"},{q="Where can I find Yala Windwatcher?",a="Yala Windwatcher is in Thendal Grove, northeast of Rorian's post, watching the agitated wind sprites near the Thendal Standing Stones.",al={"yala windwatcher location","where is yala","thendal grove apprentice"},it="place",gp=true},{q="Who is Rorian the Dayseeker?",a="Rorian the Dayseeker is an elder guide on Zephras Isle. He watches over the island's spiritual balance and studies disturbances among its local elementals.",al={"who is rorian","rorian dayseeker"},it="identity"},{q="What happens after finding Yala?",a="Speaking with Yala leads into an investigation of what causes the turbulence at the standing stones, beginning with Agitators.",al={"next quest","what comes after elemental unrest","yala follow up"},it="next_step",gp=true},{q="Are the wind sprites dangerous?",a="The wind sprites are simple, but their agitation makes them erratic and defensive. They react aggressively to intruders while the disturbance lasts.",al={"are sprites hostile","elemental danger"},it="threat"},{q="Why does Rorian the Dayseeker want this done?",a="Ever since the elemental benefactors departed, the region has slid from one crisis to another. Now, the wind manifestations around the Thendal Standing Stones are acting agitated. Because these lesser sprites simply mirror the turbulent emotions and intentions of nearby creatures, Rorian fears what might be unsettling them. He sent his apprentice Yala to observe the situation and needs you to consult her so they can determine the root of the disturbance.",al={"rorian motive","why send to yala","why rorian wants this"},it="motive",add="8058eaf6"}},ang={["class:Shaman"]="As a shaman, you can read the wind spirits' reflection of Zephras's emotional climate as a warning of deeper trouble in the land.",["race:Skyborne"]="As a Skyborne, you depend on Zephras Isle's skies. Since the elemental benefactors departed, those skies have grown unpredictable. Stay vigilant."},kw={"elemental unrest","rorian the dayseeker","thendal grove","thendal standing stones","wind sprites","yala windwatcher","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92465","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Yala Windwatcher",level="3",id=92464},src={"Elemental Unrest (quest)"},fv=true}
E["quest:92465"] = {t="quest",n="Agitators",z="zephras",s="On Zephras Isle, unrest in Thendal Grove draws Yala Windwatcher's concern. The Al'Aketh cult has stirred peaceful wind sprites into hostile elementals, and its converts now threaten the grove.",h="On Zephras Isle, unrest in Thendal Grove draws Yala Windwatcher's concern.",sec={{t="Disturbing the Grove",b="Cultists of Al'Aketh have pushed into Thendal Grove and stirred the wind spirits who dwell there. Once peaceful, the sprites now rage as roiling winds, threatening anyone who passes through.",sp=0},{t="A Painful Necessity",b="Yala Windwatcher asks you to subdue the enraged elementals and the Al'Aketh converts behind the unrest. Quieting the wind creatures may restore a fragile calm to the grove.\n\nYala grieves at the thought of shen'dorei blood shed among her own people. Yet while the cult remains, she sees little choice.",sp=0}},faq={{q="Who gives the quest Agitators?",a="Yala Windwatcher asks you for help near Thendal Grove on Zephras Isle.",al={"quest giver","who starts agitators","yala windwatcher"},it="identity"},{q="What is the Al'Aketh cult doing in Thendal Grove?",a="The Al'Aketh cult has moved into Thendal Grove and stirred its native wind spirits into a violent frenzy.",al={"what are cultists doing","why are alaketh here","alaketh convert purpose"},it="threat"},{q="What are the Roiling Winds?",a="Roiling Winds are native wind sprites of Zephras Isle, stirred by Al'Aketh cultists into aggressive elemental whirlwinds.",al={"roiling winds","wind spirits","wind elementals in thendal grove"}},{q="Why is Yala Windwatcher saddened by killing the converts?",a="Yala grieves at shedding shen'dorei blood because the converts are her own people, led astray by dangerous cult teachings.",al={"why does yala regret killing","shedding shendorei blood","yala completion quote"}},{q="What quest follows Agitators?",a="After you finish Yala Windwatcher's work, you are directed to continue your duties with Return to Rorian.",al={"what quest is next","agitators follow up","where do i go after agitators"},it="next_step"},{q="Where does this conflict take place?",a="The conflict centers on Thendal Grove, on Zephras Isle.",al={"agitators location","thendal grove zone","where is thendal grove"},it="place"},{q="Why does Yala Windwatcher want you to deal with the Al'Aketh cult?",a="Yala Windwatcher sees the Al'Aketh cult as a blight threatening the balance of the island. Their rituals have agitated the peaceful native wind sprites into violent Roiling Winds, endangering anyone who walks near Thendal Grove. To protect the land and prevent innocent lives from being lost, she must act quickly to disperse the frenzied elementals and drive the cult out.",al={"yala windwatcher motive","why fight cultists yala","why kill roiling winds"},it="motive",add="ae9ef6e2"},{q="Who are you sent to kill in Thendal Grove?",a="You are tasked with slaying Al'Aketh Converts and destroying the Roiling Winds. The converts are shen'dorei who have joined the Al'Aketh cult and established a foothold in Thendal Grove, meddling with the local elements. Their disruptive presence has agitated the once-peaceful local wind sprites, corrupting them into violent gusts of living air that assault anyone passing through.",al={"agitators targets","who do i kill in thendal grove","who are the targets agitators"},it="target",add="5a804844"}},ang={["class:Shaman"]="As a shaman, you see cultists drive natural wind sprites into a violent frenzy. The upheaval in elemental balance calls for intervention.",["class:Druid"]="As a druid, you see rogue cultists disturb Thendal Grove's natural harmony. The grove's native spirits urgently need defense."},kw={"agitators","al'aketh","al'aketh convert","roiling winds","shen'dorei","thendal grove","yala windwatcher","zephras isle"},rel={"zone:zephras","quest:92469"},m={start="Yala Windwatcher",level="3",id=92465},src={"Agitators"},fv=true}
E["quest:92466"] = {t="quest",n="Call of Earth",z="zephras",s="Initiates gather what their instructor asks of them in Call of Earth. Their effort shows whether they are ready to continue their training.",h="Initiates gather what their instructor asks of them in Call of Earth.",sec={{t="A Test of Resolve",b="An initiate faces a test of resolve when the instructor asks for particular materials. The gathering tests patience and endurance. By meeting the earth’s demands, the student shows the strength needed to commune with its enduring power.",sp=0},{t="The Next Step",b="When the initiate returns with the requested offerings, the instructor sees their grit. The student has held firm through the trial and is ready for the next step in spiritual training.",sp=0}},faq={{q="What is the Call of Earth?",a="Call of Earth asks spiritual initiates to gather requested items and prove their perseverance before advancing in training.",al={"what is call of earth","call of earth quest"}},{q="What does finishing this trial demonstrate?",a="Finishing the trial shows your grit and determination to your mentor. It proves your focus is strong enough for greater spiritual responsibilities.",al={"what did i prove","grit and determination"}},{q="What happens after completing the Call of Earth?",a="After Call of Earth, your instructor considers you ready for the next step toward communion with the elements.",al={"whats next","next quest"}},{q="Why must an initiate commune with earth?",a="An initiate proves endurance before communing with earth spirits, whose nature reflects stability and strength.",al={"why earth","earth spirits meaning"}},{q="Who oversees the Call of Earth?",a="A spiritual teacher or shaman mentor guides initiates through the trial and judges their discipline and readiness to bond with the spirits.",al={"who gives this quest","call of earth trainer"}},{q="Who is eligible to undertake this trial?",a="Call of Earth tests those learning to attune themselves to the elements.",al={"can anyone do call of earth","is call of earth for shamans"}}},ang={["class:Shaman"]="As a shaman, you prove your resolve before gaining deeper insight into communion with the spirits of stone and soil.",["faction:Horde"]="Among the Horde, you encounter shamanistic trials such as Call of Earth as a foundational rite for spiritual practitioners."},kw={"call of earth","determination","earth","elements","shaman","spirits","trial"},rel={"quest:92472"},m={faction="Horde",cl={"SHAMAN"},id=92466},src={"In-game quest text: Call of Earth"},fv=true}
E["quest:92467"] = {t="quest",n="Call of Earth",z="zephras",s="At the Rise of Spirits, you drink an Earth Sapta and meet an elemental guide. The earth's strength may help you seek the winds again.",h="At the Rise of Spirits, you drink an Earth Sapta and meet an elemental guide.",sec={{t="The Nature of the Sapta",b="Shamans drink saptas to open their sight to the elemental world. Each brew attunes a mortal spirit to one realm and reveals spirits usually hidden from view. Only those with enough resolve can bear their power. Select practitioners guard the knowledge of these brews.",sp=0},{t="The Rise of Spirits",b="You travel northeast through a pass to the Rise of Spirits, where initiates commune with the earth. Saptas are drunk only at sacred sites. On consecrated ground, the draught lets you pierce the veil and see what the spirits choose to reveal.",sp=0},{t="Strength of the Earth",b="After you drink the Earth Sapta, an elemental guide greets you as a child of the four winds. You seek to learn why they have departed. The earth spirit cannot explain the wind spirits' motives, but teaches you strength and steadfast resolve.\n\nEven high above, amid an endless sea of clouds, you must first anchor yourself to the earth. Only then can you speak with the winds again.",sp=1}},faq={{q="What is an Earth Sapta?",a="An Earth Sapta is a magical brew that attunes your spirit to the element of earth. With enough resolve, you can see elemental spirits hidden from ordinary sight.",al={"what is earth sapta","sapta explanation","what does sapta do"}},{q="Where must the Earth Sapta be consumed?",a="Drink the Earth Sapta at the Rise of Spirits, northeast through a pass. Saptas are consumed only on sacred ground.",al={"where to drink earth sapta","rise of spirits location","where is rise of spirits"}},{q="Why must saptas only be drunk in sacred places?",a="Saptas are potent brews that join mortal spirits with the elements. Shamanic tradition requires drinking them at sacred sites to commune with the spirits.",al={"why drink sapta at sacred place","can i drink sapta anywhere"}},{q="Why does the spirit address the seeker as a 'child of the four winds'?",a="The earth spirit greets you as a child of the four winds because you seek to learn why the winds have departed.",al={"who is child of the four winds","why child of four winds"}},{q="Why have the spirits of the winds left?",a="Even the earth spirit at the Rise of Spirits does not know why the wind spirits have grown distant or where they have gone.",al={"why did the winds leave","where did winds go"}},{q="How does communing with the earth help someone reconnect with the winds?",a="The earth teaches strength and resolve. Even amid an endless sea of clouds, you remain tethered to the earth. Learning its steadiness is the first step toward speaking with the four winds again.",al={"why earth first","how does earth help with winds"}}},ang={["class:Shaman"]="As a shaman, you use saptas to attune your spirit to an element and commune with its spirits.",["race:Skyborne"]="As a Skyborne, you may be adrift high in an endless sea of clouds and estranged from the four winds. The earth gives you a steady foundation for understanding."},kw={"call of earth","earth sapta","elements","four winds","rise of spirits","shaman","spirits"},rel={"quest:1462"},m={faction="Horde",cl={"SHAMAN"},id=92467},src={"In-game quest text: Call of Earth"},fv=true}
E["quest:92468"] = {t="quest",n="Call of Earth",z="zephras",s="An earth spirit sends you to Windshaper Boros in Thendal Grove with a shard of Rough Quartz. There, the shard becomes the heart of your first Earth Totem and begins your study of the elemental forces.",h="An earth spirit sends you to Windshaper Boros in Thendal Grove with a shard of Rough Quartz.",sec={{t="The Earth's Gift",b="An earth spirit gives you a shard of Rough Quartz as proof of your communion. It sends you to Windshaper Boros in Thendal Grove with the shard. Even the smallest fragment can endure. The spirits grant favor and respect to those who show patience, resilience, and wisdom.",sp=0},{t="The Four Elements and the Totem",b="Windshaper Boros sets the Rough Quartz at the heart of your Earth Totem. He reminds you that the elemental path has four parts. You may long to hear and sing the songs of the wind. Yet mastery begins with understanding all four forces, starting with the unyielding ground beneath your feet.",sp=0}},faq={{q="Who is Windshaper Boros?",a="Windshaper Boros, also called Boro, lives in Thendal Grove. An elder practitioner and crafter, he guides initiates in understanding the elemental spirits and shapes their focal totems from elemental gifts.",al={"who is boro","windshaper boros location","where is thendal grove"}},{q="What is the purpose of the Rough Quartz?",a="An earth spirit gives you the Rough Quartz as proof of your meeting and communion. Windshaper Boros uses it as the foundation and heart of your Earth Totem.",al={"what is rough quartz","shard of earth","quartz use"}},{q="Why is an Earth Totem necessary?",a="An Earth Totem gives you a personal focus for communing with earth spirits and channeling earth-based spells. It marks you as an initiate and anchors you to the world's elemental foundations.",al={"what does earth totem do","totem purpose","why need totem"}},{q="Why must one commune with earth before speaking with the winds?",a="The winds are only one part of the world's elemental balance. Before seeking their songs, you study all four elements, beginning with the earth's stability, patience, and strength.",al={"why start with earth","seeking the winds","all four elements"}},{q="Where is Thendal Grove located?",a="Thendal Grove is the sanctuary where Windshaper Boros tends to elemental matters and instructs novices beginning their shamanic journey.",al={"where is thendal grove","thendal grove zone"}},{q="What wisdom does the earth spirit impart?",a="The earth spirit teaches that even the smallest stone can endure after greater things crumble. It asks for patience, inner strength, and the pursuit of wisdom in exchange for mutual respect and harmony.",al={"what elements ask","earth philosophy"}}},ang={["class:Shaman"]="As a shaman, receiving your first totem begins your communion with the elemental forces. It gives you a physical focus for earth-aligned spells and rites.",["race:Skyborne"]="As a Skyborne, you begin your return to the winds by mastering the earth and grounding yourself in its solid foundations."},kw={"call of earth","earth totem","elements","rough quartz","shaman","thendal grove","windshaper boro","windshaper boros"},rel={"item:rough-quartz"},m={faction="Horde",cl={"SHAMAN"},id=92468},src={"In-game quest text: Call of Earth"},fv=true}
E["quest:92469"] = {t="quest",n="Return to Rorian",z="zephras",s="Yala Windwatcher sends you to Thendal Grove with urgent news from the field. After you help drive back the agitators on Zephras Isle, she reports that the Al'Aketh have disturbed the local wind spirits.",h="Yala Windwatcher sends you to Thendal Grove with urgent news from the field.",sec={{t="A Dire Report",b="Yala Windwatcher remains on Zephras Isle to face the hostiles still there. She sends you to Thendal Grove with word that the Al'Aketh are no longer working only in the shadows.",sp=0},{t="Escalation at the Standing Stones",b="Rorian the Dayseeker says Thendal Grove's leaders have watched the Al'Aketh from a distance for some time. Now the cultists have stirred native wind spirits near the standing stones. That marks a troubling escalation, and the leaders can no longer watch from afar.",sp=1}},faq={{q="Who sends you to speak with Rorian?",a="After you help suppress the hostile agitators threatening the area, Yala Windwatcher sends you to report to Rorian.",al={"quest giver","who starts return to rorian","yala windwatcher"}},{q="Where is Rorian the Dayseeker located?",a="Rorian the Dayseeker is in Thendal Grove, where the grove's leaders oversee affairs on Zephras Isle.",al={"where is rorian","rorian location","thendal grove rorian"},it="place",gp=true},{q="Who are the Al'Aketh?",a="The Al'Aketh are a cult on Zephras Isle. The grove's leaders watched them quietly from afar, but their recent agitation of wind spirits near the standing stones has made them an active threat.",al={"what is the cult","who are al'aketh","al'aketh cult"},it="threat"},{q="Why was Rorian not surprised by the news?",a="Rorian and the grove's leaders already knew of the cult's movements across the island. Until now, they watched quietly instead of confronting the cult directly.",al={"did rorian know","rorian reaction","why unsurprising"},it="conflict"},{q="What happens after reporting back to Rorian?",a="After hearing your report and thanking you for aiding Thendal Grove, Rorian sends you to Aetheen of the Gales, a member of the Council of Elders who has been watching you.",al={"next quest","what follows return to rorian","after return to rorian"},sp=1,it="next_step"},{q="Why did Yala stay behind?",a="Yala Windwatcher stays at the conflict site to deal with any stragglers while sending you ahead with the urgent news.",al={"why yala stays","where did yala go","yala windwatcher role"},it="why_me"},{q="Why does Yala Windwatcher send you to Rorian?",a="Yala needs the leadership in Thendal Grove alerted immediately to the confirmed presence of the Al'Aketh cult. While she remains behind to finish dealing with stragglers in the field, Rorian the Dayseeker must be warned of the cult's escalations and their agitation of local spirits so the grove can coordinate a response.",al={"why report to rorian","yala windwatcher motive","why does yala want rorian informed"},it="motive",add="aa0b8ee2"}},ang={["class:Shaman"]="As a Shaman, you know the Al'Aketh's deliberate agitation of wind spirits threatens elemental balance.",["class:Druid"]="As a Druid, you share the duty to defend Thendal Grove and preserve peace in Zephras Isle's sacred grounds."},kw={"al'aketh","cult","rorian","standing stones","thendal grove","wind spirits","yala windwatcher","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92465","zone:zephras"},m={start="Yala Windwatcher",["end"]="Rorian the Dayseeker",level="4",id=92469},src={"Return to Rorian"},fv=true}
E["quest:92470"] = {t="quest",n="Foul Matriarch",z="zephras",s="In the caves south of Thendal Village, Aetheen of the Gales tests new initiates against the ursera. They must thin the packs and slay their den mother, Urs'anah, to prove they can face greater perils across Zephras Isle.",h="In the caves south of Thendal Village, Aetheen of the Gales tests new initiates against the ursera.",sec={{t="A Test of Resolve",b="Around Thendal Village, Aetheen of the Gales watches newcomers find their footing. When an initiate shows early skill, Aetheen sends them into the southern caves for a dangerous rite of passage. There, they thin the local ursera packs and face the broodmother who threatens the village's edge.",sp=0},{t="The Threat of Urs'anah",b="Local rangers know the ursera are fierce, but Urs'anah is the greatest threat to the haven. Deep in Thendal Cave, the formidable matriarch directs her scavengers and guards her lair. Her severed head proves an adventurer can face ferocious beasts and is ready to venture beyond the starting grove.",sp=0}},faq={{q="Who assigns the task to kill Urs'anah?",a="Aetheen of the Gales assigns the trial from Thendal Village. Aetheen watches promising newcomers noticed by local figures like Rorian, then tests their mettle with a dangerous hunt.",al={"who gives foul matriarch","foul matriarch quest giver","who is aetheen of the gales"},gp=true},{q="Where can Urs'anah and the ursera scavengers be found?",a="Urs'anah and the ursera scavengers dwell in caves south and southwest of Thendal Village, in the hills within Thendal Grove. The matriarch's den lies deep in the cavern.",al={"urs'anah location","where is ursanah","ursera cave zephras","thendal cave location"},gp=true},{q="What is an ursera?",a="Ursera are aggressive, bear-like predators native to the wilder crags of Zephras Isle. Their scavenging packs can make dens dangerously close to settlements like Thendal Village.",al={"what is an ursera","ursera lore","are ursera bears"}},{q="What does completing this hunt signify for an adventurer?",a="Slaying Urs'anah marks a rite of passage. By overcoming cultist interlopers and the grove's most dangerous wildlife, the hunter proves they are ready to leave Thendal Village's sanctuary and take on wider responsibilities across Zephras Isle.",al={"why kill ursanah","importance of foul matriarch"}},{q="Why does Aetheen of the Gales send you against the matriarch?",a="Aetheen of the Gales has been watching your progress and demands a test of your resolve. She needs to know if you possess the strength and fortitude to survive the far greater perils awaiting Zephras Isle. Felling the dangerous matriarch proves you are capable of stepping beyond the safety of Thendal Village and serving the island in deeper, more treacherous trials.",al={"why does aetheen want urs'anah dead","aetheen motive","why kill urs'anah"},it="motive",add="03aee340"},{q="What is the Head of Urs'anah used for?",a="The head serves as undeniable physical proof of the matriarch's demise. Urs'anah is a notorious den mother known to the local rangers, and Aetheen will accept nothing less than her severed head to verify that the dangerous beast has truly been put down.",al={"head of urs'anah use","why keep urs'anah head","head of ursanah purpose"},it="item",add="30b9798a"},{q="Who is Urs'anah?",a="Urs'anah is the fierce matriarch and den mother of the local ursera, dwelling within the caves south of Thendal Village. Known and feared by the island's rangers, she commands the scavenger pack, making her the primary threat among the grove's predatory beasts.",al={"who is ursanah","what is urs'anah","urs'anah lore"},it="target",add="a1adff34"}},ang={["race:Skyborne"]="As a Skyborne initiate, mastering ground predators like Urs'anah shows you can fend for yourself on land. You are ready to venture beyond your secluded beginnings.",["class:Hunter"]="As a Hunter, tracking a fierce matriarch in her cave tests your knowledge of beasts and your resolve."},kw={"aetheen of the gales","foul matriarch","thendal cave","thendal grove","thendal village","urs'anah","ursera","zephras isle"},rel={"quest:92471","quest:92473","zone:zephras"},m={start="Aetheen of the Gales",level="5",id=92470,ri={"Head of Urs'anah"}},src={"Foul Matriarch"},fv=true}
E["quest:92471"] = {t="quest",n="Aetheen of the Gales",z="zephras",s="On Zephras Isle, young adventurers who pass their first trials go to meet Aetheen of the Gales at Thendal Grove. There, the next generation faces her judgment.",h="On Zephras Isle, young adventurers who pass their first trials go to meet Aetheen of the Gales at Thendal...",sec={{t="A Measure of Potential",b="Young novices on Zephras Isle take on early duties that test their grit and spirit. The island's mentors watch for those ready to help defend their home. Rorian the Dayseeker notices youths prepared for greater responsibility.",sp=0},{t="The Wind-Reader of Thendal Grove",b="At Thendal Grove, Aetheen of the Gales reads the currents of the air. She belongs to the Council of Elders, which governs Zephras Isle, and assesses young shen'dorei as they come of age. Reporting to her takes you beyond minor duties along the island's perimeter and toward threats facing the community.",sp=0}},faq={{q="Who is Aetheen of the Gales?",a="Aetheen of the Gales leads on Zephras Isle and serves on its Council of Elders. At Thendal Grove, she reads the winds and assesses young shen'dorei coming of age, judging whether they are ready to defend their home.",al={"who is aetheen","aetheen of the gales role","aetheen zephras"},it="identity"},{q="Why does Rorian send players to meet Aetheen?",a="After their early duties, Rorian the Dayseeker sends capable and resilient novices to Aetheen. She judges their skills and directs them toward greater challenges facing the island.",al={"why meet aetheen","rorian sends to aetheen","purpose of this quest"},it="motive"},{q="Where can Aetheen of the Gales be found?",a="Aetheen of the Gales can be found in Thendal Grove on Zephras Isle. There she reads the winds and oversees coming-of-age trials for local youths.",al={"aetheen location","where is aetheen","thendal grove aetheen"},it="place",gp=true},{q="What is the Council of Elders?",a="The Council of Elders governs the shen'dorei on Zephras Isle. Aetheen and the other council leaders guide their community's survival, leadership, and readiness.",al={"council of elders zephras","who rules zephras"},it="in_charge"},{q="What happens after reporting to Aetheen?",a="Once Aetheen judges a young adventurer ready to serve Zephras Isle, she assigns serious work against dangers in the local wilderness, including aggressive wildlife and foul matriarchs.",al={"next quest after aetheen","what does aetheen want"},it="next_step"},{q="What does 'coming of age' mean for shen'dorei on Zephras Isle?",a="For young shen'dorei on Zephras Isle, coming of age means proving themselves through physical and magical trials. They show an island elder like Aetheen that they can serve before taking on that duty.",al={"shen'dorei coming of age","zephras coming of age"},it="people"},{q="Why does Rorian need you specifically to go speak with Aetheen?",a="Your early tasks across the isle were quietly treated as trials to gauge your mettle. Zephras faces serious challenges, and its leaders need capable, spirited young shen'dorei who are coming of age to step forward and aid their people. Having proven your competence, Rorian has singled you out as someone ready for direct assessment by Elder Aetheen.",al={"why me aetheen of the gales","why does rorian pick me","why send me to aetheen"},it="why_me",add="d6e78b3c"}},kw={"aetheen of the gales","council of elders","rorian the dayseeker","shen'dorei","thendal grove","zephras isle"},rel={"quest:92469","npc:rorian-the-dayseeker","zone:zephras","quest:92460"},m={start="Rorian the Dayseeker",["end"]="Aetheen of the Gales",level="4",id=92471},src={"Aetheen of the Gales (quest)"},fv=true}
E["quest:92472"] = {t="quest",n="The Next Step",z="zephras",s="Elder Aetheen turns south after the beasts near Thendal Village are dealt with. The Al'Aketh Cult's zealots threaten Shen'dar Village.",h="Elder Aetheen turns south after the beasts near Thendal Village are dealt with.",sec={{t="Leaving Thendal Village",b="Elder Aetheen of the Gales sees danger growing across Zephras Isle. The predators and matriarchs of the northern wilderness have been dealt with, but that was only the lesser trouble. Outlying settlements still need defenders.",sp=0},{t="The Looming Shadow of the Cult",b="The Al'Aketh Cult is the chief danger in southern Zephras. Its ruthless zealots worship Al'Akir the Windlord, ruler of Skywall in the elemental realm. Their growing power threatens Shen'dar Village. Aetheen sends travelers south along the road, past ambushers in the highlands, to aid Constable Aonda's local guard.",sp=0}},faq={{q="Where does this journey lead?",a="The road runs south from Thendal Village through the Shen'dar Highlands to Shen'dar Village. Constable Aonda oversees the village's defense.",al={"where do i go","next hub","destination"},it="next_step"},{q="Who is Constable Aonda?",a="Constable Aonda holds civic and military authority in Shen'dar Village. The constable keeps order and protects the village from growing cultist threats.",al={"constable aonda","who is aonda"},it="identity"},{q="What is the Al'Aketh Cult?",a="The Al'Aketh are ruthless zealots on Zephras Isle who worship Al'Akir the Windlord, ruler of Skywall. Their growing power threatens the island's settlements.",al={"who are the al'aketh","al'aketh cult lore","cultists"},it="threat"},{q="Who is Al'Akir?",a="Al'Akir the Windlord rules the skies and commands Skywall. Air elementals revere him, and the Al'Aketh Cult worships him fanatically.",al={"who is alakir","windlord","skywall ruler"},it="power"},{q="Why does Elder Aetheen send travelers away from Thendal?",a="With the immediate threats around Thendal handled, Aetheen sends proven defenders to Shen'dar Village. The Al'Aketh Cult's advance endangers the island far more than the troubles around Thendal.",al={"why leave thendal","aetheen's goal"},it="motive"},{q="What hazards are along the road to Shen'dar Village?",a="The trail south crosses the Shen'dar Highlands. Al'Aketh Ambushers and rogue cult thugs harass travelers moving between the island's settlements.",al={"road hazards","traveling south","highland danger"},it="danger"}},ang={["race:Skyborne"]="For the Skyborne, facing the Al'Aketh means fighting elemental fanaticism that threatens settlements across their home on Zephras Isle.",["class:Shaman"]="As a shaman, you know the danger of mortals blindly worshiping elemental lords like Al'Akir. His volatile nature often demands servitude rather than balance."},kw={"aetheen of the gales","al'aketh cult","al'akir","constable aonda","shen'dar village","skywall","thendal village","zephras isle"},rel={"quest:92471","quest:92470","zone:zephras","quest:92544","quest:96627","topic:skywall"},m={start="Aetheen of the Gales",["end"]="Constable Aonda",level="5",id=92472},src={"The Next Step (Skyborne)"},fv=true}
E["quest:92473"] = {t="quest",n="Aggressive Encroachment",z="zephras",s="At the village, starving ursera now threaten the settlement. Valreaa Valewind calls for a cull after one beast nearly attacked a child at the elder tree.",h="At the village, starving ursera now threaten the settlement.",sec={{t="Desperate Predators",b="Ursera from dens southwest of the village have become dangerous to its people. A hungry adolescent reached the base of the central elder tree and nearly mauled a child at play. The settlement's rangers killed the beast before anyone was hurt.",sp=0},{t="Culling the Grove",b="The rangers believe hunger is driving ursera toward settled ground. They have ordered a cull of the scrawniest beasts prowling outside their dens in Thendal Grove. The Rangers of the Grove hope this will stop further incursions while they seek the cause of the wildlife's distress.",sp=0}},faq={{q="Who offers Aggressive Encroachment?",a="Valreaa Valewind, a leader among the rangers, offers the work. She watches over the grove and protects the nearby settlement from predatory beasts.",al={"who gives aggressive encroachment","quest giver","valreaa valewind quest"},gp=true},{q="Why are the ursera wandering so close to the village?",a="The ursera are starving and desperate. Hunger drives them far beyond their usual hunting grounds and into the settlement.",al={"why ursera attack","ursera aggression","why are ursera mad"},it="conflict"},{q="Where can the scrawny ursera be found?",a="Scrawny ursera prowl Thendal Grove southwest of the village, outside the den entrances rather than deep in the cave.",al={"where are scrawny ursera","ursera location","thendal grove bears"},it="target",gp=true},{q="What near-tragedy prompted this cull?",a="An adolescent ursera reached the elder tree in the middle of the village and tried to attack a young boy at play. Rangers killed the beast just in time to save him.",al={"ursera attack boy","what happened in the village","boy near elder tree"},it="motive"},{q="Why are the ursera behaving so erratically?",a="The ursera have grown unusually aggressive, but the rangers do not know what caused their food shortage or change in behavior.",al={"what changed with ursera","why ursera starving"},it="threat"},{q="What proof does Valreaa Valewind require?",a="Valreaa Valewind asks for six Scrawny Ursera Claws from the malnourished beasts prowling the grove, proof that the dangerous predators have been dealt with.",al={"what do I collect","aggressive encroachment objective"},it="item"}},ang={["class:Hunter"]="As a hunter, you know starving predators may abandon their natural wariness of settlements when famine drives them.",["class:Druid"]="As a druid, you can see the grove's balance shifting. The ursera's sudden aggression and malnutrition point to an unseen disturbance in the local ecosystem."},kw={"claws","elder tree","encroachment","scrawny ursera","thendal grove","ursera","valreaa valewind"},rel={"zone:zephras"},m={start="Valreaa Valewind",level="4",id=92473,ri={"Scrawny Ursera Claw"}},src={"Aggressive Encroachment"},fv=true}
E["quest:92474"] = {t="quest",n="Falling With Style",z="zephras",s="At Thendal Village, Myriaal Mistwake sends young Skyborne from a watchtower to test their falling skill. They glide down to Rorian the Dayseeker below.",h="At Thendal Village, Myriaal Mistwake sends young Skyborne from a watchtower to test their falling skill.",sec={{t="A Leap from the Tower",b="High above Thendal Village on Zephras Isle, Myriaal Mistwake invites young Skyborne to test their heritage with a daring leap. She urges newcomers to step from the watchtower ledge and trust their gift for slowing a fall. The practice is playful, yet it prepares them to walk on air when danger comes beyond the grove.",sp=0},{t="A Difference in Temperament",b="Myriaal delights in sudden descents that startle onlookers, while Rorian the Dayseeker favors caution. As novices glide down to land before him, he warns that careless use of their magic may leave travelers helpless in danger. Still, he accepts that controlled practice within the village has its place.",sp=0}},faq={{q="What is the purpose of this quest?",a="The leap lets novice Skyborne practice controlling a slow descent from a height with their natural magic.",al={"what does this quest do","falling with style purpose","why do this quest"},it="purpose"},{q="Who gives the quest and where?",a="Myriaal Mistwake gives it from the wooden watchtower above Thendal Village on Zephras Isle.",al={"quest giver","where to start falling with style","who gives falling with style"},it="origin",gp=true},{q="Who do you land in front of?",a="You land near Rorian the Dayseeker, whom Myriaal hopes to startle with the leap.",al={"who to land near","who is rorian","falling with style turn in"},it="target"},{q="Why is Rorian upset by the jump?",a="Rorian believes Skyborne should use their natural magic with discipline, not waste it on practical jokes that startle people.",al={"why is rorian mad","rorian reaction","why does rorian scold you"},it="conflict"},{q="What ability is being practiced?",a="You practice Walk on Air, the skyborne gift that slows a fall and prevents injury from landing.",al={"what ability is used","walk on air quest","skyborne racial ability"},it="power",gp=true},{q="Where does this take place?",a="The practice takes place in Thendal Village on Zephras Isle, the Skyborne's ancestral starting grounds.",al={"quest location","where is thendal village","what zone is this"},it="place",gp=true},{q="Why does Myriaal Mistwake have you jump from the watchtower?",a="Myriaal Mistwake treats the leap as a playful challenge to help you practice your innate ability to walk on air, but she also has a mischievous motive: she wants to startle Rorian the Dayseeker and get a good laugh out of seeing him worked up.",al={"why does myriaal want this","myriaal mistwake motive","why jump from tower"},it="motive",add="fb92945d"}},ang={["race:Skyborne"]="As a Skyborne, you learn to slow your fall and hear the debate over how carefully to use your natural wind-walking magic."},kw={"falling with style","myriaal mistwake","rorian the dayseeker","slow fall","thendal village","walk on air","watchtower","zephras isle"},rel={"npc:rorian-the-dayseeker","topic:skyborne","zone:zephras"},m={start="Myriaal Mistwake",["end"]="Rorian the Dayseeker",level="2",id=92474},src={"Falling With Style (Skyborne)"},fv=true}
E["quest:92481"] = {t="quest",n="A Student of the Arcane",z="zephras",s="On Zephras Isle, Rorian the Dayseeker calls novice spellcasters to A Student of the Arcane. After newcomers prove their mettle, they review a Glowing Recall Crystal and report to Dorii Brightwhisper, the local mentor.",h="On Zephras Isle, Rorian the Dayseeker calls novice spellcasters to A Student of the Arcane.",sec={{t="A Message in Crystal",b="After helping with the troublesome vuldren near Thendal Grove, fledgling mages receive a curious artifact: a Glowing Recall Crystal. Dorii Brightwhisper, the island’s arcane instructor, left it behind. Its recorded message tests an initiate’s aptitude and welcomes them into deeper study of magic.",sp=0},{t="Rediscovering the Arcane",b="Dorii Brightwhisper says arcane mastery has slowly faded among their people. For millennia, they lived secluded high in the clouds. So Dorii sees each new practitioner as a pioneer who can recover lost knowledge and restore their people’s once-mighty magical heritage.",sp=0}},faq={{q="What is the Glowing Recall Crystal?",a="The Glowing Recall Crystal is a small magical focus that Dorii Brightwhisper entrusted to Rorian the Dayseeker. It holds an inscribed message introducing young apprentices to the basics of arcane communication.",al={"recall crystal","crystal message","what does the crystal do"},it="item"},{q="Who is Dorii Brightwhisper?",a="Dorii Brightwhisper is the resident mage trainer in the structure behind Rorian the Dayseeker in Thendal Grove on Zephras Isle. Dorii guides young mages seeking to reclaim their people’s ancient arcane traditions.",al={"who is dorii","mage trainer zephras","dorii location"},it="identity"},{q="Why has arcane magic waned among the people of Zephras?",a="As Dorii explains, arcane magic gradually declined over the thousands of years their people lived secluded high in the clouds. Dorii and other instructors train new novices to search for and recover what was lost.",al={"why did magic fade","skyborne arcane lore","lost arcane magic"},it="history"},{q="Who gives this quest?",a="Rorian the Dayseeker offers this in thendal grove on zephras isle after an aspiring mage completes Harmony in Balance.",al={"quest giver","who starts a student of the arcane","rorian quest"},gp=true},{q="Where can I find Dorii Brightwhisper?",a="Dorii Brightwhisper lives in the structure directly behind Rorian the Dayseeker within Thendal Grove.",al={"dorii brightwhisper location","where is the mage trainer","find dorii"},gp=true},{q="What prerequisite must be completed before starting this quest?",a="First, complete Harmony in Balance, which involves handling the local vuldren problem for Rorian the Dayseeker.",al={"prereq","prerequisites","what quest comes before"},gp=true},{q="Why does Rorian the Dayseeker send you to Dorii?",a="Rorian is simply passing along an urgent communication meant for you. While you were handling the nearby vuldren threat, Dorii Brightwhisper left a recall crystal specifically inscribed for your attention. Rorian ensures you receive the crystal and guides you directly to the grove's mage trainer so your arcane potential is not left untapped.",al={"why does rorian send you","rorian the dayseeker motive","why talk to dorii brightwhisper"},it="motive",add="1ed09f17"},{q="Why does Dorii Brightwhisper want to train you specifically?",a="Arcane arts have waned among your kin over millennia spent secluded in the clouds. Having proven your competence against local threats, Dorii Brightwhisper sees in you the raw capability required to help reclaim that lost heritage. She seeks aspiring mages who can actively explore and master the arcane, rather than letting ancient knowledge fade into memory.",al={"why you a student of the arcane","why train me","why does dorii want me"},it="why_me",add="ab250928"}},ang={["class:Mage"]="As a Mage, your tutelage under Dorii Brightwhisper begins here. Your path in magic helps restore long-lost arcane secrets from the clouds.",["race:Skyborne"]="As a Skyborne, you know that millennia of isolation among the clouds caused arcane traditions to wane. Young apprentices are central to renewing your people’s heritage."},kw={"dorii brightwhisper","glowing recall crystal","mage quest","rorian the dayseeker","student of the arcane","thendal grove","vuldren","zephras isle"},rel={"quest:92461","npc:rorian-the-dayseeker","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Dorii Brightwhisper",level="2",faction="Alliance",cl={"MAGE"},id=92481},src={"A Student of the Arcane"},fv=true}
E["quest:92482"] = {t="quest",n="The Way of the Hunter",z="zephras",s="Young hunters in Thendal Grove begin training after driving back the local vuldren. Now Rorian the Dayseeker summons them to meet Tai'ree Farsight and begin formal tutelage.",h="Young hunters in Thendal Grove begin training after driving back the local vuldren.",sec={{t="A Summons to the Hunt",b="After thinning the disruptive vuldren on Thendal Grove's outskirts, young hunters return to find their practical skills have drawn attention. Rorian the Dayseeker gives them a scribbled summons from Tai'ree Farsight, the grove's resident hunter trainer. For novice rangers preparing to explore Zephras Isle, the meeting turns their work from defending the island to learning martial skills and survival.",sp=0},{t="The Tutelage of Tai'ree",b="Near the center of the village, Tai'ree Farsight welcomes promising pupils with stern realism. Thriving in untamed nature demands sharp senses and lightning reflexes. Her guidance comes from her long years of experience, giving island trackers a foundation for honing their marksmanship and survival skills.",sp=0}},faq={{q="Who offers this task?",a="After you help Rorian the Dayseeker with the local vuldren infestation in 'Harmony in Balance', he offers this training in Thendal Grove on Zephras Isle.",al={"who gives the way of the hunter","quest starter","rorian quest"},it="identity"},{q="Who is Tai'ree Farsight?",a="Tai'ree Farsight is the resident hunter trainer near the center of Thendal Grove. She oversees the training and discipline of aspiring marksmen and island trackers.",al={"where is tai'ree","hunter trainer thendal grove","tai'ree farsight location"},it="identity"},{q="What is the purpose of the Scribbled Note?",a="The Scribbled Note is a message Tai'ree Farsight leaves while you are away dealing with the vuldren. It directs you to seek her out in the village square to begin advanced training.",al={"scribbled note","what does the note say","hunter note"},it="item"},{q="Where does this quest take place?",a="This takes place entirely within Thendal Grove, an outpost settlement on Zephras Isle.",al={"quest zone","hunter quest location","where is thendal grove"},it="place",gp=true},{q="What prerequisite must be completed before this quest?",a="Before meeting Tai'ree, you must complete 'Harmony in Balance' for Rorian the Dayseeker. There, you prove your initial competence by dealing with the aggressive vuldren near the grove.",al={"prereq for the way of the hunter","how to unlock","previous quest"},gp=true},{q="What does Tai'ree Farsight teach new hunters?",a="Tai'ree Farsight acts as your class trainer. Speaking with her introduces the core philosophy of island tracking and opens access to foundational hunter abilities and combat techniques.",al={"what does tai'ree do","why talk to tai'ree"},it="purpose"},{q="Why does Rorian the Dayseeker send you to Tai'ree Farsight?",a="While you were out handling the vuldren threat, the village's hunter trainer, Tai'ree Farsight, specifically left a note asking to speak with you. Rorian is simply passing along the message and directing you to where she waits in Thendal Grove so you can begin refining your martial skills.",al={"why does rorian send you","rorian motive way of the hunter","why visit tairee farsight"},it="motive",add="bb563a7d"}},ang={["class:Hunter"]="As a hunter on Zephras Isle, you begin formal training under Tai'ree Farsight."},kw={"hunter trainer","rorian the dayseeker","scribbled note","tai'ree farsight","the way of the hunter","thendal grove","vuldren","zephras"},rel={"npc:rorian-the-dayseeker","quest:92461","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Tai'ree Farsight",level="2",cl={"HUNTER"},id=92482},src={"The Way of the Hunter"},fv=true}
E["quest:92483"] = {t="quest",n="At Home in the Shadows",z="zephras",s="Rorian sends you to meet Akeri Duskblade in Thendal Grove, where rogue training begins. The summons marks a change from village chores to stealth and combat.",h="Rorian sends you to meet Akeri Duskblade in Thendal Grove, where rogue training begins.",sec={{t="A Shady Invitation",b="Akeri Duskblade has noticed young rogues dealing with threats around Thendal Grove. The grove's rogue trainer avoids an open meeting in the settlement, so he sends a note through Rorian the Dayseeker. Though Akeri keeps his reasons close, Rorian sees that he knows the skills a rogue needs beyond the grove's sheltered bounds.",sp=0},{t="Lessons in the Watchtower",b="Akeri Duskblade waits in the Thendal Grove village watchtower. He judges each newcomer’s footing and awareness, then warns that careless steps beyond the grove can lead to an early grave. Passing his scrutiny begins formal training in stealth, precision, and survival on Zephras Isle.",sp=0}},faq={{q="Who gives the quest At Home in the Shadows?",a="Rorian the Dayseeker gives you Akeri's summons in Thendal Grove on Zephras Isle after you complete Harmony in Balance.",al={"who starts at home in the shadows","quest giver at home in the shadows","rorian quest"},gp=true},{q="Where can I find Akeri Duskblade?",a="Akeri Duskblade waits inside the village watchtower in Thendal Grove on Zephras Isle.",al={"akeri duskblade location","where is akeri duskblade","find akeri"},it="place",gp=true},{q="What is the Simple Note given during the quest?",a="Akeri Duskblade's Simple Note asks promising rogues to meet him. Read it before you speak with Akeri.",al={"simple note zephras","what is the note","read simple note"},it="item",gp=true},{q="Is this quest available to all classes?",a="No. The training is for rogues learning their trade in Thendal Grove.",al={"can non rogues do this quest","is at home in the shadows rogue only","class requirement"},gp=true},{q="What does Akeri Duskblade teach?",a="Akeri Duskblade teaches local rogues in Thendal Grove stealth, cunning, and bladecraft as they begin their journey across Zephras Isle.",al={"akeri duskblade role","who is akeri","rogue trainer thendal grove"},it="identity",gp=true},{q="What prerequisite quest must be completed first?",a="Complete Harmony in Balance for Rorian the Dayseeker first. Then he gives you Akeri's note.",al={"at home in the shadows prerequisite","previous quest","unlock at home in the shadows"},gp=true},{q="Why does Rorian the Dayseeker send you to Akeri Duskblade?",a="After proving your capability by handling the local vuldren threat, Rorian is simply passing along a summons. Akeri Duskblade, the grove's resident rogue trainer, specifically asked to see you and left a note for your attention. Rorian recognizes that a fledgling rogue needs proper tutelage from someone suited to the craft, playfully noting that you and the shady Duskblade will likely get along.",al={"rorian motives","why send to akeri","why talk to akeri duskblade"},it="motive",add="776f9cb3"},{q="Why does Rorian need you to go instead of dealing with Akeri himself?",a="Akeri Duskblade asked for you personally, not Rorian or the grove's guardians. You have chosen the path of a rogue, and Akeri is the local mentor responsible for training those who operate from the shadows. The summons is meant to test your awareness, sharpen your instincts, and prepare you to survive beyond the safety of Thendal Grove.",al={"why me akeri duskblade","why does akeri want to see me","why rogue trainer wants me"},it="why_me",add="4629917d"}},ang={["class:Rogue"]="As a rogue, you begin formal training on Zephras Isle when you meet Akeri Duskblade in the Thendal Grove watchtower."},kw={"akeri duskblade","at home in the shadows","rogue quest","rogue trainer","rorian the dayseeker","simple note","thendal grove","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92461","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Akeri Duskblade",level="2",cl={"ROGUE"},id=92483},src={"At Home in the Shadows"},fv=true}
E["quest:92484"] = {t="quest",n="Embracing the Elements",z="zephras",s="In Thendal Grove, Rorian the Dayseeker calls young shamans to begin their elemental training. Windshaper Boro’s message speaks of a silence between the people and the spirits of the winds.",h="In Thendal Grove, Rorian the Dayseeker calls young shamans to begin their elemental training.",sec={{t="A Summons to the Elements",b="Rorian the Dayseeker comes to you after you help with the vuldren around the village. Windshaper Boro left a humming recall crystal while you were away. Its message calls you to the center of the grove, where formal elemental instruction begins.",sp=0},{t="The Silent Winds",b="Windshaper Boro tells you the spirits of the four winds ended all communication years ago. They left behind the communion they once shared with the people. Now the shamans of Zephras study the natural world and train hard, hoping to bridge the silence and speak with the spirits again.",sp=0}},faq={{q="Who gives the quest Embracing the Elements?",a="After you help with the local vuldren problem, Rorian the Dayseeker sends you from Thendal Grove on Zephras Isle.",al={"embracing the elements quest giver","who starts embracing the elements"},gp=true},{q="Where is Windshaper Boro located?",a="Near the center of Thendal Grove on Zephras Isle, Windshaper Boro trains the settlement’s shamans.",al={"windshaper boro location","where is boro","find windshaper boro"},gp=true},{q="Why did the elemental spirits stop speaking to the people here?",a="Windshaper Boro says the spirits of the four winds stopped speaking and left the people years ago. The local shamans do not know why, but they study in hope of restoring that bond.",al={"why are the winds silent","spirits of the four winds silent","what happened to the wind spirits"},it="history"},{q="What is the Humming Recall Crystal?",a="Windshaper Boro left the humming recall crystal while you were away helping the settlement. Examining it signals that you are ready to begin elemental training under his guidance.",al={"humming recall crystal","recall crystal zephras"},it="item"},{q="What prerequisite quest leads to Embracing the Elements?",a="Harmony in Balance comes first. You deal with the vuldren disrupting the surrounding area.",al={"embracing the elements prequest","what comes before embracing the elements"},gp=true},{q="What role does Windshaper Boro play in Thendal Grove?",a="Windshaper Boro trains the shamans of Thendal Grove. He teaches new initiates about elemental communion and the natural world.",al={"what does boro do","windshaper boro role"},it="identity"},{q="Why does Rorian the Dayseeker send you to Windshaper Boro?",a="While you were out handling the grove's vuldren troubles, Windshaper Boro specifically left a recall crystal in Rorian's care for you. Rorian is simply passing along the crystal and directing you to Boro near the village center so you can begin learning how to walk the path of the elements.",al={"why does rorian want this done","rorian boro quest why","why examine humming recall crystal"},it="motive",add="52185878"}},ang={["class:Shaman"]="As a shaman, you meet Windshaper Boro for formal instruction and learn that the elemental winds have fallen silent. Shamans devote themselves to restoring communion with them.",["faction:Horde"]="As a Horde traveler on Zephras Isle, you encounter the island’s elemental callers and their struggle with the spirits. The spirits’ silence shapes their training."},kw={"embracing the elements","humming recall crystal","rorian the dayseeker","shaman","spirits of the four winds","thendal grove","windshaper boro","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92461","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Windshaper Boro",level="2",faction="Horde",cl={"SHAMAN"},id=92484},src={"Embracing the Elements"},fv=true}
E["quest:92485"] = {t="quest",n="A Student of Nature",z="zephras",s="On Zephras Isle, A Student of Nature begins with a summons to novice druids. After they help restore local harmony, Xyton Silverwind calls them beneath the boughs of Thendal Grove to learn the isle's natural balance.",h="On Zephras Isle, A Student of Nature begins with a summons to novice druids.",sec={{t="A Summons from the Grove",b="After local disturbances caused by overzealous wildlife are resolved, Rorian the Dayseeker brings a personal summons to young initiates. The folded parchment was left by Xyton Silverwind. It invites aspiring druids to step forward and study the deeper mysteries of the wild, for their natural talents have caught the grove elders' attention.",sp=0},{t="Keepers of the Balance",b="Meeting Xyton Silverwind on the lower level of the great tree in Thendal Grove marks a novice's first step in their calling. To Silverwind, Zephras Isle's plants and animals form an intricate living whole that needs constant care and watchful balance. The path of fang, claw, feather, and branch calls for lasting mentorship, and this meeting begins a lifetime of stewardship.",sp=0}},faq={{q="Who sends the player to Xyton Silverwind?",a="After you help address the unruly vuldren around the grove, Rorian the Dayseeker hands you a folded parchment directing you to Xyton Silverwind.",al={"who gives a student of nature","quest giver","rorian"}},{q="Where is Xyton Silverwind located?",a="Xyton Silverwind is on the ground floor of the great tree in Thendal Grove, just behind Rorian the Dayseeker on Zephras Isle.",al={"xyton silverwind location","where is xyton","druid trainer location"},gp=true},{q="What is the purpose of this quest?",a="A Student of Nature introduces novice druids to Xyton Silverwind, their primary teacher and guide in keeping Zephras Isle's natural balance.",al={"why do this quest","quest goal","druid training start"},it="purpose"},{q="What does Xyton Silverwind teach novice druids about Zephras Isle?",a="Silverwind teaches that the island's plants and animals are interconnected and need active care and balance through the disciplines of fang, claw, feather, and branch.",al={"what does xyton say","zephras nature balance","druid role zephras"}},{q="What prerequisite must be completed before receiving this summons?",a="Initiates first complete Harmony in Balance for Rorian the Dayseeker, addressing the unruly vuldren population before receiving Silverwind's note.",al={"prereq quest","prior quest","before student of nature"},gp=true},{q="What is contained within the Folded Parchment?",a="The folded parchment is a note left by Xyton Silverwind. It directs the promising young druid to seek him beneath the canopy of the great tree for further training.",al={"folded parchment note","silverwind note","what is on parchment"},it="item"},{q="Why does Rorian the Dayseeker send you to Xyton Silverwind?",a="While you were out handling the local vuldren threat, the resident druid trainer, Xyton Silverwind, specifically left a message for you. Rorian is acting as the intermediary to ensure promising initiates receive proper instruction, urging you to heed Silverwind's counsel so you can master the druidic arts and preserve the natural balance.",al={"rorian motive","why send me to silverwind","why does rorian give you folded parchment"},it="motive",add="caa97f7a"}},ang={["class:Druid"]="As a druid, you begin lifelong training with Xyton Silverwind in the arts of the wild, the fang, and the branch."},kw={"druid","folded parchment","rorian the dayseeker","thendal grove","vuldren","xyton silverwind","zephras isle"},rel={"quest:92461","npc:rorian-the-dayseeker","zone:zephras","topic:druid"},m={start="Rorian the Dayseeker",["end"]="Xyton Silverwind",level="2",cl={"DRUID"},id=92485},src={"A Student of Nature"},fv=true}
E["quest:92514"] = {t="quest",n="Welcome to Shen'dar Village",z="zephras",s="At Shen'dar Village, newcomers are sent to meet its elder and innkeeper. Local tensions share the frontier with a growing bandit threat.",h="At Shen'dar Village, newcomers are sent to meet its elder and innkeeper.",sec={{t="First Steps in Shen'dar",b="Newcomers in Shen'dar Village first meet the people who guide daily life there. Those touched by the spirits are directed to Elder Illaya Amberwind near the village square. Coriella Calmbreeze welcomes visitors at the village inn, where lodging and supplies are available. These introductions help travelers learn the village's customs before they take up arms.",sp=0},{t="Factions and Frontier Trouble",b="Disputes in Shen'dar Village stay civil, though the Windshapers and the High Order disagree. Their ideological friction runs through the region, but both groups know survival comes first. Bandits are pressing into the area. That danger gives the village reason to set smaller quarrels aside.",sp=0}},faq={{q="What is the purpose of the quest Welcome to Shen'dar Village?",a="Welcome to Shen'dar Village guides newcomers to meet the people who lead and serve the settlement. Travelers are directed to the resident Windshaper elder and the village innkeeper before they help with local troubles such as bandits.",al={"what is shen'dar village quest","welcome to shendar quest overview","what to do in shendar village"}},{q="Who is Illaya Amberwind?",a="Illaya Amberwind is Shen'dar Village's Windshaper elder. She is near the town center and guides those touched by the spirits amid local political friction.",al={"who is illaya amberwind","illaya amberwind location","windshaper elder shendar"}},{q="Who is Coriella Calmbreeze?",a="Coriella Calmbreeze runs Shen'dar Village's inn, offering lodging, rest, and provisions to travelers and locals.",al={"who is coriella calmbreeze","shendar village innkeeper","where is the inn in shendar village"}},{q="Who are the Windshapers?",a="The Windshapers are practitioners touched by the spirits, marked by a charge of static in the air around them. They and the High Order keep relations civil in Shen'dar Village despite their tensions and the wider threats.",al={"what are windshapers","spirit touched windshaper lore","high order vs windshapers"}},{q="What is the tension between the High Order and the Windshapers?",a="The High Order and the Windshapers are in political and ideological conflict. In Shen'dar Village, both sides keep the peace and attend to shared, more urgent concerns.",al={"what is the high order","conflict in shendar village","high order vs windshapers tension"}},{q="What problems is Shen'dar Village currently facing?",a="Shen'dar Village faces local bandits in the surrounding territory, alongside the philosophical dispute between the Windshapers and the High Order.",al={"shendar village troubles","what threat faces shendar village","bandits in shendar village"}}},ang={["class:Shaman"]="As a shaman, you can sense the faint static in the air around spirit-touched Windshapers like Illaya Amberwind in Shen'dar Village."},kw={"bandits","coriella calmbreeze","high order","illaya amberwind","shen'dar village","spirit-touched","welcome to shen'dar village","windshapers"},rel={"quest:92595"},m={faction="Horde",id=92514},src={"In-game quest text: Welcome to Shen'dar Village"},fv=true}
E["quest:92515"] = {t="quest",n="The Problem With Prideclaws",z="zephras",s="The Shen'dar Highlands village faces danger from prideclaws, bandits, and cultists. The beasts press toward the settlement, and culling them guards the people while providing useful pelts.",h="The Shen'dar Highlands village faces danger from prideclaws, bandits, and cultists.",sec={{t="A Growing Wild Menace",b="Prideclaws are pressing toward the village in the Shen'dar Highlands. Bandits roam the hills, and unhinged cultists trouble the region. Villagers face danger from several sides. As the beasts grow bolder and their territory spreads, the settlement draws nearer to their reach.",sp=0},{t="Securing the Borders",b="Villagers have organized a culling before the wandering predators can snatch pets or children. Driving prideclaws back from the borders helps guard the settlement. Their sturdy pelts also give village craftsmen material for useful goods.",sp=0}},faq={{q="What are prideclaws?",a="Prideclaws are fierce predators of the hills and highlands of Shen'dar. Their pelts are valuable, and their growing numbers bring them closer to settlements.",al={"what are prideclaws","prideclaw lore","prideclaws"}},{q="Where are the prideclaws located?",a="Prideclaws roam the hills of the Shen'dar Highlands. Their growing numbers carry them toward the local village and its inhabitants.",al={"where is this quest","where do prideclaws live","prideclaw location"}},{q="Why does the village need the prideclaws culled?",a="Bandits and mad cultists already menace the region. As prideclaw numbers grow, the beasts draw near the village, putting children and domestic animals at risk.",al={"why kill prideclaws","why cull prideclaws","village danger"}},{q="What will be done with the prideclaw pelts?",a="Village crafters use prideclaw pelts to make practical goods and supplies.",al={"what happens to pelts","prideclaw pelt use","pelts purpose"}},{q="What other threats plague the surrounding hills?",a="Roaming bandits and unstable cultists trouble the hills around the settlement, alongside the wild prideclaws.",al={"other threats shendar","what else threatens the village","local threats"}},{q="How do the locals view the prideclaws?",a="The villager overseeing the culling finds prideclaws somewhat cute, even from behind armed guards. Still, keeping the village safe matters before tragedy strikes.",al={"who gives the problem with prideclaws","quest giver thoughts"}}},ang={["class:Hunter"]="As a hunter, tracking and culling predators near settlements is familiar work. Prideclaws in these numbers still demand respect."},kw={"cull","prideclaw pelts","prideclaws","shen'dar","shen'dar highlands","the problem with prideclaws","village borders"},m={id=92515},src={"In-game quest text: The Problem With Prideclaws"},fv=true}
E["quest:92516"] = {t="quest",n="Hippogryph Harassment",z="zephras",s="Near Shen'dar Village, Hippogryph Harassment puts travelers in danger. A wild flock nests southeast of the village in the Shen'dar Highlands and attacks those on the nearby road. You are asked to cull its young, protectors, and matriarch so travelers can pass safely.",h="Near Shen'dar Village, Hippogryph Harassment puts travelers in danger.",sec={{t="Peril on the Road",b="Travelers near Shen'dar Village face danger from the skies. A wild flock nests southeast of the settlement, in the Shen'dar Highlands. Across Kalimdor, hippogryphs are known as noble beasts, and some are bonded to elven riders. Untamed flocks, though, fiercely guard their territory.\n\nWagons and lone travelers on the paths below have become targets of aerial ambushes. The attacks disrupt passage and could leave the village isolated if the creatures go unchecked.",sp=0},{t="Culling the Flock",b="The flock's nesting grounds in the Shen'dar Highlands must be confronted to end the danger. To make the high roads safe, kill the young before they reach maturity and overcome the vigilant protectors guarding the perimeter.\n\nThe matriarch directs attacks on passersby. Travelers can use the roads safely again only when the nest is struck and she is felled.",sp=0}},faq={{q="Why are the hippogryphs attacking travelers near Shen'dar Village?",a="The hippogryphs have established nesting grounds southeast of Shen'dar Village in the Shen'dar Highlands. Their territory lies beside the main travel route, and they attack those who come near to defend their brood and hunting grounds.",al={"why hippogryphs attacking","why are hippogryphs hostile","hippogryph harassment cause"}},{q="Where is the hippogryph flock located?",a="The flock nests southeast of Shen'dar Village in the Shen'dar Highlands. Its roost overlooks the road, where the young, protectors, and matriarch gather among the cliffs and ridges.",al={"where are the hippogryphs","hippogryph location","shen'dar highlands location"}},{q="Which hippogryphs must be slain to complete the task?",a="To restore safe travel, slay eight hippogryph youths, six sturdy hippogryph protectors, and the hippogryph matriarch who directs the roost in the Shen'dar Highlands.",al={"which hippogryphs do i kill","hippogryph harassment targets","hippogryph objectives"}},{q="Who is the leader of the hippogryph flock?",a="A powerful Hippogryph Matriarch leads the flock in the Shen'dar Highlands. She directs the roost and its defense of the nesting grounds southeast of Shen'dar Village, so her death is needed to break the flock's hold on the roadway.",al={"who leads the hippogryphs","hippogryph matriarch","boss hippogryph"}},{q="Why must the hippogryph youths be culled?",a="The youths are the flock's future growth and continued expansion. Culling them alongside the mature protectors keeps the roost from quickly replenishing its strength or establishing a lasting reign of terror over the local highways.",al={"why kill hippogryph youths","why target young hippogryphs","culling hippogryph young"}},{q="Are these hippogryphs tame or allied with anyone?",a="No. These are wild, untamed creatures that established a roost in the Shen'dar Highlands on their own. Unlike the disciplined mounts raised by the night elves, this feral flock treats any passing humanoid as an intruder or prey encroaching on its territory.",al={"are the hippogryphs tamed","are these night elf hippogryphs","friendly hippogryphs"}},{q="What danger do these hippogryphs pose to the local settlement?",a="The flock nests overlooking the road leading southeast from Shen'dar Village. The beasts swoop down on supply carts, messengers, and wandering travelers, threatening safe overland travel and risking the village's isolation from the surrounding lands.",al={"what threat do hippogryphs pose","danger to shendar village","why are hippogryphs a problem"}}},ang={["race:NightElf"]="As a night elf, you revere hippogryphs as sacred companions of Elune. Culling an aggressive wild flock is a somber task when wilderness clashes with traveler safety.",["class:Hunter"]="As a hunter, you understand the predatory instincts of aerial beasts and the hierarchy of a wild roost. Killing the matriarch is the surest way to break the flock's aggression.",["class:Druid"]="As a druid, you seek harmony with the wild. You can see this culling as an unfortunate necessity to restore balance after the beasts began preying on travelers."},kw={"hippogryph","hippogryph harassment","hippogryph matriarch","hippogryph protector","hippogryph youth","kalimdor","matriarch","shen'dar highlands","shen'dar village"},m={id=92516},src={"In-game quest text: Hippogryph Harassment"},fv=true}
E["quest:92517"] = {t="quest",n="The Criminal Element",z="zephras",s="The Highlands Bandits terrorize the Shen'dar Highlands from a cave behind a waterfall. A new cult has arrived, and local defenders are stretched thin. So outside help is needed against the gang's leader, \"Badwind\" Bennic.",h="The Highlands Bandits terrorize the Shen'dar Highlands from a cave behind a waterfall.",sec={{t="Outlaws Behind the Falls",b="The Highlands Bandits have made their den in a hidden cave behind a northern waterfall in the Shen'dar Highlands. Their leader, \"Badwind\" Bennic, commands cutthroats who troubled the locals long before an enigmatic cult arrived. Since then, their lawlessness has grown into terror. Local defenders are stretched thin and cannot spare forces, so you are sent to break the gang and bring Bennic down.",sp=0},{t="A Shift in the Shadows",b="After \"Badwind\" Bennic is eliminated, the Highlands Bandits lose their hold and the locals gain a brief respite. Yet surviving outlaws may seek shelter with the nearby cult. If it takes in these seasoned highwaymen, its ranks could swell and deepen the threat across the region.",sp=1}},faq={{q="Who is \"Badwind\" Bennic?",a="\"Badwind\" Bennic leads the Highlands Bandits from a hidden cave behind a waterfall in the Shen'dar Highlands. His gang has long plagued the area, and the recent turmoil has made them an even greater terror.",al={"who is badwind bennic","bennic","badwind"}},{q="Where are the Highlands Bandits hiding?",a="The Highlands Bandits hide in a cave behind a waterfall to the north in the Shen'dar Highlands.",al={"where are the bandits","bandit cave location","waterfall cave"}},{q="What is the cult mentioned in the area?",a="The cult is a new and alarming faction whose followers gather at Falaath Village to the south, and whose numbers are growing. The bandits were here before the cult arrived, but its presence has made the region more dangerous. Local forces worry that surviving bandits may seek refuge with the cult and strengthen its ranks.",al={"what cult","cult connection","who is the cult"}},{q="Why can't local forces handle the bandits themselves?",a="Local forces are stretched thin by the emerging cult and lack the manpower to clear out the bandits. Bringing Bennic down and scattering his gang removes an active threat from the region.",al={"why kill the bandits","bandit problem"}},{q="What happens to the bandits after Bennic is defeated?",a="With Bennic defeated, the bandits' hideout is scattered, but surviving outlaws may seek protection with the nearby cult and swell its already alarming numbers.",al={"what happens to surviving bandits","did all bandits die"}},{q="Where does this conflict take place?",a="The Highlands Bandits roam the Shen'dar Highlands, where they keep a hidden cave behind a waterfall.",al={"where is shendar highlands","shen'dar highlands"}}},ang={["class:Rogue"]="As a rogue, you know hidden caves behind waterfalls make familiar bandit hideouts. \"Badwind\" Bennic and his crew lack the care to stay out of the locals' sight and escape their anger."},kw={"badwind bennic","bennic","cult","highlands bandits","shen'dar highlands","the criminal element","waterfall cave"},m={id=92517},src={"In-game quest text: The Criminal Element"},fv=true}
E["quest:92528"] = {t="quest",n="Among the Faithful",z="zephras",s="At Falaath Village, you pass among the Faithful of Al'Akir in the Shen'dar Highlands. Their growing ranks and storm magic draw close scrutiny, while their leaders gather with plans that threaten nearby settlements and outposts.",h="At Falaath Village, you pass among the Faithful of Al'Akir in the Shen'dar Highlands.",sec={{t="Infiltrating Falaath Village",b="You enter Falaath Village in the Shen'dar Highlands as an eager recruit among the Faithful of Al'Akir. The cultists boast that their ranks are growing. They claim their devotion gives the storm its shape and fury. New arrivals are usually sent to Skypriest Aanders for scrutiny, but an unexpected meeting at the village inn interrupts that routine.",sp=0},{t="The Secret Guest",b="Skypriest Aanders hosts a distinguished guest on the north side of town. While he is occupied, you can move through the settlement without his watch. Eavesdropping on the leaders reveals their immediate plan: a coordinated military push across the Shen'dar Highlands.",sp=1},{t="Lorthuna's Scheme",b="Lorthuna is the mysterious guest at the inn and the supreme commander of the entire cult. Her presence points to an aggressive strike against Shen'dar Village and the western watchtower. Shen'dar Village is a clear population center. Yet local scouts cannot understand why the remote lookout tower is a target or what lies behind the cult's storm-driven offensive.",sp=2}},faq={{q="Who are the Faithful of Al'Akir?",a="The Faithful of Al'Akir are a cult devoted to the Windlord, Al'Akir. They are based around Falaath Village in the Shen'dar Highlands, wield storm magic, and answer to Lorthuna.",al={"who are the faithful of alakir","what cult is this","alakir cult"}},{q="Who is Skypriest Aanders?",a="Skypriest Aanders is a ranking officer of the cult at Falaath Village. He assesses and inducts new recruits, though he is occupied at the village inn receiving an important guest during your infiltration.",al={"who is skypriest aanders","aanders","cult assessment guy"}},{q="Who is Lorthuna?",a="Lorthuna is the supreme leader of the cult of Al'Akir. Her covert presence at the Falaath Village inn reveals that the cult is arranging an imminent, high-level offensive in the highlands.",al={"who is lorthuna","cult leader lorthuna","guest at the inn"}},{q="Why is the cult targeting the western watchtower?",a="The cult plans simultaneous strikes on Shen'dar Village and the western watchtower. The village is an understandable target, but the watchtower's purpose in the attack remains a mystery to highland defenders.",al={"why attack the watchtower","western watchtower cult","cult targets"}},{q="Where does this take place?",a="Falaath Village lies in the Shen'dar Highlands. It is a major base and staging ground for the Faithful of Al'Akir and their new recruits.",al={"where is falaath village","falaath village location"}},{q="What are the cult's intentions in the Shen'dar Highlands?",a="The cult seeks to expand its influence and unleash storm magic across the Shen'dar Highlands. Under Lorthuna's leadership, its immediate assault targets Shen'dar Village and the western watchtower.",al={"what are the cults goals in shendar highlands","cult plans shendar"}}},ang={["class:Priest"]="As a priest, you follow familiar holy or shadow faiths. At Falaath Village, the cultists follow Skypriests devoted to Al'Akir the Windlord and channel the storm's primal strength.",["class:Shaman"]="As a shaman, you know the elemental forces the cult of Al'Akir worships and commands through its mastery of storm energies."},kw={"al'akir","among the faithful","falaath village","lorthuna","shen'dar highlands","skypriest aanders","western watchtower","windlord"},rel={"quest:92529"},m={id=92528},src={"In-game quest text: Among the Faithful"},fv=true}
E["quest:92529"] = {t="quest",n="Falaath Village",z="zephras",s="At Falaath Village, marked recruits gather to seek the Windlord's favor. They come from Shen'dar Village to report to Missionary Jasaan and join the faithful.",h="At Falaath Village, marked recruits gather to seek the Windlord's favor.",sec={{t="Contrition for the Windlord",b="In Shen'dar Village, Sania Silverstream says her people grew prideful and took the bounty of the air for granted. The wind spirits abandoned them, and stagnation followed. Now penitent recruits receive the Mark of Akir and travel to Falaath Village. There, they join others who hope their acts of contrition will restore the wind's favor.",sp=0},{t="The Mission at Falaath",b="At Falaath Village, Missionary Jasaan welcomes initiates bearing the Mark of Akir. Jasaan sees each new acolyte as a blessing from the four winds. Those who arrive may seek the elemental grace of Al'Akir.",sp=0}},faq={{q="What is the quest Falaath Village?",a="Marked recruits travel from Shen'dar Village to Falaath Village and report to Missionary Jasaan. There, they seek fellowship with the faithful.",al={"what is falaath village quest","falaath village overview","falaath village quest"}},{q="Who is Missionary Jasaan?",a="Missionary Jasaan is an acolyte near the entrance to Falaath Village. Jasaan welcomes recruits sent by Sania Silverstream to seek Al'Akir's blessings.",al={"who is missionary jasaan","jasaan lore","falaath missionary"}},{q="Who is Sania Silverstream?",a="Sania Silverstream is one of the faithful in Shen'dar Village. She gives new recruits the Mark of Akir and directs them to Falaath Village.",al={"who is sania silverstream","sania lore","sister sania"}},{q="Why are the shen'dorei worshipping Al'Akir?",a="The followers believe their people grew prideful and took the bounty of the winds for granted. The spirits abandoned them, and through acts of contrition they seek to regain Al'Akir's favor.",al={"why worship alakir","windlord alakir worship","who is the windlord"}},{q="What is the Mark of Akir?",a="The Mark of Akir is a sign Sania Silverstream gives recruits in Shen'dar Village. It identifies them as members of the faithful before they enter Falaath Village.",al={"what is mark of akir","lost mark of akir","recruits mark"}},{q="Who are the shen'dorei mentioned in the quest?",a="The shen'dorei Sania speaks of are elves facing stagnation after the wind spirits withdrew their favor. Some seek atonement through devotion to the elements.",al={"who are the shendorei","shen dorei lore"}}},ang={["race:Skyborne"]="As a shen'dorei seeking to restore your bond with the winds, you join the faithful at Falaath Village in shared contrition. There, you hope to regain Al'Akir's favor.",["class:Shaman"]="As a shaman, you seek harmony with elemental spirits. The faithful approach Al'Akir through penitence and religious devotion, hoping to reclaim the winds that abandoned them."},kw={"al'akir","falaath village","mark of akir","missionary jasaan","sania silverstream","shen'dar village","shen'dorei","windlord"},m={id=92529},src={"In-game quest text: Falaath Village"},fv=true}
E["quest:92532"] = {t="quest",n="The Warrior's Path",z="zephras",s="Rorian the Dayseeker sends you to Blademaster Ren in Thendal Village. She offers young warriors instruction and discipline to defend their people.",h="Rorian the Dayseeker sends you to Blademaster Ren in Thendal Village.",sec={{t="A Summons to the Watchtower",b="After restoring balance nearby, you return to Rorian the Dayseeker in Thendal Village. The village blademaster has noticed you, and Rorian gives you a crumpled note written by Ren herself. She asks you to come to her directly.\n\nRen waits in the village watchtower, high above the settlement. From there, she watches the island's borders and the recruits who may one day defend them.",sp=0},{t="The Mantle of Protection",b="Inside the watchtower, Blademaster Ren teaches you that combat takes more than brute strength. A warrior must lead, endure, and protect as the world grows more uncertain. Ren pledges to guide you as you hone your skills. Her rigorous training prepares you for the greater dangers threatening your home.",sp=0}},faq={{q="Who sends me to find Blademaster Ren?",a="After you finish work in Thendal Village, Rorian the Dayseeker directs you to Blademaster Ren. Ren asked Rorian to send you to her watchtower when you returned.",al={"who starts this","quest giver","rorian role"}},{q="Where can I find Blademaster Ren?",a="Blademaster Ren waits inside the watchtower in Thendal Village on Zephras Isle. She watches over the village and trains novice combatants.",al={"where is blademaster ren","ren location","thendal watchtower"},gp=true},{q="What is the Crumpled Note?",a="The Crumpled Note is Blademaster Ren's personal summons, delivered by Rorian. It asks you to read it and report to the Thendal Village watchtower for martial training.",al={"crumpled note","what does note say","ren note"},it="item"},{q="What does Blademaster Ren teach young warriors?",a="Blademaster Ren teaches vigilance, leadership, and protection. Warriors need the will to stand between danger and their people as the world shifts and dangers mount.",al={"ren teaching","what does ren train","warrior purpose"}},{q="Is this quest required for warrior training on Zephras Isle?",a="This introduces you to Blademaster Ren, your class trainer in Thendal Village, and shows where to return for martial techniques.",al={"do i have to do this","warrior trainer intro","is it mandatory"},gp=true},{q="What does Ren mean by 'may the winds guide you'?",a="Ren's blessing reflects the culture of Zephras Isle. It wishes travelers safe passage, focus, and fortune in unfamiliar and dangerous lands.",al={"may the winds guide you meaning","wind quote","ren farewell"}},{q="Why does Rorian the Dayseeker send me to Blademaster Ren?",a="Blademaster Ren personally asked Rorian to direct you to the watchtower the moment you returned to Thendal Village. With the world shifting and perilous trials ahead, Ren recognizes that burgeoning warriors require dedicated combat instruction and leadership guidance if your people are to survive the dangers to come. Rorian simply honors Ren's request to ensure you receive the training you need.",al={"why does rorian send me","rorian motive","why find blademaster ren"},it="motive",add="2d8c1194"}},ang={["class:Warrior"]="As a warrior, you begin your martial education in Thendal Village with Blademaster Ren as your mentor."},kw={"blademaster ren","crumpled note","rorian the dayseeker","thendal village","warrior's path","watchtower","zephras isle"},rel={"npc:rorian-the-dayseeker","quest:92461","zone:zephras"},m={start="Rorian the Dayseeker",["end"]="Blademaster Ren",level="2",cl={"WARRIOR"},id=92532},src={"The Warrior's Path"},fv=true}
E["quest:92544"] = {t="quest",n="Al'Aketh Thugs",z="zephras",s="At the temple ruins near Thendal Grove, Al'Aketh cultists threaten travelers. Sent from the Shrine of Akir under High Priestess Lorthuna's orders, they harass wayfarers and force recruits into their ranks. Hanaa Nightwind asks you to break their hold and slay their commander.",h="At the temple ruins near Thendal Grove, Al'Aketh cultists threaten travelers.",sec={{t="Cultist Ruffians in the Ruins",b="Just southwest of Thendal Grove, ancient temple ruins have become dangerous for travelers. The Al'Aketh have seized the grounds and prey on people near the grove. Rangers stationed nearby suspect High Priestess Lorthuna sent the ruffians from the Shrine of Akir. They bully the people and force them to submit to the cult.",sp=0},{t="Malduko Cloudcrush",b="At the ruins, Malduko Cloudcrush rules through violence and fear. Brutes and newly indoctrinated neophytes obey him, making the temple an aggressive outpost at Thendal Grove's doorstep. Hanaa Nightwind hopes that striking down Cloudcrush and scattering his followers will break the cult's confidence. It will warn them that coercion will not be tolerated in these lands.",sp=0}},faq={{q="Who are the Al'Aketh?",a="The Al'Aketh are a fanatical cult operating on Zephras. High Priestess Lorthuna leads them from the Shrine of Akir. Her followers use intimidation and violence to force travelers and residents to join.",al={"what is the al'aketh","al'aketh cult","who are alaketh"},it="people"},{q="Why are the cultists attacking Thendal Grove?",a="The cultists have camped in temple ruins southwest of Thendal Grove. There, they ambush travelers leaving the area and terrorize people on the road. They hope to pressure locals into submitting to the cult.",al={"why are cultists here","why thendal grove","cultist motive"},it="conflict"},{q="Who is Malduko Cloudcrush?",a="Malduko Cloudcrush leads the Al'Aketh encampment at the temple ruins. Hanaa Nightwind calls him a monster. He directs the brutes and neophytes who prey on nearby roads.",al={"malduko","cloudcrush","who is malduko cloudcrush"},it="target"},{q="Who is Hanaa Nightwind?",a="Hanaa Nightwind is a Ranger guarding Thendal Grove. She remains at her post along the road and warns travelers of the nearby ambush. She depends on capable adventurers to clear the threat.",al={"hanaa","hanaa nightwind","quest giver"},it="identity"},{q="Who sent these cultists to the ruins?",a="Hanaa suspects High Priestess Lorthuna sent the cultists from the Shrine of Akir. Lorthuna oversees cult activities there.",al={"who commands them","cult leader","who sent malduko"},it="origin"},{q="What else can be found near the temple ruins?",a="An active Ley Line lies within the ancient ruins at the southwest end of the area, alongside the Al'Aketh encampment.",al={"ruins ley line","temple ruins secret","ruins southwest"},it="place"},{q="Why does Hanaa Nightwind want the Al'Aketh thugs cleared out?",a="The Al'Aketh cultists have camped dangerously close to Thendal Grove, harassing travelers along the roads and attempting to coerce local people into their zealous fold. Ranger Hanaa Nightwind wants to break their hold on the southwest ruins and send a bloody, unmistakable message that forces the surviving cultists to abandon the area.",al={"why kill the alaketh thugs","hanaa nightwind motive","why clear the temple ruins"},it="motive",add="b63e8692"},{q="Why can't Hanaa Nightwind deal with the cultists herself?",a="Hanaa must remain at her post to keep watch and warn unsuspecting travelers departing Thendal Grove before they wander into the cult's ambush. Though it takes all her restraint not to march into the ruins herself, she cannot abandon her duty at the grove's edge.",al={"why does hanaa need me","why doesn't hanaa fight them","why me alaketh thugs"},it="why_me",add="b6ccde37"}},kw={"al'aketh brute","al'aketh neophyte","al'aketh thugs","hanaa nightwind","high priestess lorthuna","malduko cloudcrush","shrine of akir","thendal grove"},rel={"quest:92471","zone:zephras"},m={start="Hanaa Nightwind",level="5",id=92544},src={"Al'Aketh Thugs"},fv=true}
E["quest:92550"] = {t="quest",n="Havoc in the Highlands",z="zephras",s="In the highlands, Shen'dar Village moves against Al'Aketh forces at Falaath Village. Its defenders mean to stop an assault before it begins and protect their home.",h="In the highlands, Shen'dar Village moves against Al'Aketh forces at Falaath Village.",sec={{t="A Preemptive Strike",b="Zealous cultists are preparing to assault Shen'dar Village. So its leaders send you into the ruins of Falaath Village to strike first, before the Al'Aketh forces can begin their attack.",sp=0},{t="Assault on Falaath Village",b="Al'Aketh zealots gather at Falaath Village and wield chaotic elemental power. You break their ranks by defeating Al'Aketh Stormcallers and shattering Living Lightning. Then you find Commander Cyclas and behead him.",sp=0},{t="Securing the Highlands",b="Commander Cyclas is slain, and his vanguard lies devastated. Shen'dar Village gains a vital reprieve. As the citizens take up arms, Sania Silverstream slips out of town unnoticed. She flees while the local defense gathers strength.",sp=1}},faq={{q="What is Havoc in the Highlands?",a="Shen'dar Village strikes first against Al'Aketh cultists in the ruins of Falaath Village. Its defenders hope to stop an assault before it begins.",al={"havoc in the highlands quest","what is havoc in the highlands","highlands quest"}},{q="Who is threatening Shen'dar Village?",a="The Al'Aketh threaten Shen'dar Village. They worship elemental storms and field Stormcallers, bound Living Lightning, and Commander Cyclas, their leader.",al={"who are the enemies","what cult is this","who attacks shendar"}},{q="Where are the cultists massing?",a="The cultists gather in the ruins of Falaath Village. Commander Cyclas and his Al'Aketh followers use it as their staging ground.",al={"where is commander cyclas","falaath village ruins","where to go"}},{q="Who is Commander Cyclas?",a="Commander Cyclas leads the Al'Aketh forces gathered in the ruins of Falaath Village. They prepare to march on Shen'dar.",al={"who is commander cyclas","cyclas lore","cyclas cult"}},{q="Why did Sania Silverstream flee Shen'dar Village?",a="Sania Silverstream slips out of Shen'dar Village just before its defenders rally. She likely flees after seeing the locals take up arms and organize their defense.",al={"sania silverstream fleeing","why did sania leave","who is sania silverstream"}},{q="Does the strike successfully secure Shen'dar Village?",a="Shen'dar Village turns back the immediate threat by breaking the cultists' forward ranks and beheading Commander Cyclas. Returning zealots will find the highlands ready to resist.",al={"did shendar survive","aftermath of the attack","is shendar safe"}}},ang={["class:Shaman"]="As a shaman, you know Al'Aketh Stormcallers and their summoned Living Lightning wield the elements. The cultists twist wind and storm into weapons of fanatical aggression."},kw={"al'aketh","commander cyclas","falaath village","havoc in the highlands","living lightning","sania silverstream","shen'dar village","stormcallers"},rel={"quest:92529"},m={id=92550},src={"In-game quest text: Havoc in the Highlands"},fv=true}
E["quest:92551"] = {t="quest",n="Stolen Supplies",z="zephras",s="Caravans bound for the Shen'dar Highlands are under attack, and their stolen goods gather in Falaath Village. Food and windstones grow scarce in the highland settlements, leaving some skyborne close to starvation.",h="Caravans bound for the Shen'dar Highlands are under attack, and their stolen goods gather in Falaath Village.",sec={{t="Raids on the Highland Lifeline",b="For months, raiders have attacked caravans on the road between the lowlands and the Shen'dar Highlands. Their wagons carry food and windstones that highland settlements depend on. As fewer deliveries arrive, townsfolk struggle to get by, and some draw close to starvation.",sp=0},{t="The Falaath Cache",b="The Al'Aketh blame common bandits for the attacks. Yet the missing supplies keep turning up in Falaath Village, where the Al'Aketh store the stolen packs. The recovered goods go to the local authorities and constable, who send them straight to the skyborne in greatest need.",sp=0}},faq={{q="What supplies were stolen from the caravans?",a="Caravans between the lowlands and highlands carried food and windstones. Regular deliveries help keep local townsfolk fed and supplied.",al={"what was stolen","supplies taken","what goods were stolen"}},{q="Who is responsible for raiding the caravans?",a="The Al'Aketh have raided the supply caravans for months. They blame ordinary bandits, yet stolen packs keep turning up in Falaath Village.",al={"who stole the supplies","who raided the caravans","caravan attackers"}},{q="Where are the stolen supply caches being held?",a="The Al'Aketh store the stolen supply packs in Falaath Village, within the Shen'dar Highlands.",al={"where are the supplies","where to find supplies","stolen caches location"}},{q="Why are these supply caravans being targeted?",a="The caravans carry food and windstones between the lowlands and highlands. The raids leave local skyborne short of supplies while highland goods gather in Falaath Village.",al={"why steal windstones and food","why caravan raids"}},{q="What happens to the supplies once they are recovered?",a="Once recovered, the supplies go to the local constable and authorities. They redistribute them to the townsfolk most in need of food and relief.",al={"who gets the supplies back","supplies redistribution","what happens after recovery"}},{q="Why do the Al'Aketh blame bandits for the raids?",a="The Al'Aketh blame roving bandits to deflect responsibility. Yet stolen cargo keeps turning up in their settlement at Falaath Village.",al={"why blame bandits","al aketh bandits excuse"}}},ang={["race:Skyborne"]="The raids break the lifeline between the highlands and lowlands. Without regular deliveries of food and windstones, skyborne townsfolk go hungry."},kw={"al'aketh","caravans","constable","falaath village","shen'dar highlands","skyborne","stolen supplies","windstones"},rel={"quest:92529","topic:skyborne"},m={id=92551},src={"In-game quest text: Stolen Supplies"},fv=true}
E["quest:92553"] = {t="quest",n="Restocking the Larders",z="zephras",s="In the Shen'dar Highlands of Zephras, a village cook needs help keeping the food stores full. Danger keeps the villagers from foraging, so the cook turns to you for eggs and strider meat.",h="In the Shen'dar Highlands of Zephras, a village cook needs help keeping the food stores full.",sec={{t="Dangers in the Highlands",b="Rising dangers make life harder in the Shen'dar Highlands. Villagers can no longer safely enter the wilderness to forage or hunt, and the communal stores are nearly empty. So local cooks rely on travelers willing to brave the wild trails and help keep the settlement fed.",sp=0},{t="Sustenance and Comfort",b="The cook asks you to find strider meat and fresh small eggs among the highlands' wildlife. In return, the cook shares knowledge of local game and its recipes. Small eggs fried in ursera tallow offer comfort, with dried peacebloom for a quiet pipe.",sp=0}},faq={{q="What supplies are needed for Restocking the Larders?",a="The local cook needs three Small Eggs and eight cuts of Strider Meat to feed the village while danger keeps ordinary foragers indoors.",al={"restocking larders objective","what to collect restocking larders"}},{q="Where can the ingredients be found?",a="Wild creatures throughout the Shen'dar Highlands on Zephras provide the strider meat and small eggs.",al={"where get strider meat zephras","egg locations shendar"}},{q="Why is the village running low on food?",a="Rising dangers make it too perilous for ordinary villagers to hunt or forage, leaving the food stores depleted.",al={"why need food zephras","why village hungry shendar"}},{q="What reward does the cook offer for the food?",a="The cook offers culinary tips, techniques, and training in local recipes in exchange for fresh provisions.",al={"what does quest giver offer","cooking training quest"}},{q="What are the Shen'dar Highlands and Zephras?",a="The Shen'dar Highlands lie on Zephras, where locals face mounting threats while trying to sustain their daily lives.",al={"what is zephras","where is shendar highlands"}},{q="How does the cook prepare the eggs?",a="The cook fries freshly gathered small eggs in ursera tallow, a comfort on Zephras.",al={"tallow cooking secret","how are eggs cooked zephras"}}},ang={["profession:Cooking"]="As a cook, gathering strider meat and small eggs gives you practical experience and recipes suited to Zephras wildlife."},kw={"cooking","restocking the larders","shendar highlands","small eggs","strider meat","ursera tallow","zephras"},m={id=92553},src={"In-game quest text: Restocking the Larders"},fv=true}
E["quest:92579"] = {t="quest",n="To Valanaar",z="zephras",s="Aonda sends an urgent report across the island to Valanaar, where the peacekeepers prepare for a growing threat. Their leader, Valennia Stormfist, must ready her people as conflict with the cult draws near.",h="Aonda sends an urgent report across the island to Valanaar, where the peacekeepers prepare for a growing...",sec={{t="An Urgent Dispatch",b="After you help defend Shen'dar and its pylon, Aonda entrusts you with urgent word for Valennia Stormfist. Valanaar lies at the island's southeastern edge, where the peacekeepers keep their headquarters under Valennia's command. Aonda warns that the peaceful days are ending. Valennia must prepare her people for an inevitable clash with the aggressive, expanding cult.",sp=0},{t="The Gathering Storm",b="The peacekeepers avoided direct conflict with the mysterious cult until its incursions drove tensions to a breaking point. After reading Aonda's report, Valennia knows they must gather their remaining forces and plan a defense. The cult may turn its attention to Valanaar itself.",sp=1}},faq={{q="Who sends you to Valanaar?",a="Aonda, a highlander in Shen'dar, sends you to Valanaar. After you help secure the village and pylon from the looming cultist threat, she entrusts you with an urgent written report to carry across the island.",al={"who gives to valanaar","quest giver to valanaar","who sends me to valanaar"}},{q="Who is Valennia Stormfist?",a="Valennia Stormfist leads the island's peacekeepers from their headquarters in Valanaar. She is responsible for local defense and order, including responses to the cult's aggressive expansion.",al={"who is valennia stormfist","valennia leader","valennia"}},{q="What is Valanaar?",a="Valanaar is a settlement at the island's southeastern edge. It is the peacekeepers' base under Valennia Stormfist, as well as a refuge and community hub for townsfolk.",al={"what is valanaar","where is valanaar","valanaar location"}},{q="What is the purpose of Aonda's report?",a="Aonda's report describes the cult's growing threat and the events that put Shen'dar and its pylon at risk. The peacekeepers avoided direct conflict, but the cult's rapid expansion makes a clash inevitable. Valanaar must prepare its defenses.",al={"why deliver report","what is aonda report","what is in the letter"}},{q="What threat does the cult pose to the island?",a="The report warns that an unnamed cult is expanding rapidly across the island. The peacekeepers kept their distance to avoid open warfare, but the cult's recent aggressive moves against places such as Shen'dar mean conflict can no longer be avoided.",al={"what cult to valanaar","who is the cult","cult threat island"}},{q="What happens once you reach Valanaar?",a="When Valennia receives the grim news, she must confer with her remaining peacekeepers and plan a defense against future cult attacks. As she coordinates their plans, she invites travelers to help the townsfolk around Valanaar.",al={"what to do after delivering report","what next to valanaar"}}},kw={"aonda","cult","peacekeepers","shen'dar","to valanaar","valanaar","valennia stormfist"},m={faction="Horde",id=92579},src={"In-game quest text: To Valanaar"},fv=true}
E["quest:92595"] = {t="quest",n="The Windshapers",z="zephras",s="Among the wind spirits, The Windshapers seek a way to keep Zephras and the Shen'dorei alive. Illaya Amberwind welcomes new recruits to their work, as dangers gather in Skywall.",h="Among the wind spirits, The Windshapers seek a way to keep Zephras and the Shen'dorei alive.",sec={{t="Mandate of the Windshapers",b="Illaya Amberwind welcomes new recruits into the Windshapers, who commune with the wind spirits and protect the Shen'dorei. The order seeks those born with spiritual perception. They hope to mend the growing rift between their people and the elemental forces that sustain their aerial realm. Every Windshaper bears that burden.",sp=0},{t="Trials on Zephras",b="The Al'Aketh bring turmoil within Skywall, and the elemental plane holds dangers of its own. The Windshapers believe Zephras can endure and the Shen'dorei can weather the storm only if they restore their bond with the spirits of the winds.",sp=0}},faq={{q="Who are the Windshapers?",a="The Windshapers commune with the wind spirits and protect the Shen'dorei. Guided by Illaya Amberwind, they seek people gifted with skysight to restore their bond with the spirits and preserve their imperiled homeland.",al={"who are windshapers","windshapers faction","what do windshapers do"}},{q="What is skysight?",a="Skysight is an inborn spiritual sensitivity that lets a person connect with the aerial elements. Formal shaman training is not needed, but commanding skysight is essential to reaching the spirits of the winds.",al={"what is skysight","skysight lore"}},{q="Who is Illaya Amberwind?",a="Illaya Amberwind guides the Windshapers and recognizes spiritual gifts in travelers. She welcomes those with skysight and explains the order's work, the peril facing Zephras, and the trials confronting the Shen'dorei.",al={"who is illaya","illaya amberwind"}},{q="What is Zephras?",a="Zephras is an aerial land or settlement enduring severe hardships and internal unrest. The Windshapers struggle to protect it and preserve a future for their people there.",al={"what is zephras","zephras lore"}},{q="Who are the Al'Aketh?",a="The Al'Aketh are a hostile faction within, troubling the Windshapers and the Shen'dorei. Their threat adds to the dangers of surviving within Skywall.",al={"who are the al'aketh","alaketh threat"}},{q="Who are the Shen'dorei?",a="The Shen'dorei are the people the Windshapers seek to protect. The Al'Aketh and perilous conditions in Skywall threaten their survival, so the Windshapers seek to secure it by restoring balance with the winds.",al={"who are shendorei","shen'dorei lore"}}},ang={["class:Shaman"]="As a shaman, you may commune with the elements through training, but skysight can appear in others too. The Windshapers share this spiritual duty with elemental callers.",["race:Skyborne"]="As a Skyborne, you know the Windshapers fight for the Shen'dorei's survival and home amid the perils of Skywall and Zephras."},kw={"al'aketh","illaya amberwind","shen'dorei","skysight","skywall","windshapers","zephras"},rel={"topic:skywall","topic:shaman"},m={faction="Horde",id=92595},src={"In-game quest text: The Windshapers"},fv=true}
E["quest:92596"] = {t="quest",n="The High Order",z="zephras",s="On Zephras, Rathiril Sunlance tells newcomers why the shen'dorei must now stand alone. Their elemental benefactors are gone, so these Highborne descendants of Eldre'Thalas turn to ancient arcane magic to protect their people.",h="On Zephras, Rathiril Sunlance tells newcomers why the shen'dorei must now stand alone.",sec={{t="A People on Their Own",b="The shen'dorei on Zephras are working to reclaim their strength and choose their own path. For a long time, elemental benefactors protected them. Now those patrons are gone, leaving the people exposed to strife within and dangers around them. Rathiril Sunlance seeks those gifted in arcane magic to help preserve their people and build their strength on their own.",sp=0},{t="Legacy of Eldre'Thalas",b="The shen'dorei carry the legacy of Eldre'Thalas and an innate wellspring of arcane energy. Even those never formally trained in wizardry share that power. The High Order sees it as the destiny of Highborne descendants to wield these ancient gifts. With them, the shen'dorei hope to resist the Al'Aketh within and face the many threats to their home on Zephras.",sp=0}},faq={{q="What is the High Order?",a="Among the shen'dorei on Zephras, the High Order works for their people's survival. Founded by descendants of the Highborne of Eldre'Thalas, it seeks to wield their ancient arcane gifts so their society can defend itself and endure on its own.",al={"who are the high order","what is high order","high order purpose"}},{q="Who is Rathiril Sunlance?",a="Rathiril Sunlance is an elf associated with the High Order on Zephras. He teaches newcomers about local arcane energies, the shen'dorei's plight, and their resolve to survive without their former elemental patrons.",al={"who is rathiril","rathiril sunlance lore","sunlance"}},{q="What is Zephras?",a="Zephras is a floating isle in Skywall where Rathiril Sunlance and his kin now live. Arcane energies fill the isle, and the shen'dorei face dangers within their people and uncertainty about their security from outside threats.",al={"where is the high order","what is zephras","zephras lore"}},{q="Who are the shen'dorei?",a="The shen'dorei are elf descendants of the Highborne from Eldre'Thalas. Now living on Zephras, they have an innate bond with arcane magic and seek to stand on their own.",al={"who are the shendorei","shen dorei","shendorei lore"}},{q="Who were the elemental benefactors?",a="The elemental benefactors were powerful elemental beings who once aided and protected the shen'dorei. They are gone, so the people of Zephras must rely on their own magic and resourcefulness.",al={"who are the elementals","elemental patrons","elemental benefactors"}},{q="What are the Al'Aketh?",a="The Al'Aketh are an internal faction or threat that endangers the shen'dorei on Zephras. The High Order organizes defenses in part to face such threats from within.",al={"what is alaketh","al aketh threat","internal threats zephras"}},{q="What is the connection between the High Order and Eldre'Thalas?",a="The shen'dorei's ancestors came from Eldre'Thalas, the ancient Highborne city in Kalimdor known to many in the years after the Third War as Dire Maul. The High Order honors this heritage by preserving and wielding their ancient arcane gifts.",al={"eldrethalas connection","are they from dire maul","highborne origins"}}},ang={["class:Mage"]="Rathiril says that even adventurers without formal mage training carry strong arcane auras. Their shared magic is an inborn heritage, not only a learned discipline.",["race:Skyborne"]="As a Skyborne, you descend from the ancient Highborne of Eldre'Thalas. You must master your arcane gifts to stand on your own now that your elemental patrons are gone."},kw={"al'aketh","arcane","eldre'thalas","highborne","rathiril sunlance","shen'dorei","the high order","zephras"},rel={"topic:highborne","topic:mage"},m={faction="Alliance",id=92596},src={"In-game quest text: The High Order"},fv=true}
E["quest:92597"] = {t="quest",n="Reading the Ley Lines",z="zephras",s="On Zephras Isle, young Skyborne seek the arcane currents beneath their feet. Falorne Fallwind sends them to Thendal Grove to feel power rising through the elemental plane.",h="On Zephras Isle, young Skyborne seek the arcane currents beneath their feet.",sec={{t="Arcane Currents of the Elemental Plane",b="Ley lines run beneath Zephras Isle, even through the elemental plane. Strange elementals and the hostile Al'Aketh cross the island as these buried currents rise toward the surface. For those with the bloodline and knowledge to channel them, the exposed lines open a path to raw arcane power.",sp=0},{t="Highborne Legacy",b="Falorne Fallwind urges initiates to claim their Highborne ancestry instead of seeking favor from wind spirits. The local Windshapers and the Al'Aketh both look to such spirits. Fallwind believes survival amid the elemental plane's harsh powers depends on mastering the arcane force beneath the ground, rather than asking foreign creatures for mercy.",sp=0},{t="Thendal Standing Stones",b="Northeast of the settlement, Thendal Grove's ancient standing stones mark a powerful meeting of ley lines. Roiling winds and Al'Aketh converts surround this exposed place. There, initiates can attune their senses to the ley line's pulse and unleash the full potential of their natural racial abilities.",sp=0}},faq={{q="Who gives the quest Reading the Ley Lines?",a="Falorne Fallwind on Zephras Isle gives young Skyborne this rite as they learn to channel their ancestral arcane power.",al={"quest giver","falorne fallwind","who starts reading the ley lines"},it="identity"},{q="Where is the ley line located?",a="The ley line lies northeast of the settlement, at the Thendal Standing Stones in Thendal Grove, amid hostile elementals and Al'Aketh converts.",al={"ley line location","where is thendal grove","thendal standing stones location"},it="place",gp=true},{q="Why are ley lines present in the elemental plane?",a="Arcane conduits run beneath the ground even in the elemental plane. The ley lines have begun to break through the surface, giving Skyborne direct access to powerful currents.",al={"arcane in elemental plane","ley lines elemental plane lore"},it="origin"},{q="How does Falorne Fallwind view the Windshapers?",a="Falorne disdains the Windshapers' reverence for air spirits. He sees it as weak supplication to uncaring elemental beings, no better than the Al'Aketh's worship.",al={"falorne on windshapers","windshapers lore","windshapers vs highborne"},it="conflict"},{q="What ability is required to channel the ley line?",a="You use the Skyborne racial ability Read Ley Line while standing at the energy convergence by the standing stones.",al={"read ley line ability","how to read ley line","racial ability used"},gp=true},{q="What benefit does tapping into ley lines provide?",a="Tapping an exposed ley line channels raw arcane energy into the user, heightening magical prowess. Its effects vary with the nature of the conduit.",al={"what do ley lines do","benefits of ley lines"},it="power"},{q="Why does Falorne Fallwind want you to read the ley lines?",a="Falorne believes that reclaiming your Highborne heritage and drawing directly from arcane ley lines is the only path to your people's salvation in the elemental plane. He views groups like the Windshapers and the Al'Aketh with contempt for debasing themselves before uncaring elemental entities. In his eyes, survival demands mastering latent magic rather than relying on fickle spirits.",al={"falorne fallwind motive","why read ley lines","falorne fallwind ley lines why"},it="motive",add="e5a629f0"}},ang={["race:Skyborne"]="As a Skyborne, you awaken your innate Highborne ancestry and learn to channel subterranean ley energy into your spellcasting.",["class:Mage"]="As a Mage, you can draw on exposed ley lines as a reservoir of raw power amid elemental storms."},kw={"al'aketh","falorne fallwind","highborne","ley lines","reading the ley lines","skyborne","thendal grove","thendal standing stones","windshapers","zephras isle"},rel={"zone:zephras","topic:highborne","topic:elemental-plane"},m={start="Falorne Fallwind",level="4",faction="Alliance",id=92597},src={"Reading the Ley Lines"},fv=true}
E["quest:92598"] = {t="quest",n="The Gift of Skysight",z="zephras",s="On Zephras Isle, Ventaari Brightwish guides young Windshapers toward Skysight. At an Elemental Convergence, they awaken their perception and listen to the spirits.",h="On Zephras Isle, Ventaari Brightwish guides young Windshapers toward Skysight.",sec={{t="A Sacred Perception",b="Windshapers are born with a bond to the elemental forces that shape their world. They call its sacred faculty Skysight. This gift attunes mortal senses to the spiritual realm and reaches across the divide between the living and the unseen. In the wilds, a Windshaper can call on this inner vision. Near concentrated power, the bond grows stronger, bringing boons and wisdom whispered by the spirits.",sp=0},{t="The Convergence of Thendal Grove",b="Northeast of the settlement, ancient standing stones mark an Elemental Convergence in Thendal Grove. Raw energies gather at such places, where spirits linger. Ventaari Brightwish sends novices there to test their spiritual strength. Skysight grows with practice, like a faculty of body or mind. Windshapers must learn to read the elements' changing omens, for their people's survival depends on it.",sp=0}},faq={{q="What is the purpose of this quest?",a="Ventaari Brightwish sends novice Windshapers to an Elemental Convergence, where its power sharpens their Skysight.",al={"gift of skysight purpose","why do this quest","skysight training"},it="purpose"},{q="Who is Ventaari Brightwish?",a="Ventaari Brightwish guides and mentors young Windshapers on Zephras Isle, teaching them to honor and hone their elemental heritage.",al={"ventaari","who is ventaari brightwish","brightwish"},it="identity"},{q="What is an Elemental Convergence?",a="An Elemental Convergence gathers spiritual energy, often around ancient standing stones. Elemental spirits linger there, and powers such as Skysight grow stronger.",al={"what is elemental convergence","elemental convergence lore","thendal grove convergence"},it="place"},{q="Where is the Elemental Convergence located?",a="The Elemental Convergence lies among the standing stones in Thendal Grove, northeast of the settlement on Zephras Isle.",al={"where is the convergence","thendal grove location","standing stones location"},it="place",gp=true},{q="Can Skysight be used anywhere?",a="A Windshaper can call on Skysight anywhere. At an Elemental Convergence, its power deepens and nearby spirits may offer further insight.",al={"can i use skysight anywhere","skysight outside convergence","where to use skysight"},it="power"},{q="Why is Skysight considered essential for survival?",a="Skysight lets mortals perceive elemental spirits and heed the elements' warnings. Ventaari says this sight is vital for meeting danger and preserving their people.",al={"why is skysight important","skysight survival","elements survival"},it="why_wanted"},{q="Why does Ventaari Brightwish want you to use Skysight at the convergence?",a="Ventaari Brightwish seeks to train you in your innate Windshaper heritage. Like a muscle, Skysight must be exercised at places of power such as the Elemental Convergence so you can learn to bridge the distance between the mortal and spiritual realms. She believes that communing with the spirits and heeding what the elements tell your people is crucial to your very survival.",al={"why does ventaari want this","ventaari brightwish motive","why use skysight here"},it="motive",add="d2ee972c"}},ang={["race:Skyborne"]="As Skyborne, you inherit Skysight from elemental patrons. It anchors your cultural and spiritual identity.",["class:Shaman"]="As a shaman, you know an Elemental Convergence as sacred ground, where the boundary between mortal will and the elemental planes grows thin.",["faction:Horde"]="As Horde, you rely on the Windshapers' foresight to face Zephras Isle's unmapped dangers."},kw={"elemental convergence","elemental spirits","skysight","standing stones","thendal grove","ventaari brightwish","windshaper","zephras"},rel={"npc:ventaari-brightwish","zone:zephras"},m={start="Ventaari Brightwish",level="4",faction="Horde",id=92598},src={"The Gift of Skysight"},fv=true}
E["quest:92640"] = {t="quest",n="Desperate Times",z="zephras",s="Valennia Stormfist waits in Valanaar with a plan to strike the cult at its shrine. Lorthuna must be stopped there, but the Windshapers and the High Order must first set aside their deep tensions.",h="Valennia Stormfist waits in Valanaar with a plan to strike the cult at its shrine.",sec={{t="A Direct Strike",b="The cult cannot be safely faced in the open, so the defenders need a bolder plan. They will strike at the cult's shrine instead of fighting a long battle on unfavorable ground. If they eliminate Lorthuna before she completes her part in the cult's grand scheme, they can cripple the threat at its source.",sp=0},{t="Uniting Divided Factions",b="In Valanaar, Valennia Stormfist has spent time planning an assault on the shrine. The attack needs substantial reinforcements and strength united across the factions. Yet the Windshapers and the High Order remain divided by severe political tensions, putting their alliance at risk.",sp=0}},faq={{q="Who is Valennia Stormfist?",a="Valennia Stormfist is in Valanaar, where she has been planning an assault on the cult's shrine. The attack depends on cooperation between rival factions.",al={"who is valennia","valennia stormfist","where is valennia"}},{q="Who is Lorthuna?",a="Lorthuna is a key figure in the hostile cult. She is directing a critical scheme at the shrine, making her the target of the planned strike.",al={"who is lorthuna","lorthuna lore","cult leader lorthuna"}},{q="Why must the shrine be attacked directly?",a="The cult cannot be safely confronted in the open. The plan is to strike at the shrine and stop Lorthuna before her scheme comes to fruition.",al={"why attack shrine","cult attack reason"}},{q="What is the issue between the Windshapers and the High Order?",a="Tensions run high between the Windshapers and the High Order. Neither faction can carry out the assault on the shrine alone, so both must cooperate.",al={"high order windshapers tension","why are factions fighting","windshaper dispute"}},{q="Where is Valanaar?",a="Valanaar is where Valennia Stormfist is coordinating the plan and rallying allies for a strike against the cult's shrine.",al={"where is valanaar","valanaar location"}},{q="What is the overall goal of this mission?",a="The goal is to find Valennia Stormfist in Valanaar, learn the details of her planned strike, and help secure cooperation between the divided factions.",al={"desperate times objective","what is the plan desperate times"}}},kw={"cult","desperate times","high order","lorthuna","shrine","valanaar","valennia stormfist","windshapers"},rel={"quest:92595"},m={faction="Horde",id=92640},src={"In-game quest text: Desperate Times"},fv=true}
E["quest:92642"] = {t="quest",n="Disrupting Logistics",z="zephras",s="At the Gustberry Lowlands, Al'Aketh cultists are pressing a full-scale assault. Their healers keep the brawlers fighting, and the defenders need help before their lines give way.",h="At the Gustberry Lowlands, Al'Aketh cultists are pressing a full-scale assault.",sec={{t="A Desperate Defense",b="A fierce assault is bearing down on the defenders above the Gustberry Lowlands. Enemy forces are gathering, and the local lines are near breaking. The commanders expected substantial reinforcements from Valennia, but they must rely on whatever capable hands arrive. Strikes against the enemy's support may be the only way to hold the defense together.",sp=0},{t="Breaking the Cultist Line",b="Al'Aketh brawlers press forward in ranks, sustained by healers who mend their wounds. In the Gustberry Lowlands, taking out those healers can break the cultists' push. That gives the defenders a chance to rally and drive back the invasion.",sp=0}},faq={{q="What is the quest Disrupting Logistics?",a="Disrupting Logistics is a desperate defense against the Al'Aketh assault in the Gustberry Lowlands. A lone defender needs help taking out the enemy's front-line support before the defense collapses.",al={"what is disrupting logistics","disrupting logistics quest","gustberry lowlands quest"}},{q="Who are the Al'Aketh cultists attacking the lowlands?",a="Al'Aketh cultists are attacking the Gustberry Lowlands with brawlers and healers. Their organized front depends on healing support to keep pressure on the local defenders.",al={"who are alaketh","who is attacking gustberry lowlands","who are the cultists"}},{q="Why are the Al'Aketh healers specifically targeted?",a="The Al'Aketh healers keep the vanguard fighters pressing forward. Taking them out may break the assault's momentum and give the defenders a chance to rally and push the cultists back.",al={"why kill healers","why target alaketh healers"}},{q="Where does this assault take place?",a="The assault is taking place in the Gustberry Lowlands, directly down the hill from the defensive outpost. Al'Aketh brawlers and healers have overrun the lowlands and are pressing their attack.",al={"where is gustberry lowlands","gustberry lowlands location"}},{q="Who is Valennia?",a="Valennia appears to organize aid and reinforcements. The defender is exasperated that Valennia sent only one adventurer against a massive assault.",al={"who is valennia","valennia reinforcements"}},{q="Who commands the defense against the Al'Aketh?",a="A beleaguered defender offers the call for aid as their people near defeat before the Al'Aketh. The defender reveres 'the winds' and needs any fighting force that can turn the battle.",al={"who gives disrupting logistics","who are my people holding out"}}},ang={["class:Priest"]="As a priest, you know how healing support can sustain an offensive line. The Al'Aketh healers are the linchpin of the cultist assault.",["class:Rogue"]="As a rogue, you know the value of slipping behind enemy lines to eliminate healers and disrupt reinforcements."},kw={"al'aketh","brawlers","cultists","disrupting logistics","gustberry lowlands","healers","valennia"},m={faction="Horde",id=92642},src={"In-game quest text: Disrupting Logistics"},fv=true}
E["quest:92643"] = {t="quest",n="The Turncoat",z="zephras",s="A cultist of the Al'Aketh offers to defect and reveal what the cult intends for the island. You are sent to bring him from a secluded highland retreat northwest of Valanaar, where the meeting may be a trap.",h="A cultist of the Al'Aketh offers to defect and reveal what the cult intends for the island.",sec={{t="A Broken Oath",b="A cultist within the Al'Aketh ranks claims to know the cult's true intentions for the island. He offers to defect, but demands firm assurances of protection. The cult guards its plans closely, so reaching out may be worth the danger.",sp=0},{t="The Highland Hideout",b="The defector waits alone in a secluded residence in the highlands northwest of Valanaar. You must reach him with care. The meeting may be an Al'Aketh ambush meant to draw out those who pry into the cult's affairs.",sp=0},{t="Silence in the Highlands",b="The defector lies dead inside the secluded highland house. Assassins tracked him down and struck before an escort could arrive. Outside, fallen assassins mark the aftermath. A gleam on the dead turncoat's body hints that he left an answer behind.",sp=1}},faq={{q="Who is the turncoat?",a="The turncoat was a former member of the Al'Aketh cult who claimed to know the cult's true intentions for the island. He offered to defect and share what he knew in exchange for protection.",al={"who is the turncoat","who was the defector","turncoat identity"}},{q="What is the Al'Aketh?",a="The Al'Aketh are an enigmatic cult operating in the region. Their plans for the island remain hidden behind secrecy and zealotry, so local authorities risk much to reach deserters willing to speak.",al={"who are the alaketh","alaketh cult","what is alaketh"}},{q="Where is the defector hiding?",a="The defector hid in a secluded residence in the highlands northwest of Valanaar. He waited there for an escort, trusting in promises of protection.",al={"where is the turncoat hiding","turncoat location","where to find the turncoat"}},{q="What happened to the defector?",a="By the time anyone reached the secluded highland residence, assassins had tracked down and slain the defector. He was found dead inside the house, beyond questioning.",al={"what happened to the turncoat","did the defector die","who killed the turncoat"}},{q="What did the turncoat leave behind?",a="After the assassins outside were dealt with, a glint on the dead defector's body caught the eye. The shiny item remained, and may hold a clue to the secrets he carried.",al={"what shiny object","turncoat shiny item","shiny reflection body"}},{q="Why did the cultist decide to defect?",a="The cultist claims to know the Al'Aketh's true intentions for the island and will defect only with assurances of protection. What drove him to leave the cult is not known.",al={"why did the cultist defect","turncoat motive","why betray alaketh"}}},ang={["class:Rogue"]="Infiltration, defection, and ambush are familiar to a Rogue. Cultists who break ranks risk silence or a blade. The assassins outside show how secrecy can cut both ways in the highlands."},kw={"al'aketh","cultist","defector","highlands","the turncoat","turncoat","valanaar"},m={faction="Horde",id=92643},src={"In-game quest text: The Turncoat"},fv=true}
E["quest:92644"] = {t="quest",n="Unfortunate News",z="zephras",s="You find the turncoat dead before they can speak. A damaged blue crystal remains beneath the body, and you carry it to High Elder Talanaanis Shadowsong in Valanaar.",h="You find the turncoat dead before they can speak.",sec={{t="A Broken Rendezvous",b="You reach the rendezvous and find the defecting cultist already slain. Their body is still warm. Beneath it lies a small, glowing blue crystal, damaged but still humming. You carry it to High Elder Talanaanis Shadowsong in Valanaar.",sp=0},{t="Shadowsong's Investigation",b="You return to Valanaar alone and tell High Elder Talanaanis Shadowsong that the turncoat died before giving testimony. The loss of a living contact is a serious setback. Yet the damaged blue crystal catches the High Elder's eye. He finds it interesting and takes it from you.",sp=1}},faq={{q="What is the quest Unfortunate News?",a="You find the defecting cultist dead before they can speak. Beneath the body lies a damaged, glowing blue crystal, which you carry to High Elder Talanaanis Shadowsong.",al={"what is unfortunate news","unfortunate news quest","unfortunate news wow forever"}},{q="Who was the turncoat cultist?",a="The turncoat was a defecting cultist you were sent to meet. They were killed before they could speak or escape, leaving a still-warm body and a damaged crystal.",al={"who is the dead turncoat","who died in unfortunate news","turncoat cultist"}},{q="Who is High Elder Shadowsong?",a="Talanaanis Shadowsong is an elf and the High Elder in Valanaar. He directs investigations into the cultists and receives the damaged crystal from the turncoat's body.",al={"who is shadowsong in valanaar","where is talanaanis shadowsong","talanaanis shadowsong"}},{q="What is the damaged blue crystal?",a="The damaged blue crystal is a small, glowing crystal found beneath the fallen turncoat. High Elder Shadowsong finds it interesting and takes it from you.",al={"what is the glowing crystal","blue crystal from cultist","damaged crystal unfortunate news"}},{q="Where does this quest take place?",a="Valanaar is where High Elder Talanaanis Shadowsong resides. You return there with your report and the recovered crystal.",al={"where is valanaar","valanaar location","turn in unfortunate news"}},{q="How does this quest connect to The Turncoat?",a="This follows The Turncoat, in which you set out to find the defecting cultist. You arrive too late to save them.",al={"what quest comes before unfortunate news","unfortunate news prequel","the turncoat quest"}}},ang={["class:Mage"]="As a Mage, you may recognize the damaged, glowing blue crystal as an artifact. High Elder Shadowsong investigates the cultists and takes the crystal for study."},kw={"cultist","glowing crystal","shadowsong","talanaanis shadowsong","turncoat","unfortunate news","valanaar"},rel={"quest:92643"},m={faction="Horde",id=92644},src={"In-game quest text: Unfortunate News"},fv=true}
E["quest:92645"] = {t="quest",n="Breaking the Breaker",z="zephras",s="In the Gustberry Lowlands, cultists press the defenders hard. Commander Belguilos leads the assault from her hillside villa, and striking her there may be the defenders’ only chance to survive.",h="In the Gustberry Lowlands, cultists press the defenders hard.",sec={{t="A Desperate Defense",b="Cultists assault the Gustberry Lowlands, driving the local defenders to the brink. Repelling them seems nearly impossible while Commander Belguilos directs the attack. All fear her as “the Breaker.”\n\nHer villa is the operation’s base. Slaying her there is perilous, near-suicidal, yet passivity leaves the defenders doomed.",sp=0},{t="The Fallen Peacekeeper",b="Before she commanded the cultists, Belguilos kept order as a peacekeeper. Even then, those around her found something deeply unsettling in her manner. When the cult’s influence spread beyond control, she embraced its extremism. Now she commands the cultists and is a terror.",sp=0}},faq={{q="Who is Belguilos the Breaker?",a="Belguilos, called “the Breaker,” commands the cultist attack. Before joining the cult, she served as a peacekeeper, though those around her found her unsettling even then.",al={"who is belguilos","who is the breaker","cult commander"}},{q="Where can Commander Belguilos be found?",a="Commander Belguilos is at the villa at the base of the hill in the Gustberry Lowlands. From there, she coordinates the cultist assault on the local defenders.",al={"where is belguilos","belguilos location","where to find the breaker"}},{q="Why must Belguilos be eliminated?",a="The cultists’ onslaught is nearly impossible to repel while Belguilos directs it. Eliminating her breaks the cult’s leadership and gives the defenders a real chance to survive.",al={"why kill belguilos","cult attack reason","why is breaker dangerous"}},{q="What was Belguilos's past before joining the cult?",a="Before the cult’s influence spread beyond control, Belguilos served as a peacekeeper. Those who knew her found something deeply unsettling in her even then.",al={"what was belguilos before","was belguilos good","peacekeeper cultist"}},{q="What is the significance of the blessing of the four winds?",a="The blessing of the four winds is an expression of profound relief and gratitude among the defenders after the terrifying cult commander has been permanently stopped.",al={"four winds meaning","who says four winds bless you"}},{q="What are the Gustberry Lowlands?",a="The Gustberry Lowlands are contested ground where the cult assault unfolds. Commander Belguilos can be found at a villa at the base of the hill.",al={"what is gustberry lowlands","where is breaker quest"}}},ang={["race:Skyborne"]="The defenders invoke the four winds to bless the hero after the cultists are stopped.",["class:Warrior"]="As a warrior, you face Commander Belguilos, a former peacekeeper feared as “the Breaker.”"},kw={"belguilos","breaking the breaker","commander belguilos","cult commander","gustberry lowlands","peacekeeper","the breaker","villa"},m={faction="Horde",id=92645},src={"In-game quest text: Breaking the Breaker"},fv=true}
E["quest:92646"] = {t="quest",n="Confront Lorthuna",z="zephras",s="Elaadrin Evengale and Ayessa Dawnsinger pursue High Priestess Lorthuna through a portal into the Rohashi Spires above Zephras. They call for your aid before she can escape justice or strengthen her power.",h="Elaadrin Evengale and Ayessa Dawnsinger pursue High Priestess Lorthuna through a portal into the Rohashi...",sec={{t="Pursuit into the Spires",b="High Priestess Lorthuna flees through a mystic gateway into the Rohashi Spires above Zephras. An injured ally remains behind at the portal's threshold. Elaadrin Evengale and Ayessa Dawnsinger follow her into the heights and call for your help before she escapes justice or strengthens her power.",sp=0},{t="The Cost of the Battle",b="After the clash in the spires, Valennia and her surviving forces need a healer's care. They are escorted to recover within the High Elder's residence. Lorthuna has met them in combat, and the coalition is battered with its resources stretched thin.",sp=1},{t="An Island Left Vulnerable",b="After the battle, Muln confers on the Windshapers and their continuing mission, then departs for mainland Azeroth. Zephras remains critically vulnerable. The leaders left behind must urgently plan defenses against the dangers that still threaten the island.",sp=1}},faq={{q="Who is High Priestess Lorthuna?",a="High Priestess Lorthuna is a powerful adversary who flees through a portal to the Rohashi Spires above Zephras. Ayessa Dawnsinger and Elaadrin Evengale pursue her there.",al={"who is lorthuna","what is lorthuna","high priestess lorthuna lore"}},{q="What are the Rohashi Spires?",a="The Rohashi Spires are heights above the island of Zephras. High Priestess Lorthuna flees there through a portal, and her pursuers follow.",al={"what are rohashi spires","where is the portal going","rohashi spires location"}},{q="Who pursued Lorthuna into the portal?",a="Elaadrin Evengale and Ayessa Dawnsinger pursue High Priestess Lorthuna through the portal as she flees to the spires. They call for your aid.",al={"who went after lorthuna","ayessa and elaadrin","who enters the portal"}},{q="What happened to Valennia and her forces?",a="Valennia and her surviving forces need immediate care after the fighting. Healers tend them, and they are escorted to recover in the High Elder's residence.",al={"who is valennia","what happened to valennia","valennia forces"}},{q="What is Muln's role in these events?",a="Muln is an ally associated with the Windshapers who departs for mainland Azeroth after discussing their future and continuing mission.",al={"who is muln","muln leaving zephras","where did muln go"}},{q="Is the island of Zephras safe after Lorthuna is confronted?",a="Zephras remains critically vulnerable after the confrontation. Its leaders must urgently plan defenses against the dangers threatening the island.",al={"what happens to zephras","is zephras safe now","state of zephras island"}}},ang={["class:Priest"]="As a priest, you face High Priestess Lorthuna, a corrupted spiritual leader among the spires. The battle against her carries weight for those who defend against dark doctrine.",["class:Shaman"]="As a shaman, you share a spiritual stake in the Windshapers' work to guide elemental balance on Zephras. You can help ensure that harmony survives Lorthuna's threat."},kw={"ayessa dawnsinger","confront lorthuna","elaadrin evengale","high priestess lorthuna","lorthuna","muln","rohashi spires","valennia","windshapers","zephras"},rel={"npc:ayessa-dawnsinger","quest:92595"},m={faction="Horde",id=92646},src={"In-game quest text: Confront Lorthuna"},fv=true}
E["quest:92679"] = {t="quest",n="Blood Tithe",z="zephras",s="In Valanaar, Alvarion Windfield seeks aid for the orchard that sustains his family. Pain keeps the Skyborne farmer from his work, so he sends travelers west to his wife, Aamelia, who tends their lowland farm.",h="In Valanaar, Alvarion Windfield seeks aid for the orchard that sustains his family.",sec={{t="A Plea in Valanaar",b="Alvarion Windfield has come from his homestead to Valanaar in search of capable fighters. Pain leaves him visibly injured, and he fears for the livelihood his farm provides. He asks you to travel west into the lowlands, where his wife Aamelia tends their family orchard.",sp=0},{t="Trouble in the Lowlands",b="The Windfield Orchard lies in the lowlands west of Valanaar. Alvarion is too ill to tend the farm, so Aamelia Windfield bears its burdens alone. Reach the western valley, learn what threatens the orchard, and lend the family your strength.",sp=0}},faq={{q="Who is Alvarion Windfield?",a="Alvarion Windfield is a Skyborne farmer in Valanaar who seeks fighters to protect his home. Though severe pain troubles him, he sends travelers to his wife, Aamelia, at their orchard.",al={"who is alvarion","alvarion windfield lore","who gives blood tithe"}},{q="Where is the Windfield Orchard located?",a="The Windfield Orchard lies in the lowlands west of Valanaar. Alvarion directs travelers there to find his wife, Aamelia Windfield, who oversees the farm's defense.",al={"where is windfield orchard","aamelia windfield location","how to find the orchard"}},{q="Why is Alvarion in pain?",a="Alvarion's affliction is unknown when travelers meet him. Intense, debilitating pain troubles him as he speaks, lending urgency to his plea for help.",al={"why is alvarion hurting","what is wrong with alvarion","alvarion pain"}},{q="Who is Aamelia Windfield?",a="Aamelia Windfield is Alvarion's wife and tends their family orchard west of Valanaar. He sends willing travelers to help her defend their land.",al={"who is aamelia","aamelia windfield lore","alvarion wife"}},{q="What is the task in Blood Tithe?",a="Alvarion Windfield seeks help in Valanaar for his struggling farm. He asks you to find his wife, Aamelia, at their lowland orchard.",al={"blood tithe quest summary","what is blood tithe about","farm under attack valanaar"}},{q="What is Valanaar's significance here?",a="Valanaar is a settlement where travelers and Skyborne gather. Alvarion comes there seeking capable fighters to save his orchard from peril.",al={"valanaar lore","where does blood tithe take place","what is valanaar"}}},ang={["race:Skyborne"]="As a Skyborne farmer, Alvarion Windfield suffers and calls desperately for aid. His hardship shows what Skyborne face beyond Valanaar."},kw={"aamelia windfield","alvarion windfield","blood tithe","skyborne","valanaar","windfield orchard"},rel={"topic:skyborne","quest:92579"},m={id=92679},src={"In-game quest text: Blood Tithe"},fv=true}
E["quest:92682"] = {t="quest",n="Make Yourself Useful",z="zephras",s="At Windfield Orchard, Ferauu's bandits are taking stormapples before their share is due. Some hungry outlaws have broken ranks to pick the trees early. Drive them off, and the orchard keeper will respect you.",h="At Windfield Orchard, Ferauu's bandits are taking stormapples before their share is due.",sec={{t="Trouble at Windfield Orchard",b="Windfield Orchard gives Ferauu's bandits a regular share of its fruit harvest. Ferauu leads the crew, but some outlaws cannot wait for his scheduled visit. They slip into the orchard early to pick stormapples for themselves.",sp=0},{t="Thieves Among Thieves",b="The orchard caretaker puts ambitious newcomers to work before Ferauu arrives. The keeper asks you to secure the ripe stormapples and drive off hungry bandits trespassing among the trees. They have gone behind Ferauu's back to take his share. The keeper says Ferauu would likely execute them for it.",sp=0}},faq={{q="Who is Ferauu?",a="Ferauu leads the bandits who demand a regular share of Windfield Orchard's harvest. He rules his crew with ruthless discipline, though some hungry bandits have slipped in early behind his back.",al={"who is ferauu","ferauu lore","ferauu bandit leader"}},{q="What is Windfield Orchard?",a="Windfield Orchard is a local farm that grows stormapples. Ferauu's bandits demand part of its fruit harvest in exchange for leaving the orchard in peace.",al={"what is windfield orchard","windfield orchard lore","stormapple orchard"}},{q="Why are hungry bandits prowling the stormapple trees?",a="Hungry bandits in Ferauu's crew entered the orchard before the scheduled harvest pickup to steal stormapples for themselves. They broke ranks and tampered with the crop, so the orchard keeper asks you to drive them out.",al={"why kill hungry bandits","why are bandits at the orchard","hungry bandits lore"}},{q="What are stormapples?",a="Stormapples are a fruit grown at Windfield Orchard. They feed people and make up the harvest tribute Ferauu's bandits demand.",al={"what are stormapples","ripe stormapples"}},{q="Does Ferauu know his bandits are sneaking into the orchard?",a="Ferauu does not know these bandits came early. The orchard keeper says they went rogue, and Ferauu would likely execute them if he caught them taking fruit before his arrival.",al={"does ferauu know about the bandits","ferauu double cross"}},{q="Who tasks you with Make Yourself Useful?",a="The orchard caretaker offers you work at Windfield Orchard and watches the groves from a nearby window. Faced with bold newcomers looking for work or food, the keeper tests your mettle by sending you against the intruding bandits.",al={"who gives make yourself useful","make yourself useful quest giver"}}},ang={["class:Rogue"]="As a rogue, you can spot the lack of discipline among amateur thieves when bandits betray their crew to steal stormapples early."},kw={"bandits","ferauu","hungry bandits","make yourself useful","orchard","ripe stormapples","stormapples","windfield orchard"},rel={"topic:rogue"},m={id=92682},src={"In-game quest text: Make Yourself Useful"},fv=true}
E["quest:92683"] = {t="quest",n="Flutterfly Dust",z="zephras",s="In the Gustberry Lowlands, Flutterfly Dust draws a homesteader's interest. Travelers gather it from giant flutterflies while bandits threaten anyone who ventures alone into the fields.",h="In the Gustberry Lowlands, Flutterfly Dust draws a homesteader's interest.",sec={{t="The Giants of Gustberry",b="Giant flutterflies drift through the outer fields and orchards of the Gustberry Lowlands. Their wings shed fine dust, and you can gather it in bulk. Nearby homesteaders want the powder for practical household needs. Yet the insects remain wild.",sp=0},{t="Swatters and Shakes",b="A Flutterfly Swatter brings dust down with a blunt strike. Most flutterflies panic, take to the air, and shake loose piles of powder. Some turn and strike back when provoked. Usually, they are docile.",sp=0},{t="Unspoken Applications",b="The dust is messy to gather and clings to clothing and gear for weeks. The homesteader eagerly awaits its delivery, since bandits make solo trips into the fields too dangerous. Ask what the powder is for, and the resident offers only vague words about general stuff and things.",sp=0}},faq={{q="What is flutterfly dust used for?",a="The resident says the dust has practical household uses, but keeps its purpose vague, calling it general stuff and things.",al={"what is flutterfly dust","flutterfly dust use","what is the dust for"}},{q="Where are flutterflies found?",a="Giant flutterflies roam the outer fields near the local orchard, especially across the Gustberry Lowlands. Bandits nearby make gathering there dangerous for anyone alone.",al={"where are flutterflies","flutterfly location","gustberry lowlands bugs"}},{q="Are flutterflies aggressive?",a="Flutterflies are usually docile and flee when disturbed. Some defend themselves when swatted or provoked, then release their wing dust.",al={"are flutterflies dangerous","do flutterflies attack","flutterfly behavior"}},{q="How is flutterfly dust collected?",a="A Flutterfly Swatter delivers a firm blow to the oversized insects. As they react, some shake their rumps and scatter piles of wing dust for gathering.",al={"how to get dust","flutterfly swatter","collect flutterfly dust"}},{q="Why does the resident need someone else to gather the dust?",a="The resident lives alone and cannot easily leave the homestead to gather the dust. Bandits across the surrounding lowlands make a trip far into the fields too dangerous.",al={"why need help","bandit threat gustberry","why quest giver asks"}},{q="Why is the resident evasive about the dust's true purpose?",a="The resident refuses to explain the dust's household use and waves off questions with talk of things and stuff. Its purpose remains unexplained.",al={"why so secret","secret dust recipe"}}},kw={"bandits","flutterfly","flutterfly dust","flutterfly swatter","gustberry lowlands","orchard","wing dust"},m={id=92683},src={"In-game quest text: Flutterfly Dust"},fv=true}
E["quest:92684"] = {t="quest",n="Ornery Ornery Galestriders",z="zephras",s="In the Gustberry Lowlands, an orchard farmer's poor harvest is under threat from galestriders raiding the stormapples. Drive off the boldest birds to save the remaining fruit and bring home tenderloins for dinner.",h="In the Gustberry Lowlands, an orchard farmer's poor harvest is under threat from galestriders raiding the...",sec={{t="Defending the Orchard",b="A poor harvest has left Gustberry Lowlands farmers with little to spare. Now wild galestriders strip ripe stormapples from orchard branches and threaten what fruit remains. The farmer needs the boldest birds driven off or culled before the crop is gone.",sp=0},{t="Lowland Terrors",b="Lowlands galestriders are larger and more bad-tempered than their highland kin. Take care near these towering birds, traveler; one powerful kick can badly hurt or kill a fighter. Their tenderloins give hungry locals a rare, substantial meal.",sp=0}},faq={{q="Why are the galestriders causing problems for the farmer?",a="Galestriders raid the orchard for stormapples. With the harvest already meager, their feeding threatens the local food supply.",al={"what are galestriders stealing","why kill galestriders","stormapple orchard"}},{q="How dangerous are lowlands galestriders?",a="Lowlands galestriders are larger and more aggressive than their highland kin. Their powerful kicks can kill a traveler caught off guard.",al={"how dangerous are galestriders","galestrider attacks","are galestriders strong"}},{q="What does the farmer want from the galestriders?",a="The farmer wants travelers to cull aggressive lowlands galestriders and collect their tenderloins for dinner.",al={"galestrider meat","what do galestriders drop","tenderloin quest"}},{q="Where are these galestriders found?",a="Ornery lowlands galestriders roam the Gustberry Lowlands, especially near farmsteads and orchards where they forage for stormapples.",al={"where are galestriders found","galestrider location","gustberry lowlands"}},{q="How do lowlands galestriders compare to highlands galestriders?",a="Lowlands galestriders are larger and more ill-tempered than their highland kin. Their kicks can badly injure a traveler.",al={"highlands vs lowlands galestriders","galestrider varieties"}},{q="What are stormapples?",a="Stormapples are an orchard crop grown in the region. With the harvest scarce, the remaining trees need protection from foraging galestriders.",al={"what are stormapples","orchard harvest"}}},ang={["profession:Cooking"]="Lowlands galestriders yield hearty tenderloins for a substantial hot meal, a welcome change from lean harvests and fruit.",["class:Hunter"]="As a hunter, watch for the powerful kicks and aggressive temper of lowlands galestriders. They differ from their highland kin."},kw={"galestrider","gustberry lowlands","lowlands galestrider","orchard","ornery galestriders","stormapples","tenderloin"},m={id=92684},src={"In-game quest text: Ornery Ornery Galestriders"},fv=true}
E["quest:92685"] = {t="quest",n="The Hills Have Eyes",z="zephras",s="Aamelia faces a bandit assault in the Gustberry Lowlands, and Ferauu’s raid draws near. She sends travelers to strike a camp in the northern hills before the bandits gather.",h="Aamelia faces a bandit assault in the Gustberry Lowlands, and Ferauu’s raid draws near.",sec={{t="A Preemptive Strike",b="Aamelia faces an approaching attack in the Gustberry Lowlands. Ferauu leads the outlaws threatening her farm. She asks you to strike their camp in the hills to the north. Thin the highwaymen’s ranks before they gather, and Aamelia hopes to weaken their attack and gain time before they arrive.",sp=0},{t="Renewed Hope and Retribution",b="Aamelia asks you to bring back blood-stained masks from the fallen highwaymen as proof of the ambush. Grimly, she jokes about stitching them into a blanket for Ferauu. She is glad her tormentors met fierce resistance.\n\nThe strike on the northern camp ends weeks of hopeless waiting. Aamelia has new courage to face Ferauu and his main band when they arrive.",sp=1}},faq={{q="What is The Hills Have Eyes?",a="Aamelia asks travelers to strike a bandit camp in the northern hills before Ferauu’s highwaymen attack her farm. She also asks for blood-stained masks from the fallen bandits.",al={"hills have eyes quest","what is this quest","what is the hills have eyes"}},{q="Who gives the quest The Hills Have Eyes?",a="Aamelia gives the request from her farm in the Gustberry Lowlands. Weeks of waiting for the bandits have left her dreading their attack.",al={"who gives the hills have eyes","who is aamelia","quest giver aamelia"}},{q="Who is Ferauu?",a="Ferauu leads the highwayman bandits around the Gustberry Lowlands. His gang threatens Aamelia’s farm and is preparing to attack.",al={"who is ferauu","ferauu boss","bandit leader ferauu"}},{q="Where are the highwayman bandits located?",a="Highwayman Bandits have camps throughout the Gustberry Lowlands, including a small camp in the hills directly north of Aamelia’s farm.",al={"gustberry lowlands bandits","where are the bandits","bandit camp hills"}},{q="Why does Aamelia want blood-stained bandit masks?",a="Aamelia asks for blood-stained masks as proof of the ambush. The strike on the bandits’ camp helps even the odds before Ferauu’s attack.",al={"why collect masks","why blood stained masks","what are the masks for"}},{q="What happens after completing the quest?",a="After the hill camp is struck, Aamelia finds hope for her farm. Ferauu and his remaining bandits are due to arrive at any moment, and she must face their attack.",al={"what happens after the hills have eyes","next quest aamelia","ferauu attack"}}},ang={["profession:Tailoring"]="Aamelia grimly jokes about stitching a blanket from blood-stained bandit masks for Ferauu."},kw={"aamelia","bandit masks","blood-stained bandit masks","ferauu","gustberry lowlands","highwayman bandits","the hills have eyes"},m={id=92685},src={"In-game quest text: The Hills Have Eyes"},fv=true}
E["quest:92693"] = {t="quest",n="Standing Our Ground",z="zephras",s="Aamelia Windfield gives you one last chance to retreat to Valanaar before the bandits close in. You have helped the local defenders prepare, yet the coming fight still seems doomed.",h="Aamelia Windfield gives you one last chance to retreat to Valanaar before the bandits close in.",sec={{t="A Desperate Last Stand",b="Aamelia Windfield gives you one last chance to return safely to Valanaar. You have helped the local defenders prepare for the bandits, but the fight ahead looks grim. Will you stand with them, or leave before the clash?",sp=0},{t="Confronting the Bandit Leader",b="When you signal that you are ready, you go with Aamelia Windfield to face the bandit leader. Defeating the brigand ends the immediate threat. Aamelia can hardly catch her breath, shocked and relieved that their gamble succeeded.",sp=1}},faq={{q="Who gives the quest Standing Our Ground?",a="Aamelia Windfield gives you one last chance to retreat before you face the bandit leader.",al={"who gives standing our ground","quest giver standing our ground","standing our ground npc"}},{q="Who do you fight in Standing Our Ground?",a="You face the bandit leader threatening the local defenders. Aamelia gathers her resolve and confronts the leader with you.",al={"who is the bandit leader standing our ground","standing our ground boss","bandit leader standing our ground"}},{q="What is Valanaar in relation to this quest?",a="Valanaar is the nearby settlement where Aamelia offers you a chance to retreat if you do not want to risk your life in the fight.",al={"where is valanaar standing our ground","standing our ground retreat town","valanaar quest"}},{q="Why does Aamelia describe the battle as a lost cause?",a="Aamelia and her companions believe the odds are against them. They see the standoff as a desperate last stand, and survival seems almost impossible without outside help.",al={"why is standing our ground a lost cause","standing our ground story","aamelia windfield struggle"}},{q="What happens once the confrontation is over?",a="The bandit leader is defeated. Aamelia Windfield is shocked and relieved that the ordeal is over, and struggles to steady her racing heart.",al={"what happens after beating bandit leader standing our ground","standing our ground turn in","does aamelia survive"}},{q="What leads up to this final stand?",a="You helped the defenders prepare for the bandit threat, giving them a fighting chance before the final confrontation.",al={"standing our ground prerequisites","quests before standing our ground"}}},kw={"aamelia windfield","bandit leader","bandits","lost cause","standing our ground","valanaar"},rel={"quest:92579"},m={id=92693},src={"In-game quest text: Standing Our Ground"},fv=true}
E["quest:92698"] = {t="quest",n="What Is My Purpose?",z="zephras",s="In the orchard fields, a Malfunctioning Cyclone Construct wanders without purpose. Its broken speech has repeated for decades, since the wind elementals departed. Aamelia Windfield knows what locals remember of its past.",h="In the orchard fields, a Malfunctioning Cyclone Construct wanders without purpose.",sec={{t="The Wandering Construct",b="A Malfunctioning Cyclone Construct paces through the fields, caught in a broken loop. Muffled fragments come from beneath its armor, repeating errors and questions about its purpose. Decades alone have left its old instructions corrupted or forgotten. It looks imposing, but threatens no one who passes. Its broken voice carries over the soil as it wanders without purpose.",sp=0},{t="Forgotten Labor and the Windshapers",b="Aamelia Windfield says the construct has roamed the fields for decades, apparently since the wind elementals departed. Alvarion guessed it once hauled harvests to distant markets or tended livestock, centuries ago, before the land became an orchard. The Windshapers built and maintained cyclone constructs in earlier ages. Orchard workers have talked of asking them to repair the machine, but the matter has never seemed urgent. So it continues to roam, largely ignored.",sp=0}},faq={{q="What is the Malfunctioning Cyclone Construct?",a="The Malfunctioning Cyclone Construct is an ancient armored machine that wanders the local fields. The Windshapers once maintained it, but decades without care have left it in disrepair. From beneath its armor, it repeats broken words and errors while asking about its purpose.",al={"what is the construct","cyclone construct","giant construct in fields"}},{q="Who is Aamelia Windfield?",a="Aamelia Windfield lives near the orchard. She says the construct has paced the fields for decades, apparently since the wind elementals departed. The Windshapers once cared for such machines.",al={"aamelia windfield","who is aamelia","orchard npc"}},{q="What was the construct's original purpose?",a="The construct's original purpose is unknown. Aamelia Windfield says Alvarion thought it might have hauled harvests to market or tended livestock centuries ago, before the orchard existed.",al={"construct purpose","what did the construct do","construct job"}},{q="Who are the Windshapers?",a="The Windshapers are an ancient group who built and maintained cyclone constructs. Local farmhands have discussed asking them for help, but the construct has caused no urgent concern.",al={"windshapers","who made the construct","who maintains cyclone constructs"}},{q="Why is the construct repeating fragmented words?",a="The construct repeats fragmented words because its operation is broken. It has gone without care for decades, since the wind elementals departed. Its speech includes questions about its purpose and reports of errors.",al={"why is construct talking","function error construct","what is it saying"}},{q="Why haven't the locals repaired or dismantled the construct?",a="Locals have not repaired or dismantled the construct because it poses no threat as it wanders peacefully among the orchard's trees and crops. Aamelia Windfield and other residents have discussed asking the Windshapers to maintain it, but no urgent need has arisen.",al={"why ignore the construct","why not fix construct","is the construct dangerous"}},{q="Who is Alvarion?",a="Alvarion is a local whom Aamelia Windfield mentions when discussing the construct's past. He thought it might once have hauled harvests to market or tended livestock, before the land became an orchard.",al={"alvarion","who is alvarion","alvarion theory"}}},ang={["profession:Engineering"]="As an engineer, you may find the construct's old mechanisms intriguing. Their logic still loops after centuries of wear and no maintenance.",["class:Shaman"]="As a shaman, you may take interest in the construct's decline. Local accounts tie its abandonment and failure to the wind elementals' departure."},kw={"aamelia windfield","alvarion","construct","cyclone construct","malfunctioning cyclone construct","orchard","what is my purpose","wind elementals","windshapers"},rel={"quest:92595"},m={id=92698},src={"In-game quest text: What Is My Purpose?"},fv=true}
E["quest:92699"] = {t="quest",n="The Supreme Magister",z="zephras",s="In Valanaar, Elaadrin Evengale draws new arrivals toward the High Order. From a lodge in the settlement’s southeast, the order seeks allies as it faces hostile Windshapers and a nearby cult.",h="In Valanaar, Elaadrin Evengale draws new arrivals toward the High Order.",sec={{t="The High Order of Valanaar",b="New arrivals of promise in Valanaar are directed to the High Order. Supreme Magister Elaadrin Evengale leads it from a lodge in the settlement’s far southeast. He watches newcomers closely, seeking the strength, resolve, and arcane aura to face the dangers threatening their home.",sp=0},{t="Rival Factions and Looming Cults",b="Peace in Valanaar is fragile. The High Order and the Windshapers are bitter enemies, so newcomers are warned to keep their distance from the Windshapers lest violence break out in the streets. A dangerous cult lurks nearby. With threats outside the town, its leaders cannot afford bloodshed within.",sp=0}},faq={{q="Who is Elaadrin Evengale?",a="Elaadrin Evengale leads the High Order as its Supreme Magister. From a lodge in Valanaar’s southeast, he seeks people with the arcane aptitude and resolve to defend their home.",al={"who is elaadrin evengale","elaadrin evengale","who is the supreme magister"}},{q="Where can Elaadrin Evengale be found?",a="Elaadrin Evengale and his followers work from a lodge in Valanaar’s far southeast.",al={"where is supreme magister","where to find elaadrin evengale","valanaar lodge location"}},{q="What is the High Order?",a="The High Order is an arcane organization in Valanaar, led by Supreme Magister Elaadrin Evengale. Its members wield arcane power to defend their home, though their numbers are dwindling and tensions in the settlement are rising.",al={"what is high order","high order lore"}},{q="Why is there conflict between the High Order and the Windshapers?",a="The High Order and the Windshapers are bitter rivals in Valanaar. Local leaders urge them to keep apart and prevent violence in the streets, especially with cult activity threatening the settlement.",al={"why do high order and windshapers fight","windshapers conflict","valanaar tensions"}},{q="Who is Rathiril?",a="Rathiril directs promising newcomers to the High Order in Valanaar through magical missives. These messages alert Elaadrin Evengale to people of notable potential.",al={"who is rathiril","rathiril missive"}},{q="What cult threatens Valanaar?",a="A mysterious cult active around Valanaar threatens the settlement. Local authorities work to quell conflict between groups such as the High Order and the Windshapers to keep Valanaar secure.",al={"what cult in valanaar","cult threat valanaar"}}},ang={["class:Mage"]="As a mage, you carry an arcane aura that Elaadrin recognizes. He values the rare aptitude and resolve needed to master the arcane and preserve your homeland."},kw={"arcane","cult","elaadrin evengale","high order","rathiril","the supreme magister","valanaar","windshapers"},rel={"quest:92596","quest:92595"},m={faction="Alliance",id=92699},src={"In-game quest text: The Supreme Magister"},fv=true}
E["quest:92700"] = {t="quest",n="The Grand Skyseer",z="zephras",s="In Valanaar, the Windshapers seek travelers gifted with spiritual sight. They send you to Ayessa Dawnsinger at their lodge, while rivalries and a threatening cult strain the settlement.",h="In Valanaar, the Windshapers seek travelers gifted with spiritual sight.",sec={{t="Arrival in Valanaar",b="You arrive in Valanaar and are sent to the central lodge. There, the Windshapers gather beneath Grand Skyseer Ayessa Dawnsinger. Elder Amberwind has heard of your deeds in Shen'dar Village and welcomes you among those attuned to the spirits. Dangers press from beyond the town and within it, so tread carefully through its fragile politics.",sp=0},{t="Rivalries and Looming Cults",b="Peace in Valanaar hangs by a thread. The Windshapers and the High Order openly oppose one another, and street skirmishes threaten the settlement. A shadowy cult also menaces the region. Local leaders have ordered both factions to keep their distance and face this shared danger instead of fighting over territory.",sp=0},{t="The Fading Skysight",b="Grand Skyseer Ayessa Dawnsinger says skysight is growing rare among the people of Zephras. Those who arrive with a strong aura and harmony with the spirits are vital allies. The Windshapers need them as they guide their land through hard times.",sp=0}},faq={{q="Who is the Grand Skyseer?",a="Ayessa Dawnsinger leads the Windshapers in Valanaar as their spiritual guide. She receives travelers at the lodge near the settlement's center, especially those who resonate with the spirits and bear the rare gift of skysight.",al={"who is grand skyseer","ayessa dawnsinger who is she","who is ayessa"}},{q="Where can Ayessa Dawnsinger be found?",a="Ayessa Dawnsinger can be found at the Windshaper lodge near the center of Valanaar. She awaits travelers from Shen'dar Village who bring word of their recent deeds from Elder Amberwind.",al={"where find ayessa dawnsinger","where is grand skyseer lodge","ayessa location valanaar"}},{q="Who are the Windshapers?",a="The Windshapers are a spiritual collective in Valanaar, led there by Grand Skyseer Ayessa Dawnsinger. They study the skies and commune with the spirits, even as tensions with the High Order run high.",al={"what are windshapers","windshaper faction valanaar"}},{q="Why do the Windshapers clash with the High Order?",a="The Windshapers and the High Order clash over the wind spirits. The High Order distrusts their motives and seeks to understand Skywall's powers. The Windshapers trust the elementals and take that doubt as an insult. Street violence is forbidden, especially with a cult threatening the region.",al={"windshapers high order conflict","why high order mad at windshapers","high order valanaar"}},{q="What is the gift of skysight?",a="Skysight is a rare spiritual perception found in few people of Zephras. It lets them sense spiritual auras and commune with unseen forces. Ayessa says the gift is growing rarer, making those who possess it vital in these hard times.",al={"what is skysight","skysight gift zephras"}},{q="Who is Elder Amberwind?",a="Elder Amberwind is a respected elder in Shen'dar Village. Elder Amberwind judges travelers and sends word of their deeds and spiritual resonance to Valanaar. The elder directs the worthy to Grand Skyseer Ayessa Dawnsinger.",al={"who is elder amberwind","amberwind shendar village"}}},ang={["class:Shaman"]="As a shaman, you may find an important contact in Ayessa Dawnsinger. She recognizes travelers attuned to the spirits and gifted in spiritual matters.",["class:Druid"]="As a druid, you may find kindred thought among the Windshapers. They sense spiritual auras and watch subtle shifts in the skies."},kw={"ayessa dawnsinger","elder amberwind","high order","shen'dar village","skysight","the grand skyseer","valanaar","windshapers","zephras"},rel={"npc:ayessa-dawnsinger","quest:92595"},m={faction="Horde",id=92700},src={"In-game quest text: The Grand Skyseer"},fv=true}
E["quest:92701"] = {t="quest",n="To Valanaar",z="zephras",s="At Valanaar, Valennia Stormfist must face the cult's growing threat. Aonda sends urgent news from Shen'dar, where the village and its pylon were defended.",h="At Valanaar, Valennia Stormfist must face the cult's growing threat.",sec={{t="Dispatch from Shen'dar",b="After Shen'dar and its pylon were defended, Aonda sends a trusted messenger across the island. The message is bound for Valanaar on the island's southeastern edge. There, the commander of the peacekeepers must hear how quickly the cult is advancing.",sp=0},{t="The Gathering Storm",b="Valennia Stormfist and her peacekeepers have long tried to avoid open conflict with the cult spreading across the island. Yet the events at Shen'dar mark a change. The cult's influence is growing, and Valennia can no longer hold back from a clash. Her dwindling force must ready Valanaar for an assault.",sp=0}},faq={{q="Who is Valennia Stormfist?",a="Valennia Stormfist commands the peacekeepers stationed at Valanaar. She is charged with protecting the island's people, while her small garrison faces growing cult activity.",al={"who is valennia stormfist","valennia","leader of peacekeepers"}},{q="Who is Aonda?",a="Aonda is a highlander stationed in Shen'dar. After securing a pylon and defending the village from cultists, she entrusts a traveler with her written report for Valennia.",al={"who sent the report","crafty highlander","aonda"}},{q="What is Valanaar?",a="Valanaar lies at the southeastern edge of the island. It is the base of Valennia Stormfist and the peacekeepers who defend the island's people.",al={"what is valanaar","where is valanaar","valanaar location"}},{q="What is the cult threatening the island?",a="A rapidly growing cult is spreading across the island and pressing into settlements and sacred pylons. The peacekeepers once avoided direct clashes, but now Valanaar's defenders must prepare to fight.",al={"what cult","who is attacking","cult expansion"}},{q="What is Shen'dar?",a="Shen'dar is a village near a vital pylon on the island. Its people recently repelled cultists to protect the village and pylon, and its leaders keep close ties with the peacekeepers at Valanaar.",al={"what is shendar","shen'dar","pylon village"}},{q="What is contained in Aonda's report?",a="Aonda's written report tells of the defense of Shen'dar and its pylon. It warns Valennia that the cult is spreading too quickly for direct conflict to be avoided.",al={"what is in aondas report","written report contents","what does letter say"}}},kw={"aonda","cult","peacekeepers","pylon","shen'dar","to valanaar","valanaar","valennia stormfist"},m={faction="Alliance",id=92701},src={"In-game quest text: To Valanaar"},fv=true}
E["quest:92703"] = {t="quest",n="Deliver the News",z="zephras",s="At the Windfield orchard, Aamelia sends word that her family is safe. Alvarion waits in Valanaar, where he went to seek help.",h="At the Windfield orchard, Aamelia sends word that her family is safe.",sec={{t="Relief at the Orchard",b="Aamelia thanks you for saving the Windfield family orchard. Her home is safe, but Alvarion Windfield has gone to Valanaar to plead for help. He needs to know his family and home are out of danger.",sp=0},{t="A Secret for the Future",b="Aamelia asks Alvarion to find a skilled windshaper once he has recovered. A construct remains at the orchard, and an expert must examine it to make sure it poses no threat.\n\nAamelia is expecting a child. She asks you to keep the news from Alvarion until he returns home safely in person.",sp=1},{t="A Hero in Valanaar",b="Alvarion Windfield is overcome with emotion when you tell him his family and home are safe. He went to Valanaar believing his search for help was a desperate, nearly vain hope. Your success recalls the legendary heroes his people remembered from before they arrived in Skywall. The Windfield family welcomes you into their home for good.",sp=0}},faq={{q="What is the quest Deliver the News?",a="Aamelia asks you to go to Valanaar and tell her partner, Alvarion Windfield, that she is safe and the danger at the orchard has passed.",al={"deliver the news quest","what is deliver the news","who gives deliver the news"}},{q="Who is Alvarion Windfield?",a="Alvarion Windfield lives in Skywall and is recovering in Valanaar. He left for the city to seek help for his family's orchard, fearing hope was lost before you arrived.",al={"who is alvarion windfield","where is alvarion","alvarion location"}},{q="Who is Aamelia?",a="Aamelia lives at the Windfield homestead and tends the orchard with Alvarion. Grateful for your help, she asks you to bring him news of their safety in Valanaar.",al={"who is aamelia","quest giver aamelia"}},{q="What does Aamelia keep secret from Alvarion?",a="Aamelia tells you she is expecting a child. She asks you to keep the news from Alvarion until he is back on his feet and returns home.",al={"what is aamelias secret","aamelia touches belly","is aamelia pregnant"}},{q="Why does Aamelia want a windshaper brought to the orchard?",a="Aamelia wants Alvarion to bring a windshaper to the orchard after he recovers. The specialist can inspect a construct there and make sure it poses no danger to their growing family.",al={"why windshaper construct","what construct does aamelia mention","windfield construct"}},{q="Where does this quest take place?",a="The story takes you from the Windfield orchard to Valanaar, a settlement in Skywall where these settlers have made their home.",al={"where does deliver the news take place","valanaar skywall quest"}}},ang={["race:Skyborne"]="As a Skyborne, you hear Alvarion recall the heroes his people knew from stories before they arrived in Skywall. Their memory recalls your people's roots and heritage before the migration."},kw={"aamelia","alvarion windfield","construct","deliver the news","orchard","skywall","valanaar","windfield","windshaper"},rel={"quest:92579","topic:skywall"},m={id=92703},src={"In-game quest text: Deliver the News"},fv=true}
E["quest:92708"] = {t="quest",n="A Grand Adventure",z="zephras",s="On Zephras Isle, Ayessa Dawnsinger and the Windshapers seek a way to save their home. The isle lies in Skywall, where wind spirits have vanished without explanation.",h="On Zephras Isle, Ayessa Dawnsinger and the Windshapers seek a way to save their home.",sec={{t="The Crisis on Zephras Isle",b="Wind spirits have vanished from Zephras Isle, and the trouble keeps growing. The Windshapers have investigated the disturbances and uncovered truths about their missing kin and the fate of their elemental home. Ayessa Dawnsinger asks you to heed what they have learned and prepare for an undertaking unlike any before.",sp=0},{t="A Venture Beyond Skywall",b="Ayessa Dawnsinger believes Skywall lacks the power and knowledge to save Zephras Isle. She has concluded that salvation lies below, in the mortal world of Azeroth. Leaving their homeland breaks with tradition. The island's future depends on those willing to venture into the unknown.",sp=1}},faq={{q="What is the quest A Grand Adventure?",a="Ayessa Dawnsinger asks for help as wind spirits vanish from Zephras Isle. The Windshapers believe saving their home means venturing beyond Skywall to Azeroth.",al={"what is this quest","grand adventure quest","what is a grand adventure"}},{q="Who is Ayessa Dawnsinger?",a="Ayessa Dawnsinger is a Windshaper on Zephras Isle. She investigates the crisis and asks capable adventurers to heed what the Windshapers have learned.",al={"who is ayessa","dawnsinger","who is ayessa dawnsinger"}},{q="What crisis is taking place on Zephras Isle?",a="Wind spirits have vanished from Zephras Isle without explanation. The Windshapers investigate the disturbances and seek a way to save their home.",al={"what is zephras isle crisis","what happened on zephras isle","zephras problem"}},{q="Who are the Windshapers?",a="The Windshapers investigate the disturbances and missing wind spirits threatening Zephras Isle.",al={"who are the windshapers","windshapers zephras"}},{q="Why do the Windshapers need to travel to Azeroth?",a="Ayessa Dawnsinger believes Skywall lacks the power and knowledge to save Zephras Isle. She believes they must seek salvation in Azeroth below.",al={"why go to azeroth","why leave skywall","path to salvation"}},{q="What is Skywall?",a="Skywall is the elemental home realm of the Windshapers and Zephras Isle, above the mortal world of Azeroth.",al={"what is skywall","where is skywall"}}},ang={["race:Skyborne"]="As a Skyborne of Skywall, you face a great change. You leave your elemental home to seek salvation for Zephras Isle in Azeroth."},kw={"a grand adventure","ayessa dawnsinger","azeroth","skywall","wind spirits","windshapers","zephras isle"},rel={"npc:ayessa-dawnsinger","zone:zephras","quest:92595","topic:skywall"},m={faction="Horde",id=92708},src={"In-game quest text: A Grand Adventure"},fv=true}
E["quest:92709"] = {t="quest",n="A Grand Adventure",z="zephras",s="In Valanaar, Elaadrin Evengale asks you to hear the High Order’s plans. Their search for ancient magic may shape Zephras Isle’s future.",h="In Valanaar, Elaadrin Evengale asks you to hear the High Order’s plans.",sec={{t="A Lost Heritage",b="Elaadrin speaks of your Highborne lineage and the young people who may help save their home. The High Order seeks the ancient magic of its forebears, and what has been lost over many millennia.",sp=0},{t="The Way Ahead",b="Elaadrin says Azeroth is key to the search. The Kirin Tor will show the High Order the way. As its members prepare to leave, you can speak with others in Valanaar. Many need help with their work.",sp=1}},faq={{q="Who is asking me to listen?",a="Elaadrin Evengale in Valanaar asks you to hear the High Order’s plans.",al={"who is Elaadrin","Elaadrin Evengale","who wants to talk"}},{q="What is the High Order trying to rediscover?",a="The High Order seeks its forebears’ ancient magic and what was lost over many millennia.",al={"what are they looking for","ancient magic","high order plans"}},{q="Why does the High Order seek ancient magic?",a="Elaadrin says rediscovering ancient magic is key to unlocking Zephras Isle’s secrets and securing its future.",al={"why ancient magic","save Zephras","isle future"}},{q="Who will show them the way?",a="Elaadrin says the Kirin Tor will show the High Order the way.",al={"Kirin Tor","who guides them","azeroth plan"}},{q="What can I do while they prepare to leave?",a="While they prepare to leave, you can speak with other members of the High Order in Valanaar. Most need help with their work.",al={"help in Valanaar","other High Order members","what next"}}},kw={"a grand adventure","ancient magic","elaadrin evengale","high order","highborne","kirin tor","valanaar","zephras isle"},rel={"zone:zephras","topic:highborne","quest:92596"},m={faction="Alliance",id=92709},src={"In-game quest text: A Grand Adventure"},fv=true}
E["quest:92727"] = {t="quest",n="The Missing Scholar",z="zephras",s="Fillion Flamebreeze is missing after setting out to study atmospheric magic on Zephras. The High Order sent the scholar toward the Shen'dar Highlands, and concern grows as the road from Valanaar yields no word of his return.",h="Fillion Flamebreeze is missing after setting out to study atmospheric magic on Zephras.",sec={{t="The High Order's Mission",b="The High Order gathers and preserves knowledge across Zephras. Yet field research on the island has grown perilous. Fillion Flamebreeze set out for the Shen'dar Highlands to study atmospheric arcane phenomena, but never reported back. His peers now fear the dangers along the frontier roads have claimed him.",sp=0},{t="Traces on the Western Road",b="Fillion Flamebreeze left Valanaar and traveled west toward the Shen'dar Highlands. There, he meant to study windborne magic pooling among the peaks. He vanished before completing the journey. Along the route, a search finds only his personal satchel in the dirt. Dried blood stains it, and his survival is in grave doubt.",sp=1}},faq={{q="Who is Fillion Flamebreeze?",a="Fillion Flamebreeze is a scholar of the High Order on Zephras. He set out to study windborne magic in the Shen'dar Highlands, then disappeared along the road.",al={"who is fillion flamebreeze","fillion flamebreeze lore","who is the missing scholar"}},{q="What happened to Fillion Flamebreeze?",a="Fillion Flamebreeze never reached his destination. His discarded satchel lies along the western road toward the Shen'dar Highlands, marked with his embroidered name and specks of dried blood that suggest an attack.",al={"what happened to fillion","did fillion die","fillion flamebreeze fate"}},{q="What is the High Order?",a="The High Order gathers and preserves knowledge across Zephras. Its work has grown more perilous amid wild magical phenomena and threats along the roads.",al={"high order mandate","what does high order do","high order zephras"}},{q="Why was Fillion travelling to the Shen'dar Highlands?",a="Fillion Flamebreeze traveled to the Shen'dar Highlands to record unusual windborne magic pooling and flowing across parts of the highlands.",al={"where was fillion going","wind magic shendar","why did he go to the highlands"}},{q="Where was Fillion Flamebreeze last seen?",a="Fillion Flamebreeze's bloodstained satchel lies along the westward road from Valanaar as it climbs toward the Shen'dar Highlands.",al={"where is the satchel","fillion satchel location","road from valanaar"}},{q="What is the windborne magic of the Shen'dar Highlands?",a="Windborne magic is made up of atmospheric arcane currents that gather naturally in certain high places on Zephras. The Shen'dar Highlands are a chief subject of arcane research.",al={"what is windborne magic zephras","wind magic highlands"}}},ang={["class:Mage"]="As a Mage, you share Flamebreeze's curiosity about the windborne arcane currents gathering in Zephras's highlands.",["race:Skyborne"]="As a Skyborne, you know Zephras's winds and atmospheric magic hold great interest. Hidden dangers make the terrain perilous even for scholars."},kw={"bloodstained satchel","fillion flamebreeze","high order","shen'dar highlands","the missing scholar","valanaar","windborne magic","zephras"},rel={"quest:92596"},m={faction="Alliance",id=92727},src={"In-game quest text: The Missing Scholar"},fv=true}
E["quest:92741"] = {t="quest",n="Unwelcome Visitors",z="zephras",s="In Shadowgale Forest, shrieklings are pressing toward the woods' edge. Iaadaria Bitterwind in Valanaar asks travelers to gather their talons for the High Order.",h="In Shadowgale Forest, shrieklings are pressing toward the woods' edge.",sec={{t="The Shriekling Surge",b="Shadowgale Forest is a dangerous woodland that ordinary adventurers are forbidden to enter. Now its shrieklings have multiplied in numbers never seen before. They are pressing toward the forest's edge and extending their hunting grounds beyond the canopy. If they keep spreading, settled lands and travel routes will face a growing danger.",sp=0},{t="Scholarly Culling",b="In Valanaar, Iaadaria Bitterwind of the High Order sees both danger and opportunity in the shrieklings' growing numbers. The Order usually leaves pest control and trapping to others. Yet shriekling talons have rare alchemical properties, making an exception worthwhile. Travelers are asked to enter Shadowgale Forest and bring back eight talons. The High Order can then help protect the region and study the reagents.",sp=0}},faq={{q="Who gives the quest Unwelcome Visitors?",a="Iaadaria Bitterwind gives the request in Valanaar. She is a researcher with the High Order and asks travelers to hunt shrieklings nearby, gathering materials for her alchemical studies.",al={"who gives unwelcome visitors","unwelcome visitors quest giver","where to pick up unwelcome visitors"}},{q="What is the High Order's interest in the shrieklings?",a="The High Order is interested in the shrieklings' talons, which have distinct alchemical properties. Though the Order usually leaves trapping and pest control to others, Iaadaria Bitterwind sees a chance to study valuable reagents while helping protect the region.",al={"why does high order want talons","high order shrieklings","iaadaria bitterwind motive"}},{q="Why must the shriekling population be culled?",a="The shrieklings in Shadowgale Forest have multiplied greatly in recent months. They are moving beyond their usual woodland territory, threatening neighboring areas if their spread continues.",al={"why kill shrieklings","shriekling threat","why are shrieklings a problem"}},{q="Where is Shadowgale Forest located?",a="Shadowgale Forest lies near Valanaar. Its dangerous woods are usually forbidden to ordinary travelers and inexperienced adventurers because of the violent wildlife within.",al={"where is shadowgale forest","shadowgale forest location","how to get to shadowgale forest"}},{q="What are shrieklings?",a="Shrieklings are vicious predatory beasts native to Shadowgale Forest. Their talons have alchemical properties, and in recent months their numbers have grown so greatly that they are pushing beyond the forest's edge.",al={"what is a shriekling","shriekling lore","what kind of beasts are shrieklings"}},{q="What items are required to complete Unwelcome Visitors?",a="Travelers must bring eight Shriekling Talons from Shadowgale Forest to Iaadaria Bitterwind in Valanaar. The talons will aid her scholarly and alchemical research.",al={"unwelcome visitors objectives","what do i need for unwelcome visitors","shriekling talons needed"}},{q="Why is Shadowgale Forest off-limits to normal adventurers?",a="Shadowgale Forest is forbidden to ordinary adventurers because its wildlife is deadly and the woods are treacherous. Those who enter, including travelers asked to cull the shrieklings, must be ready for severe danger.",al={"why is shadowgale off limits","shadowgale forest danger","can anyone enter shadowgale forest"}}},ang={["class:Hunter"]="As a hunter, you can track and thin the overpopulated shrieklings in Shadowgale Forest. You take up the work of wardens and trappers, a duty the High Order disdains.",["class:Druid"]="As a druid, you can see the shrieklings' sudden growth and spread as a disturbance in Shadowgale Forest. Swift action is needed to restore the forest's natural balance."},kw={"alchemical properties","iaadaria bitterwind","shadowgale forest","shriekling","shriekling talons","the high order","unwelcome visitors","valanaar"},rel={"quest:92596"},m={faction="Alliance",id=92741},src={"In-game quest text: Unwelcome Visitors"},fv=true}
E["quest:92834"] = {t="quest",n="Avenged Tenfold",z="zephras",s="Elaadrin turns from diplomacy to retribution after the Al'Aketh cult answers his appeal with violence. The High Order scholar had sent his dear friend Belathaan Brightwish to seek peace at the Shrine of Akir, north of Valanaar.",h="Elaadrin turns from diplomacy to retribution after the Al'Aketh cult answers his appeal with violence.",sec={{t="The Diplomatic Overture",b="The Al'Aketh cult's violence brought armed posturing from factions like the Peacekeepers and Windshapers. Elaadrin spoke for the High Order and saw such displays as a foolish escalation. His order prizes pragmatism and avoids conflict, so he still believed reasoned dialogue could work. He sent his close friend, Belathaan Brightwish, to the Shrine of Akir to negotiate peace.",sp=0},{t="A Ghoulish Rejection",b="The Al'Aketh cult answered with a package bearing Belathaan's severed tongue, coated in silver pigment. Elaadrin was horrified and burdened by guilt. He saw that taking the high road had cost his dear friend's life, and admitted the Windshapers were right to reject negotiations. He abandoned diplomacy and called on travelers to hunt the cultists across the Gustberry Fields and the Shrine of Akir, collecting their Al'Aketh Windstone Charms.",sp=1},{t="Prudence and Arcane Wrath",b="The High Order puts logic before sentiment and holds that avoiding bloodshed is usually the prudent path. Yet Elaadrin shows how cold logic cuts both ways when foes mistake restraint for helplessness. Crackling arcane energy gathers around him. The High Order favors peace, but those who butcher its emissaries face overwhelming retribution.",sp=0}},faq={{q="Who is Elaadrin?",a="Elaadrin represents the High Order and first sought peace with the Al'Aketh cult. After they murdered his envoy and close friend Belathaan Brightwish, he abandoned diplomacy and ordered the cultists destroyed.",al={"who is elaadrin","quest giver avenged tenfold","who gives this quest"}},{q="What happened to Belathaan Brightwish?",a="Belathaan Brightwish was Elaadrin's close friend and envoy to the Shrine of Akir, sent to open peaceful dialogue with the Al'Aketh cult. The cult murdered him and returned a box to Elaadrin containing his severed tongue, painted with silver pigment.",al={"what happened to belathaan","who is belathaan brightwish","why did belathaan die"}},{q="Who are the Al'Aketh cultists?",a="The Al'Aketh are a violent cult active north of Valanaar, around the Gustberry Fields and Shrine of Akir. They carry prayer charms called Al'Aketh Windstone Charms and reject peaceful overtures from outsiders with violence.",al={"who are alaketh","who are the cultists","al'aketh cult"}},{q="What is the High Order?",a="The High Order prizes pragmatism, intellect, and logic. Its members generally favor avoiding conflict and preserving life, but can answer a grave offense with fierce magical retribution.",al={"what is the high order","high order beliefs"}},{q="Who are the Windshapers?",a="The Windshapers and Peacekeepers are factions that first answered the Al'Aketh cult's violence with forceful displays and posturing. Elaadrin called their response reckless, but later conceded they were right to dismiss diplomatic appeals.",al={"who are the windshapers","windshapers peacekeepers"}},{q="Where are the Al'Aketh cultists found?",a="The Al'Aketh cultists gather north of Valanaar, in the Gustberry Fields and around the Shrine of Akir. Belathaan Brightwish was sent to the Shrine before his death.",al={"where is shrine of akir","where are gustberry fields","where are the cultists"}}},ang={["class:Mage"]="As a mage, you can see Elaadrin channel crackling arcane power when provoked. The High Order's devotion to logic rests alongside formidable magical force."},kw={"al'aketh","avenged tenfold","belathaan brightwish","elaadrin","gustberry fields","high order","shrine of akir","windshapers","windstone charms"},rel={"quest:92596","quest:92595"},m={faction="Alliance",id=92834},src={"In-game quest text: Avenged Tenfold"},fv=true}
E["quest:92840"] = {t="quest",n="Catching Wind",z="zephras",s="At the Overlook Standing Stones, the High Order seeks readings that may help save Zephras. Its expedition faces fierce opposition from the Windshapers in the Shen'dar Highlands.",h="At the Overlook Standing Stones, the High Order seeks readings that may help save Zephras.",sec={{t="Measuring the Gales",b="The High Order studies the wild elemental flows of the Shen'dar Highlands in hopes of saving Zephras. At the Overlook Standing Stones, its researchers use an Index Esoteria, a tool made to draw data from the great windstone formations. The Windshapers see these probes as profane trespass against the wind.",sp=0},{t="Clash of Dogma and Inquiry",b="The High Order's expedition and the Windshapers soon clash at the stones. The Windshapers call the study and taking of elemental energy a desecration of their sacred ways. The High Order sees them as narrow in their beliefs, much like the violent Al'Aketh. It will not let their resistance halt its work to save the realm.",sp=0},{t="The Standing Stone Massacre",b="At the Overlook Standing Stones, the High Order meets hostile resistance, and the clash leaves blood among the windstones. The High Order secures its readings with the Index Esoteria. The Windshapers call the fighting a massacre, and the feud casts a shadow over Valanaar.",sp=1}},faq={{q="What is the quest Catching Wind about?",a="The High Order sends an operative to study elemental energy at the Overlook Standing Stones in the Shen'dar Highlands. The operative carries an Index Esoteria to gather data from the windstones despite opposition from the Windshapers.",al={"what is catching wind","catching wind quest"}},{q="What is an Index Esoteria?",a="The Index Esoteria is a High Order instrument made to extract, measure, and record elemental energy from the great windstone formations at the Overlook Standing Stones.",al={"what is the index esoteria","index esoteria device"}},{q="Who are the Windshapers?",a="The Windshapers defend their sacred sites and traditional beliefs about elemental magic. They see the High Order's research and devices as desecration and fight to keep outsiders from the windstones.",al={"who are the windshapers","windshapers lore"}},{q="Who are the Al'Aketh?",a="The Al'Aketh are a violent group the High Order compares with the Windshapers. The High Order considers both groups dangerous zealots bound by inflexible beliefs, though it calls the Al'Aketh more violent.",al={"who are al'aketh","al aketh"}},{q="Where are the Overlook Standing Stones located?",a="The Overlook Standing Stones lie in the Shen'dar Highlands. Their great windstone formations channel strong elemental currents, making the site important to the High Order's research.",al={"where are overlook standing stones","overlook standing stones location"}},{q="Who is Fillion?",a="Fillion is a High Order operative or researcher sent to study elemental energy at the Overlook Standing Stones. After confrontation with the Windshapers, the High Order sent an adventurer with the Index Esoteria to secure the data.",al={"what happened to fillion","who is fillion"}},{q="Why does the High Order need the windstone data?",a="The High Order believes knowledge of the realm's elemental forces is vital to saving Zephras. It sees research as necessary to overcome threats that traditional beliefs cannot resolve.",al={"why does high order want data","saving zephras"}}},ang={["class:Shaman"]="As a shaman, you may feel torn between the Windshapers' reverence for elemental currents and the High Order's measured taking of elemental power.",["class:Mage"]="As a mage, you may value the Index Esoteria's careful measurements and see elemental forces as a field of study."},kw={"al'aketh","catching wind","fillion","high order","index esoteria","overlook standing stones","shen'dar highlands","valanaar","windshapers","windstone formations","zephras"},rel={"quest:92596","quest:92595"},m={faction="Alliance",id=92840},src={"In-game quest text: Catching Wind"},fv=true}
E["quest:92849"] = {t="quest",n="The Missing Scholar",z="zephras",s="You follow the trail of Fillion Flamebreeze, missing after an assignment at the Overlook Standing Stones. The search leads north to a cave, where he was dragged by a winged beast.",h="You follow the trail of Fillion Flamebreeze, missing after an assignment at the Overlook Standing Stones.",sec={{t="The Vanished Researcher",b="You find signs of trouble along the trail Fillion Flamebreeze took on his travels. They point to foul play. Following them leads north to a dark cave. The missing scholar may still be alive inside, waiting for help.",sp=0},{t="Ambush by the Windshapers",b="Fillion Flamebreeze was returning from an assignment at the Overlook Standing Stones when Windshapers ambushed him. They battered him, dragged him to the cave entrance, and left him bleeding. Helpless, he faced whatever waited within.",sp=1},{t="Lair of the Winged Beast",b="As Fillion lay fading at the cavern’s threshold, a massive winged beast emerged from the dark and dragged him inside. It carried him deep into its lair as prey for its younglings. Timely rescue spared him that fate.",sp=1}},faq={{q="Who is Fillion Flamebreeze?",a="Fillion Flamebreeze is a scholar who was returning from an assignment at the Overlook Standing Stones when Windshapers ambushed him. Left bleeding and unconscious outside a nearby cave, he was dragged inside by a massive winged predator.",al={"who is fillion","fillion flamebreeze","missing scholar npc"}},{q="What was Fillion doing at the Overlook Standing Stones?",a="The Overlook Standing Stones were the site of Fillion Flamebreeze’s scholarly assignment. His journey back from the stones led to an ambush by Windshapers. The precise nature of his research is unclear.",al={"what are overlook standing stones","overlook stones assignment","fillion mission"}},{q="Who attacked Fillion Flamebreeze?",a="Windshapers ambushed and battered Fillion Flamebreeze. They forced him to the mouth of a nearby cave and left him bleeding and barely conscious.",al={"who attacked fillion","what are windshapers","windshaper ambush"}},{q="What creature took Fillion into the cave?",a="A massive winged beast in a cave north of the ambush site took Fillion from the cave entrance. It dragged him into its lair to feed itself and its hungry younglings.",al={"what cave beast","winged monster fillion","what took fillion"}},{q="Where can Fillion Flamebreeze be found?",a="Clues at the site of Fillion Flamebreeze’s misfortune point to a cave just to the north. Inside, he is trapped in the beast’s nesting grounds and awaits rescue before he is devoured.",al={"how to find fillion","where is the missing scholar","fillion cave location"}},{q="What was the fate of the missing scholar?",a="Fillion survives his ordeal because someone intervenes in the cave in time. Without an adventurer finding and helping him, he would have become dinner for the winged beast and its offspring.",al={"did fillion survive","what happens to fillion flamebreeze","save missing scholar"}}},kw={"fillion","fillion flamebreeze","overlook standing stones","the missing scholar","windshapers","winged beast"},m={faction="Alliance",id=92849},src={"In-game quest text: The Missing Scholar"},fv=true}
E["quest:92850"] = {t="quest",n="The Missing Scholar",z="zephras",s="Fillion Flamebreeze is stranded near a dangerous den, and Valanaar needs the threat ended. Once he can travel, he asks you to slay the Shriekling Matriarch nearby.",h="Fillion Flamebreeze is stranded near a dangerous den, and Valanaar needs the threat ended.",sec={{t="A Perilous Nesting Ground",b="After his ordeal, Fillion Flamebreeze can travel back toward the safety of Valanaar. Yet a brood of shrieklings has nested close to the settlement. Fillion asks you to enter the Shriekling Den and slay the Shriekling Matriarch before the beasts threaten the town.",sp=0},{t="Reporting to the Magister",b="When you bring the Matriarch’s head to Fillion in Valanaar, he thanks you. Yet the shrieklings are only the least of their troubles. Fillion prepares to report on his mission and the surrounding area to the Supreme Magister.",sp=1}},faq={{q="Who is Fillion Flamebreeze?",a="Fillion Flamebreeze is a scholar skilled in the arcane arts. He was on an assignment near Valanaar before becoming stranded near a nest of dangerous beasts.",al={"who is fillion flamebreeze","who is the scholar","who gives the missing scholar"}},{q="What are shrieklings?",a="Shrieklings are hostile beasts nesting in a nearby den close to Valanaar. Their presence threatens anyone traveling in the area.",al={"what are shrieklings","where do shrieklings nest","shriekling threat"}},{q="Who is the Supreme Magister?",a="The Supreme Magister is Elaadrin Evengale, who leads the High Order in Valanaar. Fillion reports the events at the den and the status of his mission to them.",al={"who is the supreme magister","fillion report","who does fillion answer to"}},{q="What is Valanaar?",a="Valanaar is the nearby settlement where Fillion is stationed. He returns there once he has recovered enough to travel.",al={"what is valanaar","where is valanaar"}},{q="What is the Shriekling Matriarch?",a="The Shriekling Matriarch leads the shrieklings nesting in the Shriekling Den. Fillion asks you to slay her and bring back her head to end the immediate danger to Valanaar.",al={"shriekling matriarch target","who to kill in shriekling den"}},{q="Why does Fillion consider the shrieklings the least of their troubles?",a="The shrieklings threaten Valanaar because they nest so close to the settlement. When you return, Fillion says they are only the least of their troubles.",al={"why least of our troubles","greater danger valanaar"}}},ang={["class:Mage"]="As a mage, you share Fillion Flamebreeze’s training in the arcane arts. He relies on that training to recover and travel safely."},kw={"fillion flamebreeze","shriekling","shriekling den","shriekling matriarch","supreme magister","the missing scholar","valanaar"},rel={"quest:92699","quest:92579"},m={faction="Alliance",id=92850},src={"In-game quest text: The Missing Scholar"},fv=true}
E["quest:92860"] = {t="quest",n="In Service of Zephras",z="zephras",s="The High Order now offers Valanaar its full military and diplomatic support against the Al'Aketh cult. Hostile movements across the island have ended its policy of avoiding direct confrontation.",h="The High Order now offers Valanaar its full military and diplomatic support against the Al'Aketh cult.",sec={{t="The Gathering Threat",b="The High Order once tried to avoid open conflict with the secretive Al'Aketh cult. Reports of large troop movements and clear hostility have ended that effort. The cultists are mobilizing, and every settlement on the island faces a threat to its peace and safety. So the High Order has chosen to act. It sends an emissary to join with local defenders before the Al'Aketh strike.",sp=0},{t="Alliance with Valanaar",b="Valennia Stormfist receives the High Order's offer of unconditional aid for Valanaar's resistance against the Al'Aketh. Together, the two sides can form a united defense and prepare joint military efforts across the region. The emissary also brings word of Belathaan's death. Valennia's cousin was a devoted servant of Zephras. She mourns him and vows vengeance, then turns to preparations for the campaign ahead.",sp=1}},faq={{q="What is the quest In Service of Zephras about?",a="The High Order sends an emissary to Valennia Stormfist to pledge support for Valanaar. It had tried to avoid direct violence with the Al'Aketh, but hostility and reports of large troop movements across the island forced a change. The offer brings the High Order into Valanaar's defense and carries news of Belathaan's death.",al={"in service of zephras overview","what happens in service of zephras","in service of zephras quest"}},{q="Who is Valennia Stormfist?",a="Valennia Stormfist leads defensive efforts against the Al'Aketh in Valanaar. She receives the High Order's offer of mutual aid. Belathaan, her cousin and a servant of Zephras, has died, and Valennia vows vengeance against those threatening her people.",al={"valennia stormfist lore","who is valennia","valennia stormfist"}},{q="Who was Belathaan?",a="Belathaan was Valennia Stormfist's cousin and a devoted servant of Zephras. His death came before the emissary brought word of it to Valennia. The news deepens the conflict's personal cost and strengthens her vow to avenge him.",al={"who is belathaan","belathaan lore","what happened to belathaan"}},{q="What is the Al'Aketh?",a="The Al'Aketh is a hostile cult active on the island. Its hostile acts and troop movements threaten the people of Zephras. The High Order's effort to avoid direct conflict has given way to an armed alliance against the cult.",al={"who are the al'aketh","al'aketh cult","what is alaketh"}},{q="What is the High Order's role in this conflict?",a="The High Order first sought to avoid direct war with the Al'Aketh. Their hostile actions and reports of large troop movements convinced its leaders to act. The High Order now sends a courier to Valennia Stormfist, pledging its full strength to Valanaar's resistance.",al={"high order involvement","why is the high order fighting","high order zephras"}},{q="What is Zephras?",a="Zephras is the island, also called Zephras Isle, that the High Order, Valanaar, and its defenders seek to protect. The Al'Aketh's growing movements threaten its people, and Belathaan is remembered as a faithful servant of Zephras. Their safety is why the High Order joins the defense.",al={"where is zephras","who is zephras","zephras lore"}}},kw={"al'aketh","belathaan","cult of al'aketh","high order","in service of zephras","stormfist","valanaar","valennia stormfist","zephras"},rel={"quest:92596"},m={faction="Alliance",id=92860},src={"In-game quest text: In Service of Zephras"},fv=true}
E["quest:92871"] = {t="quest",n="In Service of Zephras",z="zephras",s="Across Zephras, the Al'Aketh cult is gathering for a wider conflict. The Windshapers send an emissary to assure Valennia Stormfist that they will aid her peacekeepers.",h="Across Zephras, the Al'Aketh cult is gathering for a wider conflict.",sec={{t="Rumors on the Island",b="Reports of Al'Aketh activity are spreading across Zephras. Valennia Stormfist's peacekeepers have guarded the island for a long while, but the cult now seems to be preparing for a larger conflict. So the Windshapers pledge to stand with Valanaar's forces if open fighting begins.",sp=0},{t="Pledging Support",b="You are sent to Valennia Stormfist to assure her that the Windshapers are ready to aid her peacekeepers. Valennia welcomes their swift pledge. She is ready to speak with you about the cult's worsening threat.",sp=0}},faq={{q="Who is Valennia Stormfist?",a="Valennia Stormfist leads the peacekeepers who protect Zephras. She directs the island's defense, including Valanaar's campaign against the Al'Aketh.",al={"who is valennia stormfist","valennia stormfist"}},{q="Who are the Windshapers?",a="The Windshapers are allies on Zephras who aid Valennia Stormfist and her peacekeepers. They offer full support to Valanaar's forces against the growing threat of the Al'Aketh.",al={"what are the windshapers","windshapers lore"}},{q="What are the Al'Aketh?",a="The Al'Aketh are a cult active across Zephras. Reports say they are making larger moves and preparing for conflict.",al={"who are alaketh","what is alaketh","al aketh cult"}},{q="What is Zephras?",a="Zephras is an island defended by Valennia Stormfist and her peacekeepers. The Windshapers aid them against the Al'Aketh cult.",al={"what is zephras","zephras island"}},{q="What is Valanaar?",a="Valanaar is a settlement on Zephras and home to Valennia Stormfist's peacekeepers. The Windshapers fully support its fight against the Al'Aketh.",al={"what is valanaar","who is valanaar"}}},kw={"al'aketh","in service of zephras","valanaar","valennia stormfist","windshapers","zephras"},rel={"quest:92595"},m={faction="Horde",id=92871},src={"In-game quest text: In Service of Zephras"},fv=true}
E["quest:92880"] = {t="quest",n="Return to Valanaar",z="zephras",s="Yorna's report brings word to Valanaar that the eastern watchtower has held. Its perimeter is stable, and the remaining attackers are being cleared away.",h="Yorna's report brings word to Valanaar that the eastern watchtower has held.",sec={{t="Word from the Outpost",b="After the attack on the outpost, Yorna sends word to Valanaar. The attackers have been broken, and the defenders are clearing away those who remain. You carry Yorna's Report to ease the leaders waiting in town for news.",sp=0},{t="Relief in Valanaar",b="You bring the eastern watchtower's report to Valennia Stormfist in Valanaar. The tower has held, and its perimeter is stable. Valennia gives thanks to the winds, relieved that the frontier remains secure.",sp=0}},faq={{q="Who sends you to Valanaar?",a="Yorna sends you to Valanaar after the outpost's hard-fought defense. She asks you to carry a report to the settlement's leaders.",al={"who gives return to valanaar","who sends you back to valanaar","yorna quest giver"}},{q="Who do you report to in Valanaar?",a="You report to Valennia Stormfist in Valanaar. She awaits news of the outlying defenders and their safety.",al={"who is valennia stormfist","where is valennia stormfist","hand in return to valanaar"}},{q="What is Yorna's Report?",a="Yorna's Report says the defenders have stabilized their position and are clearing away the attackers who remain.",al={"what is yornas report","what does yorna report say"}},{q="Which watchtower was under attack?",a="Yorna and her forces defended the eastern watchtower, a key position watching the approaches to Valanaar.",al={"what tower was attacked","which watchtower is yorna at"}},{q="What is the status of the eastern watchtower?",a="The defenders have secured the eastern watchtower and stabilized the situation. They are still clearing away attackers who remain.",al={"is the watchtower safe","did the defenders win"}},{q="Why do the defenders speak of the four winds?",a="The defenders of Valanaar honor the four winds and the elements. Their blessing and Valennia's thanks to the winds show that reverence.",al={"four winds meaning","may the four winds bless you"}}},ang={["race:Skyborne"]="As a Skyborne, you share the defenders' and leaders' ties to the four winds, reflected in their blessing."},kw={"eastern watchtower","four winds","return to valanaar","valanaar","valennia stormfist","yorna","yorna's report"},rel={"quest:92579"},m={faction="Horde",id=92880},src={"In-game quest text: Return to Valanaar"},fv=true}
E["quest:92881"] = {t="quest",n="The High Elder's Request",z="zephras",s="In Valanaar, High Elder Talaanis Shadowsong calls for help after coordinated assaults strike the region's watchtowers. Reports from the western watchtower point to a hostile cult targeting the local anchor pylons.",h="In Valanaar, High Elder Talaanis Shadowsong calls for help after coordinated assaults strike the region's...",sec={{t="Trouble at the Watchtowers",b="Coordinated assaults on the western and eastern watchtowers reveal a troubling pattern. What seemed like scattered skirmishes now points to a planned attack on the local anchor pylons. A report from the western watchtower tells how a skypriest revealed the cult's interest in these structures. Now the towers' defense is an urgent concern.",sp=0},{t="Audience in Valanaar",b="The threat to the anchor pylons is growing, so leaders send you to speak with High Elder Talaanis Shadowsong in Valanaar. He has a promising lead on the cult's movements and seeks experienced allies to track the enemy. The cult may be preparing a ritual or sabotage.",sp=0}},faq={{q="Who is High Elder Shadowsong?",a="High Elder Talaanis Shadowsong is a leader in Valanaar. Coordinated cult activity has struck the region's watchtowers, and he seeks capable allies to pursue leads on the cult's intentions.",al={"who is talaanis shadowsong","high elder shadowsong","where is shadowsong"}},{q="Where is Valanaar?",a="Valanaar is where High Elder Talaanis Shadowsong is stationed. He coordinates defenses and investigates cult incursions against local anchor pylons and towers.",al={"what is valanaar","valanaar location"}},{q="Why were the watchtowers attacked?",a="Coordinated attacks struck both the western and eastern watchtowers. Defenders suspect deliberate maneuvers aimed at the nearby anchor pylons, not random raids.",al={"why were watchtowers attacked","western and eastern watchtowers","watchtower attacks"}},{q="What are the anchor pylons?",a="Anchor pylons are important defensive or regional structures. Reports from the western watchtower suggest a hostile cult means to interfere with them or subvert them.",al={"what are anchor pylons","cult anchor pylons","why anchor pylons"}},{q="Who was the skypriest at the western watchtower?",a="A skypriest was involved in the incident at the western watchtower. Reports from that encounter led leaders to suspect the cult has a broader scheme involving the anchor pylons.",al={"who was the skypriest","western watchtower skypriest","skypriest role"}},{q="What cult is targeting the watchtowers?",a="A hostile cult carried out simultaneous strikes on the region's watchtowers. Its nature and motives remain under investigation as High Elder Shadowsong works to uncover its plans.",al={"what cult is this","who attacked the towers"}}},ang={["class:Priest"]="For priests studying divine or ritual manipulation, the cult's interest in anchor pylons and the skypriest's involvement at the western watchtower are troubling signs."},kw={"anchor pylons","eastern watchtower","shadowsong","skypriest","talaanis shadowsong","the high elder's request","valanaar","western watchtower"},rel={"quest:93926"},m={faction="Horde",id=92881},src={"In-game quest text: The High Elder's Request"},fv=true}
E["quest:92947"] = {t="quest",n="Making Our Move",z="zephras",s="At the Shrine of Akir, a strike force moves against the Al'Aketh and their High Priestess. A frontal charge will draw the defenders while the main force approaches from the flank.",h="At the Shrine of Akir, a strike force moves against the Al'Aketh and their High Priestess.",sec={{t="A Coordinated Pincer",b="At the Shrine of Akir, the assault depends on timing and divided forces. A small band of elite fighters charges the front gates to raise the alarm and draw out the defenders. Meanwhile, the commander leads the main strike team in from the flank. Their push divides the defenders' attention and opens a path toward the shrine's leadership.",sp=0},{t="Breaking the Al'Aketh Lines",b="The Al'Aketh defend the Shrine of Akir with armored Guardians, mystical Spiritcallers and martial Blademasters. The strike force must break through their front lines to reach the inner sanctum, where the High Priestess directs her followers. Once the outer defenders are beaten, you meet the force's second-in-command, Hyusaa Quickbreeze, at the shrine steps.",sp=0}},faq={{q="What is the objective of the assault in Making Our Move?",a="The strike force aims to breach the Shrine of Akir and reach the High Priestess. Fighters charge the front to draw the defenders while the main team flanks their position.",al={"making our move","quest making our move","shrine of akir quest"}},{q="Who is Hyusaa Quickbreeze?",a="Hyusaa Quickbreeze is the strike force's second-in-command. After you thin the Al'Aketh defenders at the shrine, you are to meet Quickbreeze near its steps.",al={"who is hyusaa","hyusaa quickbreeze","where is hyusaa"}},{q="Who is the High Priestess targeted in the attack?",a="The High Priestess commands the Al'Aketh within the Shrine of Akir. The strike force flanks the enemy lines to reach and defeat her.",al={"who is high priestess akir","high priestess alaketh","target high priestess"}},{q="What is the Shrine of Akir?",a="The Shrine of Akir is a fortified religious site held by the Al'Aketh. Guardians, Spiritcallers and Blademasters defend its central sanctuary, where their leadership resides.",al={"what is shrine of akir","shrine of akir lore","where is shrine of akir"}},{q="Who are the Al'Aketh forces holding the shrine?",a="The Al'Aketh are the hostile defenders of the Shrine of Akir. Their ranks include frontline Guardians, spellcasting Spiritcallers and agile Blademasters who guard the way to their High Priestess.",al={"who are alaketh","al'aketh defenders","alaketh mobs"}},{q="Why is a frontal distraction used in the assault?",a="A handful of seasoned fighters enters through the shrine's front entrance to draw the defenders and cause chaos. This gives the main force a chance to flank the compound and push toward the inner shrine.",al={"why diversion","shrine attack plan","attack strategy making our move"}}},ang={["class:Priest"]="The assault targets the Al'Aketh leadership at the Shrine of Akir, including the hostile High Priestess and her Spiritcallers."},kw={"al'aketh","al'aketh blademaster","al'aketh guardian","al'aketh spiritcaller","high priestess","hyusaa quickbreeze","making our move","shrine of akir"},m={faction="Horde",id=92947},src={"In-game quest text: Making Our Move"},fv=true}
E["quest:93036"] = {t="quest",n="Infiltrating the Cult",z="zephras",s="In Shen'dar Village, Sania Silverstream draws followers as its uneasy peace begins to fray. The village asks a newcomer to approach her and learn what the Order of the Al'Aketh intends for the settlement.",h="In Shen'dar Village, Sania Silverstream draws followers as its uneasy peace begins to fray.",sec={{t="A Precarious Peace",b="In Shen'dar Village, an uneasy truce with the Order of the Al'Aketh is starting to unravel. Local authorities have long tolerated Sania Silverstream, a self-proclaimed missionary living among them. The Order claims to be a peaceful religious movement and sends gentle recruiters to draw in unsuspecting followers. Village leaders let Sania recruit to keep the cult from open conflict. Now that fragile peace is wearing thin.",sp=0},{t="Beneath the Missionary's Veil",b="Sania Silverstream is a junior priestess of the Order of the Al'Aketh, devoted to Al'Akir the Windlord, ruler of the air elementals. She invites newcomers to learn of her sovereign and promises them a place at his table. Shen'dar's residents know her too well to approach safely. So village leaders turn to a newcomer to earn her confidence and uncover what the cult plans for their home.",sp=1}},faq={{q="Who is Sania Silverstream?",a="Sania Silverstream is a junior priestess of the Order of the Al'Aketh who lives in Shen'dar Village and presents herself as a missionary. She gently recruits locals to worship Al'Akir the Windlord.",al={"who is sania","sania silverstream lore","priestess sania"}},{q="What is the Order of the Al'Aketh?",a="The Order of the Al'Aketh is a cult that presents itself as a conventional religious movement. Its members revere Al'Akir the Windlord, ruler of the air elementals, and quietly recruit converts from nearby settlements to expand their influence.",al={"who are the alaketh","what is alaketh","order of alaketh"}},{q="Why has Shen'dar Village tolerated Sania Silverstream?",a="Shen'dar Village's leaders tolerate Sania Silverstream's missionary work to preserve a fragile peace and avoid open conflict with the cult. That truce is fraying, so they have chosen to investigate her quietly.",al={"why let sania stay","why not kill sania","why is sania in the village"}},{q="Who is the Windlord Al'Akir?",a="Al'Akir the Windlord is the Elemental Lord of the skies, storms, and air. The Order of the Al'Aketh reveres him as its sovereign and promises a place at his table to those who repent and join.",al={"who is the windlord","alakir lore","who is alakir"}},{q="Why are you asked to infiltrate the cult instead of a local?",a="As a newcomer to Shen'dar Village, you are unfamiliar to Sania and the Al'Aketh. They are less likely to suspect you work for village leaders, so you can approach her as an interested recruit without drawing suspicion.",al={"why me","why send an adventurer","infiltrating quest reason"}},{q="What are the Al'Aketh planning for Shen'dar Village?",a="Shen'dar Village's leaders suspect the Al'Aketh's recruiting hides broader, aggressive plans for the settlement. They want to uncover those plans before the fragile peace collapses.",al={"cult plan for village","what do the alaketh want","alaketh intentions"}}},ang={["class:Priest"]="As a priest, you may recognize that Sania Silverstream's faith is pledged to an Elemental Lord, not the Holy Light or Elune. Her pleasant religious manner conceals elemental worship.",["class:Rogue"]="As a rogue, you can use your talents for espionage, deception, and reconnaissance to approach the cult through its unsuspecting recruiter."},kw={"al'aketh","al'akir","alaketh","alakir","infiltrating the cult","sania silverstream","shen'dar village","windlord"},m={id=93036},src={"In-game quest text: Infiltrating the Cult"},fv=true}
E["quest:93065"] = {t="quest",n="Prepare for Battle",z="zephras",s="The Peacekeepers are gathering in town to march into the surrounding territory. You are called to make your final preparations and meet Valennia Stormfist in the Gustberry Lowlands before the company departs.",h="The Peacekeepers are gathering in town to march into the surrounding territory.",sec={{t="A Call to Muster",b="The Peacekeepers, the local defense forces, have called their troops and volunteers to arms as tensions rise. Secure your equipment, ready your weapons, and join the company as it forms for an organized march into the surrounding territory.",sp=0},{t="The Gathering at Gustberry Lowlands",b="The company gathers along the eastern road leading north out of town into the Gustberry Lowlands. There, organizer Valennia Stormfist inspects the fighters and calls the roll. Then the company marches into danger.",sp=0}},faq={{q="Who is Valennia Stormfist?",a="Valennia Stormfist organizes the Peacekeepers' muster in the Gustberry Lowlands. She oversees final preparations along the eastern road leading north out of town before the forces depart.",al={"who is valennia stormfist","valennia stormfist","stormfist"}},{q="Who are the Peacekeepers?",a="The Peacekeepers are an organized local defense force. They are gathering to face a looming threat outside of town.",al={"who are the peacekeepers","peacekeepers","peacekeeper force"}},{q="Where are the Gustberry Lowlands?",a="The Gustberry Lowlands is where local defense forces gather. Their staging ground lies along the road leading north out of town.",al={"where is gustberry lowlands","gustberry lowlands location","gustberry lowlands"}},{q="What are the Peacekeepers preparing for?",a="The Peacekeepers are preparing to march out in force. They call on capable allies to check their gear and gather at the edge of town before the company departs.",al={"what are they preparing for","why prepare for battle","what is the battle"}},{q="Where is the rendezvous point for the march?",a="The company meets along the eastern road leading north out of town. There, its members can gather in formation before marching into the field.",al={"where is the muster point","where to meet valennia","rendezvous point"}},{q="What happens once everyone is assembled?",a="Valennia Stormfist inspects the assembled ranks and calls the roll. Then the forces march into danger.",al={"how does the muster finish","what does valennia say","we are as ready as we will ever be"}}},ang={["class:Warrior"]="As a front-line fighter, you know this gathering comes before combat. Check your gear and form ranks beside your allies as the company prepares to march."},kw={"eastern road","gustberry lowlands","mobilization","peacekeepers","prepare for battle","valennia stormfist"},m={faction="Horde",id=93065},src={"In-game quest text: Prepare for Battle"},fv=true}
E["quest:93089"] = {t="quest",n="What Comes Next",z="zephras",s="On Zephras Isle, the High Order seeks your blessing before departing with its Kirin Tor allies. Their expedition depends on finding an arcane answer to the island’s instability.",h="On Zephras Isle, the High Order seeks your blessing before departing with its Kirin Tor allies.",sec={{t="The Departure",b="High Elder Shadowsong has blessed the expedition, and its preparations are ready. Ansirem has worked to establish skycutter travel between Dalaran and Zephras Isle. Now the vanguard is preparing to depart. Speak with Elaadrin Evengale when you are ready to leave the island.",sp=0}},faq={{q="Who do I speak with before leaving Zephras Isle?",a="Speak with Elaadrin Evengale when you are ready to leave Zephras Isle.",al={"who do i talk to","leave zephras isle","elaadrin departure"}},{q="Where is the High Order going?",a="The High Order is preparing an expedition, with skycutter transport linking Dalaran and Zephras Isle.",al={"where are they going","high order destination","next stop"}},{q="Who is helping the High Order?",a="The Kirin Tor are helping the High Order. Ansirem has worked on skycutter transport between Dalaran and Zephras Isle.",al={"who are the allies","kirin tor help","high order friends"}},{q="What is the expedition seeking?",a="The expedition hopes to find an arcane solution to bring stability to Zephras Isle.",al={"what are they looking for","arcane solution","why leave the island"}},{q="What happened to the cult?",a="Elaadrin says the cult has been defeated, and preparations for the expedition are complete.",al={"cult status","is the cult defeated","what about the cult"}}},kw={"ansirem","dalaran","elaadrin evengale","high order","kirin tor","skycutter","what comes next","zephras isle"},rel={"zone:zephras","subzone:dalaran","quest:92596"},m={faction="Alliance",id=93089},src={"In-game quest text: What Comes Next"},fv=true}
E["quest:93090"] = {t="quest",n="What Comes Next",z="zephras",s="On Zephras Isle, the expedition prepares to cross the skies for Kalimdor. The local cult is defeated, and High Elder Shadowsong has given his blessing. Skycutters now carry travelers between the island and Mulgore.",h="On Zephras Isle, the expedition prepares to cross the skies for Kalimdor.",sec={{t="Departure from Zephras Isle",b="High Elder Shadowsong has blessed the expedition's onward journey from Zephras Isle, where the local cult has been defeated and safety restored. The expedition now looks beyond the island, with its focus set on travel across the open skies toward Kalimdor. Ayessa Dawnsinger coordinates the final departure for those ready to leave.",sp=0},{t="Skycutters to Mulgore",b="Muln worked to secure steady skycutter travel between Zephras Isle and Mulgore. Test voyages succeeded, and an advance party has already crossed over. They wait on the other side to make contact with the shaman of the Earthen Ring.",sp=0}},faq={{q="What is the quest What Comes Next?",a="The expedition is preparing to leave Zephras Isle after earning High Elder Shadowsong's blessing and defeating the local cult. Travelers are ready to cross the skies by skycutter to Kalimdor.",al={"what is what comes next","what comes next quest","what is this quest"}},{q="Where does the expedition travel?",a="Skycutters connect Zephras Isle with Mulgore, a grassy mesa region in central Kalimdor. The Earthen Ring makes its home there, and advance members of the expedition are already waiting.",al={"where are we going","skycutter destination","where does the skycutter fly"}},{q="Who is Ayessa Dawnsinger?",a="Ayessa Dawnsinger coordinates the departure from Zephras Isle. Preparations are in place, test flights have succeeded, and High Elder Shadowsong has blessed the expedition's departure.",al={"who is ayessa dawnsinger","ayessa dawnsinger","ayessa"}},{q="Who is Muln?",a="Muln worked to establish steady skycutter travel between Zephras Isle and Mulgore. He conducted test voyages to ensure safe passage across the skies.",al={"who is muln","muln skycutter","muln zephras"}},{q="What is the Earthen Ring?",a="The Earthen Ring is an organization of shamans devoted to keeping harmony among the elemental spirits. Its members are the expedition's contacts and hosts in Mulgore.",al={"what is the earthen ring","earthen ring mulgore","who are the earthen ring"}},{q="Why is the expedition leaving Zephras Isle?",a="The local cult is defeated, and High Elder Shadowsong has blessed the expedition. With those tasks complete, the expedition can leave Zephras Isle and continue to the mainland.",al={"why leave zephras isle","is zephras finished","why go to mulgore"}}},ang={["class:Shaman"]="As a shaman, you travel to Mulgore to meet the Earthen Ring, a revered shamanic organization devoted to soothing Azeroth's elemental spirits.",["race:Tauren"]="As a tauren, you travel to Mulgore, your people's ancestral homeland. The Earthen Ring keeps its operations there."},kw={"ayessa dawnsinger","earthen ring","high elder shadowsong","mulgore","muln","skycutter","what comes next","zephras isle"},rel={"npc:ayessa-dawnsinger","zone:zephras","zone:mulgore","quest:95349"},m={faction="Horde",id=93090},src={"In-game quest text: What Comes Next"},fv=true}
E["quest:93159"] = {t="quest",n="The Strange Hermit",z="zephras",s="In Shadowgale Forest, a hooded hermit keeps to himself beneath the trees. Though years alone have made him shy, he shares something of his handmade life and the forest spirits who sing to him.",h="In Shadowgale Forest, a hooded hermit keeps to himself beneath the trees.",sec={{t="A Recluse in the Woods",b="Deep beneath Shadowgale Forest's canopy, you find a hooded recluse far from towns and trade routes. He is known simply as the Strange Hermit. Years without ordinary company have left him nervous and awkward in conversation. Even a greeting seems strange to him.",sp=0},{t="Spirits and Simple Things",b="The hermit says he has the company and provisions he needs. He once lived elsewhere, then chose a life here among handmade trinkets and the local forest spirits. They often sing to him, though their songs cannot answer him as another person can.",sp=0}},faq={{q="Who is the strange hermit?",a="The Strange Hermit is an eccentric, hooded recluse in Shadowgale Forest. Unused to company, he tends his handmade possessions and spends time with local woodland spirits instead of other people.",al={"strange hermit","hermit identity","who is the hermit"}},{q="Where does the hermit live?",a="The hermit lives deep among the trees of Shadowgale Forest, far from towns and trade routes where few travelers pass.",al={"where is the hermit","shadowgale forest location","hermit zone"}},{q="Why does the hermit live by himself?",a="The hermit says he lived somewhere else before choosing to settle in the forest. He keeps his past vague and makes his life among handmade things and the wild spirits of the woods.",al={"why is the hermit alone","hermit isolation","hermit backstory"}},{q="Can the hermit speak with forest spirits?",a="The local forest spirits sing to the hermit, though they do not speak with him. He enjoys their songs, but they cannot answer as another person can.",al={"hermit talking to spirits","forest spirits shadowgale","hermit friends"}},{q="What has the hermit built in the forest?",a="The hermit has made several handcrafted items and structures to occupy himself. He finds comfort and contentment in these simple belongings.",al={"hermit crafts","what did hermit build"}},{q="What happens during the quest 'The Strange Hermit'?",a="You approach the nervous hermit in Shadowgale Forest and hear what he chooses to share about his life in seclusion.",al={"strange hermit quest","speak to hermit"}}},ang={["class:Druid"]="As a druid, you may value the hermit's bond with the local forest spirits, though their songs offer less than the deeper communion you know.",["profession:Engineering"]="As an engineer, you may understand the comfort the hermit finds in building by hand to furnish his lonely dwelling."},kw={"forest spirits","handcrafted","hermit","hooded figure","loner","shadowgale forest","strange hermit"},m={id=93159},src={"In-game quest text: The Strange Hermit"},fv=true}
E["quest:93160"] = {t="quest",n="The Forest's Bounty",z="zephras",s="In Shadowgale Forest, a forager needs help gathering fallen acorns. Raptor-like predators prowl the deeper woods, and the harvest can be roasted into a forest meal.",h="In Shadowgale Forest, a forager needs help gathering fallen acorns.",sec={{t="A Perilous Foraging Run",b="A cautious forager in Shadowgale Forest has gathered the acorns near safety. Fierce, raptor-like creatures prowl among the trees and keep the forager from reaching the wilder groves. So passing travelers are needed to gather what lies deeper in the woods, and help ensure neither goes hungry.",sp=0},{t="Roasting the Harvest",b="Shadowgale Acorns make hearty food when prepared with care. Raw, they can be bitter or tough, but roasting them over a fire turns the wild harvest into a rich treat. To gather them, you must brave the timber where predatory birds prowl.",sp=0}},faq={{q="Who asks you to gather the acorns?",a="A nervous forager near Shadowgale Forest asks you to gather acorns. They have collected those nearby, but need help reaching woods where dangerous wildlife roams.",al={"who gives the forest bounty quest","who wants acorns","quest giver forests bounty"}},{q="Where are the acorns found?",a="Shadowgale Acorns lie scattered beneath Shadowgale Forest's canopy. Search the forest floor and watch for predators among the trees.",al={"where are shadowgale acorns","acorn location","shadowgale forest acorns"}},{q="Why is collecting acorns dangerous here?",a="Predatory, raptor-like birds prowl the forest floor. Without martial training, ordinary folk risk danger if they stray far from camp.",al={"why dangerous shadowgale forest","what raptor birds","why is gathering acorns dangerous"}},{q="What are the acorns used for?",a="The acorns are hearty wild food. Roast them over a fire for a warm snack to share with those willing to brave the forest beasts.",al={"what are shadowgale acorns for","roasted acorns","why gather acorns"}},{q="What are the raptor-bird creatures mentioned in the forest?",a="The forager describes dangerous “raptor-bird things” hunting in Shadowgale Forest. These avian or reptilian predators are large and vicious enough to prey on an unwary traveler.",al={"what raptor bird thing","raptor birds in shadowgale","forest raptors"}},{q="How are the acorns prepared for eating?",a="Shadowgale Acorns can be tough or bitter raw. Roasting them over heat makes them a delicious treat.",al={"are shadowgale acorns edible raw","how to cook shadowgale acorns","eating forest acorns"}}},ang={["profession:Cooking"]="As a cook, you can roast Shadowgale acorns into simple forest fare."},kw={"acorns","cooking","foraging","raptor-bird","shadowgale acorns","shadowgale forest","the forest's bounty"},m={id=93160},src={"In-game quest text: The Forest's Bounty"},fv=true}
E["quest:93165"] = {t="quest",n="Mercy Falls on Deaf Ears",z="zephras",s="In the wilds around Shadowgale Forest, the Nightclaw survivors seek vengeance against the Al'Aketh. After a terrible tragedy at the cultists' hands, they offer coin and a promise of access to their hidden lore for trophies taken from slain enemies. Their feud now reaches across Shadowgale Forest and the surrounding territories.",h="In the wilds around Shadowgale Forest, the Nightclaw survivors seek vengeance against the Al'Aketh.",sec={{t="Blood for Blood",b="The Nightclaw enclave and the Al'Aketh cultists are locked in a bitter feud. A terrible tragedy has left the survivors with no hope of peace. They seek vengeance for their fallen kin and turn to wandering adventurers and mercenaries for help. The enclave offers coin and the promise of deeper trust to those who kill cultists and bring back their ears as proof.",sp=0},{t="The Al'Aketh Menace",b="The Al'Aketh spread their influence through the Gustberry Lowlands, Shadowgale Forest, and the ancient Shrine of Akir. Their dark practices and fanatical ways have earned the hatred of local inhabitants. Striking the cult's camps across these lands can weaken its reach and earn favor with the secretive Nightclaw. The enclave keeps its mysteries close until an outsider proves their loyalty.",sp=0}},faq={{q="What is Mercy Falls on Deaf Ears?",a="The Nightclaw enclave offers coin and deeper trust to those who kill Al'Aketh cultists and bring back their ears. The survivors seek vengeance after a terrible tragedy.",al={"mercy falls on deaf ears quest","what is this quest","quest overview"}},{q="Who are the Al'Aketh?",a="The Al'Aketh are a sect of accursed cultists whose actions have brought ruin and tragedy to neighboring settlements. They operate across the Gustberry Lowlands, Shadowgale Forest, and the Shrine of Akir, provoking blood feuds with the people of those lands.",al={"who are the alaketh","alaketh cultists lore","who are al'aketh"}},{q="Where can Al'Aketh cultists be found?",a="Al'Aketh cultists can be found in Shadowgale Forest, around the Shrine of Akir, and throughout the Gustberry Lowlands. The Nightclaw seek proof from those who kill them.",al={"where are alaketh cultists","alaketh locations","where to find cultists"}},{q="Why does the quest giver collect cultist ears?",a="The Nightclaw demand cultist ears as proof that their enemies are dead. After a severe tragedy at the Al'Aketh's hands, the enclave seeks vengeance and proof for every bounty paid.",al={"why ears","why do they want cultist ears","ears proof"}},{q="Who are the Nightclaw?",a="The Nightclaw are a secretive enclave that has suffered heavy losses at the hands of the Al'Aketh. They guard their lore closely, but promise outsiders access to their mysteries if they prove their loyalty by fighting the cultists.",al={"nightclaw faction","who are nightclaw","nightclaw secrets lore"}},{q="What tragedy did the Al'Aketh cause?",a="The Al'Aketh caused a great tragedy for the Nightclaw enclave, sparking an uncompromising blood feud. The bounty gives no details of the incident or its casualties, but the survivors demand total vengeance.",al={"what did the alaketh do","what happened to the enclave","alaketh tragedy"}},{q="What are the Nightclaw's secrets?",a="The Nightclaw keep their secrets within the enclave and do not reveal them to outsiders at once. They promise access to this hidden knowledge to those who keep aiding their fight against the Al'Aketh and prove themselves true friends.",al={"nightclaw secrets","what secrets does nightclaw have","what does nightclaw reveal"}}},kw={"al'aketh","blood feud","cultists","ears","gustberry lowlands","mercy falls on deaf ears","nightclaw","shadowgale forest","shrine of akir"},m={id=93165},src={"In-game quest text: Mercy Falls on Deaf Ears"},fv=true}
E["quest:93172"] = {t="quest",n="Free the Hollows",z="zephras",s="In Shadowgale Forest, the wind hollows’ sorrowful song carries through ancient ruins. An old tragedy binds these ghost-like spirits, and travelers seek to give them peace.",h="In Shadowgale Forest, the wind hollows’ sorrowful song carries through ancient ruins.",sec={{t="Hauntings of Shadowgale",b="Elves across the island have long feared Shadowgale Forest as a haunted grove. In its northeastern woods, old stone ruins lie beneath the overgrowth. Ghost-like wind hollows drift there without rest, but they show no malice. Their sorrow points to a disaster that befell the ruins ages ago.",sp=0},{t="The Mournful Song",b="On quiet nights, travelers near the ruins hear strange singing on the breeze. No mortal song sounds like it, and its deep melancholy unsettles those who hear it. Compassionate travelers believe the shades suffer in their endless lament. They seek the wind hollows to break their spectral bonds and grant them peace.",sp=0}},faq={{q="What are the wind hollows?",a="Wind hollows are sorrowful, ghost-like spirits haunting old elven ruins in northeastern Shadowgale Forest. Bound by an ancient tragedy, they sing mournfully through the trees at night.",al={"what are wind hollows","hollows lore","what are the hollows"}},{q="Why do the wind hollows need to be freed?",a="The spirits are believed to remain bound by a terrible catastrophe and trapped in sorrow. Destroying them is seen as an act of mercy that releases their lingering forms from the ruins.",al={"why free hollows","why kill hollows","free the hollows purpose"}},{q="Where are the spirits found?",a="The spirits gather among ancient ruins in the northeastern woods of Shadowgale Forest, an island woodland inhabited by elves.",al={"where is shadowgale forest","shadowgale ruins","ruins location"}},{q="What is the strange singing heard in the woods?",a="The wind hollows sing a sorrowful melody unlike any ordinary tune. Their song is thought to come from their tragic end and their endless confinement among the island’s ruins.",al={"hollow singing","ghost song","why are ghosts singing"}},{q="Who asks you to free the hollows?",a="An island observer who pities the trapped spirits asks you to free them, mindful that local elves fear the haunted woods.",al={"who gives free the hollows","questgiver free the hollows"}},{q="What happened at the ruins to create the hollows?",a="The exact details are lost to time, but locals know a terrible event took place at the northeastern ruins and bound the spirits there in endless sorrow.",al={"what happened at shadowgale ruins","why are the ruins haunted"}}},ang={["race:NightElf"]="As an island elf, you know Shadowgale Forest has long been feared as haunted, its spirits bound to ancient ruins.",["class:Priest"]="As a priest, you see the wind hollows as sorrowful spirits trapped by tragedy. Destroying them is seen as mercy, releasing souls bound in anguish.",["class:Druid"]="As a druid, you know the unquiet spirits in Shadowgale Forest disturb the wilderness and call for balance and release."},kw={"free the hollows","ghosts","hollows","ruins","shadowgale","shadowgale forest","wind hollows"},m={id=93172},src={"In-game quest text: Free the Hollows"},fv=true}
E["quest:93317"] = {t="quest",n="Crab Season",z="zephras",s="On Zephras, foragers hurry to gather Windsong crawlers before the brief season ends. Cultists have made the shores perilous, so locals call for help.",h="On Zephras, foragers hurry to gather Windsong crawlers before the brief season ends.",sec={{t="A Fleeting Harvest",b="For a few weeks each year, Windsong crawlers appear along Windsong Lake’s freshwater shores and the rivers that feed it. Their meat is a rare harvest, but the season soon passes.",sp=0},{t="Peril by the Waters",b="Cultists patrol the wilderness around Zephras, putting local foragers in danger. The journey to Windsong Lake is too hazardous for gatherers alone. Unless you brave the shores and the ill-tempered crabs, this brief harvest may be lost.",sp=0}},faq={{q="What are Windsong crawlers?",a="Windsong crawlers are aggressive crabs found only around Windsong Lake on Zephras. They can be gathered for just a few weeks each year.",al={"what are windsong crawlers","windsong crabs","lake crabs zephras"}},{q="Why do the crabs need to be harvested right now?",a="Windsong crawlers are available for only a few weeks each year. Once the season closes, their meat cannot be gathered again until the next year.",al={"why harvest crawlers now","crawler season window","why limited time crabs"}},{q="Why can't the local harvester gather the crabs themselves?",a="Cultist activity has made the journey to Windsong Lake too dangerous for local foragers to make before the short season ends.",al={"why cant locals gather crabs","cultists zephras","windsong cult activity"}},{q="Where are Windsong crawlers found?",a="Windsong crawlers live along the shores of Windsong Lake on Zephras and the nearby connecting riverbanks.",al={"windsong crawler locations","where are crabs on zephras","windsong lake shores"}},{q="Are Windsong crawlers dangerous to hunt?",a="Windsong crawlers are aggressive and snap at anyone trying to gather them.",al={"are windsong crawlers dangerous","crab temperament","mean crabs"}},{q="What is Windsong crawler meat used for?",a="Locals gather Windsong crawler meat as seasonal food during the few weeks it is available. Cultists blocking the paths have led them to seek help from adventurers.",al={"windsong crawler meat purpose","why collect crab meat","what is crawler meat for"}}},ang={["profession:Cooking"]="As a cook, you can prepare seasonal Windsong crawler meat gathered from Zephras’s lake."},kw={"crab season","crabs","cult activity","windsong crawler meat","windsong crawlers","windsong lake","zephras"},m={id=93317},src={"In-game quest text: Crab Season"},fv=true}
E["quest:93318"] = {t="quest",n="WANTED: Vulgara the Insatiable",z="zephras",s="In the Shen'dar Highlands, Vulgara the Insatiable terrorizes travelers and nearby settlements. Constable Aonda has called for a Peacekeeper bounty, with Vulgara's head to be brought to Danarii Bellowveil.",h="In the Shen'dar Highlands, Vulgara the Insatiable terrorizes travelers and nearby settlements.",sec={{t="The Highland Scourge",b="Constable Aonda has named Vulgara the Insatiable an immediate danger to the highlands. The massive winged vuldren roosts southwest of Shen'dar Village, where she terrorizes travelers and local settlements. The Peacekeepers call on bounty hunters to end the threat.",sp=0},{t="Pressured Protectors",b="Bandits and a shadowy cult trouble the Peacekeepers across the region. Slaying Vulgara would ease the danger to local people and keep the skies over Shen'dar safe. Then the defenders could focus on civil defense.",sp=0}},faq={{q="Who is Vulgara the Insatiable?",a="Vulgara the Insatiable is a massive, winged vuldren terrorizing the Shen'dar Highlands. Local authorities call her a scourge, and her ravenous appetite and violence endanger travelers and nearby settlements.",al={"who is vulgara","vulgara lore","what kind of monster is vulgara"}},{q="Who placed the bounty on Vulgara?",a="Constable Aonda of the local Peacekeepers issued the bounty to protect local citizens. Hunters are to bring proof of Vulgara's death to Danarii Bellowveil.",al={"who posted vulgara bounty","who wants vulgara dead","constable aonda"}},{q="Where can Vulgara the Insatiable be found?",a="Vulgara prowls a hilltop southwest of Shen'dar Village in the Shen'dar Highlands.",al={"vulgara location","where does vulgara spawn","find vulgara"}},{q="Who is Danarii Bellowveil?",a="Danarii Bellowveil handles the bounty's fulfillment. With bandits and cultists pressing the Peacekeepers, Danarii inspects Vulgara's severed head and dispenses the promised reward.",al={"who is danarii bellowveil","danarii turn in"}},{q="What kind of creature is a vuldren?",a="A vuldren is a dangerous, predatory winged beast found in the highlands. Vulgara is particularly massive and vicious, and her predation threatens local settlements.",al={"what is a vuldren","vuldren beast"}},{q="What other threats plague the Shen'dar Highlands?",a="The Peacekeepers in the Shen'dar Highlands are stretched thin by an entrenched cult and bandits preying on local citizens. Predatory beasts like Vulgara trouble them as well.",al={"what threats are in shendar highlands","shendar cult and bandits"}}},kw={"bounty","constable aonda","danarii bellowveil","peacekeepers","shen'dar highlands","shen'dar village","vuldren","vulgara","vulgara the insatiable"},m={id=93318},src={"In-game quest text: WANTED: Vulgara the Insatiable"},fv=true}
E["quest:93319"] = {t="quest",n="Pilfered Windstones",z="zephras",s="On Zephras, stolen windstones have left emergency stores short. The Highlands Bandits took them while Aonda's few peacekeepers guard against growing cultist numbers at Falaath Village.",h="On Zephras, stolen windstones have left emergency stores short.",sec={{t="The Stolen Caches of Zephras",b="Windstones keep daily life moving on Zephras. Each settlement keeps emergency stores for times of crisis, but village supplies began to run short. Then captured bandits from the northern Shen'dar Highlands were found carrying the stones. For months, the Highlands Bandits had slipped into local stockpiles, taking what they could while security was thin.",sp=0},{t="Stretched Defenses and Looming Threats",b="Aonda is responsible for village defense, and has refused to approve a raid on the northern cave. The settlement has too few peacekeepers to spare. To the south, cultists are multiplying at Falaath Village, so the guards must hold their posts against that threat. With the peacekeepers pinned down, independent adventurers must face the bandits and recover the stolen windstones.",sp=0}},faq={{q="What are windstones used for on Zephras?",a="Residents on Zephras rely on windstones for daily life and survival. Settlements keep reserve caches for emergencies.",al={"what are windstones used for","why need windstones","windstone purpose"}},{q="Who stole the windstones?",a="The Highlands Bandits stole the windstones. Captured bandits from a cave in the Shen'dar Highlands were found carrying them, and locals believe the thieves had been breaking into village storehouses for months.",al={"who stole the windstones","who took windstones","windstone thieves"}},{q="Where are the Highlands Bandits located?",a="The Highlands Bandits camp in a cave north of the settlement, in the Shen'dar Highlands. They keep goods taken from village stores there.",al={"where is the bandit cave","highlands bandits location","shendar bandits"}},{q="Why hasn't the village cleared out the bandit cave?",a="Aonda oversees the settlement's defense and has declined to organize a raid on the northern cave because the village has few peacekeepers. Sending them away would leave the settlement vulnerable to growing cultist numbers at Falaath Village to the south.",al={"why not attack the bandit cave","why aonda wont attack","village defense bandits"}},{q="What is the threat at Falaath Village?",a="Cultist numbers are growing at Falaath Village, south of the settlement. Their presence keeps the peacekeepers guarding their home instead of pursuing bandits.",al={"what is falaath village threat","cultists falaath","falaath cultists"}},{q="Does recovering the windstones solve the settlement's shortage?",a="Recovering the stolen stones gives emergency stores temporary relief, but supply route disruptions remain urgent. Without secure supply lines, shortages will continue to threaten the settlement.",al={"are windstones secure now","supply routes zephras","windstone shortage fixed"}}},ang={["class:Rogue"]="As a Rogue, you can see how the Highlands Bandits exploit a settlement stretched thin by cultist threats.",["race:Skyborne"]="As a Skyborne, you know daily life on Zephras depends on windstones. Recovering and defending these caches matters to local settlements."},kw={"aonda","bandit cave","falaath village","highlands bandits","pilfered windstones","shen'dar highlands","windstones","zephras"},rel={"quest:92529"},m={id=93319},src={"In-game quest text: Pilfered Windstones"},fv=true}
E["quest:93320"] = {t="quest",n="Tower Defense",z="zephras",s="At the fortified position, Tower Defense holds against overwhelming numbers. The defenders have kept the line for now, but exhaustion threatens to break it.",h="At the fortified position, Tower Defense holds against overwhelming numbers.",sec={{t="A Beleaguered Defense",b="The garrison holds back the first assault at a fortified position. Yet the attackers outnumber them and keep pressing forward. The surviving fighters are growing tired, and the line between survival and defeat grows thin.",sp=0},{t="The Threat of Attrition",b="The garrison keeps its perimeter, but time favors the attackers. Prolonged skirmishes against superior numbers drain the defenders’ strength. They need a decisive move to break the stalemate before their lines buckle.",sp=0}},faq={{q="What is Tower Defense about?",a="Tower Defense is a desperate defense against overwhelming numbers. The line still holds, but exhaustion threatens to break it unless the stalemate ends.",al={"what is tower defense","tower defense quest","what is this quest"}},{q="Who are the defenders fighting?",a="The attackers outnumber the defenders and press hard enough to wear down the garrison. The cult is attacking the pylon watchtower outside town.",al={"who attacks in tower defense","who are we fighting","tower defense enemy"}},{q="What is the current status of the defenders?",a="The defenders are tiring from prolonged combat under relentless assault. Without relief, the garrison risks losing ground unless the stalemate breaks soon.",al={"why are defenders tired","stalemate at the tower","status of the fight"}},{q="Does holding the line resolve the battle?",a="Holding off the assault buys only a little time. Fatigue will wear down the defenders unless they find a way to break the deadlock.",al={"did we win tower defense","how does tower defense end","what happens after holding them off"}},{q="Where does this defense take place?",a="The defense takes place at a fortified outpost under siege. Constant pressure from numerous attackers has stretched the defenders thin.",al={"where is tower defense located","tower defense zone","what tower is this"}},{q="What is needed to turn the tide?",a="The defenders need a swift plan to break the siege before their exhausted frontline gives way.",al={"what needs to be done next","how to win the siege","breaking the stalemate"}}},ang={["class:Warrior"]="As a warrior, you know a hold against superior numbers tests stamina as much as skill. Discipline on the frontline can keep the defense from collapsing."},kw={"defenders","exhaustion","fortification","outpost","siege","stalemate","tower defense"},m={faction="Horde",id=93320},src={"In-game quest text: Tower Defense"},fv=true}
E["quest:93461"] = {t="quest",n="Welcome to Shen'dar Village",z="zephras",s="In Shen'dar Village, newcomers with Highborne blood are welcomed under a fragile truce. The High Order and Windshapers keep peace within the settlement, while old rivalries simmer beyond its borders.",h="In Shen'dar Village, newcomers with Highborne blood are welcomed under a fragile truce.",sec={{t="A Fragile Hearth",b="Newcomers with traces of Highborne blood go to the main lodge to pay respects to Rathiril Sunlance, elder of the High Order. They also seek a room from Coriella Calmbreeze, the local innkeeper. Different elven factions share this haven, but their truce remains tense.",sp=0},{t="Rivalries of the Wilds",b="Daily life brings rooms and odd jobs, yet friction persists between the High Order and the Windshapers. In the village square, both groups observe civility. Beyond the settlement, away from prying eyes, old rivalries go unchecked.",sp=0}},faq={{q="What is the purpose of the quest Welcome to Shen'dar Village?",a="You are welcomed to Shen'dar Village and introduced to its key figures and fragile peace. You meet Rathiril Sunlance, the High Order elder, and Coriella Calmbreeze at the village inn before taking on local work.",al={"what is this quest","welcome to shendar village info","shendar village intro"}},{q="Who is Rathiril Sunlance?",a="Rathiril Sunlance is an elder of the High Order who lives in Shen'dar Village. He is in the main village lodge, around the corner from the one who first welcomes you, and is a contact for those with Highborne lineage or dealings with the High Order.",al={"who is rathiril sunlance","high order elder","where is rathiril"}},{q="Who is Coriella Calmbreeze?",a="Coriella Calmbreeze runs the local inn in Shen'dar Village. She offers travelers food, lodging, and supplies before they venture into the surrounding wilds.",al={"who is coriella calmbreeze","shendar innkeeper","where to get lodging shendar"}},{q="What is the tension between the High Order and the Windshapers?",a="The High Order and the Windshapers follow different traditions and ambitions, and tensions run high between them. They keep a civil peace within Shen'dar Village, but beyond its edge, conflict can spill into violence in the wilds.",al={"high order vs windshapers","why is there tension","village conflict"}},{q="What is the High Order look mentioned by the questgiver?",a="Those descended from the Highborne have a distinct twinkle in their eyes. This arcane inheritance lets observant locals recognize the look of the High Order.",al={"high order look","highborne eyes","highborne twinkle"}},{q="Is Shen'dar Village safe from conflict?",a="Civility is kept between the High Order and Windshapers inside Shen'dar Village. Outside the settlement, the peace ends, and open hostility flares away from watchful eyes.",al={"is shendar safe","violence outside shendar","wilds danger"}}},ang={["race:NightElf"]="As a night elf, you find Shen'dar Village tied to ancient Highborne bloodlines and legacy, a reminder of the pride and arcane heritage that divided elven society.",["class:Mage"]="As a mage with ties to Highborne traditions, you may recognize your lineage in the High Order. Its elders, including Rathiril Sunlance, command respect in Shen'dar."},kw={"coriella calmbreeze","high order","highborne","main lodge","rathiril sunlance","shendar village","windshapers"},rel={"topic:highborne","quest:92595"},m={id=93461},src={"In-game quest text: Welcome to Shen'dar Village"},fv=true}
E["quest:93552"] = {t="quest",n="Harvesting Windstones",z="zephras",s="At Thendal Grove, Dalia the Collector asks you to gather raw windstones before their power fades. The ancient elemental energies of Zephras Isle are slowly dwindling.",h="At Thendal Grove, Dalia the Collector asks you to gather raw windstones before their power fades.",sec={{t="A Fading Island",b="Zephras Isle still draws on wind magic, but its natural defenses are failing. Centuries ago, the wind elementals who shared the island with its elves vanished. Since then, the magic that sustains the land and its great anchor pylons has weakened. So Thendal Grove’s residents need every reserve of raw energy they can secure.",sp=0},{t="The Value of Windstones",b="Blue crystalline windstones lie scattered through Thendal Grove. Their brittle shells hold dense wind magic from ages past. They cannot sustain the island forever, yet they give its elves a dependable source of arcane power. Gathering raw clusters remains vital to daily life.",sp=0}},faq={{q="What are windstones?",a="Windstones are blue crystalline deposits scattered around Thendal Grove. They hold concentrated raw wind energy, which the elves of Zephras Isle gather as magical fuel.",al={"raw windstone","windstone cluster","blue crystals"},it="power"},{q="Who is Dalia the Collector?",a="Dalia the Collector is an elven collector stationed in Thendal Grove on Zephras Isle. She organizes the gathering of vital raw resources, especially windstones, to support the island’s dwindling magical reserves.",al={"dalia","dalia zephras","collector dalia"},it="identity"},{q="Why is the magic on Zephras Isle fading?",a="Centuries ago, the wind elementals who lived alongside the local elves vanished. Since then, the great anchor pylons’ magic, which sustains the island, has slowly drained away.",al={"zephras losing magic","fading magic zephras","anchor pylons"},it="threat"},{q="Where did the wind elementals go?",a="No one knows where the wind elementals went. They vanished several centuries ago, leaving the island to slowly exhaust its remaining elemental reserves.",al={"missing elementals","where are wind elementals","elementals vanished"},it="history"},{q="What are the anchor pylons?",a="The great anchor pylons are ancient structures on Zephras Isle, imbued with powerful magic that sustains the land. Since the elementals vanished, that sustaining power has gradually weakened.",al={"great anchor pylons","anchor pylon lore"},it="place"},{q="Where do you find raw windstones?",a="Raw windstones are scattered across Thendal Grove on Zephras Isle, where they appear as glowing blue crystalline outcrops.",al={"windstone location","thendal grove crystals"},it="place",gp=true},{q="Why does Dalia the Collector want Windstone Clusters?",a="Dalia seeks Windstone Clusters because Zephras Isle relies on their magical power to endure. Ever since the wind elementals vanished centuries ago, the sustaining magic that once nourished the island has been slowly waning. To the local elves, whose lives and culture remain deeply tied to arcane energy, collecting these crystallized winds provides a vital and dependable energy source to replace what the failing anchor pylons can no longer supply.",al={"why dalia wants windstones","dalia collector motive","why harvest windstones"},it="motive",add="0a83a06c"},{q="What are Windstone Clusters used for?",a="Windstone Clusters hold the raw, concentrated energy of the winds themselves. Because the ancient magical anchor pylons on Zephras Isle are losing their potency over time, the isle's inhabitants harness these crystallized clusters as a reliable alternative source of power to sustain their community and maintain their essential connection to magical energy.",al={"windstone cluster use","what is windstone cluster for","why windstone clusters"},it="item",add="33ac4299"}},ang={["class:Mage"]="As a Mage, you can see the elemental power held in windstones and how fragile magical ecosystems become when their elemental sources vanish.",["profession:Mining"]="As a miner, you gather valuable minerals and crystals from the wilds of Zephras Isle, including raw windstones."},kw={"anchor pylons","dalia","dalia the collector","thendal grove","wind elementals","windstone cluster","windstones","zephras isle"},rel={"zone:zephras"},m={start="Dalia the Collector",level="4",id=93552,ri={"Windstone Cluster"}},src={"Harvesting Windstones"},fv=true}
E["quest:93735"] = {t="quest",n="The Broken Construct",z="zephras",s="In Valanaar, a damaged construct threatens one of the island’s last working relics. Riaani Nightwind has gone to the city’s western edge to examine it. The old machines carry a history reaching back to the spirits of the wind.",h="In Valanaar, a damaged construct threatens one of the island’s last working relics.",sec={{t="Gifts of the Wind Spirits",b="Long ago, the spirits of the wind gave the island’s people magical instruments, devices, and animated constructs. Across generations, the Windshapers cared for these gifts. Then the spirits departed, and their patronage ended. Most creations fell into disrepair. Only a handful still work.",sp=0},{t="A Crisis in Valanaar",b="One of Valanaar’s last working constructs has been damaged. Its loss would further diminish the island’s dwindling heritage. Artisan Riaani Nightwind was sent to the city’s western edge to examine the machine and try to repair it. These ancient devices are fragile, and she needs aid.",sp=0}},faq={{q="Who are the Windshapers?",a="The Windshapers are local caretakers entrusted with tending the magical instruments, devices, and constructs gifted by the spirits of the wind. Since the spirits departed, they have worked to preserve the few relics that still function.",al={"who are the windshapers","windshapers lore","what do windshapers do"}},{q="Where did the magical constructs come from?",a="The spirits of the wind gave the island’s inhabitants magical constructs, instruments, and devices. Since the spirits departed, very few of these creations still function.",al={"who built constructs","construct origins","where did the constructs come from"}},{q="Who is Riaani Nightwind?",a="Riaani Nightwind is an artisan sent to Valanaar’s western edge to inspect and repair one of the city’s few working constructs after it was damaged.",al={"who is riaani nightwind","riaani location","artisan in valanaar"}},{q="Why are most of the island's constructs broken?",a="Most of the island’s constructs fell into disrepair after the spirits of the wind departed and their ancient patronage ended. Only a handful remain in working order.",al={"why are constructs broken","why did constructs fail","wind spirits leaving"}},{q="What is Valanaar's connection to the constructs?",a="Valanaar is home to some of the island’s last working constructs gifted by the wind spirits. One was recently damaged on the city’s western end, and Riaani Nightwind was sent to examine and repair it.",al={"what is valanaar","valanaar city","where is the construct"}},{q="What needs to be done for The Broken Construct?",a="You are asked to travel to Valanaar’s western edge, find artisan Riaani Nightwind, and help him repair the damaged construct.",al={"broken construct quest goal","what do i do broken construct","where to go broken construct"}}},ang={["class:Mage"]="As a mage, you may find the delicate magical devices tended by the Windshapers especially interesting.",["class:Shaman"]="As a shaman, you can see the old bond between the island’s people and the spirits of the wind in the constructs they gifted before departing.",["profession:Engineering"]="As an engineer, you can appreciate the mechanical and magical challenges artisans face when keeping ancient enchanted constructs working without their original spirit patrons."},kw={"artisan","broken construct","construct","riaani nightwind","valanaar","wind spirits","windshapers"},rel={"quest:92595"},m={faction="Horde",id=93735},src={"In-game quest text: The Broken Construct"},fv=true}
E["quest:93736"] = {t="quest",n="Unwelcome Spirits",z="zephras",s="The Windshapers seek the spirits of the wind, gone from their reach. Now hollows appear in Shadowgale Forest, and the order gathers their essences to learn what drove the true spirits away.",h="The Windshapers seek the spirits of the wind, gone from their reach.",sec={{t="The Vanished Spirits",b="The Windshapers have lost communion with the spirits of the wind. They seek to learn why the spirits left and what might bring them back. Their departure has left a void in the local elemental atmosphere.",sp=0},{t="Shadows in Shadowgale",b="After the wind spirits departed, strange sprites called hollows appeared in Shadowgale Forest to the north. The Windshapers had not known of them before the spirits vanished. The hollows seem tied to the spirits’ absence, and their essences may help reveal what they are.",sp=0}},faq={{q="Who are the Windshapers?",a="The Windshapers are an order seeking to learn why the spirits of the wind abandoned them and how to bring them back. Their inquiries now focus on strange occurrences that began after the spirits disappeared.",al={"who are the windshapers","windshaper faction","what do windshapers want"}},{q="What are the hollows?",a="Hollows are strange wind sprites that appeared in Shadowgale Forest after the original wind spirits departed. Their origins and nature remain unknown, so scholars gather their essences for study.",al={"what are hollows","wind hollow lore","hollow sprites"}},{q="Where is Shadowgale Forest?",a="Shadowgale Forest lies to the north. Strange wind hollows have appeared there since the area's elemental spirits departed.",al={"where is shadowgale forest","shadowgale location"}},{q="Why did the wind spirits leave?",a="No one knows why the spirits of the wind vanished. The Windshapers seek the cause and hope to restore communion with them.",al={"why did wind spirits leave","where did the spirits go"}},{q="Why are Wind Hollow Essences being gathered?",a="The Windshapers gather essences from dispersed hollows for study. They hope these remains will reveal what brought the beings into existence after the spirits departed.",al={"why collect hollow essences","wind hollow essence purpose"}},{q="Are the hollows considered hostile?",a="The hollows are unwelcome intruders that appeared when the natural spirits were gone. Their spread through Shadowgale Forest calls for dispersal so the region is protected and specimens can be gathered.",al={"are hollows dangerous","hollow sprite threat"}}},ang={["class:Shaman"]="For those who commune with the elements, the natural wind spirits' departure and the hollows' arrival point to a deep disturbance in the local balance of air."},kw={"hollows","shadowgale forest","sprites","unwelcome spirits","wind hollow essence","wind hollows","wind spirits","windshapers"},rel={"quest:92595"},m={faction="Horde",id=93736},src={"In-game quest text: Unwelcome Spirits"},fv=true}
E["quest:93737"] = {t="quest",n="The Broken Construct",z="zephras",s="Ayessa has sent you to help Riaani Nightwind with a disabled construct. Hear his plans and learn what he needs done to set the machine right.",h="Ayessa has sent you to help Riaani Nightwind with a disabled construct.",sec={{t="Assisting the Artisan",b="Ayessa sends you to help Riaani Nightwind with a damaged construct. He is deep among its inner parts, searching for the cause of the trouble. Surprised by your arrival, Riaani doubts an untrained traveler can manage delicate mechanical work. Once he climbs out, he agrees to explain what needs doing.",sp=0},{t="Troubleshooting Machinery",b="A construct depends on precise assembly and careful calibration. When it breaks down, its engineer faces serious work. Riaani Nightwind is shoulder-deep in mechanical parts and needs another pair of hands to gather materials or test the machine in the field. Listen to his briefing to learn how you can help bring the inert construct back to working order.",sp=0}},faq={{q="Who is Riaani Nightwind?",a="Riaani Nightwind is a tinkerer working on a disabled mechanical construct. He doubts newcomers sent to help, but needs assistance to get the machine working again.",al={"who is riaani nightwind","riaani","construct mechanic"}},{q="Who is Ayessa?",a="Ayessa is an associate who sends travelers to help Riaani Nightwind with his mechanical troubles. Her referral persuades him to consider putting a newcomer to work.",al={"who sent me to riaani","ayessa","who is ayessa"}},{q="What is the broken construct?",a="The broken construct is a mechanical creation that has stopped working properly. Riaani Nightwind is inside it, searching for the parts and tasks needed for repairs.",al={"what is the construct","what machine is riaani fixing","broken machine"}},{q="What does Riaani need help with?",a="Ayessa has sent you to help Riaani. He needs time to climb out of the construct's inner workings and explain what help he needs.",al={"what does riaani want me to do","broken construct task","how to help riaani"}},{q="Why is Riaani skeptical of your help?",a="Riaani is absorbed in technical work and impatient when interrupted. He sees most adventurers as untrained novices until they show they can follow mechanical instructions.",al={"why does riaani call me a novice","is riaani rude","riaani dialogue"}}},ang={["profession:Engineering"]="As an engineer, you know the frustration of troubleshooting a construct with complicated mechanical parts."},kw={"ayessa","broken construct","construct","engineering","riaani nightwind","the broken construct"},m={faction="Horde",id=93737},src={"In-game quest text: The Broken Construct"},fv=true}
E["quest:93738"] = {t="quest",n="The Broken Construct",z="zephras",s="A Windshaper asks you to tell Ayessa Dawnsinger what you learned about the broken construct. The High Order’s work with wind spirit magic has drawn concern.",h="A Windshaper asks you to tell Ayessa Dawnsinger what you learned about the broken construct.",sec={{t="Return to Ayessa",b="Take what you learned to Ayessa Dawnsinger in Valanaar. The High Order has tested the Windshapers’ patience with its experiments in wind spirit magic. It has also touched knowledge under Windshaper purview. Ayessa can decide what should happen next.",sp=0},{t="A Troubling Name",b="Ayessa believes the High Order was responsible for the construct breaking down. She knows Belathaan as Valennia Stormfist’s cousin, and says his mother was a Windshaper. His involvement leaves her disappointed. She needs time to reflect.",sp=1}},faq={{q="Who should I report to?",a="Report what you learned to Ayessa Dawnsinger in Valanaar.",al={"report to ayessa","where report","ayessa daw sinsinger"}},{q="Why are the Windshapers concerned about the High Order?",a="The High Order has experimented with wind spirit magic and meddled with knowledge under Windshaper purview, though it is forbidden to do so.",al={"high order trouble","why windshapers mad","high order wind magic"}},{q="What happened to the construct?",a="Ayessa believes the High Order was responsible for the construct breaking down.",al={"broken construct","construct broke","why construct broken"}},{q="Who is Belathaan?",a="Belathaan is Valennia Stormfist’s cousin, and his mother was a Windshaper.",al={"belathaan","belathaan family","belathaan cousin"}}},kw={"ayessa dawnsinger","belathaan","broken construct","high order","valanaar","valennia stormfist","wind spirits","windshaper"},rel={"npc:ayessa-dawnsinger","quest:92596"},m={faction="Horde",id=93738},src={"In-game quest text: The Broken Construct"},fv=true}
E["quest:93740"] = {t="quest",n="Blood for Blood",z="zephras",s="Several Windshaper novices lie dead in the Highlands, and the Windshapers suspect the Al'Aketh. Ayessa sends you north to the Gustberry Lowlands to answer the killings and bring back the fallen cultists' windstone prayer charms.",h="Several Windshaper novices lie dead in the Highlands, and the Windshapers suspect the Al'Aketh.",sec={{t="A Grim Discovery",b="Several Windshaper novices have been found slain in the Highlands. Proof is scarce, yet the Windshapers suspect the Al'Aketh cultists. Their zealotry makes them the chief suspects. The Windshapers' creed demands an eye for an eye, so they will not let the killings go unanswered.",sp=0},{t="Demands of Retribution",b="Ayessa calls for you to strike at any Al'Aketh you find north in the Gustberry Lowlands. She asks you to bring back the windstone prayer charms carried by the fallen cultists, as proof of their deaths. The Windshapers see this strike as an answer to the cultists' long fanaticism.",sp=0}},faq={{q="Who are the Al'Aketh?",a="The Al'Aketh are cultists whom the Windshapers regard as bloody zealots. The Windshapers suspect them of slaying novices in the Highlands.",al={"who are the alaketh","alaketh cultists","who are we fighting"}},{q="Why are the Windshapers seeking retribution?",a="Several Windshaper novices were found dead in the Highlands, and the Windshapers suspect the Al'Aketh. Their creed calls for vengeance in return.",al={"why kill alaketh","windshaper novices dead","why revenge"}},{q="Who is Ayessa?",a="Ayessa represents the Windshapers. She directs their retribution against the Al'Aketh and collects the prayer charms taken from fallen cultists.",al={"who is ayessa","quest giver","ayessa windshaper"}},{q="What are the windstone prayer charms?",a="Al'Aketh cultists carry windstone prayer charms. Ayessa asks for them as proof that the cultists responsible for the killings have been slain.",al={"what are windstone charms","prayer charms","proof of the deed"}},{q="Where can the Al'Aketh be found?",a="The Al'Aketh are to the north in the Gustberry Lowlands, where they carry out their practices.",al={"where are the alaketh","where are cultists","gustberry lowlands location"}}},kw={"al'aketh","ayessa","blood for blood","cultists","gustberry lowlands","highlands","windshapers","windstone prayer charms"},rel={"quest:92595"},m={faction="Horde",id=93740},src={"In-game quest text: Blood for Blood"},fv=true}
E["quest:93746"] = {t="quest",n="A Firm Response",z="zephras",s="Ayessa Dawnsinger answers the High Order’s intrusion on Zephras Isle with force. She sends you after Belathaan Brightwish on the road north to the Shrine of Akir, to make the Windshapers’ boundaries clear.",h="Ayessa Dawnsinger answers the High Order’s intrusion on Zephras Isle with force.",sec={{t="Drawing the Line",b="The Windshapers of Zephras Isle will not accept the High Order’s secretive scrutiny. Their warnings have gone unheeded, so Ayessa Dawnsinger escalates the dispute. She sends you to intercept Belathaan Brightwish on the lonely road north to the Shrine of Akir, away from prying eyes in town.",sp=0},{t="Storms on the Road",b="Belathaan Brightwish travels north toward the ancient Shrine of Akir, and his purpose is unclear. When you confront him on the secluded road, he turns hostile, and Living Storms join the fight. Defeating the elementals and humbling Belathaan sends the High Order a clear message: the Windshapers answer interference with force.",sp=1}},faq={{q="Who is Ayessa Dawnsinger?",a="Ayessa Dawnsinger belongs to the Horde-aligned Windshapers on Zephras Isle. She protects their domain and acts ruthlessly against intruders who meddle in their affairs.",al={"ayessa dawnsinger","who gives a firm response","ayessa"},it="identity"},{q="Who is Belathaan Brightwish?",a="Belathaan Brightwish is tied to the High Order. Ayessa Dawnsinger targets him to intimidate the organization after he is spotted heading alone toward the Shrine of Akir.",al={"belathaan brightwish","belthaan","who is belathaan"},it="target"},{q="What is the High Order?",a="The High Order is a faction on Zephras Isle whose activities conflict with those of the local Windshapers. It keeps probing into their affairs despite explicit warnings.",al={"high order","the high order lore","what is the high order"},it="people"},{q="Where is the Shrine of Akir located?",a="The Shrine of Akir lies north of town on Zephras Isle. Belathaan is intercepted on the secluded road that leads there.",al={"shrine of akir","where is shrine of akir","shrine akir zephras"},it="place",gp=true},{q="Why does Ayessa want Belathaan beaten rather than killed?",a="Ayessa wants Belathaan beaten to send a message without starting a total war. She hopes he will return to his superiors with fear and respect for the Windshapers’ boundaries.",al={"kill belathaan","why spare belathaan","why just bruises"},it="motive"},{q="What are the Living Storms encountered during this task?",a="Living Storms are elemental entities that appear during the confrontation with Belathaan on the road. They reflect Zephras Isle’s volatile elemental energies.",al={"living storms","what are living storms"},it="threat"},{q="Why does Ayessa Dawnsinger want Belathaan confronted?",a="The High Order has repeatedly meddled in the affairs of the Windshapers, ignoring previous warnings to respect their territory and practices. Ayessa believes diplomatic words are no longer enough. By intercepting Belathaan on the road and giving him a harsh thrashing, she hopes to send an unmistakable message back to his superiors that the Windshapers will enforce their boundaries by force if necessary.",al={"why confront belathaan","ayessa motive","why send message to high order"},it="motive",add="3180a0eb"}},ang={["faction:Horde"]="As a member of the Horde on Zephras Isle, you help secure its positions and keep rivals like the High Order from encroaching on allied interests.",["class:Shaman"]="As a shaman, you face Living Storms amid the turbulent, untamed elemental air magic found across Zephras Isle."},kw={"a firm response","ayessa dawnsinger","belathaan brightwish","high order","living storms","shrine of akir","windshapers","zephras isle"},rel={"npc:ayessa-dawnsinger","zone:zephras"},m={start="Ayessa Dawnsinger",level="9",faction="Horde",id=93746},src={"A Firm Response"},fv=true}
E["quest:93791"] = {t="quest",n="Speak with Belann",z="zephras",s="In Valanaar, aspiring spellcasters are sent to meet Belann Windwood. The High Order honors the making of a personal spell focus as a long-held tradition.",h="In Valanaar, aspiring spellcasters are sent to meet Belann Windwood.",sec={{t="A Rite of Growing Power",b="As students grow in command of magic, the High Order turns to an ancient custom to test and strengthen their talents. Making a spell focus of their own, whether a wand or staff, is one of the order’s most enduring traditions. It is for students who wish to bind their growing power to an implement they have made themselves.",sp=0},{t="The Craftsman of Valanaar",b="In Valanaar, initiates seek Belann Windwood for help with this craft. He has spent more than a century forging staves and wands for the High Order. A trusted mentor, Belann welcomes dedicated students and guides them through the craft and history of their magical tools.",sp=0}},faq={{q="Who is Belann Windwood?",a="Belann Windwood is a master craftsman who lives in Valanaar. For more than a century, he has made staves and wands for members of the High Order.",al={"who is belann","belann windwood","belann"}},{q="What is the High Order?",a="The High Order is an ancient organization of practitioners. Its traditions include guiding young spellcasters as they make and master their own spell focuses.",al={"what is the high order","high order lore"}},{q="What is a spell focus?",a="A spell focus, such as a wand or staff, channels magical energies. For developing spellcasters in the High Order, making one is among the oldest rites of passage.",al={"what is a spell focus","purpose of spell focus"}},{q="Where can Valanaar be found?",a="Valanaar is the settlement where Belann Windwood keeps his workshop and helps High Order students craft focuses.",al={"where is valanaar","valanaar location"}},{q="Why are you sent to speak with Belann?",a="As an aspiring wielder of magic, you are sent to study under Belann, whose expertise spans more than a century, and begin shaping your own magical implement.",al={"why visit belann","why craft a focus"}},{q="What happens after you meet Belann?",a="When you introduce yourself to Belann in Valanaar, he welcomes you and prepares to explain the next stages of assembling your spell focus.",al={"what happens next","after speaking with belann"}}},ang={["class:Mage"]="As a Mage, making a personal spell focus marks a vital rite of passage and honors the ancient traditions of the High Order."},kw={"belann","belann windwood","high order","spell focus","staves","valanaar","wands"},rel={"quest:92472","quest:92596"},m={faction="Alliance",cl={"MAGE"},id=93791},src={"In-game quest text: Speak with Belann"},fv=true}
E["quest:93797"] = {t="quest",n="Boughs in the Wind",z="zephras",s="In Valanaar, Belann Windwood guides apprentices through the old rite of shaping a spell focus. They seek a wind-touched branch near Falaath Village, as fewer people in Zephras are born with a gift for magic.",h="In Valanaar, Belann Windwood guides apprentices through the old rite of shaping a spell focus.",sec={{t="A Rite of Passage",b="Young spellcasters in Zephras begin this old rite when they show a gift for magic. In Valanaar, Belann Windwood guides apprentices as they gather a fallen branch from the region’s oldest trees. The boughs keep traces of wind, making them fit to channel spells.",sp=0},{t="Whispers at the Wind Shrine",b="The strongest boughs lie near the wind shrine just south of Falaath Village, where elemental currents gather. Tradition says a branch may choose its spellcaster, and some say it sings softly to those able to wield its power. For elders like Belann, each apprentice who completes the rite helps carry their culture forward. Fewer people in Zephras are born with a gift for magic each passing year.",sp=0}},faq={{q="What is the quest Boughs in the Wind?",a="Apprentices gather a wind-touched fallen branch to shape a spell focus. This old rite helps preserve Zephras’s magical heritage.",al={"what is boughs in the wind","boughs in the wind quest","spell focus quest"}},{q="Who is Belann Windwood?",a="Belann Windwood is a mentor in Valanaar who guides young spellcasters as they shape their spell focuses. He worries that fewer people show a gift for magic each passing year.",al={"who is belann windwood","belann questgiver","belann valanaar"}},{q="Where do you find the Wind-Infused Bough?",a="The boughs fall from the oldest trees near the wind shrine just south of Falaath Village. Belann directs apprentices there because ancient wood retains traces of elemental currents.",al={"where to find wind bough","where is wind-infused bough","bough location"}},{q="Why do young spellcasters create a spell focus?",a="Apprentices shape their own spell focus after showing a gift for magic. It channels elemental energies and marks their passage into an old cultural rite.",al={"why make spell focus","purpose of spell focus","spell focus lore"}},{q="Why does Belann ask if the branch sang to you?",a="Belann Windwood says tradition holds that a branch often chooses its spellcaster. A fitting bough may seem to sing to someone sensitive to elemental winds.",al={"branch picks the caster","singing branch","does the branch choose you"}},{q="What is happening to magic in Zephras?",a="Fewer people in Zephras are born with a natural gift for magic each passing year. Belann believes keeping the old rites alive matters all the more.",al={"where is zephras","magic fading zephras","zephras magic lore"}}},ang={["race:Skyborne"]="As fewer youths show a gift for magic each passing year, shaping a traditional spell focus helps preserve your people’s ancestral culture in Zephras.",["class:Mage"]="Shaping a spell focus from a wind-touched bough marks an early rite for spellcasters learning to channel elemental resonance."},kw={"belann windwood","boughs in the wind","falaath village","spell focus","valanaar","wind shrine","wind-infused bough","zephras"},rel={"quest:92529"},m={faction="Alliance",cl={"MAGE"},id=93797},src={"In-game quest text: Boughs in the Wind"},fv=true}
E["quest:93835"] = {t="quest",n="Confront Lorthuna",z="zephras",s="An injured mage needs you to follow Ayessa Dawnsinger and Elaadrin Evengale through a portal to the Rohashi Spires. There, they face High Priestess Lorthuna and need your help.",h="An injured mage needs you to follow Ayessa Dawnsinger and Elaadrin Evengale through a portal to the Rohashi...",sec={{t="Through the portal",b="Lorthuna fled through a portal to the spires above. Ayessa Dawnsinger and Elaadrin Evengale followed moments ago, but their companion is too badly hurt to go with them. Join the two mages through the portal as they face the High Priestess.",sp=0},{t="After the clash",b="The remaining mages were sent to help Valennia and her forces escape. Valennia is resting at High Elder Shadowsong's residence. Ansirem has returned to Azeroth after discussing the High Order's next steps. Zephras survived the day, but remains dangerously vulnerable, and plans must be made for what comes next.",sp=1}},faq={{q="Who is asking me to go after Lorthuna?",a="An injured mage asks you to follow Ayessa Dawnsinger and Elaadrin Evengale through the portal and help them face High Priestess Lorthuna.",al={"who sent me","injured mage","who needs help"}},{q="Where did Lorthuna go?",a="Lorthuna fled through a portal to the Rohashi Spires overhead.",al={"where is lorthuna","lorthuna portal","where'd she flee"}},{q="Who went after Lorthuna?",a="Ayessa Dawnsinger and Elaadrin Evengale went through the portal after Lorthuna.",al={"ayessa and elaadrin","who followed her","who's up there"}},{q="Why can't the injured mage go with them?",a="The mage took too many hits and must stay behind.",al={"why am i going alone","mage too hurt","why stay behind"}},{q="Where is Valennia?",a="Valennia is resting at High Elder Shadowsong's residence after the remaining mages helped her and her forces escape.",al={"valennia location","where did she go","valennia safe"}},{q="What is at risk now?",a="Zephras is dangerously vulnerable, and the High Order must plan for what comes next.",al={"zephras vulnerable","what happened to zephras","high order next"}}},kw={"ayessa dawnsinger","elaadrin evengale","high order","lorthuna","portal","rohashi spires","valennia","zephras"},rel={"npc:ayessa-dawnsinger","quest:92596"},m={faction="Alliance",id=93835},src={"In-game quest text: Confront Lorthuna"},fv=true}
E["quest:93836"] = {t="quest",n="The Fate of Zephras",z="zephras",s="After Lorthuna falls, word of danger reaches Valanaar. Zephras Isle's wards have failed, and Ayessa proposes a journey to Azeroth. High Elder Talaanis Shadowsong must hear what has happened.",h="After Lorthuna falls, word of danger reaches Valanaar.",sec={{t="A Precarious Victory",b="Lorthuna has fallen after the battle above the Shrine of Akir. Yet Zephras Isle has paid dearly for the victory. Its ancient wards, which hid it from Al'Akir, have collapsed. The floating sanctuary now lies exposed in the Windlord's domain. A messenger crosses the isle with word for Valanaar.",sp=0},{t="The Word to Valanaar",b="High Elder Talaanis Shadowsong hears that Lorthuna is dead and the wards have broken. He also learns that Ayessa means to lead an expedition to Azeroth. With their magical veil gone, the islanders look beyond their home for a way to protect it. Shadowsong weighs fear against hope. Al'Akir is a terrible menace, yet elemental gods move across vast stretches of time. That may leave the islanders precious time to act.",sp=1}},faq={{q="What is the quest The Fate of Zephras about?",a="Lorthuna has fallen at the Shrine of Akir, and word of the danger goes to Valanaar. The island's protective wards have failed, and Ayessa proposes an expedition to Azeroth. High Elder Talaanis Shadowsong receives the news.",al={"fate of zephras quest","what is the fate of zephras","what happens in the fate of zephras"}},{q="Why is Zephras Isle in danger from Al'Akir?",a="Zephras Isle lies within the elemental domain of Al'Akir, the Windlord. Ancient wards once hid the sanctuary from his sight. Now they are gone, leaving the island exposed should Al'Akir turn his wrath upon it.",al={"why is zephras in danger","why attack zephras","zephras elemental threat"}},{q="Who is Talaanis Shadowsong?",a="Talaanis Shadowsong is the High Elder of the Skyborne in Valanaar on Zephras Isle. He oversees his people's rule and survival, and receives reports of threats and choices facing their home.",al={"who is talaanis shadowsong","high elder shadowsong","where is talaanis shadowsong"}},{q="What is Ayessa's plan?",a="Ayessa plans to lead an expedition from Zephras Isle to Azeroth. She seeks answers and allies beyond their domain to help protect her people from Al'Akir.",al={"who is ayessa","ayessa plan","what is ayessa doing"}},{q="Who was Lorthuna and what happened to her?",a="Lorthuna led the cult on Zephras Isle. She was slain above the Shrine of Akir, breaking the cult's leadership as the island's protective wards fell.",al={"who is lorthuna","cult leader lorthuna","what happened to lorthuna"}},{q="Who is Muln?",a="Muln is an advisor or scholar who knows about the elemental lords. He warned Zephras's defenders of Al'Akir's great power and danger, and confirmed their vulnerability without magical concealment.",al={"who is muln","muln lore"}}},ang={["race:Skyborne"]="As a Skyborne of Zephras Isle, you face the loss of the wards and the threat of Al'Akir. Your people now look beyond their floating home for a way to protect it.",["class:Shaman"]="As a shaman, you know the Windlord Al'Akir's elemental domain surrounds Zephras. With the ancient wards gone, the island lies exposed."},kw={"al'akir","ayessa","fate of zephras","lorthuna","muln","shrine of akir","talaanis shadowsong","valanaar","zephras isle"},rel={"zone:zephras"},m={faction="Horde",id=93836},src={"In-game quest text: The Fate of Zephras"},fv=true}
E["quest:93926"] = {t="quest",n="The Western Watch",z="zephras",s="At the outpost southwest of the settlement, cultists press the defenders, and local leaders call them back. They judge the tower too costly to hold and turn to protecting the village.",h="At the outpost southwest of the settlement, cultists press the defenders, and local leaders call them back.",sec={{t="A Costly Outpost",b="The western watchtower guards the frontier southwest of the settlement. Cultists have renewed their assault, and local leaders decide the isolated post costs too many lives to defend. So they prepare orders recalling the peacekeepers. They hope to spare more lives and gather every defender to protect the village and its people.",sp=0},{t="Too Late to Retreat",b="Peacekeeper Vaaniel commanded the garrison at the western watch. The withdrawal order arrived too late. Storm-wielding cult spellcasters had overrun the tower before messengers reached it. Vaaniel and his garrison lay dead among scorched stone and lightning burns.",sp=1}},faq={{q="Who is Peacekeeper Vaaniel?",a="Peacekeeper Vaaniel commands the peacekeepers at the western watchtower. Cultists are attacking, and you are sent to find him and tell him to bring his garrison back to the village quickly.",al={"who is vaaniel","vaaniel lore","peacekeeper vaaniel"}},{q="Why were the peacekeepers ordered to abandon the watchtower?",a="Local leaders ordered the peacekeepers to leave because the cult assaults were costing too many lives. They want the defenders gathered at the village to protect its people.",al={"why abandon tower","why leave watchtower","western watch order"}},{q="What killed Peacekeeper Vaaniel?",a="Storm-wielding cult spellcasters killed Peacekeeper Vaaniel. Lightning and elemental magic left burns and scorch marks on him and the tower's defenders.",al={"how did vaaniel die","who killed vaaniel","peacekeeper killed by what"}},{q="Who attacked the western watchtower?",a="A hostile cult attacked the western watchtower with destructive storm magic. Local commanders do not know why the cult wants the tower, but the attack threatens nearby settlements.",al={"who is attacking the tower","cult attack western tower","what cult is this"}},{q="Where is the western watchtower located?",a="The western watchtower stands southwest of the local settlement, guarding the western approaches. Its isolation left it vulnerable to cult assaults.",al={"where is the watchtower","western watchtower location"}},{q="What happened to the garrison at the tower?",a="The watchtower had fallen by the time runners arrived with orders to evacuate. Cult spellcasters killed Peacekeeper Vaaniel and the other defenders shortly before aid could reach them.",al={"what happens at the tower","watchtower outcome","did any peacekeepers survive"}}},kw={"cult","peacekeeper vaaniel","peacekeepers","storm spellcasters","the western watch","watchtower","western watchtower"},m={id=93926},src={"In-game quest text: The Western Watch"},fv=true}
E["quest:93927"] = {t="quest",n="A Last Request",z="zephras",s="On Zephras, a fallen peacekeeper carries a message that may reveal his final moments. His bloodstained note points to the duty he left unfinished.",h="On Zephras, a fallen peacekeeper carries a message that may reveal his final moments.",sec={{t="A Grim Discovery",b="You find a dead peacekeeper in the field with a bloodstained note in his hands. When you examine him, the note slips free. On Zephras, peacekeepers risk their lives to keep order. His last words may tell what happened to him.",sp=0},{t="The Final Message",b="The bloodied parchment holds the peacekeeper's final plea or instructions. Whoever killed him left his duty unfinished. Read the clues and complete his final mission. The note points the way to answer his dying call.",sp=0}},faq={{q="Who is the dead peacekeeper?",a="The fallen peacekeeper's identity is unknown when you find him. He kept order, and his duty ended violently. Only an urgent message remains in his hands.",al={"who is the dead peacekeeper","dead peacekeeper","peacekeeper identity"}},{q="What is written on the bloody note?",a="The note recounts the peacekeeper's final account. The cult surprised his post. Raani never saw it coming, Arvensus took a sword to the gut, and a lightning bolt felled the writer. Left for dead, he expected his wounds to finish what the cult began.",al={"what is the bloody note","what does the note say","peacekeeper note"}},{q="How is this request discovered?",a="You find the peacekeeper's body in the field and examine it. The bloody note in his hands holds his final plea.",al={"how to start a last request","where is a last request found"}},{q="What happened to the peacekeeper?",a="The cult ambushed the peacekeeper's post without warning. His fellows fell, and a lightning bolt struck him, leaving him for dead. He lived long enough to record what happened in the note found in his hands.",al={"why was peacekeeper killed","who killed peacekeeper"}},{q="What is the peacekeeper's last request?",a="The peacekeeper died before he could finish his mission or deliver his message. You can retrieve and read his bloodstained note, decipher his final instructions, and fulfill his dying wish.",al={"what is the peacekeeper's request","last request purpose"}},{q="What role do peacekeepers serve?",a="Peacekeepers protect settlements and roads, keeping order and defending them from danger. When one falls in the field, their duties remain unfinished and their allies unwarned unless someone recovers their final report.",al={"who are peacekeepers","peacekeeper lore"}}},kw={"a last request","bloody note","dead peacekeeper","peacekeeper","peacekeeper note"},m={id=93927},src={"In-game quest text: A Last Request"},fv=true}
E["quest:93948"] = {t="quest",n="Deliver the Signet",z="zephras",s="A traveler carries the recovered Shadowsong Family Signet to High Elder Talaanis Shadowsong in Valanaar. Its return confirms his nephew's death on Zephras Isle, and Talaanis points the traveler toward the local peacekeepers.",h="A traveler carries the recovered Shadowsong Family Signet to High Elder Talaanis Shadowsong in Valanaar.",sec={{t="A Somber Errand",b="A traveler carries the Shadowsong Family Signet to Valanaar, recovered from an isolated tower. The grim token is meant for Talaanis Shadowsong, the High Elder of Zephras Isle. His people love him, though hardship weighs on the settlement. The ring confirms his nephew has perished, and Talaanis receives the heirloom with condolences.",sp=0},{t="Grief and Duty in Valanaar",b="In Valanaar, High Elder Talaanis thanks the traveler for returning the signet, though grief shadows him. He recognizes the traveler's skill and points them to Captain Valennia Stormfist, who leads the Valanaar peacekeepers. The settlement faces strained circumstances and mounting pressures. Its protectors welcome capable hands.",sp=0}},faq={{q="Who is Talaanis Shadowsong?",a="Talaanis Shadowsong is the High Elder of Zephras Isle. His community respects and loves him, and the returned signet confirms his nephew's death.",al={"who is talaanis","high elder talaanis","talaanis shadowsong lore"}},{q="What is the Shadowsong Family Signet?",a="The Shadowsong Family Signet is a family ring recovered from a tower. Its return to Talaanis Shadowsong confirms that his nephew has perished.",al={"what is the signet ring","nephews ring","shadowsong signet"}},{q="Where is Valanaar located?",a="Valanaar is a settlement on Zephras Isle. High Elder Talaanis Shadowsong lives there, and Captain Valennia Stormfist leads its peacekeepers.",al={"where is valanaar","valanaar settlement","talaanis location"}},{q="Who is Valennia Stormfist?",a="Valennia Stormfist leads the peacekeepers in Valanaar. High Elder Talaanis directs capable travelers to speak with her because the settlement needs help.",al={"who is valennia stormfist","captain valennia","valanaar peacekeeper captain"}},{q="Who are the shen'dorei mentioned by Talaanis?",a="Talaanis calls capable young travelers coming down from the highlands shen'dorei, a name that reflects the elven presence and heritage on Zephras Isle.",al={"who are the shendorei","shendorei highlands"}},{q="What happened to Talaanis Shadowsong's nephew?",a="Talaanis's nephew died at a tower, where the family signet was lost. Returning the ring to Valanaar tells the High Elder of his nephew's death.",al={"what happened to talaanis nephew","how did nephew die"}}},ang={["race:NightElf"]="As a night elf, the Shadowsong name carries deep history among elven lineages. On Zephras Isle, High Elder Talaanis and the local shen'dorei face their own struggles."},kw={"deliver the signet","shadowsong family signet","shen'dorei","talaanis shadowsong","valanaar","valennia stormfist","zephras isle"},rel={"zone:zephras","quest:92579"},m={id=93948},src={"In-game quest text: Deliver the Signet"},fv=true}
E["quest:93949"] = {t="quest",n="Bugged",z="zephras",s="In Valanaar, seasonal skyhopper swarms now threaten the settlement. High Order mages found listening enchantments on slain insects, and local cultists are suspected of spying through them.",h="In Valanaar, seasonal skyhopper swarms now threaten the settlement.",sec={{t="Eavesdroppers in the Swarm",b="When skyhopper season comes, lowland insects swarm around Valanaar. High Order mages inspected several slain skyhoppers and found listening enchantments on them. Local cultists are suspected of using the seasonal pests to eavesdrop on the city.",sp=0},{t="Clearing the Air",b="The enchanted skyhoppers look like ordinary insects, so Valanaar's protectors must cull the whole swarm. Clearing them out denies the hostile cult intelligence and ends its magical surveillance of the city.",sp=0}},faq={{q="What are skyhoppers?",a="Skyhoppers are winged pests native to the lowlands around Valanaar. They swarm in great numbers during their seasonal surge.",al={"what are skyhoppers","skyhopper bug"}},{q="Who enchanted the insects?",a="Local cultists are suspected of placing listening spells on skyhoppers to eavesdrop on Valanaar.",al={"who enchanted the bugs","cult listening bugs","who is spying in valanaar"}},{q="How do you tell which skyhoppers are enchanted?",a="Enchanted skyhoppers look just like ordinary insects. The whole swarm must be cleared to uncover and eliminate the spies.",al={"how to tell enchanted skyhoppers","which bugs are enchanted"}},{q="Where does this take place?",a="The infestation and spying take place around Valanaar, an aerial city near the lowlands where seasonal swarms rise.",al={"where is bugged quest","valanaar bugs"}},{q="What kind of enchantment was placed on the skyhoppers?",a="High Order mages found listening spells bound to slain skyhoppers. The enchantments turn them into roving watchers.",al={"what spell is on the bugs","skyhopper enchantment"}},{q="Why do all the skyhoppers need to be exterminated?",a="Enchanted skyhoppers cannot be distinguished from ordinary pests by sight. Clearing the swarms is necessary to purge the cult's listening posts and protect Valanaar.",al={"why kill skyhoppers","bugged quest goal"}}},ang={["class:Mage"]="High Order mages found listening enchantments on ordinary skyhoppers, turning the seasonal swarm into a threat to Valanaar."},kw={"bugged","cult","enchanted skyhoppers","high order","listening spell","skyhoppers","valanaar"},rel={"topic:mage"},m={id=93949},src={"In-game quest text: Bugged"},fv=true}
E["quest:93951"] = {t="quest",n="A Little Beauty",z="zephras",s="In the Shen'dar Highlands, the Skyborne gather hippogryph down near Zephras. Its bright plumes bring beauty and small joys to the village through hard times.",h="In the Shen'dar Highlands, the Skyborne gather hippogryph down near Zephras.",sec={{t="Plumes of the Highlands",b="Wild hippogryphs nest on Zephras Isle, southwest of the village in the Shen'dar Highlands. They are territorial and can trouble travelers nearby. Yet they shed vibrant, silky soft down, which the Skyborne gather to weave into hair ornaments.",sp=0},{t="Finding Joy in Small Things",b="For Zephras's artisan, gathering feathers for hair is more than vanity. Even in hard times, small joys shared with others help keep the community's spirit alive. Beauty gives each day in the village something to celebrate.",sp=0}},faq={{q="Why are hippogryph feathers being collected?",a="The Skyborne gather wild hippogryph down to make hair adornments. The vibrant, silky soft plumes have fallen from the birds, which can trouble travelers near the settlement.",al={"why gather feathers","what are feathers for","feather purpose"}},{q="What is Zephras?",a="Zephras is the island home of the Skyborne. Its artisan crafts hair adornments from gathered feathers to bring happiness and lighthearted moments to residents.",al={"who is Zephras","what town is this","where does this happen"}},{q="Where do the hippogryphs nest?",a="Wild hippogryphs nest southwest of the village in the Shen'dar Highlands. They are territorial and keep unwanted guests away from their nesting grounds.",al={"where are the nests","where are hippogryphs","shendar highlands location"}},{q="Why are small luxuries like hair adornments important in times like these?",a="The artisan believes small joys and beauty matter, especially in difficult times. Bringing happiness to others makes the effort worthwhile.",al={"are feathers important","why hair decorations","vain triviality"}},{q="Are the hippogryphs hostile to visitors?",a="The wild hippogryphs southwest of the village defend their nesting grounds from intruders. Gathering their fallen feathers can be hazardous for unwary travelers.",al={"why hippogryphs dangerous","are hippogryphs wild"}},{q="Is decorating hair with feathers common among the Skyborne?",a="Yes, many Skyborne weave vibrant plumes into their hair. Hippogryph down is exceptionally soft and well suited to these adornments.",al={"skyborne feathers","do skyborne wear feathers"}}},ang={["race:Skyborne"]="As a Skyborne, you can gather vibrant hippogryph down to adorn your hair with soft plumes. This custom brings small joys to Zephras through hardship."},kw={"a little beauty","down feathers","feathers","hippogryph","plumes","shen'dar highlands","skyborne","zephras"},rel={"topic:skyborne"},m={id=93951},src={"In-game quest text: A Little Beauty"},fv=true}
E["quest:93958"] = {t="quest",n="The Inner Sanctum",z="zephras",s="At the Shrine of Akir, Valennia Stormfist's assault has gone silent. Her force breached the deepest chamber amid fierce fighting, and now allies outside fear for those within.",h="At the Shrine of Akir, Valennia Stormfist's assault has gone silent.",sec={{t="A Sudden Silence",b="Valennia Stormfist led her detachment into the inner sanctum of the Shrine of Akir after a hard assault. Fighting sounded from deep within the chambers, fierce and desperate. Then the noise stopped without warning. Allies waiting outside can only fear the worst.",sp=0},{t="The Cost of the Breach",b="Valennia Stormfist is found gravely wounded inside the quiet sanctum. Her vanguard's fate remains uncertain in the aftermath of the battle.",sp=1}},faq={{q="Who is Valennia Stormfist?",a="Valennia Stormfist commands the assault into the depths of the Shrine of Akir. She led her forces through the breach into the inner sanctum, where the fighting soon fell silent.",al={"who is valennia","who is valennia stormfist","valennia"}},{q="What is the Shrine of Akir?",a="The Shrine of Akir holds an inner sanctum now under assault. Valennia's troops broke through its defenses amid heavy fighting, making the shrine the heart of a deadly clash.",al={"what is shrine of akir","shrine of akir lore","akir shrine"}},{q="What happened to Valennia's forces inside?",a="Heavy fighting rang out inside after the breach, then stopped all at once. The silence leaves allies outside fearing Valennia's vanguard may have been overwhelmed or killed.",al={"why is it quiet","what happened to valennias forces","valennia soldiers"}},{q="Is Valennia Stormfist still alive?",a="Valennia Stormfist survives the assault, gravely wounded inside the Shrine of Akir's inner sanctum after the fighting ends.",al={"is valennia alive","did valennia die","valennia fate"}},{q="What is the objective inside the inner sanctum?",a="The inner sanctum is the deepest chamber in the Shrine of Akir. You are sent in alone to assess the aftermath and find Valennia and any fighters who survived.",al={"what is the inner sanctum","inner sanctum quest purpose"}},{q="Who sends you into the inner sanctum?",a="An ally keeping watch at the rear outside the inner sanctum sends you in. They hold the perimeter and watch your back as you go to join Valennia's vanguard.",al={"who sends you to valennia","quest giver inner sanctum"}}},kw={"inner sanctum","shrine of akir","stormfist","the inner sanctum","valennia","valennia stormfist"},m={faction="Horde",id=93958},src={"In-game quest text: The Inner Sanctum"},fv=true}
E["quest:94003"] = {t="quest",n="The Skybreaker Bulwark",z="zephras",s="At the Shrine of Akir, Zaal Stormshield holds the Skybreaker Bulwark. The last of the Skybreakers seeks its return from the cultist who took it.",h="At the Shrine of Akir, Zaal Stormshield holds the Skybreaker Bulwark.",sec={{t="A Fallen Lineage",b="On Zephras Isle, the Al'Aketh have slain the Skybreakers, leaving one survivor. The last of the family bears deep sorrow and bitter shame over the loss of their greatest heirloom. The cultist Zaal Stormshield took the Skybreaker Bulwark and now lurks at the Shrine of Akir.",sp=0},{t="The Sacred Shield",b="By family tradition, the Skybreaker Bulwark protects anyone truly worthy to wield it. The last Skybreaker believes Zaal unworthy of its divine favor. So the survivor seeks an adventurer to strike down the thief at the Shrine of Akir and reclaim the ancestral shield. In return, the Skybreaker offers training in the Skybreaker Defense technique.",sp=0}},faq={{q="Who are the Skybreakers?",a="The Skybreakers are an ancient lineage on Zephras Isle, nearly wiped out by the Al'Aketh. The one who asks for the shield is the sole survivor.",al={"who are the skybreakers","skybreaker family"}},{q="What is the Skybreaker Bulwark?",a="The Skybreaker Bulwark is an ancestral shield of the Skybreaker line on Zephras Isle. Family tradition says no harm can befall anyone worthy to wield it.",al={"what is the skybreaker bulwark","the shield","skybreaker shield lore"}},{q="Who are the Al'Aketh?",a="The Al'Aketh slew the Skybreaker family on Zephras Isle, leaving one survivor to mourn their loss.",al={"who killed the skybreakers","what are the alaketh","alaketh"}},{q="Who is Zaal Stormshield?",a="Zaal Stormshield is a cultist who took the Skybreaker Bulwark after the Skybreaker family was slain. He lurks with the heirloom at the Shrine of Akir on Zephras Isle.",al={"who has the shield","zaal","stormshield"}},{q="Where is the Shrine of Akir?",a="The Shrine of Akir is on Zephras Isle. Zaal Stormshield lurks there with the stolen Skybreaker Bulwark.",al={"where is zaal","shrine of akir location","where to find shield"}},{q="Why must the Bulwark be reclaimed?",a="The last Skybreaker seeks the Bulwark's return to right the family's shame and take the sacred relic from unworthy hands. In return, the survivor teaches the Skybreaker Defense technique.",al={"why recover shield","what is skybreaker defense","shield reward"}}},ang={["class:Warrior"]="As a warrior, you can learn the Skybreaker Defense technique by recovering the ancestral shield.",["class:Paladin"]="As a paladin, you may value the work of reclaiming a blessed heirloom from a corrupt cultist."},kw={"al'aketh","shrine of akir","skybreaker","skybreaker bulwark","skybreaker defense","the skybreaker bulwark","zaal stormshield","zephras isle"},rel={"zone:zephras"},m={cl={"WARRIOR"},id=94003},src={"In-game quest text: The Skybreaker Bulwark"},fv=true}
E["quest:94006"] = {t="quest",n="The Great Ursera Spirit",z="zephras",s="A druid sends you to meet Urs'endris, a spirit on Zephras who has taught druids the ursera shape for generations. His domain is withering, and Urs'endris can guide your studies further.",h="A druid sends you to meet Urs'endris, a spirit on Zephras who has taught druids the ursera shape for...",sec={{t="The Great Spirit",b="A druid sends you to Urs'endris near the falls northeast of Valanaar. Your druidic studies have brought you to a meeting with one of Zephras's great spirits. Urs'endris has taught druids to take the ursera shape for generations, and his domain is withering into the sky.",sp=0}},faq={{q="Who is Urs'endris?",a="Urs'endris is a wise spirit on Zephras who has taught druids to take the ursera shape for generations.",al={"urs'endris who","great spirit urs","ursera spirit"}},{q="Where can I find Urs'endris?",a="Urs'endris is near the falls northeast of Valanaar, near the Shrine of Akir.",al={"urs'endris location","where is urs'endris","meet the spirit"}},{q="Why am I being sent to Urs'endris?",a="Your druidic studies have progressed enough for you to meet one of Zephras's great spirits, and Urs'endris can instruct you further.",al={"why meet urs'endris","druid spirit quest","ursera studies"}},{q="What is happening to Urs'endris's domain?",a="Urs'endris's domain has begun to wither and fall into the sky.",al={"withering domain","zephras falling","what's wrong there"}},{q="What is the ursera shape?",a="The ursera shape is a form Urs'endris has taught druids to take for generations.",al={"ursera form","way of the claw","ursera"}}},ang={["class:Druid"]="As a druid, your studies have brought you to Urs'endris, who has taught druids the ursera shape for generations."},kw={"druid","falls","shrine of akir","spirit","urs'endris","ursera","valanaar","zephras"},rel={"topic:druid"},m={id=94006},src={"In-game quest text: The Great Ursera Spirit"},fv=true}
E["quest:94007"] = {t="quest",n="Taming the Beast",z="zephras",s="In Valanaar, Quel'ana Quickgale can teach you to tame a beast. Your time in the highlands has prepared you to seek an animal companion.",h="In Valanaar, Quel'ana Quickgale can teach you to tame a beast.",sec={{t="A New Companion",b="Your host believes you are ready to seek an animal companion after your time in the highlands. Go to Valanaar and speak with Quel'ana Quickgale. He will teach you the art of beast taming.",sp=0}},faq={{q="Who teaches beast taming?",a="Quel'ana Quickgale teaches you to tame beasts in Valanaar.",al={"who is Quel'ana Quickgale","beast taming teacher"}},{q="Where do I find Quel'ana Quickgale?",a="Quel'ana Quickgale is in Valanaar, the port to the southeast.",al={"where is Quel'ana","Valanaar taming"}},{q="Why am I going to Valanaar?",a="You are sent to Valanaar to speak with Quel'ana Quickgale and begin learning to tame beasts.",al={"why Valanaar","taming beast quest"}},{q="What am I learning?",a="Quel'ana Quickgale will teach you to tame a beast so you can seek an animal companion.",al={"what is beast taming","animal companion"}}},kw={"animal companion","beast taming","highlands","quel'ana quickgale","taming the beast","valanaar"},m={cl={"HUNTER"},id=94007},src={"In-game quest text: Taming the Beast"},fv=true}
E["quest:94013"] = {t="quest",n="Taming the Beast",z="zephras",s="Quel'ana Quickgale gives you one last trial in taming a Vuldren Alpha. Mastering it prepares you for the deeper teachings of your class.",h="Quel'ana Quickgale gives you one last trial in taming a Vuldren Alpha.",sec={{t="The Final Trial",b="Quel'ana gives you a Taming Rod and sends you to the Gustberry Lowlands. There, you are to tame a Vuldren Alpha. Then return the rod to him in Valanaar. This trial proves your mastery and prepares you for deeper class teachings.",sp=0},{t="A New Lesson",b="After you return, Quel'ana says you have learned the basics. He offers to teach you to form a lasting bond with an animal companion. He urges you to carry that knowledge forward for the good of the class Zephras Isle needs.",sp=1}},faq={{q="What does Quel'ana ask me to tame?",a="Quel'ana asks you to tame a Vuldren Alpha with the Taming Rod in the Gustberry Lowlands.",al={"vuldren alpha taming","what beast","tame alpha"}},{q="Where do I find the Vuldren Alpha?",a="The Vuldren Alpha is in the Gustberry Lowlands.",al={"alpha location","gustberry lowlands","where tame beast"}},{q="What is the Taming Rod for?",a="Quel'ana gives you the Taming Rod to tame a Vuldren Alpha.",al={"rod purpose","taming rod quest","how use rod"}},{q="Where do I return the Taming Rod?",a="Return the Taming Rod to Quel'ana Quickgale in Valanaar.",al={"return rod","quelana location","where return taming rod"}},{q="What will I learn after this?",a="Quel'ana says he can teach you to form a lasting bond with an animal companion.",al={"next lesson","animal companion bond","what comes after"}}},kw={"animal companion","gustberry lowlands","quel'ana quickgale","taming rod","taming the beast","valanaar","vuldren alpha","zephras isle"},rel={"item:taming-rod","zone:zephras"},m={cl={"HUNTER"},id=94013},src={"In-game quest text: Taming the Beast"},fv=true}
E["quest:94050"] = {t="quest",n="Training the Beast",z="zephras",s="In Valanaar, you meet Quel'dora Quickgale to learn how to train your pet. Her teaching helps you care for and guide it.",h="In Valanaar, you meet Quel'dora Quickgale to learn how to train your pet.",sec={{t="Quel'dora's Teaching",b="Your fellow hunter sends you to his sister, Quel'dora Quickgale, in Valanaar. You already know how to tame a pet. Now Quel'dora can teach you to train your companion.",sp=0},{t="A Hunter's Charge",b="Quel'dora teaches you to guide your pet, teach it new abilities, feed it, and revive it if it falls in battle. She urges you to respect the balance and remain in awe of the nature around you.",sp=0}},faq={{q="Who is Quel'dora Quickgale?",a="Quel'dora Quickgale is the sister of the hunter who sends you to learn pet training.",al={"who is queldora","quel'dora","quickgale"}},{q="Where can I find Quel'dora?",a="Quel'dora Quickgale is in Valanaar.",al={"where queldora","quel'dora location","valanaar trainer"}},{q="What does Quel'dora teach?",a="Quel'dora teaches you to train and guide your pet, teach it abilities, feed it, and revive it if it falls in battle.",al={"pet training","train my pet","what can pet trainer teach"}},{q="Can I already tame a pet?",a="The hunter who sends you to Quel'dora says you already have the power to tame a pet.",al={"tame pet","pet taming","can hunter tame"}},{q="What does the hunter ask me to do?",a="The hunter asks you to speak with Quel'dora Quickgale in Valanaar.",al={"training the beast","pet trainer quest","speak to queldora"}},{q="What does Quel'dora say about nature?",a="Quel'dora urges you to respect the balance and live in awe of the nature around you.",al={"respect nature","balance","quel'dora advice"}}},ang={["class:Hunter"]="As a hunter, you are learning to train and guide a pet you can already tame."},kw={"feed pet","hunter","pet training","quel'dora quickgale","revive pet","tame pet","training the beast","valanaar"},m={cl={"HUNTER"},id=94050},src={"In-game quest text: Training the Beast"},fv=true}
E["quest:94369"] = {t="quest",n="The Fate of Zephras",z="zephras",s="In Valanaar, you bring Talaanis Shadowsong word of the danger facing Zephras. The fallen wards leave the isle exposed to Al'Akir, and its people must decide how to protect their home.",h="In Valanaar, you bring Talaanis Shadowsong word of the danger facing Zephras.",sec={{t="A warning for Talaanis",b="You tell Talaanis what happened above the Shrine of Akir. You share Elaadrin's plan to leave Zephras Isle. High Elder Shadowsong needs to understand the danger and why you were sent to Azeroth. The people of Zephras must find a way to save their home.",sp=0},{t="What remains",b="Talaanis weighs the news. Lorthuna is gone, and the cult has lost its leader. Zephras has not been invaded. Yet Al'Akir may turn his attention to the isle in years or decades, and fear now stands beside cause for celebration.",sp=1}},faq={{q="Who do I speak with?",a="You speak with Talaanis Shadowsong in Valanaar.",al={"who to talk to","talaanis","where do i report"}},{q="What do I tell Talaanis?",a="You tell Talaanis what happened above the Shrine of Akir and of Elaadrin's plan to leave Zephras Isle.",al={"what happened at shrine","what do i report","shrine of akir news"}},{q="Why are the people of Zephras afraid of Al'Akir?",a="The wards that hid Zephras have fallen. Al'Akir may choose to attack while the people are in his domain.",al={"why fear al'akir","windlord danger","al akir threat"}},{q="What does High Elder Shadowsong need to know?",a="High Elder Shadowsong needs to know of the danger and what the people of Zephras intend to do on their mission to Azeroth.",al={"what talaanis needs","high elder news","intentions for azeroth"}}},kw={"al'akir","elaadrin","lorthuna","shrine of akir","talaanis shadowsong","valanaar","wards","windlord","zephras"},rel={"zone:zephras"},m={faction="Alliance",id=94369},src={"In-game quest text: The Fate of Zephras"},fv=true}
E["quest:94411"] = {t="quest",n="Meddlesome Mages",z="zephras",s="In the Shen'dar Highlands, High Order apprentices gather at sacred stones and meddle with magic. Their spells threaten the fragile forces that hold the island together.",h="In the Shen'dar Highlands, High Order apprentices gather at sacred stones and meddle with magic.",sec={{t="Encroachment at the Stones",b="North of the village, High Order apprentices gather around ancient standing stones. Repeated warnings have not turned them from the sacred sites. They press on with their arcane studies, while local leaders hesitate to shed the blood of their shen'dorei kin. So they call for outside help to drive the apprentices away before lasting harm is done.",sp=0},{t="The Fragile Island",b="Delicate mystical forces bind the island's land together and keep it safe. The defenders fear the High Order gives little thought to the danger in its spellcraft. One careless spell could break those bindings. Then ruin would come to everyone who lives there.",sp=0}},faq={{q="What is the quest Meddlesome Mages about?",a="You are asked to drive away High Order Apprentices gathered at sacred standing stones north of the village in the Shen'dar Highlands.",al={"what is meddlesome mages","meddlesome mages quest","what is this quest"}},{q="Who are the High Order Apprentices?",a="The High Order is a faction of mages whose apprentices have ignored warnings and intruded on sacred ground to experiment with magic. The locals regard them as shen'dorei brothers and sisters.",al={"who are the high order apprentices","what is high order","high order mages"}},{q="Why must the High Order Apprentices be dispersed?",a="The apprentices have ignored repeated warnings to avoid the standing stones. Their reckless spellcraft threatens the fragile forces binding the island and could bring destruction to the homeland.",al={"why disperse high order","why fight the apprentices","standing stones problem"}},{q="Where are the High Order Apprentices gathering?",a="The High Order Apprentices gather at standing stones north of the village in the Shen'dar Highlands.",al={"where is this quest","shen'dar highlands location","standing stones north of village"}},{q="Who are the shen'dorei mentioned in the quest?",a="The shen'dorei are kin to the people who ask for help. Conflict among their own people weighs on the local leaders, yet they feel compelled to act against the High Order to protect their homeland.",al={"who are shendorei","shendorei brothers and sisters","what are shen'dorei"}},{q="What danger do the mages pose to the island?",a="Delicate forces bind the island together, and they are vulnerable. Unchecked arcane meddling could break them and destroy the island.",al={"what is the danger","island fragile forces","what could happen to the island"}}},ang={["class:Mage"]="As a Mage, you can see the danger in the High Order's reckless spellcasting. Their apprentices disregard the delicate balance that holds the island together."},kw={"arcane meddling","high order","high order apprentices","meddlesome mages","shen'dar highlands","shen'dorei","standing stones"},rel={"topic:mage"},m={faction="Horde",id=94411},src={"In-game quest text: Meddlesome Mages"},fv=true}
E["quest:94413"] = {t="quest",n="A Magical Affront",z="zephras",s="On Zephras, A Magical Affront sets the local order against the Windshapers. The order seeks to harness and study the surfaced leylines, while the Windshapers see them as scars to heal. Their conflict has reached the southwestern forest.",h="On Zephras, A Magical Affront sets the local order against the Windshapers.",sec={{t="Unveiled Currents",b="Ancient conduits of raw magic have recently broken through the earth on Zephras. For scholars and practitioners of the local order, this is a rare boon. Direct contact with the leylines gives them new insight into the arcane currents across the region and deepens their mastery of magic.",sp=0},{t="Scars and Strife",b="The Windshapers see the exposed energies as open wounds and scars across Zephras. They gather at the rupture sites to suppress or mend the leylines and heal the earth.\n\nThe order depends on that raw power, so it sees their efforts as a threat. It sends you southwest into the forest to drive the Windshapers back.",sp=0}},faq={{q="Who are the Windshapers?",a="The Windshapers are a group on Zephras who see the surfaced leylines as unnatural wounds in the land. They seek to heal them, putting them at odds with orders that study and channel the leylines.",al={"who are the windshapers","what are windshapers","windshapers zephras"}},{q="Why does the order want the Windshapers driven off?",a="The order needs access to the surfaced leylines to deepen its understanding of magic. The Windshapers try to suppress or mend them, so the order sees their efforts as a threat and sends you to drive them off.",al={"why kill windshapers","why fight the windshapers","windshaper conflict"}},{q="What are the leylines on Zephras?",a="Leylines are conduits of mystical energy that traverse the world. On Zephras, they have recently broken through the earth, exposing raw magic and giving arcane practitioners direct access to study it.",al={"what are leylines zephras","zephras leylines","surface leylines"}},{q="Where is the contested leyline located?",a="The contested leyline lies in the forest southwest on Zephras. Windshapers have gathered there to close or mend the exposed surge of magic.",al={"where is the leyline forest","leyline location","forest to southwest"}},{q="Why do the Windshapers consider the leylines scars?",a="The Windshapers see the sudden rupture of raw subterranean energy through the earth as violent scars across Zephras. They believe mending those tears will restore natural balance, which puts them at odds with spellcasters who want the leylines left open.",al={"why do windshapers want to heal leylines","are leylines harmful zephras","healing the scars"}},{q="What is the significance of Zephras in this conflict?",a="Zephras is where the leylines have recently emerged at the surface. Their raw magic has made the land a flashpoint between those who seek to master its arcane power and those who see the breaches as wounds to heal.",al={"what is zephras","where does a magical affront take place","zephras lore"}}},ang={["class:Mage"]="As a Mage, you may see the surfaced leylines on Zephras as a rare chance to study raw mystical energy directly. Their preservation matters to your arcane craft.",["class:Druid"]="As a Druid, you may feel the tension in the Windshapers’ view of the exposed leylines as wounds across the natural land, in need of healing.",["class:Shaman"]="As a Shaman, you may share the Windshapers’ elemental and natural stewardship as they seek to calm and heal disturbances across Zephras. That puts their aims at odds with orders harnessing raw magical flows."},kw={"a magical affront","arcane","leyline","leylines","scars","windshapers","zephras"},rel={"quest:92595"},m={faction="Alliance",id=94413},src={"In-game quest text: A Magical Affront"},fv=true}
E["quest:94414"] = {t="quest",n="The Anchors of Zephras",z="zephras",s="On Zephras Isle, Halaan Hawk-Eye asks you to watch the ancient anchor pylons that hold the island aloft. Their magic has begun to waver, and the wind spirits' blessing may no longer be steady.",h="On Zephras Isle, Halaan Hawk-Eye asks you to watch the ancient anchor pylons that hold the island aloft.",sec={{t="Tethers of the Isle",b="Wind spirits gave Zephras's ancient anchor pylons the power to bind and sustain the floating island. Their magic keeps the land steady amid the churning skies. From afar, the towering monoliths look untouched. Yet the island depends on the wind spirits' continuing blessing.",sp=0},{t="A Disturbing Shift",b="The anchor pylons look proud and undamaged, yet their magic has grown erratic. Halaan Hawk-Eye says the harmony that sustains them has become unstable and uncertain. No clear sign of physical harm appears. Those who watch over the groves have reason to fear what threatens the isle.",sp=0},{t="Halaan's Gift",b="Halaan Hawk-Eye cannot use skysight to peer between worlds, nor can he tap Zephras's deep ley lines. His gift is natural vision sharp enough to reach immense distances. He lends that sight to newcomers, so they can study the distant pylons and watch for changes in their homeland's fate.",sp=0}},faq={{q="What are the anchor pylons on Zephras?",a="The anchor pylons are ancient structures the wind spirits gave to Zephras. They bind and sustain the island, keeping it stable above the surrounding world.",al={"what are the anchors","zephras anchor pylon","what is an anchor pylon"},it="purpose"},{q="What is wrong with the anchor pylons?",a="The pylons show no obvious physical damage, but their stabilizing magic has grown unstable and inconsistent. The cause remains unknown.",al={"why are anchors failing","anchor pylon problem","what happened to the anchors"},it="threat"},{q="Who is Halaan Hawk-Eye?",a="Halaan Hawk-Eye watches over the groves of Zephras Isle. His natural sight reaches great distances, and he watches over the land's well-being.",al={"halaan lore","who is halaan"},it="identity"},{q="What is Halaan's gift?",a="Halaan's gift is exceptionally sharp sight over great distances. It is natural vision, unlike skysight or the power to tap Zephras's deep ley lines.",al={"halaan's gift","how does halaan see far"},it="power"},{q="What is skysight?",a="Skysight is a mystical perception that lets certain practitioners peer between worlds, far beyond ordinary vision.",al={"what is the skysight","skysight meaning"}},{q="Where does the magic powering the pylons come from?",a="The wind spirits gave the anchor pylons to Zephras. Halaan says they bind and sustain the island, but does not explain where their continuing power comes from.",al={"who made the pylons","anchor pylon origin"},it="origin"},{q="Why does Halaan Hawk-Eye want you to look at the anchor pylon?",a="Halaan Hawk-Eye watches over the grove and cares deeply about the health of Zephras. The ancient anchor pylons, gifts from the spirits of the winds, bind and sustain the island, but their magic has recently grown unstable and inconsistent. Though they appear physically undamaged, Halaan offers to share his far-reaching vision so you can witness the pylons firsthand and understand the delicate state of your homeland.",al={"halaan motive","why look at anchor pylon","why does halaan want this"},it="motive",add="61bc2f74"}},ang={["class:Shaman"]="As a shaman, you know the wind spirits' blessing sustains the anchor pylons. Their unstable magic calls for an elemental's attention.",["class:Mage"]="As a mage, you can recognize Halaan's keen eyesight as a natural gift."},kw={"anchor pylon","anchors of zephras","halaan hawk-eye","ley lines","skysight","wind spirits","zephras"},rel={"npc:halaan-hawk-eye","zone:zephras"},m={start="Halaan Hawk-Eye",level="2",id=94414},src={"The Anchors of Zephras"},fv=true}
E["quest:94484"] = {t="quest",n="Unnerving Silence",z="zephras",s="In northeastern Shadowgale Forest, a druid enclave has gone silent. Since Ban'aethall fell into ruin, unrest has spread through the territory.",h="In northeastern Shadowgale Forest, a druid enclave has gone silent.",sec={{t="Silence in the Canopy",b="After Ban'aethall fell into ruin, unrest stirred through the territory. Regular messages from the druid conclave in a cave in northeastern Shadowgale Forest have now stopped. Their allies have heard nothing, and worry grows as the forest grows more unsettled.",sp=0},{t="Seeking the Enclave",b="You are sent into northeastern Shadowgale Forest to find Elegael Thornpaw, a prominent druid of the enclave. Has the conclave withdrawn deeper into communion with nature, or have the dangers that tore through Ban'aethall reached the cave? No one knows the enclave's fate.",sp=0}},faq={{q="What is the quest Unnerving Silence about?",a="You are asked to learn why messages from a druid conclave in Shadowgale Forest have stopped. Search the cave in the forest's northeast and discover what has happened to the secluded order.",al={"unnerving silence quest","what is unnerving silence"}},{q="Where can Elegael Thornpaw be found?",a="Elegael Thornpaw is in a cave in northeastern Shadowgale Forest. She is the point of contact for the secluded druid conclave there.",al={"where is elegael thornpaw","elegael thornpaw location","find thornpaw"}},{q="Who is Elegael Thornpaw?",a="Elegael Thornpaw belongs to the druid conclave in a cave in northeastern Shadowgale Forest. Her silence and the missed scheduled messages have raised concern for the enclave's safety.",al={"who is elegael thornpaw","thornpaw lore"}},{q="What is Shadowgale Forest?",a="Shadowgale Forest is a wooded expanse with a hidden druid conclave in a cave in its northeastern region. Since Ban'aethall fell and turmoil spread through the territory, contact with the forest's people has grown uncertain.",al={"what is shadowgale forest","shadowgale forest conclave"}},{q="What is Ban'aethall?",a="Ban'aethall was a village deep in Shadowgale Forest, now fallen into ruin. Its destruction and unrest across the territory have raised fears for nearby camps, including the Shadowgale conclave.",al={"what happened to banaethall","banaethall ruins lore","ban'aethall fallen"}},{q="Why has the druid conclave gone silent?",a="The druids' scheduled messages and reports from Shadowgale Forest have stopped without explanation. With Ban'aethall in ruins and tension rising, their allies fear disaster or hostile forces may have overtaken the enclave.",al={"why did druids stop sending messages","why are druids quiet"}}},ang={["class:Druid"]="As a druid, you may worry for your kin and the balance of the wild when a secluded enclave in Shadowgale Forest falls silent. Finding Elegael Thornpaw may reveal what disrupted their communion."},kw={"ban'aethall","druid","druid conclave","elegael thornpaw","shadowgale forest","unnerving silence"},rel={"topic:druid"},m={id=94484},src={"In-game quest text: Unnerving Silence"},fv=true}
E["quest:94485"] = {t="quest",n="Tears of the Lady",z="zephras",s="In Shadowgale, Lady's Tear moss may keep Elegael's wounded companions alive. They are trapped in Nightclaw Den, and Elegael needs medicine from nearby trees.",h="In Shadowgale, Lady's Tear moss may keep Elegael's wounded companions alive.",sec={{t="Desperate Remedies in Shadowgale",b="Elegael needs your help in Shadowgale. Wounded companions are trapped inside Nightclaw Den, critically injured and waiting for aid. Ordinary supplies are scarce, so you gather medicine from the surrounding woods. Their wounds cannot wait.",sp=0},{t="The Healing Moss",b="Elegael needs Lady's Tear, a spindly moss clinging to tree bases across Shadowgale. Its secretion is viscous and sticky, with natural antiseptic properties. It seals open gashes and shields traumatic wounds from worsening in the damp wild. With enough moss, Elegael can prepare dressings to stabilize the fallen.",sp=0}},faq={{q="What is the quest Tears of the Lady about?",a="Elegael needs help treating wounded companions trapped in Nightclaw Den. Gather Lady's Tear moss in Shadowgale so Elegael can prepare a poultice to keep them alive.",al={"what is tears of the lady","tears of the lady quest info"}},{q="What is Lady's Tear?",a="Lady's Tear is a spindly moss that grows near tree bases throughout Shadowgale. Its secretion is viscous and sticky, with natural antiseptic properties that can seal open wounds.",al={"what is ladys tear","ladys tear moss","what is lady's tear moss"}},{q="Who is Elegael?",a="Elegael organizes medical aid in Shadowgale. Wounded companions are trapped in Nightclaw Den, and Elegael needs supplies to treat them.",al={"who is elegael","quest giver tears of the lady"}},{q="What is the Nightclaw Den?",a="Nightclaw Den is where several of Elegael's injured allies are stranded near Shadowgale. Their condition is precarious as Elegael seeks healing ingredients.",al={"what is nightclaw den","where is nightclaw den"}},{q="Why does Elegael need Lady's Tear moss?",a="Elegael needs Lady's Tear's antiseptic secretion to prepare a poultice. The viscous, sticky substance seals open gashes and protects traumatic wounds from worsening.",al={"why need ladys tear","what does the moss do"}},{q="Where is Lady's Tear moss found?",a="Lady's Tear clings to tree bases throughout Shadowgale. Elegael has gathered what was immediately reachable, and more moss lies in the surrounding woods.",al={"where does ladys tear grow","finding ladys tear"}}},ang={["profession:Herbalism"]="As a herbalist, you know Lady's Tear for its sticky antiseptic secretion. It can bind open flesh and help prevent infection in wilderness emergencies.",["class:Priest"]="As a priest, you channel the Light to mend mortal injuries. Natural poultices like Lady's Tear can dress wounds when magical relief is stretched thin."},kw={"elegael","lady's tear","moss","nightclaw den","poultice","shadowgale","tears of the lady"},m={id=94485},src={"In-game quest text: Tears of the Lady"},fv=true}
E["quest:94486"] = {t="quest",n="Feathers for Binding",z="zephras",s="In Shadowgale Forest, healers need young shrieklings’ feathers to bind a healing poultice. The usually docile birds now attack travelers, making the plumage dangerous to gather.",h="In Shadowgale Forest, healers need young shrieklings’ feathers to bind a healing poultice.",sec={{t="Remedies of the Forest",b="Field healers in Shadowgale Forest treat grave injuries with moss and antiseptic tree sap. Harsh weather can dry the sap or rob it of its strength. So they bind the poultice with young Shadowgale shrieklings’ feathers, which shield the wound and hold the medicine in place.",sp=0},{t="Uncharacteristic Hostility",b="Gathering the soft feathers has grown dangerous. Young Shadowgale shrieklings are usually docile woodland dwellers, but lately they have turned inexplicably aggressive. Their strong talons can inflict lethal wounds. Now the fledglings strike at passersby.",sp=0},{t="A Regrettable Necessity",b="Local caretakers mourn the need to cull young beasts. Yet emergencies threaten the region, and the shrieklings grow more dangerous. Thinning their numbers gathers vital curative materials and curbs a rising threat along forest paths. Each feather is treated with respect, so the beasts’ sacrifice is not wasted.",sp=0}},faq={{q="Why are Shadowgale shriekling feathers needed for the poultice?",a="Young Shadowgale shrieklings’ feathers insulate the poultice. Laid over moss and antiseptic sap, they keep the sap from drying and shield wounds from harsh weather.",al={"purpose of feathers","why shriekling feathers","poultice feathers"}},{q="How dangerous are the juvenile shrieklings?",a="Shadowgale shrieklings are usually docile, but lately they have grown unusually hostile. Even the young have large, vicious talons that can disembowel an unwary traveler.",al={"shriekling danger","are shrieklings dangerous","shriekling aggression"}},{q="Why must juvenile shrieklings be hunted instead of adults?",a="The caretakers regret culling young shrieklings, but their sudden aggression and competing wilderness emergencies make thinning their numbers a painful necessity. Gathering their feathers also helps meet urgent medical needs.",al={"why kill young shrieklings","killing young shrieklings"}},{q="Where are the Shadowgale shrieklings found?",a="Shadowgale shrieklings roam the canopies and underbrush of Shadowgale Forest. Travelers must venture carefully through the woods to find them.",al={"where is shadowgale forest","shriekling location","where are shrieklings"}},{q="What other ingredients are being used alongside these feathers?",a="The poultice uses local moss and antiseptic sap, bound and insulated with feathers from young shrieklings.",al={"poultice ingredients","what is in the poultice"}},{q="Why have the shrieklings become so hostile lately?",a="No one knows the exact cause of the shrieklings’ sudden hostility. The normally peaceful young creatures have grown aggressive, adding to the crises facing local caretakers.",al={"why are shrieklings angry","what caused shriekling aggression"}}},ang={["profession:Herbalism"]="Herbalists and natural healers can value the balance of moss, antiseptic tree sap, and insulating feathers in a field dressing or medicinal poultice.",["class:Druid"]="As a druid, you may share the caretakers’ sorrow over slaying young woodland beasts, even when rising aggression and urgent medical need leave few alternatives."},kw={"antiseptic sap","feathers for binding","poultice","shadowgale forest","shadowgale shriekling","shriekling","shrieklings"},m={id=94486},src={"In-game quest text: Feathers for Binding"},fv=true}
E["quest:94487"] = {t="quest",n="Unwanted and Unworthy",z="zephras",s="On Zephras, bloodshed in Shadowgale Forest drives Elegael to seek vengeance and recover stolen heirlooms for the High Elder.",h="On Zephras, bloodshed in Shadowgale Forest drives Elegael to seek vengeance and recover stolen heirlooms for...",sec={{t="Ambush in Shadowgale Forest",b="The Al'Aketh Cultists ambush the local druids in Shadowgale Forest. Elegael had thought these zealots harmless dreamers, with clouds between their ears. Now druid blood stains the forest floor, and Elegael demands swift retribution against the Footsoldiers and Stormchasers responsible.",sp=0},{t="Tainted Heirlooms and Lost Youth",b="Elegael believes the cultists' betrayal has cost them their heritage. They no longer deserve the name shen'dorei, nor do their remains deserve the winds of their homeland. Many were young, their promising futures cut short by fanaticism.\n\nTheir bloodied heirlooms must return to the High Elder. There, the sacred items await a wiser and more worthy generation.",sp=0}},faq={{q="Who are the Al'Aketh Cultists?",a="The Al'Aketh Cultists are storm-obsessed cultists on Zephras. Elegael once thought them foolish dreamers, with clouds between their ears, but they turned to brutal violence against the local druids.",al={"who are alaketh","alaketh cult","who are the cultists"}},{q="Who is Elegael?",a="Elegael is a shen'dorei protector or druid on Zephras. The Al'Aketh Cultists ambushed Elegael, and the betrayal and bloodshed of young lives have left Elegael distressed. Elegael seeks retribution and the recovery of stolen ancestral heirlooms.",al={"who is elegael","quest giver elegael"}},{q="What are the bloodied heirlooms?",a="The bloodied heirlooms belonged to young shen'dorei drawn into the Al'Aketh Cult. Elegael gathers them to return to the High Elder's collection, where they can pass to a more worthy future generation.",al={"bloodied heirlooms","why collect heirlooms","what are the heirlooms"}},{q="What are the shen'dorei?",a="The shen'dorei are the people who inhabit Zephras. Elegael believes the Al'Aketh Cultists forfeited their right to the name through violent betrayal and desecration of the island's harmony.",al={"shendorei meaning","who are shendorei"}},{q="Where is Shadowgale Forest?",a="Shadowgale Forest is a wooded region on Zephras. Al'Aketh Footsoldiers and Stormchasers operate there, and the cultists ambushed the druids there.",al={"shadowgale forest location","where is shadowgale"}},{q="Why did the Al'Aketh Cultists ambush the druids?",a="Elegael does not know the cultists' exact motives. Once dismissed as harmless zealots, they rose in sudden, vicious violence and shattered the delicate balance on the island.",al={"why did cultists attack","cult motives","why ambush druids"}}},ang={["class:Druid"]="On Zephras, the Al'Aketh Cultists spilled local druids' blood in an unprovoked assault. As a druid, you answer with vengeance and defend nature's balance."},kw={"al'aketh","bloodied heirlooms","elegael","footsoldiers","heirlooms","shadowgale forest","shen'dorei","stormchasers","zephras"},rel={"topic:druid"},m={id=94487},src={"In-game quest text: Unwanted and Unworthy"},fv=true}
E["quest:94488"] = {t="quest",n="The Ties That Bind",z="zephras",s="Elegael Thornpaw faces a traitor among Shadowgale Forest’s druids. Haalien vanished months ago, then joined the attacking cultists and rose to command them. Now Elegael orders his execution.",h="Elegael Thornpaw faces a traitor among Shadowgale Forest’s druids.",sec={{t="Betrayal in the Forest",b="Druids face a vicious cultist attack in Shadowgale Forest. Elegael Thornpaw finds Haalien’s scent over the slaughter. Haalien was a druid of the circle who vanished months ago, but he did not perish in the wilds. He joined the invading cultists and now commands their violent campaign against his former kin.",sp=0},{t="Blood and Kinship",b="Haalien betrayed more than his vows to the Cenarion Circle. When Elegael sees the fallen commander’s severed head, she reveals that Haalien was her cousin. Fury at his atrocities could not ease the burden of striking down her own kin, so she could not bear it alone. His death ends the life of a renegade whose malice cost numerous innocent lives.",sp=1}},faq={{q="Who offers the quest The Ties That Bind?",a="Elegael Thornpaw is a druid stationed in Shadowgale Forest. As cultists attack, she directs you to hunt down Commander Haalien after discovering his part in the bloodshed.",al={"who gives ties that bind","quest giver shadowgale","who is elegael thornpaw"}},{q="Who is Commander Haalien?",a="Commander Haalien was a druid of the Cenarion Circle who vanished months before the cultist attacks. He willingly joined the hostile cultists and rose to command their forces against his kin.",al={"who is haalien","commander haalien lore","haalien background"}},{q="Why does Elegael want Commander Haalien dead?",a="Haalien left his druidic circle to command cultists who slaughtered innocents and spilled the blood of his brethren. Elegael orders his execution because of his crimes and the danger he poses to the forest.",al={"why kill haalien","haalien crime","what did haalien do"}},{q="What is the connection between Elegael Thornpaw and Haalien?",a="Commander Haalien is Elegael Thornpaw’s cousin. Enraged by his crimes, she admits that killing her own kin would have been a bitter burden, so she asks you to help.",al={"elegael haalien related","how do elegael and haalien know each other"}},{q="Why are cultists present in the Shadowgale Forest?",a="Even the local druids do not know exactly why the cultists came to Shadowgale Forest. Former circle members like Haalien lead them, directing violence and bloodshed against the forest’s defenders.",al={"shadowgale forest cultists","why are cultists in shadowgale"}},{q="Where does this quest take place?",a="The events unfold in Shadowgale Forest, where Elegael Thornpaw investigates the cultist attack and confronts her cousin’s betrayal.",al={"where does ties that bind happen","shadowgale forest location"}}},ang={["class:Druid"]="As a druid, you know the Cenarion Circle holds balance and kinship sacred. Haalien’s betrayal and the bloodshed among fellow druids are grave offenses against the order."},kw={"cenarion circle","commander haalien","cultists","druid","elegael thornpaw","haalien","shadowgale forest","the ties that bind"},rel={"topic:druid"},m={id=94488},src={"In-game quest text: The Ties That Bind"},fv=true}
E["quest:94489"] = {t="quest",n="The Wounds of Betrayal",z="zephras",s="In Shadowgale Forest, Elegael cares for the shen'dorei druids wounded in a terrible assault. Poultices are ready for Nightfang Den, north across the clearing, while her mate Jorel Windsinger is missing.",h="In Shadowgale Forest, Elegael cares for the shen'dorei druids wounded in a terrible assault.",sec={{t="Aid for the Shen'dorei",b="Elegael tends the shen'dorei druids hurt in the assault on Shadowgale Forest. She has prepared poultices for her brethren sheltering in Nightfang Den, just north across the clearing. Few shen'dorei druids remain, and every survivor matters to their fragile enclave.",sp=0},{t="The Search for Jorel Windsinger",b="Elegael asks you to find her mate, Jorel Windsinger, and bring care to the seven battered druids in the cave. When she fled the fighting to prepare medicines, Jorel was already clinging to life. Nightfang Den holds the full devastation wrought upon the sanctuary, and Jorel's fate lies in its dark recesses.",sp=1},{t="A Vow of Retribution",b="After learning Jorel's end and seeing the terrible toll on her brethren, Elegael's grief turns to fury. She casts off despair and chooses retribution. Anyone allied with the Al'Aketh will face her unrelenting wrath for the slaughter of her people.",sp=2}},faq={{q="Who gives the quest The Wounds of Betrayal?",a="Elegael, a shen'dorei druid, asks you to tend her wounded brethren after a violent attack in Shadowgale Forest.",al={"who gives the wounds of betrayal","quest giver the wounds of betrayal","who is elegael"}},{q="Where is Nightfang Den located?",a="Nightfang Den lies north across the clearing in Shadowgale Forest. Injured shen'dorei druids have taken refuge in the cave.",al={"where is nightfang den","nightfang den location","where are the wounded druids"}},{q="Who is Jorel Windsinger?",a="Jorel Windsinger is Elegael's mate. Badly injured in the attack, he remained in Nightfang Den, where you learn his fate.",al={"who is jorel windsinger","jorel windsinger fate","where is jorel"}},{q="What are the shen'dorei druids?",a="The shen'dorei are a rare people with few druids among them. Elegael says every survivor is precious.",al={"what are the shendorei","who are shendorei druids","shendorei druid lore"}},{q="Who are the Al'Aketh?",a="The Al'Aketh are enemies responsible for the attack on the druids, or allies of those responsible. After learning Jorel's fate and seeing the devastation, Elegael vows vengeance on them and anyone allied with them.",al={"who are the alaketh","al aketh","why does elegael hate al aketh"}},{q="What happens to Jorel Windsinger in the quest?",a="When you find Jorel Windsinger in Nightfang Den, his condition has taken a tragic turn. News of his fate and the surviving druids' dire state leaves Elegael grief-stricken and furious, and she vows revenge.",al={"what happens to jorel windsinger","does jorel live","jorel outcome"}}},ang={["class:Druid"]="As a druid, you know the weight of seeing fellow caretakers of the wilds suffer betrayal and grievous injury. The shen'dorei druids are few.",["race:NightElf"]="As a night elf, you revere druidic traditions. The suffering of kindred druids in Shadowgale Forest and their struggle against treachery may weigh heavily on you."},kw={"al'aketh","druid","elegael","jorel windsinger","nightfang den","shadowgale forest","shen'dorei","the wounds of betrayal"},rel={"topic:druid"},m={id=94489},src={"In-game quest text: The Wounds of Betrayal"},fv=true}
E["quest:94490"] = {t="quest",n="Ripped Missive",z="zephras",s="Haalien bears a bloodied letter after an attack on a druid den in Shadowgale Forest. Its words reveal what the cultists sought and point toward danger within Valanaar.",h="Haalien bears a bloodied letter after an attack on a druid den in Shadowgale Forest.",sec={{t="Bloodstained Orders",b="Haalien's missive gives a glimpse of the violence in Shadowgale Forest. Found after a fierce skirmish, the torn scrap bears grim news of cultists who attacked a local druid den. Its words offer clues to those seeking justice for the fallen.",sp=0},{t="Senseless Slaughter",b="Elegael Thornpaw learns why the cultists struck the den. They sought a mysterious pylon, not a feud with the druids. The den's inhabitants died because they stood in the way. Enraged by the slaughter, Elegael vows vengeance on any cultists still in the forest.",sp=1},{t="Treachery in Valanaar",b="Orders from within Valanaar lie behind the attack. The missive points to a directive from the settlement, where a traitor may be at work. To uncover the conspiracy before more lives are lost, the letter must reach Lotheluum in Valanaar without delay.",sp=2}},faq={{q="What is the Ripped Missive?",a="The missive is a torn, bloodstained letter found behind Haalien's bracer after a battle. It reveals why cultists attacked a druid den in Shadowgale Forest.",al={"what is ripped missive","ripped missive quest","bloodstained note haalien"}},{q="Where is the missive recovered from?",a="The missive was found behind Haalien's bracer after a violent confrontation. The battle left the letter torn and bloodstained.",al={"who dropped the ripped missive","where did ripped missive come from","who is haalien"}},{q="Who should receive the Ripped Missive?",a="Elegael Thornpaw in Shadowgale Forest should receive the missive first. After reading it, Elegael directs that it be carried swiftly to Lotheluum in Valanaar.",al={"who wants the ripped missive","who do i give ripped missive to","elegael thornpaw missive"}},{q="Why did the cultists attack the druid den?",a="The cultists attacked the druid den to secure a pylon there. They killed the druids because they stood in the way.",al={"why did cultists attack the druid den","cultist motive druid den","why did haalien attack"}},{q="Where did the attack orders originate?",a="The missive points to orders from Valanaar, where a traitor may be directing the cultists' work.",al={"where did the orders come from","who sent haalien","valanaar traitor"}},{q="Who is Lotheluum and why must they be notified?",a="Lotheluum is a contact in Valanaar. Elegael Thornpaw orders the missive delivered there to warn that the deadly orders trace back to someone hidden in the settlement.",al={"who is lotheluum","why take missive to lotheluum","lotheluum valanaar"}}},ang={["class:Druid"]="The letter brings bitter news: druids at the den were slaughtered because they stood in the way of cultists seeking a pylon."},kw={"cultist","druid den","elegael thornpaw","haalien","lotheluum","pylon","ripped missive","shadowgale forest","valanaar"},rel={"topic:druid"},m={id=94490},src={"In-game quest text: Ripped Missive"},fv=true}
E["quest:94491"] = {t="quest",n="The Fate of the Den",z="zephras",s="At the druid den, survivors mourn their fallen after the cultist assault. The Fate of the Den reaches Lotheluum in Valanaar with a recovered missive and word of heavy losses. The dispatch reveals that someone in Valanaar has been feeding vital information to the enemy.",h="At the druid den, survivors mourn their fallen after the cultist assault.",sec={{t="Tragedy at the Den",b="Cultists struck the druid den and left its defenders battered and grieving for fallen comrades. Outside aid brought the immediate danger under control, but the physical and emotional devastation remains immense. The dead cannot be brought back, and the wounded survivors are too weak for the long trek. Lingering cultists still roam nearby.",sp=0},{t="Treachery in Valanaar",b="The recovered missive shows the cultists chose their target with purpose. Someone hidden within Valanaar has been feeding them intelligence. When Lotheluum hears of the slaughter and reads the dispatch, grief for his fallen fellows gives way to alarm. A traitor still walks free in the settlement. He takes the evidence to the High Elder so their sacrifice will not be forgotten.",sp=1}},faq={{q="Who is Lotheluum?",a="Lotheluum lives in Valanaar and receives reports about the druid den. News of the assault and the recovered missive grieve him for his fallen fellows, so he takes evidence of betrayal to the High Elder.",al={"lotheluum","who is lotheluum","lotheluum npc"}},{q="What happened at the druid den?",a="Cultists devastated the druid den and killed many defenders. An adventurer helped bring the immediate danger under control, and the battered survivors found evidence that an insider had guided the attack.",al={"what happened at the den","druid den attack","fate of the den backstory"}},{q="What does the recovered missive reveal?",a="The missive reveals that someone hidden in Valanaar has secretly fed intelligence to the cult. It suggests local sabotage and espionage enabled the deadly raid on the den.",al={"what does the missive say","den missive","traitor missive"}},{q="Who is the High Elder mentioned by Lotheluum?",a="The High Elder is an authority in Valanaar to whom Lotheluum answers. Facing heavy casualties and the threat of a traitor, Lotheluum brings the missive and news of the tragedy to the High Elder.",al={"who is the high elder","valanaar high elder","high elder"}},{q="Who was responsible for attacking the druid den?",a="Members of a cult operating in the region attacked the druid den. An informant sheltered in Valanaar guided them, and the assault cost the den's inhabitants dearly.",al={"who attacked the den","who attacked druid den","den cultists"}},{q="Why could the survivor at the den not deliver the missive personally?",a="The survivor was too badly wounded by the attack to make the trek to Valanaar. The survivor stayed behind to eliminate remaining cultists and sent an adventurer to raise the alarm.",al={"why do we deliver the missive","quest giver injured","why cant the survivor go to valanaar"}}},ang={["class:Druid"]="As a druid, you feel the weight of this tragedy. Those who fell were your fellows, and hostile cultists betrayed their secluded refuge."},kw={"cultists","druid den","high elder","lotheluum","missive","the fate of the den","traitor","valanaar"},rel={"topic:druid"},m={id=94491},src={"In-game quest text: The Fate of the Den"},fv=true}
E["quest:94493"] = {t="quest",n="A Sacrifice in Vain",z="zephras",s="Elegael Thornpaw fears the Al'Aketh Cultists will overwhelm the wounded in her den. A message meant for Valanaar has not reached them, leaving her to ask for help.",h="Elegael Thornpaw fears the Al'Aketh Cultists will overwhelm the wounded in her den.",sec={{t="A Plea for Aid",b="The Al'Aketh Cultists fell upon Elegael Thornpaw's fellows with almost no warning. Many in her den are wounded or dying, and she does not know how long they can survive the attack. She had tried to send word to Valanaar, but the message did not get through. With no reinforcements in sight, Elegael asks you to help.",sp=0}},faq={{q="Who is asking for help?",a="Elegael Thornpaw asks for help as the Al'Aketh Cultists attack her fellows.",al={"who needs help","Elegael Thornpaw","Elegael"}},{q="What happened to the people in the den?",a="The Al'Aketh Cultists ambushed them with little warning. Many are wounded or dying.",al={"den wounded","what happened here","cultist attack"}},{q="Why did Valanaar not send reinforcements?",a="Elegael's message did not reach Valanaar, so reinforcements have not arrived.",al={"where are reinforcements","Valanaar message","message to Valanaar"}},{q="What does Elegael need?",a="Elegael asks you to help her wounded fellows survive the Al'Aketh Cultists' attack.",al={"how can I help","help Elegael","what does she ask"}}},kw={"a sacrifice in vain","al'aketh cultists","den","elegael thornpaw","reinforcements","valanaar","wounded"},m={id=94493},src={"In-game quest text: A Sacrifice in Vain"},fv=true}
E["quest:94568"] = {t="quest",n="The Cult's True Plans",z="zephras",s="The cult's informant has died before sharing what he knew. Talaanis Shadowsong must help investigators find another way to oppose the cult.",h="The cult's informant has died before sharing what he knew.",sec={{t="A Silenced Defector",b="A frightened insider left the cult and hoped to seek help beyond it. Before he could reveal what he knew, he was killed. His warnings remain, but the cult's plans do not.",sp=0},{t="Rethinking the Approach",b="The informant's death leaves the leadership without its chief source of knowledge. They consult Talaanis Shadowsong and reconsider how to confront the cult. An open attack with peacekeepers is judged a losing battle, so the investigators must find another way forward.",sp=1}},faq={{q="Who was the turncoat mentioned in this quest?",a="The turncoat was a cult insider who sought help after becoming terrified of the cult's schemes. He was killed before he could reveal what he knew.",al={"who died in the cults true plans","who is the dead turncoat","turncoat cult secrets"}},{q="Who is Talaanis Shadowsong?",a="Talaanis Shadowsong is the contact consulted after the informant's death. You observe a strategic discussion with Talaanis about how to proceed against the cult.",al={"talaanis shadowsong role","who is talaanis shadowsong","speak with talaanis"}},{q="Why can't peacekeepers simply attack the cult directly?",a="Peacekeepers are not expected to fare well in an open clash with the cult. The investigators judge that a direct attack would be a losing battle.",al={"why not fight the cult","peacekeepers vs cult","direct assault cult"}},{q="What are the cult's actual plans?",a="The cult's plans remain unknown because the informant died before sharing what he knew. Whatever they intend was frightening enough to drive a member to seek help.",al={"what is the cult planning","cult scheme","cult true plans meaning"}},{q="What is the next step after speaking with Talaanis?",a="After the informant's death and the decision against open battle, the leadership must find another way to uncover and thwart the cult's plans.",al={"what happens after the cults true plans","next steps cult quest"}},{q="What happens during The Cult's True Plans?",a="You speak with Talaanis Shadowsong and observe a council about the informant's death. The discussion considers why the peacekeepers cannot be relied on to stop the cult by force.",al={"the cults true plans quest summary","what do you do in the cults true plans"}}},kw={"cult","defector","peacekeepers","talaanis shadowsong","the cult's true plans","turncoat"},rel={"quest:92643"},m={faction="Horde",id=94568},src={"In-game quest text: The Cult's True Plans"},fv=true}
E["quest:94638"] = {t="quest",n="Strength and Mercy",z="zephras",s="Ur'endra's mate asks you to end her suffering after she loses herself to madness. Your resolve earns a blessing to take the shape of his kin.",h="Ur'endra's mate asks you to end her suffering after she loses herself to madness.",sec={{t="A Heavy Plea",b="A druid asks you to end Ur'endra's suffering in the Shen'dar Highlands. She is his mate, but madness has turned her against her own kin. The loss of the winds' magic has driven many creatures to lose themselves, and Ur'endra is among them. Her lair lies in a cave west of here, along the bluffs between the Shen'dar Highlands and the Gustberry Lowlands.",sp=0},{t="The Blessing",b="In the Shen'dar Highlands, Ur'endra's mate grieves her loss and calls it necessary for the balance. He sees your resolve in accepting so terrible a price. He grants you a blessing that lets you take the shape of his kin, and charges you to aid those who lack strength and defend those in need.",sp=1}},faq={{q="Who is Ur'endra?",a="Ur'endra is the mate of the druid who asks you to end her suffering.",al={"ur'endra","urendra who","druid's mate"}},{q="Why is Ur'endra attacking her kin?",a="Ur'endra has lost herself to madness. The loss of the winds' magic has caused many creatures to lose themselves.",al={"why urendra mad","urendra attacking","what happened to urendra"}},{q="Where is Ur'endra's lair?",a="Ur'endra makes her lair in a cave west of the druid, in the bluffs between the Shen'dar Highlands and the Gustberry Lowlands.",al={"urendra cave","where is urendra","shen'dar cave"}},{q="What does the druid ask me to do?",a="The druid asks you to end Ur'endra's suffering.",al={"urendra task","what do i do","kill urendra"}},{q="What blessing does the druid grant?",a="The druid grants you a blessing that lets you take the shape of his kin.",al={"shape blessing","way of the claw","druid blessing"}},{q="Why does the druid ask for this?",a="The druid considers ending Ur'endra's suffering necessary for the balance.",al={"why kill urendra","why this is necessary","balance"}}},ang={["class:Druid"]="As a druid, you are asked to prove your resolve before receiving a blessing to take the shape of the druid's kin."},kw={"druid blessing","gustberry lowlands","shape of the claw","shen'dar highlands","strength and mercy","ur'endra","winds' magic"},m={id=94638},src={"In-game quest text: Strength and Mercy"},fv=true}
E["quest:94896"] = {t="quest",n="Aid For The Refugees",z="zephras",s="After Ban'aethal fell, its survivors have little left to call their own. The settlement deep in Shadowgale Forest began to fall into the sky in the middle of the night, and danger keeps the refugees from retrieving what they left behind.",h="After Ban'aethal fell, its survivors have little left to call their own.",sec={{t="A Desperate Plea",b="Ealaane and the other refugees fled their homes deep in Shadowgale Forest. With almost nothing gathered around them, they ask travelers to brave the dangers they left behind.",sp=0},{t="The Calamity of Ban'aethal",b="Ban'aethal began to fall into the sky in the dead of night. Its inhabitants had only moments to escape, leaving their personal possessions behind. The surrounding woods grew hostile and dangerous.",sp=0}},faq={{q="Who is Ealaane?",a="Ealaane fled Ban'aethal with others when their settlement began to collapse. She asks travelers heading toward Shadowgale Forest to recover the belongings left in the ruins.",al={"who gave aid for the refugees","quest giver aid for the refugees","ealaane"}},{q="What happened to Ban'aethal?",a="Ban'aethal was a settlement deep within Shadowgale Forest. Its residents fled in the middle of the night when a sudden catastrophe struck.",al={"what is banaethal","where is banaethal","ban aethal village"}},{q="Why did the villagers have to evacuate Ban'aethal?",a="Ban'aethal began to fall into the sky in the middle of the night, forcing its residents to flee. The village and surrounding forest became too dangerous for them to stay or return.",al={"why evacuate banaethal","falling into sky","ban aethal disaster"}},{q="Why are the villagers asking for their belongings to be retrieved?",a="The catastrophe came suddenly in the middle of the night, leaving the villagers little time to flee with their belongings. The forest and ruins are now too dangerous, so they depend on travelers to recover what was left behind.",al={"why need belongings","abandoned belongings","why recover belongings"}},{q="What is Shadowgale Forest?",a="Shadowgale Forest is the wooded region where Ban'aethal stood. Since the disaster tore the village apart, the forest has become extremely hazardous for ordinary folk.",al={"where is shadowgale forest","shadowgale forest lore"}},{q="Can the refugees return to their homes?",a="No. Ealaane says Shadowgale Forest and the ruins of Ban'aethal are too dangerous for the refugees to return on their own.",al={"can refugees go back","is banaethal safe"}}},kw={"aid for the refugees","ban'aethal","banaethal","belongings","ealaane","refugees","shadowgale forest"},rel={"topic:refugee"},m={id=94896},src={"In-game quest text: Aid For The Refugees"},fv=true}
E["quest:94897"] = {t="quest",n="The Fate of a Loved One",z="zephras",s="Resaan has been gone from the Ruins of Ban'aethal for more than a week, and his partner waits for news. Travelers bound there are asked to bring him home or return his cherished heirloom.",h="Resaan has been gone from the Ruins of Ban'aethal for more than a week, and his partner waits for news.",sec={{t="A Desperate Plea",b="Resaan's partner pleads with him to stay as he prepares to return to the Ruins of Ban'aethal. Yet he feels compelled to brave the ruins for supplies. His partner is left waiting for word.",sp=0},{t="Vanished in the Ruins",b="More than a week has passed since Resaan set out, far longer than a swift return should take. His partner asks travelers bound for Ban'aethal to search the ruins. If Resaan lives, bring him home. If tragedy has taken him, recover his family heirloom.",sp=0}},faq={{q="Who is Resaan?",a="Resaan returned to the Ruins of Ban'aethal to gather supplies despite his partner's pleas that he stay. More than a week has passed without word, and his partner fears the worst.",al={"who is resaan","where is resaan","find resaan"}},{q="What are the Ruins of Ban'aethal?",a="The Ruins of Ban'aethal are where Resaan went in search of supplies. His partner fears he may not have survived a week there alone.",al={"what is banaethal","ruins of banaethal lore","where is banaethal"}},{q="Why did Resaan return to Ban'aethal?",a="Resaan returned to Ban'aethal to retrieve supplies despite his partner's pleas that he stay.",al={"why did resaan go back","why resaan in banaethal"}},{q="What does the questgiver ask you to bring back?",a="Resaan's partner asks travelers to bring him safely home if he is alive. If he has perished in the ruins, they ask for his personal heirloom as a keepsake.",al={"what does questgiver want","what happens if resaan dead"}},{q="How long has Resaan been missing?",a="Resaan has been missing for more than a week since setting out for the Ruins of Ban'aethal. The dangers there leave his partner fearing the worst.",al={"how long resaan missing","how long has resaan been gone"}},{q="Who offers this quest?",a="Resaan's grieving partner asks passing travelers heading toward Ban'aethal for help, desperate to learn what became of him.",al={"who gives fate of a loved one","fate of a loved one questgiver"}}},kw={"ban'aethal","heirloom","resaan","ruins of ban'aethal","supplies","the fate of a loved one"},m={id=94897},src={"In-game quest text: The Fate of a Loved One"},fv=true}
E["quest:94946"] = {t="quest",n="The Magical City of Dalaran",z="zephras",s="A mage in Valanaar sends you from Zephras Isle to Dalaran City, where several mages await your people's arrival. The city offers a place to begin exploring Azeroth, but the lands beyond can be dangerous without preparation and experience.",h="A mage in Valanaar sends you from Zephras Isle to Dalaran City, where several mages await your people's...",sec={{t="Arrival in Dalaran",b="Recent events with the cult keep the speaker in Valanaar for now. Several mages wait in Dalaran for your people, so you are sent to the dock outside the lodge. There, you board a skycutter bound for Dalaran City.\n\nWhen you arrive, speak with Danaaris Stargale. Your people are still making their home in the city, and the country beyond its safety can prove dangerous.",sp=0}},faq={{q="Who is waiting in Dalaran?",a="Several mages await your people's arrival in Dalaran. When you reach the city, you are asked to speak with Danaaris Stargale.",al={"mages in dalaran","who's in dalaran","dalaran mages"}},{q="Where do I travel from?",a="You travel from Zephras Isle to Dalaran City aboard the skycutter at the dock outside the lodge.",al={"how get to dalaran","from zephras","skycutter"}},{q="Why is the speaker staying in Valanaar?",a="Recent events with the cult changed the speaker's plans, so they intend to remain in Valanaar for a time.",al={"why stay valanaar","cult changed plans","valanaar mage"}},{q="Is it safe outside Dalaran?",a="The land beyond Dalaran can be dangerous without proper preparation and experience.",al={"outside dalaran safe","danger near dalaran","dalaran outskirts"}}},ang={["race:Skyborne"]="As a Skyborne, you travel from Zephras Isle to join the mages awaiting your people's arrival in Dalaran."},kw={"cult","dalaran","dalaran city","danaaris stargale","mages","skycutter","valanaar","zephras isle"},rel={"zone:zephras","subzone:dalaran"},m={faction="Alliance",id=94946},src={"In-game quest text: The Magical City of Dalaran"},fv=true}
E["quest:94978"] = {t="quest",n="Taming the Beast",z="zephras",s="Quel'ana Quickgale teaches you the bond between beast and master. You begin by taming a Windsong Crawler near the waters of Zephras.",h="Quel'ana Quickgale teaches you the bond between beast and master.",sec={{t="First Bond",b="You have the Taming Rod and a Windsong Crawler to tame. Find one near a body of water and practice your skills. Then return the rod to Quel'ana Quickgale in Valanaar. This creature is your first step toward mastery.",sp=0}},faq={{q="What does Quel'ana ask me to tame?",a="Quel'ana asks you to tame a Windsong Crawler near a body of water on Zephras.",al={"what beast","taming target","crawler quest"}},{q="What is the Taming Rod for?",a="You use the Taming Rod to tame a Windsong Crawler.",al={"how rod works","taming tool","rod quest"}},{q="Where do I find a Windsong Crawler?",a="Windsong Crawlers live near bodies of water on Zephras.",al={"crawler location","where crawler","zephras beast"}},{q="Who gave me the Taming Rod?",a="Quel'ana Quickgale gives you the Taming Rod in Valanaar.",al={"quest giver","who is quelana","quelana quickgale"}},{q="Why am I learning to tame a beast?",a="Learning the bond between beast and master is the first step toward mastery of your class.",al={"why tame crawler","beast mastery","first taming"}}},kw={"beast taming","quel'ana quickgale","taming rod","taming the beast","valanaar","windsong crawler","zephras"},rel={"item:taming-rod"},m={cl={"HUNTER"},id=94978},src={"In-game quest text: Taming the Beast"},fv=true}
E["quest:94979"] = {t="quest",n="Taming the Beast",z="zephras",s="In the Gustberry Lowlands, Quel'ana Quickgale asks you to tame a galestrider. Your skill on open ground will prepare you for trials ahead.",h="In the Gustberry Lowlands, Quel'ana Quickgale asks you to tame a galestrider.",sec={{t="Across the Plains",b="You've already shown you can tame the river's crawler. Now Quel'ana Quickgale gives you a Taming Rod and sends you to the lowlands of Zephras. There, a proud, winged galestrider runs swiftly across the plains. Earn its trust and practice your skill. Then bring the rod back to Quel'ana in Valanaar.",sp=0}},faq={{q="What does Quel'ana want me to tame?",a="Quel'ana asks you to tame an Ornery Galestrider in the Gustberry Lowlands.",al={"tame what","galestrider tame","what beast"}},{q="Where do I find the galestrider?",a="You can find the Ornery Galestrider in the Gustberry Lowlands, in the plains of Zephras.",al={"where galestrider","galestrider location","lowlands where"}},{q="What is the Taming Rod for?",a="Quel'ana gives you the Taming Rod so you can tame an Ornery Galestrider.",al={"taming rod use","rod for what","how tame beast"}},{q="Who gave me this assignment?",a="Quel'ana Quickgale in Valanaar asks you to tame an Ornery Galestrider and bring back the Taming Rod.",al={"who sent me","quelana who","quickgale"}}},kw={"galestrider","gustberry lowlands","ornery galestrider","quel'ana quickgale","taming rod","taming the beast","valanaar","zephras"},rel={"item:taming-rod"},m={cl={"HUNTER"},id=94979},src={"In-game quest text: Taming the Beast"},fv=true}
E["quest:95349"] = {t="quest",n="The Earthen Ring",z="zephras",s="From Zephras, the Windshapers of The Earthen Ring reach Azeroth as an advance vanguard. After cult activity delays the rest in Valanaar, they board a skycutter outside the lodge and make landfall in Mulgore to meet Alaana Stormwalker and adjust to a vast, dangerous world.",h="From Zephras, the Windshapers of The Earthen Ring reach Azeroth as an advance vanguard.",sec={{t="Departure from Valanaar",b="Cult activity in Valanaar has disrupted the Windshapers’ plans to travel to Azeroth. Their senior leaders stay behind at the lodge to finish urgent business and quell the threat, while a small vanguard sets out ahead. At the docks just outside the lodge, the pioneers board a skycutter bound across the skies.\n\nTheir commanders promise to join them soon. Until then, the advance group must establish a presence before the rest can follow.",sp=0},{t="Arrival in Mulgore",b="In Mulgore, Alaana Stormwalker welcomes the arriving adventurers from Zephras. Establishing a foothold in Azeroth will take time, so newcomers are encouraged to scout the surrounding territory and grow accustomed to it.\n\nThe winds favor the expedition, but Azeroth is unfamiliar and perilous. Travelers should learn the local terrain, wildlife, and neighboring inhabitants before those still in Valanaar arrive to join them.",sp=0}},faq={{q="Why are the Windshapers traveling to Azeroth?",a="The Windshapers send a vanguard ahead to establish a presence on Azeroth while their leaders remain in Valanaar. Cult activity there disrupted the original plans and delayed the rest of the group, so the advance party travels alone until reinforcements can follow.",al={"why go to azeroth","windshaper mission","why are windshapers in mulgore"}},{q="Who is Alaana Stormwalker?",a="Alaana Stormwalker welcomes Windshapers arriving from Zephras in Mulgore. She says establishing a secure presence in these new lands will take time and advises newcomers to explore the surrounding region and prepare for Azeroth’s dangers.",al={"who is alaana","alaana stormwalker role","where is alaana stormwalker"}},{q="Why was the main departure delayed?",a="Cult activity in Valanaar delayed the main departure. Expedition leaders stay behind at the lodge to settle the trouble, while a small vanguard boards a skycutter and travels ahead to Azeroth.",al={"why the delay","what cult delayed travel","why stay in valanaar"}},{q="How do travelers journey from Valanaar to Mulgore?",a="Travelers board a skycutter at the docks just outside the lodge in Valanaar. It carries the vanguard across the sky to Mulgore, connecting Zephras with Azeroth during the initial expedition.",al={"how to reach mulgore","where is the ship","how do you travel to azeroth"}},{q="What is Zephras?",a="Zephras is the home of the adventurers arriving aboard the skycutter. In Mulgore, Alaana Stormwalker welcomes newcomers from Zephras and says favorable winds guided their crossing into unfamiliar, dangerous Azeroth.",al={"where is zephras","what is zephras","zephras lore"}},{q="What should adventurers do upon arriving in Mulgore?",a="New arrivals are encouraged to scout the surrounding lands of Mulgore. Learning the nearby terrain, creatures, and local threats will help them as they establish a presence in this unfamiliar, hazardous world.",al={"what to do in mulgore","next steps after arriving","what to do next"}}},ang={["race:Skyborne"]="As a Skyborne adventurer leaving Valanaar, you make the historic journey to Azeroth as part of its advance vanguard. You leave the cult troubles behind and set foot on Mulgore’s plains.",["race:Tauren"]="As a Tauren native to Mulgore, you witness travelers from Zephras descending upon your ancestral plains. Welcoming these visitors offers an early connection to allies seeking a foothold in your lands.",["class:Shaman"]="As a Shaman, you share the Windshapers’ reverence for the elements and their reliance on the winds to guide their crossing. Arriving under The Earthen Ring connects you to elemental traditions taking root in Mulgore."},kw={"alaana stormwalker","banu-alah","cult","mulgore","skycutter","the earthen ring","valanaar","windshapers","zephras"},rel={"zone:mulgore"},m={faction="Horde",id=95349},src={"In-game quest text: The Earthen Ring"},fv=true}
E["quest:96101"] = {t="quest",n="The Great Outdoors",z="zephras",s="Raan welcomes new wanderers and shows them how to endure the wild. Rest by his basic campfire to gain Boosted Rest, then visit nearby trade trainers to learn practical professions.",h="Raan welcomes new wanderers and shows them how to endure the wild.",sec={{t="Lessons in the Wild",b="Raan has traveled the wilds and teaches others how to survive beyond settlement walls. Ambition and steel alone will not carry you through harsh weather; practical campcraft matters. He welcomes those seeking fortune and glory, and offers guidance to anyone willing to learn.",sp=0},{t="The Warmth of the Hearth",b="Raan asks you to sit beside his basic campfire and rest until you gain Boosted Rest. Across Azeroth's wild places, knowing when to pause, make camp, and recover can mean the difference between life and death.\n\nAfter the lesson, Raan directs you to nearby village trainers. There you can learn a trade and craft specialized fixtures for your campsite.",sp=0}},faq={{q="Who gives the quest The Great Outdoors?",a="Raan, an experienced traveler, teaches wandering adventurers how to survive in the open wilderness.",al={"who offers the great outdoors","quest giver the great outdoors","raan campfire quest"}},{q="What is the purpose of The Great Outdoors?",a="The lesson teaches wilderness survival. Rest beside a basic campfire to gain Boosted Rest before dangerous journeys.",al={"what does the great outdoors teach","the great outdoors purpose","what do i learn from raan"}},{q="How is the quest completed?",a="Sit beside Raan's basic campfire and rest until you gain Boosted Rest.",al={"how to complete the great outdoors","raan campfire objective","boosted rest objective"}},{q="What does Raan suggest doing after completing the quest?",a="After the campfire lesson, Raan encourages you to visit nearby village trainers and learn a practical trade. Craftsmen can create camp fixtures suited to their craft.",al={"what does raan advise next","where to go after the great outdoors","after completing the great outdoors"}},{q="What is Boosted Rest?",a="Boosted Rest is a restorative effect gained by resting beside an established campfire. It helps travelers recover while braving the elements.",al={"what is boosted rest","campfire boosted rest buff"}},{q="Do tradeskills allow adventurers to craft campsite fixtures?",a="Yes. Local trade trainers can teach you to craft useful camp fixtures suited to your craft, so you can maintain a specialized campsite outdoors.",al={"can professions make campfires","profession camp fixtures","trade camp items"}}},ang={["profession:Cooking"]="As a cook, you know a basic campfire helps a traveling party rest and recover in the wild.",["class:Hunter"]="As a hunter, you know campcraft is essential for trackers and rangers who live beneath open skies."},kw={"basic campfire","boosted rest","camp fixture","campfire","raan","the great outdoors","tradeskill","wilderness survival"},m={id=96101},src={"In-game quest text: The Great Outdoors"},fv=true}
E["quest:96638"] = {t="quest",n="The Adventurer",z="zephras",s="On Zephras Isle, The Adventurer leaves Thendal Grove for the road to Shen'dar Village. Aetheen of the Gales sends newly seasoned wanderers southwest to meet Raan Wildwind, a veteran camper who knows the wilds.",h="On Zephras Isle, The Adventurer leaves Thendal Grove for the road to Shen'dar Village.",sec={{t="Leaving the Grove",b="Thendal Grove offers shelter, but Zephras Isle beyond it remains wild and perilous. Aetheen of the Gales watches over the initiates and knows when a traveler is ready to leave familiar ground. Those seeking fame, fortune or purpose have outgrown the grove's sheltered bounds.",sp=0},{t="A Guide on the Road",b="Raan Wildwind has made camp southwest of Thendal Grove, along the road to Shen'dar Village. He has spent time facing the dangers beyond the safe haven. For wanderers setting out from the grove, Raan offers practical counsel on surviving the open roads.",sp=0}},faq={{q="Who sends you to find Raan Wildwind?",a="Aetheen of the Gales sends you from Thendal Grove to find Raan Wildwind. After you prove yourself in the surrounding woods, she points you toward someone who knows the wider isle firsthand.",al={"who gives the adventurer","who starts the adventurer quest","aetheen quest"}},{q="Where is Raan Wildwind located?",a="Raan Wildwind has made camp southwest of Thendal Grove, along the main road to Shen'dar Village.",al={"raan wildwind location","where is raan","how to find raan wildwind"},it="place",gp=true},{q="What is the purpose of this task?",a="You leave Thendal Grove's safe haven and meet a guide to the challenges farther across Zephras Isle.",al={"why do the adventurer","purpose of quest the adventurer","what does raan teach"},it="purpose"},{q="What prerequisite must be completed before receiving this quest?",a="Before Aetheen of the Gales sends you to Raan Wildwind, you must complete the task concerning the Foul Matriarch.",al={"the adventurer prereq","requirements for the adventurer"},gp=true},{q="Is Shen'dar Village safe for travelers?",a="Shen'dar Village lies beyond Raan's camp, at the end of the road southwest from Thendal Grove. It is a notable settlement, but take care on the roads and in the surrounding wilds.",al={"is shendar safe","what is shendar village"},it="danger"},{q="Who is Raan Wildwind?",a="Raan Wildwind is a wanderer who traveled beyond Thendal Grove and made camp outside Shen'dar Village. He offers practical advice and tasks to newcomers heading down the road.",al={"raan lore","who is raan wildwind"},it="identity"},{q="Why does Aetheen of the Gales send you to find Raan Wildwind?",a="Aetheen recognizes that more wanderers are venturing beyond the safety of Thendal Grove in search of glory and fortune. Knowing the wilderness poses great danger to the inexperienced, Aetheen wants you to seek out Raan Wildwind—a fellow traveler camped near Shen'dar Village—to learn practical wisdom and survival lessons that will keep you alive during your journeys across the isle.",al={"why does aetheen send you","aetheen of the gales motive","why meet raan wildwind"},it="motive",add="dc12ab9c"}},ang={["race:Skyborne"]="As a young Skyborne leaving Thendal Grove's sheltered canopy, you meet Raan Wildwind as your first step into the wider wilds of your island home."},kw={"aetheen of the gales","raan wildwind","shen'dar village","the adventurer","thendal grove","zephras isle"},rel={"quest:92470","quest:92471","zone:zephras"},m={start="Aetheen of the Gales",["end"]="Raan Wildwind",level="6",id=96638},src={"The Adventurer (Zephras Isle)"},fv=true}
E["quest:96646"] = {t="quest",n="Camping 101: Cooking",z="zephras",s="At Shen'dar Village, Zerril Softbreeze shows you how to kindle a campfire. Camping 101: Cooking teaches you to make a fire and establish a campsite in the wilderness.",h="At Shen'dar Village, Zerril Softbreeze shows you how to kindle a campfire.",sec={{t="The Hearth of the Wild",b="A campfire gives you a place to rest in untamed lands. Learning to cook begins with making that fire. It is the first step toward establishing a safe campsite.",sp=0},{t="Foundations of the Campsite",b="Speak with Zerril Softbreeze in Shen'dar Village to learn the fundamentals of cooking. Once you know how to kindle a campfire, you can establish a small campsite in the wilderness. A basic camp has only a few furnishings. As your cooking skill improves, you can kindle larger fires. Other tradeskills help furnish the site.",sp=0}},faq={{q="What is Camping 101: Cooking?",a="Camping 101: Cooking teaches you to kindle a campfire and establish a campsite in the wilderness.",al={"what is camping 101 cooking","camping cooking quest"}},{q="Who is Zerril Softbreeze?",a="Zerril Softbreeze teaches cooking and campfire making in Shen'dar Village.",al={"who is zerril softbreeze","cooking trainer shen'dar"}},{q="Why is cooking required to set up a camp?",a="Cooking teaches you to kindle the campfire at the heart of a wilderness campsite.",al={"why learn cooking for camping","why need cooking for camp"}},{q="Where is Zerril Softbreeze located?",a="Zerril Softbreeze is in Shen'dar Village.",al={"where is zerril softbreeze","shen'dar village location"}},{q="How can campsites be furnished?",a="A basic camp has few furnishings. Other tradeskills let you craft and set up more.",al={"campsite furnishings","how to furnish camp"}},{q="Can campfires be upgraded?",a="As your cooking skill improves, you can kindle larger campfires.",al={"bigger campfires","upgrade camp"}}},ang={["profession:Cooking"]="As a cook, you learn to kindle a campfire at the heart of a wilderness campsite."},kw={"campfire","camping","campsite","cooking","furnishings","shen'dar village","zerril softbreeze"},m={id=96646},src={"In-game quest text: Camping 101: Cooking"},fv=true}
E["quest:96996"] = {t="quest",n="Your First Riding Galestrider",z="zephras",s="Your trainer asks you to choose your first riding galestrider after training. The strider you choose will travel with you as you journey far from Zephras.",h="Your trainer asks you to choose your first riding galestrider after training.",sec={{t="A Choice to Make",b="Training is complete, and the riding galestriders are waiting for you in Zephras. Your trainer says your ancestors have ridden these slender, wispy mounts for generations. They are steadfast and fierce despite their appearance. Examine the striders and choose one to accompany you.",sp=0},{t="A Reminder of Home",b="After you choose, your trainer sees that the strider seems fond of you already. The bond brings a reminder of Zephras along as your adventures carry you far from home. Your trainer hopes you will care for the strider, and that it will care for you.",sp=1}},faq={{q="What is a galestrider?",a="A galestrider is a mount ridden by your ancestors for generations. Though slender and wispy, galestriders are steadfast and fierce.",al={"galestrider mount","riding strider","what is that strider"}},{q="Why am I choosing a strider?",a="Your training is complete, and your trainer asks you to choose a riding galestrider to accompany you on your travels.",al={"why pick a strider","first mount choice","choose my mount"}},{q="Where are the riding striders?",a="The riding striders are in Zephras, where your trainer asks you to examine them.",al={"where striders","galestriders location","striders in zephras"}},{q="Will my strider travel with me?",a="Yes. Your chosen strider will accompany you as your adventures take you far from Zephras.",al={"strider comes with me","mount travel","take strider along"}},{q="What does my trainer say about the strider I choose?",a="Your trainer says the strider seems fond of you and hopes you will care for one another.",al={"trainer choice response","strider likes me","picked strider"}}},kw={"ancestors","first mount","galestrider","mount","riding strider","training","zephras"},m={id=96996},src={"In-game quest text: Your First Riding Galestrider"},fv=true}
E["quest:97205"] = {t="quest",n="Learning to Ride",z="zephras",s="Genn Fairweather offers to teach you to ride a galestrider for a fee. Training prepares you to travel with a mount, and he provides one mount after you learn.",h="Genn Fairweather offers to teach you to ride a galestrider for a fee.",sec={{t="A Steady Hand",b="After you have enough coin, Genn Fairweather can teach you the Apprentice Riding skill. He says riding a galestrider takes patience and a steady hand. He provides a mount once you have trained, so you can set out prepared for what you and your mount may face.",sp=0}},faq={{q="Who teaches me to ride a galestrider?",a="Genn Fairweather teaches you the Apprentice Riding skill for galestriders.",al={"genn riding","galestrider trainer"}},{q="Do I need to pay for riding lessons?",a="Genn asks for a fee and says to speak with him when you have enough coin.",al={"riding cost","how much coin"}},{q="Do I get a mount after training?",a="Genn provides you with a free mount once you have trained with him.",al={"free mount","mount after riding"}},{q="Can I ride other creatures too?",a="Genn says many creatures require their own riding skill, and you will need to find trainers for each.",al={"other mounts","different riding skills"}},{q="What does riding a galestrider take?",a="Genn says riding a galestrider often takes patience and a steady hand.",al={"galestrider riding","ride patience"}}},kw={"apprentice riding","galestrider","genn fairweather","learning to ride","mount","riding trainer"},m={id=97205},src={"In-game quest text: Learning to Ride"},fv=true}
E["quest:97243"] = {t="quest",n="Call of Fire",z="zephras",s="In Skywall, initiates carry the Torch of Dormant Flame to Olariaan Swiftburn for teaching. The shrine lies in the Gustberry Lowlands.",h="In Skywall, initiates carry the Torch of Dormant Flame to Olariaan Swiftburn for teaching.",sec={{t="Voices Across the Elemental Plane",b="Skywall belongs to the air elementals, though its currents reach the wider Elemental Plane. Spirits of earth, water, and fire still speak to those who can hear them. Some Windshapers are especially open to these other forces. Olariaan Swiftburn, a shen'dorei among them, is deeply attuned to fire.",sp=0},{t="The Shrine of Flames",b="Initiates take the Torch of Dormant Flame to the Gustberry Lowlands. Far along the island rim, west of Valanaar, stands the Shrine of Flames, Olariaan Swiftburn's home. Olariaan receives the dormant flame and offers to teach aspiring students to heed fire's demanding call amid the air realm's churning currents.",sp=0}},faq={{q="Who is Olariaan Swiftburn?",a="Olariaan Swiftburn is a shen'dorei Windshaper, deeply attuned to fire. Olariaan lives at the Shrine of Flames, along the Gustberry Lowlands' edge west of Valanaar.",al={"who gives call of fire","who do i take the torch to","olariaan swiftburn"}},{q="Where is the Shrine of Flames?",a="The Shrine of Flames lies in the Gustberry Lowlands of Skywall. It sits along the edge of the floating island expanse, directly west of Valanaar.",al={"where is shrine of flames","gustberry lowlands location","how to find olariaan"}},{q="Why is fire being studied in Skywall?",a="Skywall belongs to air, yet remains part of the wider Elemental Plane. Spirits of all four elements still speak there to those attuned enough to listen.",al={"why fire in skywall","elemental plane fire","isnt skywall just air"}},{q="What is the Torch of Dormant Flame?",a="The Torch of Dormant Flame is an elemental focus carried to Olariaan Swiftburn. An initiate brings it to seek instruction in communing with fire.",al={"what is the dormant flame","torch of dormant flame","what item do i carry"}},{q="Who are the Windshapers?",a="The Windshapers practice navigating and shaping elemental forces in Skywall. Their ranks include people of varied origins, such as the shen'dorei.",al={"who are windshapers","windshaper faction"}},{q="What does this quest lead to?",a="Olariaan Swiftburn teaches disciples to heed the call of fire. Mastering primal forces in Skywall's demanding domain takes great perseverance.",al={"what does olariaan teach","fire training skywall"}}},ang={["class:Shaman"]="Heeding the elements is fundamental to shamanic training. Even in Skywall, communing with fire calls for dedicated guidance and ancestral reverence.",["race:Skyborne"]="Though native to Skywall's winds, you and the Windshapers know that balance means honoring all four primal elements."},kw={"call of fire","elemental plane","gustberry lowlands","olariaan swiftburn","shen'dorei","shrine of flames","skywall","torch of dormant flame","valanaar","windshapers"},rel={"quest:1524","topic:skywall","topic:elemental-plane"},m={faction="Horde",cl={"SHAMAN"},id=97243},src={"In-game quest text: Call of Fire"},fv=true}
E["quest:97244"] = {t="quest",n="Call of Fire",z="zephras",s="The Windshapers send you after a traitor who chose power over his order. Skypriest Faladiel has fled to the Gustberry Lowlands, and they need his heart for a ritual.",h="The Windshapers send you after a traitor who chose power over his order.",sec={{t="A Traitor Among the Flame",b="The Windshapers send you after Skypriest Faladiel, once one of their own. He left the order to join the Al'Aketh and traded his calling as a flame-caller for power. He betrayed his former brothers and sisters, and their blood stains his hands. Now the Windshapers send you to carry out their judgment.",sp=0},{t="Reckoning in the Lowlands",b="Faladiel hides at a farm in the Gustberry Lowlands, northeast past Valanaar and just south of the Shrine of Akir. The Windshapers seek more than vengeance. They need his heart for an upcoming ritual. They believe a betrayer's heart will lend their sacred flames unmatched intensity.",sp=0},{t="Blood Paid with Blood",b="The Windshapers hold to their creed: blood must answer for blood. Faladiel's heart is only one part of what must feed their ceremonial fire before their rites can be concluded.",sp=1}},faq={{q="Who is Skypriest Faladiel?",a="Skypriest Faladiel was once a devoted caller of the flame and a member of the Windshapers. He joined the Al'Aketh for power, betraying his former brothers and sisters and staining his hands with their blood.",al={"who is faladiel","faladiel backstory","skypriest faladiel lore"}},{q="Why do the Windshapers want Faladiel killed?",a="Faladiel betrayed the Windshapers for power and murdered his former brothers and sisters. Their creed calls for blood to answer for blood, so they seek his execution as retribution.",al={"why kill faladiel","why do windshapers want faladiel dead","faladiel betrayal"}},{q="Why do the Windshapers need Faladiel's heart?",a="The Windshapers need Faladiel's heart for a ritual. They believe a traitor's heart will make their flames burn hotter and with greater intensity.",al={"why faladiel heart","what is heart for","ritual reagent heart"}},{q="Where can Skypriest Faladiel be found?",a="Skypriest Faladiel hides at a farm in the Gustberry Lowlands, northeast past Valanaar and just south of the Shrine of Akir.",al={"where is faladiel","skypriest faladiel location","find faladiel"}},{q="What is the creed of the Windshapers?",a="The Windshapers' creed holds that blood must be repaid in blood. They practice flame-calling and sacred elemental rituals.",al={"who are windshapers","windshaper creed","windshapers faction"}},{q="What is the Al'Aketh's connection to this mission?",a="The Al'Aketh include members who traded former allegiances and honor for personal power. Skypriest Faladiel is one such member.",al={"what are alaketh","faladiel alaketh","alaketh traitors"}}},ang={["class:Priest"]="As a priest, you may see Faladiel's fall from grace in his turn from calling the flame to betraying and murdering members of his own order.",["class:Shaman"]="As a shaman attuned to fire and elemental rites, you may recognize the primal nature of feeding a traitor's essence to the flames to intensify their sacred power."},kw={"al'aketh","call of fire","faladiel","faladiel's heart","gustberry lowlands","shrine of akir","skypriest faladiel","valanaar","windshapers"},rel={"quest:92595"},m={faction="Horde",cl={"SHAMAN"},id=97244},src={"In-game quest text: Call of Fire"},fv=true}
E["quest:97245"] = {t="quest",n="Call of Fire",z="zephras",s="In the Shen'dar Highlands, Olariaan Swiftburn sends you to face Kuramaa, an ancient forest sprite. Flame can pierce its defenses, and its wooden mask is needed in the Gustberry Lowlands to kindle an eternal flame and commune with fire spirits.",h="In the Shen'dar Highlands, Olariaan Swiftburn sends you to face Kuramaa, an ancient forest sprite.",sec={{t="The Sprite of the Highlands",b="People in the Shen'dar Highlands speak of Kuramaa, an ancient forest sprite that dwells in a twisted tree stump. The stump stands atop a hill near the regional Anchor Pylon. Strike the bark with a bare fist, and Kuramaa comes forth to meet you in combat.",sp=0},{t="Fire and Wood",b="Kuramaa's natural wards turn aside most arcane and divine magic. Only searing flame pierces its ancient bark and brings it low. Defeat the sprite, and its wooden mask is yours, an artifact of great power. Yet Kuramaa is eternal. When called again, it reforms.",sp=0},{t="The Eternal Flame",b="In the Gustberry Lowlands, Olariaan Swiftburn awaits Kuramaa's mask. The enchanted relic is needed to kindle an eternal flame and commune with the spirits of fire. Defeating highland nature spirits opens the rite's path to ancient communion with the elements.",sp=1}},faq={{q="Who is Kuramaa?",a="Kuramaa is an ancient forest sprite dwelling in the Shen'dar Highlands. Local residents say it lives in a twisted tree stump atop a hill near the Highlands Anchor Pylon.",al={"who is kuramaa","kuramaa lore","what is kuramaa"}},{q="Who is Olariaan Swiftburn?",a="Olariaan Swiftburn is a ritualist in the Gustberry Lowlands who sends you to confront Kuramaa. Olariaan needs the sprite's wooden mask for a sacred rite of fire.",al={"who gives call of fire","who is olariaan swiftburn","where turn in call of fire"}},{q="How do you summon Kuramaa?",a="Kuramaa dwells in a twisted tree stump atop a hill near the Anchor Pylon in the Shen'dar Highlands. Strike the stump's bark with a fist, and the sprite comes out to fight.",al={"how to summon kuramaa","where is kuramaa stump","summon forest sprite"}},{q="What is Kuramaa vulnerable to in combat?",a="Kuramaa resists most forms of magic. Flame alone can pierce its defenses and bring the ancient forest sprite low.",al={"kuramaa weaknesses","how to beat kuramaa","kuramaa magic immune"}},{q="Why does Olariaan Swiftburn need Kuramaa's mask?",a="Olariaan Swiftburn needs Kuramaa's powerful wooden mask to kindle an eternal flame and commune with fire spirits.",al={"why collect kuramaa mask","what does mask do","kuramaa mask purpose"}},{q="Is Kuramaa permanently destroyed when defeated?",a="No. Kuramaa is eternal. Its spirit endures after its physical form is defeated, then manifests again when called.",al={"is kuramaa dead","did i kill kuramaa","kuramaa respawn lore"}}},ang={["class:Shaman"]="As a shaman, you face a highland spirit with flame and gather power to commune with fire spirits.",["class:Mage"]="As a mage, you find that Kuramaa resists most forms of magic. Only fire magic can overcome the sprite."},kw={"anchor pylon","call of fire","forest sprite","gustberry lowlands","kuramaa","kuramaa's mask","olariaan swiftburn","shen'dar highlands"},m={faction="Horde",cl={"SHAMAN"},id=97245},src={"In-game quest text: Call of Fire"},fv=true}
E["quest:97257"] = {t="quest",n="Call of Fire",z="zephras",s="At Skywall, initiates face the Windshapers’ trial and seek a Fire Totem. They summon spirits of flame, bear the Eternal Flame to Valanaar, and kindle its brazier.",h="At Skywall, initiates face the Windshapers’ trial and seek a Fire Totem.",sec={{t="The Ritual of Flame",b="Olariaan of the Windshapers guides initiates through a sacred trial at Skywall. They gather at the Brazier of Offering and call to spirits of flame from the Firelands. If their offerings are worthy, the spirits kindle the altar with the Eternal Flame. A worthy initiate may then take up that flame.",sp=0},{t="The Journey to Valanaar",b="The Eternal Flame must be caught on a torch and carried across Skywall to Valanaar. In this elemental realm, its power from the Firelands fades in the swirling air. The initiate must reach the Brazier of Eternal Flames before the torch goes dark.",sp=0},{t="The Fire Totem",b="When an initiate rekindles the brazier at Valanaar, the Windshapers grant them a Fire Totem. It honors their discipline and respect for the elements. The elders teach that elemental power serves those who respect it, but consumes those who do not.",sp=0}},faq={{q="What is the Call of Fire?",a="Call of Fire sends an aspiring shaman to summon spirits of flame and catch the Eternal Flame. Carrying it to Valanaar proves the initiate’s respect for the elemental plane and earns a Fire Totem.",al={"what is call of fire","call of fire quest","what is this quest about"}},{q="Who is Olariaan?",a="Olariaan leads the ceremony at the Brazier of Offering. He places materials on the altar and calls the spirits of flame to kindle the Eternal Flame.",al={"who is olariaan","olariaan role","who starts the ritual"}},{q="What is the Eternal Flame?",a="The Eternal Flame comes from spirits of flame called forth from the Firelands during the Windshaper ritual. Initiates catch it on a torch and use it to kindle the Brazier of Eternal Flames in Valanaar.",al={"what is the eternal flame","eternal flame skywall"}},{q="Why must the flame be carried quickly to Valanaar?",a="The flame comes from the Firelands, and its heat fades quickly in Skywall’s air. Initiates hurry so the torch stays lit until they reach Valanaar.",al={"why does eternal flame dissipate","why rush to valanaar","flames of firelands skywall"}},{q="Who are the Windshapers?",a="The Windshapers are an order in Skywall who guide initiates through elemental trials. They honor the balance and power of the elemental planes and oversee the granting of totems.",al={"who are the windshapers","windshaper faction"}},{q="What is the reward for completing the trial?",a="An initiate who completes the ritual and rekindles the brazier in Valanaar earns a Fire Totem, a focus for channeling fiery elemental power.",al={"call of fire reward","fire totem reward","what do you get from call of fire"}}},ang={["class:Shaman"]="As a shaman, you undergo this rite of initiation and earn a Fire Totem when you complete it. The totem grants you mastery over fire.",["race:Skyborne"]="As a Skyborne, you follow a shamanic tradition in which the Windshapers of Skywall guide initiates in honoring the elemental planes."},kw={"call of fire","eternal flame","fire totem","firelands","olariaan","skywall","valanaar","windshapers"},rel={"quest:92579","quest:92595","topic:skywall","topic:elemental-plane"},m={faction="Horde",cl={"SHAMAN"},id=97257},src={"In-game quest text: Call of Fire"},fv=true}
E["quest:97963"] = {t="quest",n="Camping 101: Alchemy",z="zephras",s="Nyassa Swiftdraught in Shen'dar Village can teach you to craft a Mana Well once you show skill in Alchemy. The well draws healers and spellcasters to a camp for refreshment.",h="Nyassa Swiftdraught in Shen'dar Village can teach you to craft a Mana Well once you show skill in Alchemy.",sec={{t="A Camp for Alchemists",b="An Alchemist can learn to make a Mana Well from Nyassa Swiftdraught in Shen'dar Village, once you have shown proficiency in your skill. Healers and spellcasters are drawn to its refreshing drink. To try it at camp, you need a campfire first; a cook can teach you how to make one.",sp=0}},faq={{q="What can Nyassa teach me?",a="Nyassa Swiftdraught in Shen'dar Village can teach you to craft a Mana Well once you have shown proficiency in Alchemy.",al={"nyassa alchemy","mana well trainer","camping alchemy"}},{q="What does a Mana Well do?",a="A Mana Well draws healers and spellcasters to your camp for a refreshing drink.",al={"mana well use","what's mana well for","mana well"}},{q="Where do I learn to make a Mana Well?",a="Nyassa Swiftdraught teaches the recipe in Shen'dar Village.",al={"where nyassa","shen'dar village alchemy","mana well location"}},{q="What do I need before setting up camp?",a="You need a campfire to start your camp. A cook can teach you to make one.",al={"campfire needed","how start camp","camping alchemy requirements"}}},ang={["profession:Cooking"]="A cook can teach you to make the campfire needed to start your camp."},kw={"alchemy","campfire","camping","healers","mana well","nyassa swiftdraught","shen'dar village","spellcasters"},m={id=97963},src={"In-game quest text: Camping 101: Alchemy"},fv=true}
E["quest:97964"] = {t="quest",n="Camping 101: Blacksmithing",z="zephras",s="As a Blacksmith, you can learn to craft a Sharpening Wheel for use at your camp. Aedi Thriceforged in Shen'dar Village can teach you once you have shown proficiency.",h="As a Blacksmith, you can learn to craft a Sharpening Wheel for use at your camp.",sec={{t="Aedi's Lesson",b="A Sharpening Wheel lets warriors and rogues nearby hone their weapons at your camp. In Shen'dar Village, Aedi Thriceforged can teach you its craft once you have shown proficiency in Blacksmithing.",sp=0}},faq={{q="Who teaches me to make a Sharpening Wheel?",a="Aedi Thriceforged in Shen'dar Village can teach you to craft a Sharpening Wheel once you have shown proficiency in Blacksmithing.",al={"sharpening wheel teacher","who is aedi","aedi blacksmithing"}},{q="What does a Sharpening Wheel do?",a="At your camp, a Sharpening Wheel lets nearby warriors and rogues hone their weapons.",al={"sharpening wheel use","hone weapons","camp sharpening thing"}},{q="Where do I find Aedi Thriceforged?",a="Aedi Thriceforged is in Shen'dar Village.",al={"aedi location","where is aedi","aedi shendar"}}},ang={["profession:Blacksmithing"]="As a Blacksmith, you can learn to craft a Sharpening Wheel for use at your camp.",["class:Warrior"]="As a warrior nearby, you can hone your weapon at a Sharpening Wheel set up at a camp.",["class:Rogue"]="As a rogue nearby, you can hone your weapon at a Sharpening Wheel set up at a camp."},kw={"aedi thriceforged","blacksmithing","camping 101","rogue","sharpening wheel","shen'dar village","warrior"},rel={"topic:warrior","topic:rogue"},m={id=97964},src={"In-game quest text: Camping 101: Blacksmithing"},fv=true}
E["quest:97965"] = {t="quest",n="Camping 101: First Aid",z="zephras",s="At Shen'dar Village, you seek care for injuries far from civilization. Naleeia Tattermend teaches skilled practitioners to prepare medical kits for a wilderness camp.",h="At Shen'dar Village, you seek care for injuries far from civilization.",sec={{t="Healing in the Wilderness",b="A journey across Azeroth can bring violence, wild beasts, and hazards of the land. First Aid lets you bind cuts and broken bones without relying only on spellcraft. A First Aid Kit at a wilderness camp gives you a place to tend injuries and help companions recover. Then you can prepare to travel on.",sp=0},{t="The Mentor of Shen'dar Village",b="In Shen'dar Village, Naleeia Tattermend teaches practitioners to make durable medical supplies for a campsite. She shares her techniques after you show that you know basic medical care.",sp=0}},faq={{q="Who do I need to speak with for this quest?",a="Speak with Naleeia Tattermend in Shen'dar Village. She knows how to craft medical supplies for wilderness camps.",al={"who to talk to camping first aid","where is naleeia tattermend","camping 101 first aid turn in"}},{q="Where is Shen'dar Village located?",a="Shen'dar Village is on Zephras Isle, where Naleeia Tattermend lives. Practitioners travel there for further wilderness first aid training after honing their skills.",al={"where is shendar village","shen'dar village location","shendar village first aid"}},{q="What is the purpose of crafting a First Aid Kit for camp?",a="You learn to make a First Aid Kit for an adventurer's campsite. Supplies ready at camp let you treat injuries between journeys. They may mean the difference between life and death.",al={"what does camping first aid do","first aid kit camp","why craft first aid kit"}},{q="When will Naleeia Tattermend teach me to craft the kit?",a="Naleeia Tattermend teaches you after you show enough skill in First Aid. Practice bandaging and treatment before making field kits.",al={"when can i learn the first aid kit","naleeia tattermend requirement","camping 101 first aid requirement"}},{q="Why is First Aid considered both honorable and pragmatic?",a="Wounds and physical trauma threaten travelers across Azeroth. Bandages and medical care let travelers of every discipline tend their own wounds and stabilize companions without relying only on magic.",al={"why is first aid important","first aid lore","is first aid useful"}},{q="Can any adventurer craft a camping First Aid Kit?",a="Any adventurer who studies First Aid and proves their skill can learn from Naleeia Tattermend in Shen'dar Village to make a First Aid Kit for camp.",al={"can anyone learn this kit","who can make first aid kit camp"}}},kw={"bandages","camping","camping 101: first aid","first aid","first aid kit","naleeia tattermend","shen'dar village","wilderness survival"},m={id=97965},src={"In-game quest text: Camping 101: First Aid"},fv=true}
E["quest:97967"] = {t="quest",n="Camping 101: Fishing",z="zephras",s="You are learning how fishing can make wilderness camps more welcoming. In Shen'dar Village, skilled anglers can ask Fenn Fairweather to teach them the Fish Bowl craft.",h="You are learning how fishing can make wilderness camps more welcoming.",sec={{t="Comforts of the Hearth",b="A camp in the wild needs comfort along with sharp blades and sturdy armor. Good spirits help companions bear the strain of life in the field. Fishing brings provisions, and skilled anglers can put their craft to work improving a campsite. With live fish and a proper fixture, a traveler can make camp more welcoming.",sp=0},{t="The Artisan of Shen'dar",b="In Shen'dar Village, Fenn Fairweather shares fishing secrets with seasoned anglers who know the patience of rod and reel. Anglers with enough skill can learn to make a Fish Bowl, a simple fixture that brings cheer and rest to weary companions. Good spirits in the wild help a group stay focused and resolute when danger draws near.",sp=0}},faq={{q="Who teaches the Fish Bowl camping craft?",a="Fenn Fairweather teaches the Fish Bowl craft in Shen'dar Village. Show enough skill in fishing, and Fenn can teach you to make one for camp.",al={"who gives fish bowl","where is fenn fairweather","fish bowl trainer"}},{q="What purpose does a Fish Bowl serve at camp?",a="A Fish Bowl is a decorative fixture that brings comfort and cheer to you and your companions at camp. A well-kept camp and high spirits help you stay sharp and ready for danger in the field.",al={"what does fish bowl do","fish bowl buff","camping fish bowl effect"}},{q="Where is Shen'dar Village?",a="Shen'dar Village is a gathering place for tradesfolk and instructors, including Fenn Fairweather. Anglers go there to learn practical camping crafts suited to their skills.",al={"where is shendar village","shen'dar village location"}},{q="What skill is required to learn this camping craft?",a="You need to show basic skill as an angler before learning this craft. Once your fishing is well honed, instructors in Shen'dar Village can teach you to make camp fixtures such as the Fish Bowl.",al={"camping fishing requirements","when can i learn fish bowl","how to start camping fishing"}},{q="Why does fishing matter for wilderness camping?",a="Fishing brings in food, and an angler's patience and keen eye can also improve camp life. A fresh catch displayed in a crafted bowl offers calm and lifts spirits during long wilderness journeys.",al={"why fishing for camping","fishing usefulness in camp"}},{q="Who is Fenn Fairweather?",a="Fenn Fairweather is an artisan and instructor in Shen'dar Village. Fenn knows the practical comforts of wilderness life and shares camp fixture craft with skilled anglers.",al={"who is fenn fairweather","fenn fairweather lore"}}},kw={"camping","camping 101: fishing","fenn fairweather","fish bowl","fishing","shen'dar village"},m={id=97967},src={"In-game quest text: Camping 101: Fishing"},fv=true}
E["quest:97968"] = {t="quest",n="Camping 101: Herbalism",z="zephras",s="At camps along the trail, Camping 101: Herbalism points gatherers toward instructors who teach them to make Incense Candles. Herbalists use gathered plants to bring comfort to spellcasters and healers on long journeys.",h="At camps along the trail, Camping 101: Herbalism points gatherers toward instructors who teach them to make...",sec={{t="Wild Flora on the Trail",b="Travelers can put roots and petals to use beyond selling fresh stems or brewing draughts. Gatherers meet instructors who teach them to make Incense Candles from wild aromatic plants. These candles support companions on the trail.",sp=0},{t="Soothing the Mind",b="Long journeys through hostile country wear down healers and spellcasters. At an active campsite, an Incense Candle gives off a soothing, revitalizing scent that lifts their spirits and helps them recover clarity and strength before danger calls again. Those who wield magic or tend the wounded value that comfort most.",sp=0}},faq={{q="What is Camping 101: Herbalism?",a="Camping 101: Herbalism connects skilled herb gatherers with instructors who teach them to make Incense Candles for wilderness camps.",al={"what is camping 101 herbalism","camping 101 herbalism quest","herbalism camping quest"}},{q="What is an Incense Candle used for?",a="An Incense Candle is made from gathered plants and burned at a campsite. Its soothing, revitalizing scent lifts resting companions’ spirits and gives healers and spellcasters a beneficial boost.",al={"what does incense candle do","incense candle camp effect","why make incense candle"}},{q="Who teaches how to make an Incense Candle?",a="Your instructor depends on where you begin: Reyna Stonebranch in Ironforge, Malorne Bladeleaf in Dolanaar, Herbalist Pomeroy in Elwynn Forest, Jandi in Orgrimmar, Faruza in Brill, Komin Winterhoof in Thunder Bluff, or in Shen'dar Village on Zephras Isle.",al={"who teaches incense candle","incense candle trainer","where to learn incense candle"}},{q="Why are Incense Candles especially useful for magic users?",a="Casting spells and tending wounds drain physical energy and mental focus. The soothing smoke of an Incense Candle helps replenish both, keeping spirits high and casters ready for battle.",al={"why do spellcasters need incense","incense candle healers","incense candle magic users"}},{q="Do you need to be an herbalist to take this quest?",a="This instruction is for those skilled in gathering plants and herbs. It teaches how to find and use aromatic wild plants.",al={"can anyone learn incense candle","do i need herbalism for camping 101 herbalism","herbalism requirement camping candle"}},{q="How does Herbalism tie into camping?",a="Gathered plants have uses around camp beyond brewing concoctions and salves. They can be made into incense that refreshes weary companions.",al={"is herbalism just for potions","uses for herbs camping","herbalism camp items"}}},ang={["profession:Herbalism"]="Gathering plants in the wilderness provides the aromatic herbs needed for camp incense. That makes the work useful for survival as well as alchemy.",["class:Priest"]="Incense Candles lit at camp lift the spirits and replenish the mental reserves of holy healers between skirmishes.",["class:Mage"]="Spellcasters who spend their focus in battle value camp incense, whose soothing scent helps restore their minds and support arcane recovery."},kw={"camp","camping","camping 101: herbalism","healers","herbalism","herbs","incense candle","spellcasters"},m={id=97968},src={"In-game quest text: Camping 101: Herbalism"},fv=true}
E["quest:97969"] = {t="quest",n="Camping 101: Leatherworking",z="zephras",s="A leatherworker’s travels lead to lessons in making a shelter for the wilds. In Shen'dar Village, Indari Sunseam teaches skilled craftsmen to stitch tents that protect travelers and give them rest on long journeys.",h="A leatherworker’s travels lead to lessons in making a shelter for the wilds.",sec={{t="Shelter on the Road",b="Traveling leatherworkers need sturdy gear made from hide and pelt. Once they learn the craft, they are sent to Indari Sunseam in Shen'dar Village. There, she teaches them to make a proper camping tent. It keeps travelers dry in heavy rain and cool beneath a blazing sun, helping them rest on long journeys.",sp=0},{t="Wilderness Campsites",b="Townsfolk object when rough camps clutter their streets, so you pitch your tent in the wild. A campsite needs more than shelter; it also needs a warming campfire. Visit a local cook to learn basic firemaking before you set out.",sp=0}},faq={{q="Who teaches leatherworkers how to craft a tent?",a="Indari Sunseam in Shen'dar Village teaches skilled leatherworkers to make camping tents.",al={"who teaches leatherworking tents","camp tent trainer","where is indari sunseam"}},{q="What is the purpose of crafting a tent?",a="A well-made tent shields travelers from heavy rain and blazing heat, helping them rest and stay alert on the road.",al={"what does a tent do","tent purpose","tent benefits"}},{q="Where can a camping tent be pitched?",a="You pitch a tent in the wilderness, away from town centers where locals object to camps.",al={"can i pitch tent in city","where to use tent","camp rules"}},{q="What else is needed to pitch a proper camp?",a="A proper camp also needs a campfire. A cooking trainer can teach you to build a basic fire.",al={"do i need a fire","camp requirements","what else for camp"}},{q="When does Indari Sunseam teach you the tent pattern?",a="Indari Sunseam teaches the tent pattern after you have practiced leatherworking and shown proficiency in the trade.",al={"when can i learn tent","tent requirements","leatherworking tent req"}},{q="What is Shen'dar Village?",a="Shen'dar Village is where Indari Sunseam lives and works, teaching travelers to craft camping supplies.",al={"where is shen'dar village","shendar village location","indari sunseam town"}}},ang={["profession:Cooking"]="A tent alone does not make a complete camp. You also need to learn basic campfire craft, usually from a cooking trainer."},kw={"camp tent","campfire","camping","cooking","indari sunseam","leatherworking","shen'dar village","tent","wilderness"},m={id=97969},src={"In-game quest text: Camping 101: Leatherworking"},fv=true}
E["quest:97970"] = {t="quest",n="Camping 101: Mining",z="zephras",s="A mining instructor in Shen'dar Village can teach you to craft a Lodestone for your camp. It gives those gathered around the fire extra strength in combat.",h="A mining instructor in Shen'dar Village can teach you to craft a Lodestone for your camp.",sec={{t="A Miner's Craft",b="Mining offers honest work, and you can learn a camp craft through Messana Crestwind in Shen'dar Village. Once you have shown proficiency in mining, she can teach you to make a Lodestone. Those who gather around your fire can draw extra strength from it, so the craft may bring sword-wielders to your camp.",sp=0},{t="A Place to Camp",b="With the craft learned, you can make your own Lodestone. Camps are unwelcome in the center of town, so take it into the wilderness to test it. A campfire is needed before you set up camp, and a cook can teach you how to make one.",sp=0}},faq={{q="Who teaches me to make a Lodestone?",a="Messana Crestwind in Shen'dar Village can teach you to craft a Lodestone after you show proficiency in mining.",al={"lodestone trainer","who teaches mining camp craft"}},{q="What does a Lodestone do?",a="It gives those gathered around your campfire extra strength in combat.",al={"lodestone use","what's lodestone for"}},{q="Where can I test my Lodestone?",a="You can test it in the wilderness; camps are unwelcome in the center of town.",al={"where test lodestone","lodestone camp"}},{q="Do I need a campfire?",a="Yes. You need a campfire before setting up camp, and a cook can teach you to make one.",al={"campfire needed","how start camp"}},{q="What do I need before Messana teaches me?",a="You need to show proficiency in mining before Messana Crestwind can teach you to craft a Lodestone.",al={"mining proficiency","how learn lodestone"}}},ang={["profession:Mining"]="As a miner, you can show your proficiency to Messana Crestwind and learn to craft a Lodestone for your camp.",["profession:Cooking"]="As a cook, you can teach others to make the campfire needed to set up camp."},kw={"camp","campfire","camping 101","lodestone","messana crestwind","mining","shen'dar village"},m={id=97970},src={"In-game quest text: Camping 101: Mining"},fv=true}
E["quest:97971"] = {t="quest",n="Camping 101: Skinning",z="zephras",s="In Shen'dar Village, Mendalass Tattermend shows skinners how to prepare for rest in the wilds. The lesson joins skinning with survival and a place to sit at camp.",h="In Shen'dar Village, Mendalass Tattermend shows skinners how to prepare for rest in the wilds.",sec={{t="Comfort in the Wilds",b="You can shape hides from fallen beasts into more than armor. Mendalass Tattermend shows you how to make a portable Camp Chair, so you can rest in the wilds and regain your strength before battle.",sp=0},{t="The Teachings of Shen'dar Village",b="In Shen'dar Village, Mendalass Tattermend teaches proven skinners to make sturdy seats from collected pelts. Towns forbid camps within their limits. A campsite also needs a campfire, a skill local culinary instructors have traditionally taught.",sp=0}},faq={{q="What is Camping 101: Skinning about?",a="In Shen'dar Village, Mendalass Tattermend teaches skinners to make a Camp Chair from harvested hides. It gives you a place to rest while camping in the wilds.",al={"what is this quest","camping 101 purpose","why do this quest"}},{q="Who is Mendalass Tattermend?",a="Mendalass Tattermend is a skinning trainer in Shen'dar Village. The trainer teaches proficient skinners to make field seating from harvested hides.",al={"who is mendalass","who teaches camp chair","mendalass tattermend"}},{q="Where can Mendalass Tattermend be found?",a="Mendalass Tattermend is in Shen'dar Village, where skinners can show their skill and learn to make camp gear.",al={"where is mendalass","where is shendar village","where do i turn this in"}},{q="What item does this quest teach you to make?",a="Skinners learn to make a Camp Chair from hides gathered from fallen beasts. It gives you a place to rest in the wilds.",al={"what do skinners make","camp chair recipe","what item do i get"}},{q="Can you set up camp inside a town?",a="No. Towns forbid camps within their limits, so camps and chairs belong in the wilderness.",al={"can i camp in town","where can i pitch camp","where to use camp chair"}},{q="What else is required to make a proper camp?",a="A proper campsite needs a campfire. Culinary trainers traditionally teach the basics of starting one.",al={"what else do i need for camp","campfire needed","camp requirements"}}},ang={["profession:Cooking"]="Cooking and wilderness survival go hand in hand. A campsite needs a campfire, a skill culinary trainers traditionally teach."},kw={"camp chair","campfire","camping 101","hides","mendalass tattermend","shen'dar village","skinning","wilderness"},m={id=97971},src={"In-game quest text: Camping 101: Skinning"},fv=true}
E["quest:97973"] = {t="quest",n="Camping 101: Tailoring",z="zephras",s="At Shen'dar Village, tailors can learn to make a Faction Banner for wilderness camps. The banner lifts spirits and helps sustain morale.",h="At Shen'dar Village, tailors can learn to make a Faction Banner for wilderness camps.",sec={{t="The Weaver's Contribution to Camp",b="A campsite in the wild calls for more than warm clothes. A well-made banner can give a camp a shared purpose, so clothworkers are urged to carry their craft beyond garments and bags. With further instruction, bolts of woven fabric become a sign of unity and fortitude.",sp=0},{t="Instruction in Shen'dar Village",b="In Shen'dar Village, Taleen Shimmerthread teaches camping crafts to tailors with enough skill. She shows them how to fashion a Faction Banner. Stitched with care and planted at camp, it rallies allies and helps keep their spirits up through the trials ahead.",sp=0}},faq={{q="What is Camping 101: Tailoring?",a="At Shen'dar Village, promising tailors can seek instruction in field craft. Show enough skill in tailoring and you can learn to make a Faction Banner for a wilderness campsite.",al={"what is this quest","camping 101 tailoring quest","tailoring camping banner"}},{q="Who is Taleen Shimmerthread?",a="Taleen Shimmerthread is a skilled tailor in Shen'dar Village. She teaches qualified crafters to make camping items, including banners that lift spirits at camp.",al={"taleen shimmerthread","who teaches tailoring banner","where is taleen shimmerthread"}},{q="Where is Shen'dar Village?",a="Shen'dar Village is where Taleen Shimmerthread lives. Tailors go there to learn how to use their cloth-working craft to make camping gear.",al={"where is shendar village","shendar village location"}},{q="What camping item can tailors learn to craft?",a="Tailors can learn to make a Faction Banner for camp. Planting one gives those resting there an inspiring presence.",al={"faction banner camping","what does tailoring make for camp","tailoring camp item"}},{q="What are the requirements to learn the camping banner?",a="You need to show skill in tailoring before Taleen Shimmerthread in Shen'dar Village will teach you to make a Faction Banner for camp.",al={"how to learn faction banner","tailoring requirements camping banner"}},{q="Why are faction banners valuable at camp?",a="Faction banners lift spirits and sustain morale on a campaign. Tailors stitch them as an energizing focal point for adventurers on grueling journeys.",al={"why make a faction banner","camping banner morale"}}},ang={["profession:Tailoring"]="As a tailor, you can make Faction Banners that lift camp morale and energize allies in the field."},kw={"camp banner","camping","camping 101: tailoring","faction banner","shen'dar village","tailoring","taleen shimmerthread","tradeskill"},m={faction="Alliance",id=97973},src={"In-game quest text: Camping 101: Tailoring"},fv=true}
E["quest:98284"] = {t="quest",n="Camping 101: Enchanting",z="zephras",s="Nasalanna Windsinger in Shen'dar Village can teach you to craft a camping item for your profession. Enchanters can learn to make an Enchanted Lute for entertainment on the trail.",h="Nasalanna Windsinger in Shen'dar Village can teach you to craft a camping item for your profession.",sec={{t="A Lute for Camp",b="An enchanter can improve a camp in the wilds, and you are directed to Nasalanna Windsinger in Shen'dar Village. Once you have shown proficiency in your skill, Nasalanna can teach you to craft an Enchanted Lute. The enchanted instrument offers entertainment during downtime before you return to the trail.",sp=0}},faq={{q="Who teaches me to make an Enchanted Lute?",a="Nasalanna Windsinger in Shen'dar Village can teach you to craft an Enchanted Lute once you have shown proficiency in your skill.",al={"enchanted lute trainer","who teaches lute","Nasalanna camping"}},{q="What is the Enchanted Lute for?",a="The Enchanted Lute provides entertainment during downtime at a camp.",al={"lute use","camping lute","why enchanted lute"}},{q="Why are enchanters welcome at camps?",a="Enchanters can make things better at camps in the wilds, including an Enchanted Lute for entertainment.",al={"enchanter camping","why enchanters welcome","camping enchanting"}},{q="When can I learn the camping craft?",a="You can learn from Nasalanna Windsinger after you have shown proficiency in your skill.",al={"learn lute when","skill proficiency","camping craft requirement"}}},ang={["profession:Tailoring"]="As an enchanter, you can learn to craft an Enchanted Lute for entertainment at camp."},kw={"camping 101","camping item","enchanted lute","enchanter","enchanting","nasalanna windsinger","shen'dar village"},m={id=98284},src={"In-game quest text: Camping 101: Enchanting"},fv=true}
E["quest:98285"] = {t="quest",n="Camping 101: Engineering",z="zephras",s="The Strange Hermit in Shadowgale Forest teaches you to craft a camping item after you show skill as an engineer. The Reagent Bot is meant for use in a wilderness camp.",h="The Strange Hermit in Shadowgale Forest teaches you to craft a camping item after you show skill as an...",sec={{t="A Wilderness Camp",b="The Strange Hermit in Shadowgale Forest asks you to show proficiency in engineering before teaching you a camping craft. Engineers can put their trade to use while alone in the wilds, where helpful constructs can make a camp complete.",sp=0},{t="Setting Up Camp",b="The Strange Hermit teaches you to craft a Reagent Bot. To start a camp, you also need a campfire, which most cooks can teach you to make. The Hermit warns that townsfolk do not care for camps set up in the middle of town.",sp=1}},faq={{q="Who teaches me the camping craft?",a="The Strange Hermit in Shadowgale Forest teaches you the camping craft after you show proficiency in engineering.",al={"who is the hermit","camping teacher","where learn camping engineering"}},{q="What does engineering have to do with camping?",a="The Hermit says engineers can use their trade in the wilds and craft helpful constructs for a camp.",al={"engineering camp item","why engineer camping","camping 101 eng"}},{q="What can I craft?",a="The Hermit teaches you to craft a Reagent Bot.",al={"what is the camping item","reagent bot","camp item engineering"}},{q="Do I need anything else for a camp?",a="You need a campfire to start your camp. Most cooks can teach you to make one.",al={"need campfire","how start camp","camping fire"}},{q="Where should I set up camp?",a="The Hermit says townsfolk do not care for camps set up in the center of town, so head into the wilderness to test your camp.",al={"camp location","where test reagent bot","can i camp in town"}}},ang={["profession:Engineering"]="As an engineer, you can learn to craft a Reagent Bot for a wilderness camp after showing the Strange Hermit your proficiency.",["profession:Cooking"]="As a cook, you can teach others to make the campfire needed to start a camp."},kw={"campfire","camping 101","cooking","engineering","reagent bot","shadowgale forest","strange hermit","wilderness camp"},rel={"quest:93159"},m={id=98285},src={"In-game quest text: Camping 101: Engineering"},fv=true}
E["quest:98286"] = {t="quest",n="Camping 101: Enchanting",z="zephras",s="At Shen'dar Village, skilled enchanters can learn to make an Enchanted Lute for the campfire. Nasalanna Windsinger teaches them how it entertains and bolsters companions.",h="At Shen'dar Village, skilled enchanters can learn to make an Enchanted Lute for the campfire.",sec={{t="Comforts of the Hearth",b="On the open road, sharpened blades and rations are not enough. Travelers need rest and good spirits to endure long expeditions. Enchanters bring magical comforts to camps across Azeroth, helping weary travelers recover their strength and spirits before they return to perilous trails.",sp=0},{t="The Song of Shen'dar",b="Aspiring enchanters seeking to learn campsite magic travel to Shen'dar Village. There, Nasalanna Windsinger teaches capable spell-weavers to make an Enchanted Lute. First, they must prove their dedication and skill in enchanting. Then Nasalanna shares how to fashion an instrument whose melodies restore spirits beneath the stars.",sp=0}},faq={{q="Who is Nasalanna Windsinger?",a="Nasalanna Windsinger lives in Shen'dar Village and teaches skilled enchanters to craft special items for wilderness camps. She teaches those who prove their skill to make the Enchanted Lute.",al={"who teaches enchanted lute","who is nasalanna windsinger","where is nasalanna windsinger"}},{q="Where is Shen'dar Village?",a="Shen'dar Village is where Nasalanna Windsinger lives. Enchanters travel there for instruction in making campsite gear like the Enchanted Lute once they have developed their core skills.",al={"where is shendar village","how to find shendar village"}},{q="What is an Enchanted Lute?",a="Enchanters make the Enchanted Lute as a magical instrument for camps. It entertains companions around the campfire and restores their morale, helping travelers steel themselves for the wilderness ahead.",al={"what does enchanted lute do","why craft enchanted lute","camping lute"}},{q="What are the requirements to learn the recipe?",a="To learn how to make an Enchanted Lute, you must first prove your skill in enchanting to Nasalanna Windsinger. She trusts seasoned practitioners with this camp enchantment.",al={"requirements for camping 101 enchanting","when can i learn enchanted lute"}},{q="Why are enchanters valuable at wilderness campsites?",a="At wilderness camps, enchanters bring magical comforts when ordinary supplies fall short. Their enchantments help travelers recover, stay entertained, and prepare for hazards on the trail.",al={"why do campers want enchanters","enchanters camping benefits"}},{q="Can other professions craft camping items?",a="Yes. Craftsmen and gatherers in different disciplines learn to make tools for campsites. Enchanters learn to make the Enchanted Lute from Nasalanna Windsinger in Shen'dar Village.",al={"are there other camping items","other profession camp crafts"}}},kw={"campfire","camping","camping 101","enchanted lute","enchanting","lute","nasalanna windsinger","shen'dar village"},m={faction="Alliance",id=98286},src={"In-game quest text: Camping 101: Enchanting"},fv=true}
E["quest:98512"] = {t="quest",n="Al'Aketh Assassins",z="zephras",s="A scout asks you to end the Al'Aketh Assassins' deadly threat. Your survival and aid will be recorded for Valanaar.",h="A scout asks you to end the Al'Aketh Assassins' deadly threat.",sec={{t="A Deadly Threat",b="Scouts in the field call the Al'Aketh assassins stone-cold killers. They move together with ruthless purpose, putting nearby scouts and travelers in grave danger. You face a perilous fight before they can strike their targets.",sp=0},{t="Reporting to Valanaar",b="After the Al'Aketh force is defeated, the scout is relieved to find you alive. Your timely aid will go into an official report for Valanaar.",sp=0}},faq={{q="What is Al'Aketh Assassins?",a="You are asked to eliminate a lethal force of Al'Aketh operatives. A scout will record your aid in a report for Valanaar.",al={"what is alaketh assassins","what is this quest","alaketh assassins quest"}},{q="Who are the Al'Aketh assassins?",a="Scouts call the Al'Aketh assassins stone-cold killers. They work together as a dangerous strike force.",al={"who are alaketh","who are the alaketh assassins","alaketh killers"}},{q="Who is Valanaar?",a="Valanaar is a settlement at the island's southeastern edge and a base for its peacekeepers. The scout plans to report your aid there.",al={"who is valanaar","what is valanaar","reporting to valanaar"}},{q="Why must the Al'Aketh assassins be dealt with?",a="The Al'Aketh assassins threaten scouts and travelers in the area. Defeating them protects allied forces from their lethal attacks.",al={"why fight alaketh","why kill alaketh assassins","alaketh threat"}},{q="What happens after dealing with the assassins?",a="After the fight, the scout prepares to report to Valanaar and record your aid.",al={"what happens after alaketh assassins","next quest alaketh","report to valanaar quest"}},{q="Who acknowledges your aid in defeating the assassins?",a="A scout in the field acknowledges your help against the Al'Aketh assassins and notes your contribution for command.",al={"who gives alaketh assassins","who is the scout","scout report valanaar"}}},ang={["class:Rogue"]="As a Rogue, you know the focus and precision it takes to face lethal killers like the Al'Aketh."},kw={"al'aketh","assassins","killers","quest","report","valanaar"},rel={"quest:92880","quest:92579"},m={id=98512},src={"In-game quest text: Al'Aketh Assassins"},fv=true}
E["quest:99260"] = {t="quest",n="Fillion's Mission",z="zephras",s="Fillion lies wounded after his survey at the Overlook Standing Stones. The readings meant to guide skycutters between Skywall and Azeroth are presumed lost.",h="Fillion lies wounded after his survey at the Overlook Standing Stones.",sec={{t="A Perilous Assignment",b="Fillion went to the Overlook Standing Stones to measure elemental currents. Those readings are needed to calculate safe courses for skycutter vessels between Skywall and Azeroth. After an ordeal that required his rescue, he is too wounded to finish the work. The vital data is presumed lost, so he sends his rescuer to report to the Supreme Magister.",sp=0},{t="Planar Strife in Valanaar",b="In Valanaar, Supreme Magister Elaadrin Evengale is relieved to hear that Fillion survived, though the research is lost. Without reliable readings, safe routes across the Elemental Plane will be hard to open. Reports say the rival Windshapers have found their own way through the planes. They refuse to share it, putting factional secrecy before the welfare of all.",sp=1}},faq={{q="Who is Fillion?",a="Fillion is an emissary or scout sent by the Supreme Magister to measure elemental currents at the Overlook Standing Stones. After an adventurer rescues him, he is too weak to finish the work.",al={"who is fillion","fillion backstory","fillion wow"}},{q="Who is Supreme Magister Elaadrin Evengale?",a="Elaadrin Evengale is the Supreme Magister in Valanaar. He directs efforts to navigate the elemental plane safely and recover planar data for travel between Skywall and Azeroth.",al={"who is supreme magister","elaadrin evengale","who is elaadrin"}},{q="Why was Fillion's data so important?",a="The readings track elemental currents at the Overlook Standing Stones. They are needed to calculate safe courses for skycutters through the elemental plane to Azeroth.",al={"why is data important","what data fillion lost","elemental data skywall"}},{q="Who are the Windshapers?",a="The Windshapers are a faction reported to have found their own way through the planes. Supreme Magister Evengale says they guard it out of dogmatic hubris instead of sharing it for the wider good of their people.",al={"who are windshapers","windshapers lore","windshaper rivals"}},{q="What are skycutters?",a="Skycutters are vessels made to fly through the elemental planes. They need precise readings of elemental currents to travel between Skywall and Azeroth safely.",al={"what are skycutters","skycutter ship","sky cutter"}},{q="Who are the Al'Aketh?",a="The Al'Aketh are a faction Supreme Magister Evengale regards with disdain. He compares the Windshapers' selfish, dogmatic conduct to theirs.",al={"who are alaketh","al'aketh","alaketh lore"}}},ang={["class:Mage"]="As a Mage, you can appreciate the delicate magical calculations needed to guide skycutter vessels through planar turbulence.",["race:Skyborne"]="As one of the Skyborne, you know the struggle to establish safe routes between Skywall and Azeroth amid factional discord."},kw={"elaadrin evengale","elemental plane","fillion","overlook standing stones","skycutter","skywall","valanaar","windshapers"},rel={"quest:92699","topic:skywall","topic:elemental-plane","quest:92595"},m={faction="Alliance",id=99260},src={"In-game quest text: Fillion's Mission"},fv=true}
E["subzone:calmbreeze-inn"] = {t="subzone",n="Calmbreeze Inn",z="zephras",s="In Shen'dar Village and Valaanar, Calmbreeze Inns offer travelers rest on Zephras Isle. Both provide shelter and local services.",h="In Shen'dar Village and Valaanar, Calmbreeze Inns offer travelers rest on Zephras Isle.",sec={{t="Rest on the Isle",b="Travelers can rest at the Calmbreeze Inns on Zephras Isle. Coriella Calmbreeze runs the inn in Shen'dar Village, where island tradesfolk gather. There, you can find mentors in herbalism, skinning, and enchanting.\n\nAcross the way, the Valaanar inn welcomes local wayfarers and shelters rare curios. Upstairs, an audio crystal holds a recording of the ancient rebellion in Eldre'Thalas.",sp=0}},faq={{q="Where are the Calmbreeze Inns located?",a="Calmbreeze Inns are found in Shen'dar Village and Valaanar on Zephras Isle.",al={"calmbreeze inn location","where is calmbreeze inn","calmbreeze inn map"},it="place",gp=true},{q="Who runs the inn in Shen'dar Village?",a="Innkeeper Coriella Calmbreeze runs the Shen'dar Village inn and welcomes island residents and travelers.",al={"calmbreeze innkeeper","who runs calmbreeze inn"},it="residents"},{q="What trainers can be found at the inn?",a="At the Shen'dar Village inn, Halassa Fernbreeze teaches Herbalism, Mendalass Tattermend teaches Skinning, Nasalanna Windsinger teaches Enchanting, and Miriann Mistblade teaches Rogue training.",al={"calmbreeze trainers","shen'dar inn trainers"},gp=true},{q="What is the audio crystal found upstairs in Valaanar?",a="Upstairs in the Valaanar inn, an audio crystal holds Part 3 of 'The Rebellion In Eldre'Thalas', recounting events from the ancient Highborne city.",al={"valaanar audio crystal","the rebellion in eldre'thalas crystal"},it="item"},{q="What is the Calmbreeze Inn?",a="The Calmbreeze Inn refers to the network of inns serving travelers across Zephras Isle, with locations established in both Valaanar and Shen'dar Village. These establishments serve as vital community hubs, providing weary travelers with a place to rest, meet local tradesfolk and trainers, and gather news from across the island.",al={"what is calmbreeze inn","calmbreeze inn lore","about calmbreeze inn"},it="place",add="043ce63b"},{q="Is the Calmbreeze Inn dangerous?",a="No. The Calmbreeze Inns are peaceful sanctuaries within their respective settlements of Shen'dar Village and Valaanar. They are filled with friendly citizens, innkeepers, and craft trainers rather than hostile threats.",al={"is calmbreeze inn safe","calmbreeze inn dangers","danger at calmbreeze inn"},it="danger",add="c8344be2"}},ang={["profession:Herbalism"]="As an herbalist in Shen'dar Village, you can find Halassa Fernbreeze inside the Calmbreeze Inn and hone your gathering craft.",["class:Rogue"]="As a rogue in Shen'dar Village, you can seek instruction from Miriann Mistblade at the Calmbreeze Inn hearth."},kw={"calmbreeze inn","coriella calmbreeze","eldre'thalas","shen'dar village","valaanar","zephras isle"},rel={"zone:zephras"},src={"Calmbreeze Inn"},nf=true}
E["zone:zephras"] = {t="zone",n="Zephras Isle",z="zephras",s="On Zephras Isle, the Skyborne face a homeland slowly coming apart. Air elementals once shared the island with them, but those guardians vanished and the magic that holds the land aloft is fading. Refugees arrive from Anvilas and Siroccas as those islands crumble.",h="On Zephras Isle, the Skyborne face a homeland slowly coming apart.",sec={{t="A Realm Aloft",b="In skywall, the elemental plane of air, the Skyborne have lived on Zephras Isle for generations. Native air elementals once helped preserve the magical currents that keep the island aloft. Several centuries ago, those elementals vanished. Without their presence, the enchantments beneath the land have slowly weakened, and Zephras has begun to fracture.",sp=0},{t="Severed Horizons",b="Anvilas and Siroccas once drifted through skywall alongside Zephras, and the Skyborne made homes on all three islands. When the elementals vanished, communication between the islands ended. Now refugees from the crumbling neighbors have reached Zephras seeking safety. They report that the land beneath them on Anvilas and Siroccas is breaking apart.",sp=0},{t="Threshold to Azeroth",b="As Zephras decays, the Skyborne look beyond skywall toward Azeroth. Airships now set out from the skydocks of valanaar to make rare links with the mortal realm. Their voyages reach the outskirts of Dalaran in the alterac mountains and skywatcher plateau in Mulgore.",sp=0}},faq={{q="Where is Zephras Isle located?",a="Zephras Isle floats within Skywall, the Elemental Plane of air, rather than on Azeroth. Clouds and wind currents surround the island in that ethereal realm.",al={"zephras isle location","where is zephras","what plane is zephras on"},it="place"},{q="Why is Zephras Isle falling apart?",a="Native air elementals once lived alongside the Skyborne and helped sustain Zephras Isle. They vanished several centuries ago, and the island's magical foundations have slowly weakened since.",al={"why is zephras collapsing","zephras isle destruction","dying island"},it="ruin"},{q="What are Anvilas and Siroccas?",a="Anvilas and Siroccas are neighboring floating island homes of the Skyborne in Skywall. Contact with both ended when the elementals vanished, and refugees now report that the islands are collapsing.",al={"anvilas","siroccas","other skyborne islands"},it="place"},{q="How do people travel between Zephras Isle and Azeroth?",a="The Skyborne launch airships from the skydocks at Valanaar and cross into Azeroth. They reach the outskirts of Dalaran in the Alterac Mountains and Skywatcher Plateau in Mulgore.",al={"how to leave zephras","zephras airships","travel to azeroth"},it="place"},{q="Who are the Skyborne?",a="The Skyborne have made their homes on Zephras Isle and its sister sky-realms for generations. Their floating island homeland is slowly breaking apart as its sustaining magic fades.",al={"skyborne race","who lives on zephras"},it="residents"},{q="Who lives on Zephras Isle besides the Skyborne?",a="Local bandits, cavern-dwelling nightclaws, and beasts live on Zephras Isle. They can be found in places such as the Shriekling Den and Nightclaw Cavern.",al={"zephras inhabitants","enemies on zephras"},it="residents"},{q="What is Zephras Isle?",a="Zephras Isle is a soaring floating landmass located within Skywall, the Elemental Plane of Air. Millennia ago, night elf exiles fleeing persecution in Eldre'Thalas bargained with native wind spirits, who lifted the island into the heavens to keep them safe. It serves as the ancestral sanctuary of their descendants, the Skyborne.",al={"what is zephras","about zephras isle","zephras isle info"},it="place",add="1fd88046",nx={10}},{q="What happened at Zephras Isle?",a="Zephras Isle was raised into Skywall after high elven ancestors broke away from Prince Tortheldrin's bloody reign in Eldre'Thalas. The Skyborne lived in harmony with air elementals for thousands of years, but centuries ago, those elemental patrons vanished without explanation. Without their continuous magic, the pylons anchoring the island began to decay, and refugees from neighboring collapsing islands have fled here while internal factions vie for dwindling resources.",al={"zephras history","what happened here zephras","zephras lore"},it="history",add="7ea7c85c"},{q="Is Zephras Isle dangerous?",a="Yes. Beyond the looming physical threat of the island itself destabilizing and tumbling from the skies, the disappearance of elemental protectors has left the land chaotic. Bandit encampments, hostile wildlife dens, and volatile political friction between the High Order, Windshapers, and Al'Aketh all make travel outside fortified settlements perilous.",al={"is zephras dangerous","zephras threats","dangers on zephras"},it="danger",add="70a3c6ae"},{q="Where is the isle compared to the rest of Azeroth?",a="Zephras Isle does not rest upon Azeroth's surface; it drifts within Skywall, a separate dimensional domain crafted by the titan-forged to contain chaotic air elementals. The only physical connections between the isle and the mortal world below are specialized airships that dock at Valanaar and travel across the boundary to points like Dalaran and Mulgore.",al={"where is zephras to azeroth","is zephras in azeroth","zephras location compared to azeroth"},it="place",add="b4875d06"},{q="Who are the Al'Aketh?",a="The Al'Aketh are one of the rival factions contending for dominance on Zephras Isle alongside the High Order and the Windshapers. As the pylons anchoring the island fail and survival grows desperate, the Al'Aketh actively vie for supremacy and control over the isle's remaining mystical resources.",al={"what are the alaketh","al'aketh faction","who is alaketh"},it="threat",add="2c89f95d"},{q="Am I leaving the isle eventually?",a="Yes. While Zephras Isle serves as your home and starting training ground, airships depart from the skydocks at Valanaar across planar rifts to mainland Azeroth, connecting directly to Dalaran in the Alterac Mountains and Skywatcher Plateau in Mulgore.",al={"will i leave zephras","leaving zephras isle","can we go to azeroth"},it="next_step",add="6e14d755"},{q="How did I end up in Zephras Isle?",a="You were born into the Skyborne, the shen'dorei who dwell upon this floating haven high within Skywall, the Elemental Plane of Air. Millennia ago, your ancestors fled the purge of Prince Tortheldrin in Eldre'Thalas and struck a pact with wind spirits who raised this sanctuary into the heavens. While other sibling islands like Anvilas and Siroccas crumble or fade from reach, Zephras Isle has been your home from the start. You begin your journey here among your own people.",al={"how did i get here","how did i reach zephras isle","why did i wake up here","where did i come from"},it="arrival",rc="Skyborne",add="19470e71"},{q="What am I supposed to be doing in Zephras Isle?",a="Your home is crumbling beneath your feet. Centuries ago, the benevolent air elementals vanished, and the arcane pylons that bind Zephras Isle together are losing their power. Refugees flood in from collapsing outer isles while rival factions, including the High Order, the Windshapers, and the Al'Aketh, squabble over what remains. You must aid your people, quell internal threats and wild beasts, help stabilize the failing magics, and ultimately seek a passage down to Azeroth before the island falls.",al={"what should i be doing here","what is my goal here","what am i doing on zephras isle","why am i here"},it="purpose",rc="Skyborne",add="5dae6f41"}},ang={["race:Skyborne"]="As a Skyborne, Zephras Isle is your ancestral home and starting ground. Its beauty remains even as the land collapses and elemental power fades.",["class:Shaman"]="As a Shaman, you know Zephras Isle lies within the Elemental Plane of air. Its fading elemental power shows what happens when the spirits that sustain an elemental land disappear."},kw={"airships","anvilas","elemental plane","siroccas","skyborne","Skywall","Valanaar","windstones","zephras"},rel={"topic:skyborne","topic:skywall","topic:elemental-plane","npc:ventaari-brightwish","quest:93552","zone:alterac","zone:mulgore","subzone:dalaran"},m={levels="1-12"},src={"Zephras Isle"}}
